-- Восстановление faq и правильная чистка чужих вопросов.
--
-- Вчерашний fix_faq_foreign_questions_2026-09-12.sql считал индексы удаляемых
-- вопросов по английской версии и применял их ко всем восьми языкам. Посылка
-- была неверна: переводы FAQ — не переводы английских вопросов, а независимые
-- наборы, у них своё содержимое и свой порядок. В английском чистка сработала
-- верно, в остальных семи удалились произвольные вопросы, а чужие остались.
--
-- Этот файл собран так, чтобы ничего не потерять:
--   • прежнее содержимое поднято из SQL-файлов в репозитории
--     (gen_tool_choose_faq_*.sql, fix_tool_faq.sql, compare_refresh_*.sql);
--   • объединено с тем, что сейчас в базе, по тексту вопроса;
--   • отфильтровано по каждому языку отдельно, по содержимому, а не по индексу.
--
-- Правило то же: вопрос убираем, если он называет другой инструмент каталога
-- и не называет свой. Вопросы без имён остаются.
-- Идемпотентно: присвоение готовых массивов.

UPDATE tools SET faq = $x$[{"q": "AdCreative.ai vs Canva — для чего каждый?", "a": "AdCreative.ai специализируется на рекламе: генерирует баннеры, оценивает их эффективность и оптимизирует под конкретные платформы. Canva — универсальный дизайн для любого контента. Для профессиональной рекламы AdCreative точнее, для всего остального — Canva."}, {"q": "AdCreative.ai бесплатный?", "a": "AdCreative.ai не предлагает постоянного бесплатного плана — только пробный период. Starter — $21/мес (10 кредитов). Canva бесплатен с базовыми функциями; Canva Pro — $15/мес."}, {"q": "Canva подходит для создания рекламы?", "a": "Да. Canva имеет шаблоны для Facebook Ads, Google Display, Instagram и других платформ. Canva Pro добавляет удаление фона и Brand Kit. Для высоких объёмов и оптимизации CTR AdCreative.ai предлагает больше специализированных функций."}]$x$::jsonb
 WHERE slug = 'adcreative-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "AdCreative.ai לעומת Canva – מה עדיף?", "a": "AdCreative.ai מתמחה ב-Ad Performance ו-Performance Marketing. Canva כלי עיצוב כללי. AdCreative לפרסום ממומן; Canva לכל שאר העיצוב."}, {"q": "AdCreative.ai כמה עולה?", "a": "AdCreative.ai מ-$21/חודש ל-Startup. Canva Pro ב-$15/חודש. AdCreative יקר יותר אך ממוקד לפרסום."}, {"q": "AdCreative.ai – כיצד AI מגדיל ביצועים?", "a": "AdCreative.ai ניתח מיליוני מודעות ולמד מה עובד. AI מחבר אלמנטים (צבעים, מיקום, עיצוב) לפי מה שהניב ביצועים. מציג גם Score לכל קריאייטיב."}]$x$::jsonb
 WHERE slug = 'adcreative-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Las imágenes de DALL-E 3 son libres de derechos?", "a": "Según los términos de OpenAI, los usuarios de pago tienen derechos sobre las imágenes generadas. Sin embargo, hay debate legal sobre los derechos de autor de imágenes generadas por IA. Para uso comercial con garantías claras — Adobe Firefly (entrenado con contenido con licencia) es la opción más segura legalmente."}, {"q": "¿Adobe Firefly puede generar desde texto sin Photoshop?", "a": "Sí. Adobe Firefly tiene una interfaz web (firefly.adobe.com) donde puedes generar imágenes desde texto sin necesitar Photoshop. Las funciones de Generative Fill e integración profunda sí requieren Photoshop. La web app tiene plan gratuito con créditos limitados."}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Ist Adobe Firefly kommerziell sicher?", "a": "Ja. Adobe trainiert Firefly ausschließlich mit Adobe Stock-Bildern, gemeinfreien Werken und lizenzierten Inhalten. Das macht es kommerziell sicher ohne Copyright-Risiken. Adobe bietet sogar eine Entschädigung falls es trotzdem zu IP-Problemen kommt."}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Безопасен ли Adobe Firefly в плане авторских прав?", "a": "Да. Adobe Firefly обучен исключительно на изображениях Adobe Stock, контенте с открытыми лицензиями и материалах общественного достояния. Созданные изображения можно использовать коммерчески без риска нарушения авторских прав — в отличие от большинства других генераторов."}, {"q": "Качество Midjourney выше, чем у Adobe Firefly?", "a": "По художественному и эстетическому качеству Midjourney, как правило, выдаёт более выразительные результаты. Firefly превосходит его в фотореалистичных снимках продуктов и брендинговом визуале. С выходом Firefly 3 (2025) разрыв существенно сократился."}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "ChatGPT Images לעומת Adobe Firefly?", "a": "DALL-E 3 יצירתי ומבין תיאורים מורכבים. Firefly בטוח מסחרית ומשתלב עם Adobe. יצירה חופשית – DALL-E; עיצוב מקצועי – Firefly."}, {"q": "Adobe Firefly חינמי?", "a": "Firefly מציע 25 Credits חינמיים לחודש; Creative Cloud כולל Firefly Credits. ChatGPT Images כלול ב-ChatGPT Plus ($20/חודש)."}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "DALL-E 3 vs Adobe Firefly — lequel est le meilleur ?", "a": "DALL-E 3 suit mieux les instructions textuelles précises. Firefly est meilleur pour l'intégration professionnelle dans Photoshop et la sécurité commerciale. Pour une génération dans ChatGPT → DALL-E 3 ; pour les professionnels Adobe → Firefly."}, {"q": "Adobe Firefly peut-il modifier des photos existantes ?", "a": "Oui. Via Generative Fill dans Photoshop, Firefly peut étendre, supprimer ou remplacer des éléments dans des photos existantes. C'est l'une des fonctionnalités les plus puissantes pour l'édition photo professionnelle."}, {"q": "DALL-E 3 est-il sûr pour un usage commercial ?", "a": "DALL-E 3 via ChatGPT permet l'usage commercial du contenu généré selon les conditions d'OpenAI. Adobe Firefly offre des garanties d'indemnisation commerciale plus explicites car il est spécifiquement entraîné sur du contenu sous licence."}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "DALL-E 3 vs Adobe Firefly — qual é o melhor?", "a": "DALL-E 3 segue melhor instruções textuais precisas. Firefly é melhor para integração profissional no Photoshop e segurança comercial. Para geração no ChatGPT → DALL-E 3; para profissionais Adobe → Firefly."}, {"q": "Adobe Firefly pode modificar fotos existentes?", "a": "Sim. Via Generative Fill no Photoshop, Firefly pode expandir, remover ou substituir elementos em fotos existentes. É uma das funcionalidades mais poderosas para edição de fotos profissional."}, {"q": "DALL-E 3 é seguro para uso comercial?", "a": "DALL-E 3 via ChatGPT permite uso comercial do conteúdo gerado conforme os termos da OpenAI. Adobe Firefly oferece garantias de indenização comercial mais explícitas pois é especificamente treinado em conteúdo licenciado."}]$x$::jsonb
 WHERE slug = 'adobe-firefly' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Descript o Adobe Podcast para podcasters principiantes?", "a": "Adobe Podcast (Enhance Speech) es más simple — subes el audio, lo mejoras y listo. Descript es más potente pero requiere más aprendizaje. Para empezar con mejora básica — Adobe Podcast; para producción profesional de podcasts con edición completa — Descript."}, {"q": "¿Adobe Podcast Enhance Speech funciona bien?", "a": "Sí. Enhance Speech de Adobe es sorprendentemente efectivo — toma audio grabado con micro de laptop o en ambientes ruidosos y lo transforma para sonar como grabado en estudio. Es gratuito y no requiere instalación. Una de las mejores herramientas de mejora de audio accesibles."}]$x$::jsonb
 WHERE slug = 'adobe-podcast' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Descript vs Adobe Podcast — яка різниця?", "a": "Descript — повний редактор подкастів і відео з транскрибуванням і монтажем через текст. Adobe Podcast — простий онлайн-інструмент для покращення якості аудіо. Descript для повного виробництва; Adobe Podcast для швидкого покращення запису."}, {"q": "Adobe Podcast Enhance справді покращує якість?", "a": "Так. Adobe Podcast Enhance (Speech Enhancement) значно покращує якість аудіо знятого на звичайний мікрофон — зменшує шум, покращує чіткість. Безкоштовний і доступний без Adobe CC."}]$x$::jsonb
 WHERE slug = 'adobe-podcast' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Descript או Adobe Podcast – מה עדיף?", "a": "Descript הוא עורך פודקאסט ווידאו מלא עם תמלול, עריכת טקסט וכלי AI. Adobe Podcast מתמחה בשיפור איכות שמע. ל-Descript ביצועים ולאינטגרציה עם Adobe – Podcast."}, {"q": "האם Adobe Podcast Enhance Speech עובד?", "a": "כן, Enhance Speech של Adobe עובד היטב להסרת רעשי רקע ולשיפור בהירות הקול. זהו אחד הכלים החינמיים היעילים ביותר לשיפור שמע."}]$x$::jsonb
 WHERE slug = 'adobe-podcast' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Descript vs Adobe Podcast — lequel est le meilleur ?", "a": "Descript est un éditeur audio/vidéo complet — idéal pour les podcasters qui veulent tout en un. Adobe Podcast Enhance est excellent pour améliorer rapidement la qualité audio. Pour la production complète de podcast → Descript ; pour améliorer des enregistrements → Adobe Podcast."}, {"q": "Adobe Podcast Enhance est-il gratuit ?", "a": "Oui. Adobe Podcast Enhance (l'outil d'amélioration audio) est gratuit à utiliser. Descript a un plan gratuit avec des limites ; Pro à partir de 24 $/mois."}, {"q": "Adobe Podcast fonctionne-t-il en français ?", "a": "Oui. Adobe Podcast Enhance améliore la qualité audio quelle que soit la langue. La transcription automatique fonctionne aussi en français. C'est un bon outil pour les podcasteurs francophones."}]$x$::jsonb
 WHERE slug = 'adobe-podcast' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Descript vs Adobe Podcast — qual escolher?", "a": "Descript é mais completo para edição de podcast e vídeo. Adobe Podcast é melhor para melhoria de qualidade de áudio. Para edição completa, Descript; para melhorar qualidade de áudio de gravações domésticas, Adobe Podcast."}, {"q": "Adobe Podcast realmente melhora o áudio?", "a": "Sim, o Adobe Podcast Enhance melhora dramaticamente áudios gravados em ambientes domésticos. Remove ruído de fundo, corrigi reverberação e equaliza o volume. É impressionante para áudios de qualidade média."}]$x$::jsonb
 WHERE slug = 'adobe-podcast' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Was ist Aider?", "a": "Aider ist ein Open-Source KI-Coding-Assistent für das Terminal. Sie starten Aider in Ihrem Projekt-Verzeichnis, wählen das Modell (Claude, GPT-4, etc.) und können dann in natürlicher Sprache Änderungen anfordern. Aider ändert die Dateien und erstellt automatisch Git-Commits."}, {"q": "Ist Aider kostenlos?", "a": "Aider selbst ist kostenlos und Open-Source. Die Kosten entstehen durch das verwendete Modell — Claude oder GPT-4 API-Nutzung. Mit Ollama und lokalen Modellen kann Aider vollständig kostenlos genutzt werden."}, {"q": "Aider vs Claude Code: Was ist besser?", "a": "Beide sind Terminal-basierte KI-Coding-Agenten. Claude Code ist tiefer in Anthropics Claude-Ökosystem integriert und generell leistungsfähiger für komplexe Aufgaben. Aider ist Open-Source, modellflexibel und hat eine aktive Community. Claude Code für maximale Qualität; Aider für Open-Source-Flexibilität."}, {"q": "Welche Programmiersprachen unterstützt Aider?", "a": "Aider versteht praktisch alle Programmiersprachen da es auf LLMs basiert. Es hat spezifische Unterstützung für das Repository-Mapping bei Python, JavaScript, TypeScript, Go, Java, C++, Ruby und weiteren gängigen Sprachen, was Aider hilft, den Code-Kontext besser zu verstehen."}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Aider?", "a": "Aider — это open-source ИИ-ассистент для написания кода, работающий в терминале. Он подключается к ИИ-моделям (Claude, GPT-4, Gemini) и может редактировать несколько файлов одновременно, автоматически фиксируя изменения в git после каждого шага."}, {"q": "Aider лучше GitHub Copilot?", "a": "Они подходят для разных задач. Aider лучше для автономного рефакторинга нескольких файлов из командной строки. Copilot лучше для встроенных подсказок в реальном времени внутри IDE. Многие разработчики используют оба инструмента."}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Aider vs GitHub Copilot — quelle est la différence ?", "a": "Aider est un outil terminal qui apporte de manière autonome des modifications à la base de code. Copilot est un plugin IDE pour l'autocomplétion et le chat. Aider pour les tâches complexes multi-fichiers via CLI ; Copilot pour l'écriture quotidienne de code dans l'IDE."}, {"q": "Aider est-il gratuit ?", "a": "Aider est open-source et gratuit. Vous payez pour l'API : API Claude, API OpenAI ou gratuitement via DeepSeek ou des modèles locaux. GitHub Copilot — à partir de 10 $/mois."}, {"q": "Aider pour Python — est-il adapté ?", "a": "Aider convient parfaitement à Python. C'est l'un des outils IA externes les plus populaires dans la communauté Python. Excellente prise en charge des refactorisations, tests et grandes bases de code."}, {"q": "Comment démarrer avec Aider ?", "a": "Installez : pip install aider-chat. Ajoutez une clé API (Anthropic ou OpenAI). Lancez aider dans le répertoire du projet. Aider voit automatiquement le contexte git et propose des modifications. Toute la documentation sur aider.chat."}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Aider vs GitHub Copilot — qual é a diferença?", "a": "Aider é uma ferramenta de terminal que faz alterações autônomas na base de código. Copilot é um plugin de IDE para autocompletar e chat. Aider para tarefas complexas em múltiplos arquivos via CLI; Copilot para escrita diária de código no IDE."}, {"q": "Aider é gratuito?", "a": "Aider é open-source e gratuito. Você paga pela API: API Claude, API OpenAI ou gratuitamente via DeepSeek ou modelos locais. GitHub Copilot — a partir de $10/mês."}, {"q": "Aider para Python — é adequado?", "a": "Aider se encaixa perfeitamente com Python. É uma das ferramentas de IA externas mais populares na comunidade Python. Excelente suporte para refatorações, testes e grandes bases de código."}, {"q": "Como começar com o Aider?", "a": "Instale: pip install aider-chat. Adicione uma chave de API (Anthropic ou OpenAI). Execute aider no diretório do projeto. O Aider vê automaticamente o contexto do git e propõe alterações. Toda a documentação em aider.chat."}]$x$::jsonb
 WHERE slug = 'aider' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Akkio o DataRobot para ML sin código?", "a": "DataRobot está más orientado a empresas grandes con equipos de datos — más potente pero mucho más caro. Akkio está diseñado para equipos de negocio sin científicos de datos — más accesible y fácil de configurar. Para PMEs y equipos de marketing/ventas — Akkio; para grandes empresas con datos complejos — DataRobot."}, {"q": "¿Akkio es gratuito?", "a": "Akkio tiene un plan gratuito limitado con proyectos básicos. Los planes de pago empiezan desde $49/mes. Julius AI tiene plan gratuito con 15 análisis/mes; planes desde $22/mes."}, {"q": "¿Qué datos puede analizar Akkio?", "a": "Akkio funciona con datos tabulares en CSV, Excel, Google Sheets o conectores directos a CRM (HubSpot, Salesforce). Para ML predictivo, necesitas datos históricos con la variable objetivo que quieres predecir (ej: clientes que se dieron de baja vs. los que no)."}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Akkio vs Julius AI — в чём разница?", "a": "Akkio строит предиктивные ML-модели (прогнозирование) по вашим данным. Julius AI анализирует данные через диалог: задаёте вопрос — получаете визуализацию. Akkio для прогностики, Julius для исследовательского анализа."}, {"q": "Akkio бесплатный?", "a": "Akkio предлагает бесплатный пробный период. Платные планы от $50/мес. Julius AI предлагает ограниченный бесплатный план; Pro — $20/мес."}, {"q": "Akkio требует знания ML?", "a": "Нет. Akkio позиционируется как no-code ML-платформа. Вы загружаете данные, выбираете целевую переменную и Akkio строит предиктивную модель. Экспертиза в машинном обучении не требуется."}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Akkio vs Julius AI — яка різниця?", "a": "Akkio будує прогнозні ML-моделі без коду для бізнес-прогнозування. Julius AI аналізує наявні дані через розмову і генерує візуалізації. Akkio для прогнозування; Julius для пізнавальної аналітики."}, {"q": "Akkio безкоштовний?", "a": "Akkio має пробний план. Платні плани від $49/міс. Julius AI має безкоштовний план; Pro від $20/міс."}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Akkio לעומת Julius AI?", "a": "Akkio לבניית מודלי ML ולחיזוי. Julius AI לניתוח נתונים ויצירת גרפים. Akkio ל-ML; Julius לניתוח ו-EDA."}, {"q": "Akkio חינמי?", "a": "Akkio מציע תקופת ניסיון; מחיר מ-$49/חודש. Julius AI מציע תוכנית חינמית מוגבלת; Pro ב-$28/חודש."}]$x$::jsonb
 WHERE slug = 'akkio' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿AutoGPT todavía es relevante en 2025?", "a": "AutoGPT fue pionero en agentes IA autónomos en 2023. En 2025, Claude Code, Manus y otros agentes más maduros han igualado o superado sus capacidades con mejor experiencia de uso. AutoGPT sigue siendo relevante como proyecto open-source y plataforma de experimentación, pero no es la opción más práctica para producción."}, {"q": "¿Cuál es la diferencia entre AutoGPT y LangChain?", "a": "AutoGPT es un agente de IA con objetivo fijo de completar tareas de forma autónoma. LangChain es un framework para desarrolladores para construir aplicaciones con LLMs y agentes. AutoGPT es para usuarios finales; LangChain es para desarrolladores que quieren construir sus propios sistemas de agentes."}, {"q": "¿Los agentes IA son seguros?", "a": "Los agentes IA como AutoGPT y Manus pueden ejecutar código, navegar la web y realizar acciones. Esto requiere precaución — siempre revisar los permisos antes de dar acceso a datos sensibles o sistemas críticos. Para experimentación — entornos aislados; para producción — revisión humana de acciones críticas."}]$x$::jsonb
 WHERE slug = 'autogpt' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist AutoGPT?", "a": "AutoGPT ist ein Open-Source autonomer KI-Agent der LLMs nutzt um Aufgaben selbstständig in mehreren Schritten zu erledigen. Es kann browsen, Code schreiben, Dateien lesen und APIs nutzen. Es war eines der ersten autonomen KI-Agenten-Frameworks."}, {"q": "AutoGPT vs Manus: Welches ist einfacher?", "a": "Manus ist deutlich einfacher: kein Setup, direkt nutzbar im Browser. AutoGPT erfordert technisches Setup (Python, API-Keys, Installation). Manus für sofortige Nutzung; AutoGPT für technische Nutzer die Agenten-Systeme verstehen und anpassen wollen."}, {"q": "Ist AutoGPT noch relevant?", "a": "AutoGPT hat das Agenten-Konzept popularisiert aber wurde von anderen Tools überholt. Neuere Frameworks wie LangGraph, CrewAI und kommerzielle Tools wie Manus sind ausgereifter. AutoGPT ist weiterhin aktiv aber nicht mehr führend."}]$x$::jsonb
 WHERE slug = 'autogpt' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "AutoGPT vs Manus — в чём разница?", "a": "AutoGPT — один из первых open-source ИИ-агентов, ориентированный на разработчиков и кастомизацию. Manus — коммерческий ИИ-агент общего назначения, ориентированный на конечных пользователей. AutoGPT для тех, кто хочет строить, Manus для тех, кто хочет использовать."}, {"q": "AutoGPT ещё актуален?", "a": "AutoGPT был пионером концепции ИИ-агентов в 2023 году. Сейчас более мощные альтернативы (Claude Code, Manus, Devin) превзошли его по качеству. Однако AutoGPT остаётся ценным open-source проектом для обучения и кастомизации."}]$x$::jsonb
 WHERE slug = 'autogpt' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "AutoGPT vs Manus — яка різниця?", "a": "AutoGPT — відкритий дослідницький проєкт для побудови ШІ-агентів. Manus — готовий комерційний ШІ-агент для делегування завдань. AutoGPT для розробників і дослідників; Manus для кінцевих користувачів що хочуть делегувати роботу."}, {"q": "AutoGPT ще активно розвивається?", "a": "AutoGPT — один із перших відкритих ШІ-агентів. Екосистема навколо агентів стала більш зрілою з такими інструментами як CrewAI і AutoGen від Microsoft. Перевірте репозиторій AutoGPT для поточного статусу розробки."}, {"q": "Чи безпечно довіряти завдання ШІ-агентам?", "a": "ШІ-агенти можуть робити помилки і потребують перевірки. Починайте з низькоризикових завдань. Завжди перевіряйте вихідні дані для важливої роботи. Не надавайте агентам доступу до критичних систем без відповідних засобів безпеки."}]$x$::jsonb
 WHERE slug = 'autogpt' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "AutoGPT לעומת Manus?", "a": "AutoGPT Framework לפיתוח Agents. Manus מוצר מוכן לביצוע משימות. AutoGPT למפתחים; Manus לאנשי עסקים."}, {"q": "AutoGPT חינמי?", "a": "AutoGPT Open Source חינמי; Agentive (הפלטפורמה המנוהלת) בתשלום. Manus גישה מוגבלת/Waitlist."}, {"q": "AutoGPT לעומת LangChain?", "a": "AutoGPT Framework שלם לבניית Agents. LangChain ספריה לבניית LLM Applications. AutoGPT לאוטומציה של Agents; LangChain לבניית אפליקציות LLM גנריות."}]$x$::jsonb
 WHERE slug = 'autogpt' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "AutoGPT vs Manus — quelle est la différence ?", "a": "AutoGPT est un framework open-source pour construire des agents IA — plus technique. Manus est un agent IA commercial prêt à l'emploi — plus accessible. Développeurs voulant personnaliser des agents → AutoGPT ; utilisateurs voulant déléguer des tâches → Manus."}, {"q": "AutoGPT est-il toujours pertinent ?", "a": "AutoGPT a été pionnier dans les agents IA mais l'espace a beaucoup évolué. Des alternatives plus récentes comme LangChain, CrewAI et AutoGen sont souvent préférées par les développeurs. Pour les utilisateurs finaux, des agents commerciaux comme Manus sont plus pratiques."}, {"q": "AutoGPT est-il gratuit ?", "a": "AutoGPT est open-source et gratuit. Vous payez pour les APIs IA utilisées (OpenAI, Anthropic). Manus a un modèle d'accès par invitation avec une tarification en évolution."}]$x$::jsonb
 WHERE slug = 'autogpt' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "AutoGPT vs Manus — qual é a diferença?", "a": "AutoGPT é um framework open-source para construir agentes de IA — mais técnico. Manus é um agente de IA comercial pronto para usar — mais acessível. Desenvolvedores que querem personalizar agentes → AutoGPT; usuários que querem delegar tarefas → Manus."}, {"q": "AutoGPT ainda é relevante?", "a": "AutoGPT foi pioneiro em agentes de IA mas o espaço evoluiu muito. Alternativas mais recentes como LangChain, CrewAI e AutoGen são frequentemente preferidas por desenvolvedores. Para usuários finais, agentes comerciais como Manus são mais práticos."}, {"q": "AutoGPT é gratuito?", "a": "AutoGPT é open-source e gratuito. Você paga pelas APIs de IA usadas (OpenAI, Anthropic). Manus tem um modelo de acesso por convite com preços em evolução."}]$x$::jsonb
 WHERE slug = 'autogpt' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Beautiful.ai o Google Slides para equipos?", "a": "Beautiful.ai tiene diseño automático superior — los slides se ajustan solos. Google Slides tiene colaboración más familiar y es gratuito. Para calidad de diseño sin esfuerzo — Beautiful.ai. Para colaboración sencilla sin costo — Google Slides. Muchos equipos usan Google Slides para borradores y Beautiful.ai para versiones finales."}, {"q": "¿Cuánto cuesta Beautiful.ai?", "a": "Beautiful.ai tiene una prueba gratuita de 14 días. Los planes de pago empiezan desde $12/mes (Pro). Pitch tiene plan gratuito con presentaciones ilimitadas; planes de team desde $25/mes."}, {"q": "¿Beautiful.ai puede exportar a PowerPoint?", "a": "Sí. Beautiful.ai permite exportar a PDF y PowerPoint. Esto facilita compartir con personas que no tienen cuenta de Beautiful.ai. La calidad del export a PowerPoint es buena, aunque algunas animaciones automáticas pueden simplificarse en la conversión."}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Beautiful.ai vs Pitch: Welches ist besser für Startups?", "a": "Pitch ist beliebter bei Startups für Investor-Decks: bessere Templates für Fundraising und stärkere Kollaboration. Beautiful.ai ist gut für regelmäßige Unternehmenspräsentationen wo Konsistenz wichtig ist. Für Investor-Pitches — Pitch; für laufende Business-Präsentationen — Beautiful.ai."}, {"q": "Ist Beautiful.ai kostenlos?", "a": "Beautiful.ai hat keinen dauerhaft kostenlosen Plan. Pro ab $12/Monat (jährlich). Pitch hat einen kostenlosen Plan für bis zu 3 Mitglieder; Pro ab $8/Mitglied/Monat."}, {"q": "Kann Beautiful.ai Markenschriften und -farben verwenden?", "a": "Ja. Beautiful.ai unterstützt Branding: eigene Farben, Schriften und Logos. Sie können Brand-Templates erstellen die das gesamte Team für konsistente Präsentationen nutzt. Das ist einer der Hauptvorteile für Marketing-Teams."}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Может ли Beautiful.ai экспортировать в PowerPoint?", "a": "Да. Beautiful.ai может экспортировать презентации в формат PowerPoint (.pptx). Полезно, когда нужно делиться файлами с людьми, ожидающими традиционные форматы слайдов. Веб-нативный формат Gamma не экспортируется в PowerPoint так же чисто."}, {"q": "Что лучше для бизнес-презентаций — Gamma или Beautiful.ai?", "a": "Для быстрых ИИ-сгенерированных презентаций, которыми делятся в цифровом виде, Gamma быстрее и современнее. Для традиционных бизнес-презентаций, которые могут потребовать экспорта PowerPoint, Beautiful.ai даёт больше контроля. Оба производят профессиональные результаты."}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Beautiful.ai чи Pitch — що краще для стартапів?", "a": "Pitch популярніший серед стартапів для інвестор-деків: кращі шаблони для fundraising і сильніша колаборація. Beautiful.ai добре для регулярних корпоративних презентацій де важлива консистентність. Для пітчів інвесторам — Pitch; для бізнес-презентацій — Beautiful.ai."}, {"q": "Beautiful.ai безкоштовний?", "a": "Beautiful.ai не має постійного безкоштовного плану. Pro від $12/міс (річна оплата). Pitch має безкоштовний план до 3 учасників; Pro від $8/учасник/міс."}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Beautiful.ai לעומת Pitch לסטארטאפים?", "a": "Pitch מועדף לגיוס כסף – templates לסטארטאפ ו-Analytics. Beautiful.ai לצוותי שיווק עם Brand. Pitch לגיוס; Beautiful.ai למצגות שיווקיות."}, {"q": "Beautiful.ai חינמי?", "a": "Beautiful.ai אין תוכנית חינמית קבועה; Pro ב-$12/חודש. Pitch חינמי עד 3 חברים; Pro ב-$8/חבר/חודש."}, {"q": "Beautiful.ai Brand – כיצד זה עובד?", "a": "Beautiful.ai מאפשר להגדיר צבעי Brand, פונות ולוגו. כל המצגות של הצוות ישתמשו בהגדרות אלה אוטומטית. מועיל מאוד לצוותי Marketing."}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Beautiful.ai vs Pitch — lequel est le meilleur pour les startups ?", "a": "Pitch est plus populaire pour les pitch decks d'investisseurs : meilleurs templates pour le fundraising et collaboration plus forte. Beautiful.ai est bon pour les présentations d'entreprise régulières où la cohérence est importante. Pour les pitchs investisseurs → Pitch ; pour les présentations régulières → Beautiful.ai."}, {"q": "Beautiful.ai est-il gratuit ?", "a": "Beautiful.ai n'a pas de plan gratuit permanent. Pro à partir de 12 $/mois (annuel). Pitch a un plan gratuit jusqu'à 3 membres ; Pro à partir de 8 $/membre/mois."}, {"q": "Beautiful.ai peut-il utiliser les polices et couleurs de marque ?", "a": "Oui. Beautiful.ai prend en charge le branding : couleurs, polices et logos personnalisés. Vous pouvez créer des templates de marque que toute l'équipe utilise pour des présentations cohérentes. C'est l'un des principaux avantages pour les équipes marketing."}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Beautiful.ai vs Pitch — qual é o melhor para startups?", "a": "Pitch é mais popular para pitch decks de investidores: melhores templates para fundraising e colaboração mais forte. Beautiful.ai é bom para apresentações corporativas regulares onde a consistência importa. Para pitches de investidores → Pitch; para apresentações regulares → Beautiful.ai."}, {"q": "Beautiful.ai é gratuito?", "a": "Beautiful.ai não tem plano gratuito permanente. Pro a partir de $12/mês (anual). Pitch tem plano gratuito até 3 membros; Pro a partir de $8/membro/mês."}, {"q": "Beautiful.ai pode usar fontes e cores da marca?", "a": "Sim. Beautiful.ai suporta branding: cores, fontes e logos personalizados. Você pode criar templates de marca que toda a equipe usa para apresentações consistentes. É uma das principais vantagens para equipes de marketing."}]$x$::jsonb
 WHERE slug = 'beautiful-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Bolt.new?", "a": "Bolt.new es un constructor de aplicaciones de IA basado en el navegador de StackBlitz. Describe tu tarea en lenguaje natural y crea una aplicación web completa con frontend, backend y base de datos directamente en el navegador sin ninguna configuración local."}, {"q": "¿Bolt.new es mejor que Cursor?", "a": "Están orientados a usuarios diferentes. Bolt.new es para prototipado rápido y no-desarrolladores. Cursor es para desarrolladores profesionales con asistencia de IA en un entorno local. Muchos usan Bolt para prototipos y Cursor para desarrollo de producción."}, {"q": "¿Se puede crear una aplicación de producción en Bolt.new?", "a": "Bolt.new puede crear código listo para producción para aplicaciones pequeñas. Para aplicaciones complejas con infraestructura personalizada, los desarrolladores suelen exportar el código y continuar en un IDE local."}, {"q": "¿Cuánto cuesta Bolt.new?", "a": "Nivel gratuito con tokens limitados. Pro es $20/mes. Planes de equipo disponibles para proyectos colaborativos."}, {"q": "¿Puede Bolt.new desplegar mi app?", "a": "Sí. Bolt.new incluye hosting propio a través de StackBlitz. Puedes publicar tu app instantáneamente sin configurar un proveedor de hosting separado."}, {"q": "¿Qué stack tecnológico usa Bolt.new?", "a": "Bolt.new soporta React, Next.js, Vue, Svelte y otros frameworks populares. Se conecta a Supabase para bases de datos y puede integrarse con APIs de terceros."}]$x$::jsonb
 WHERE slug = 'bolt-new' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Für wen ist Bolt.new geeignet?", "a": "Bolt.new ist ideal für Nicht-Entwickler die schnell Prototypen benötigen, für Entwickler die Ideen schnell validieren wollen, und für einfache Web-Apps ohne komplexe Backend-Anforderungen. Für Produktionscode in großen Teams mit komplexen Anforderungen ist Cursor oder ein lokales Setup besser geeignet."}, {"q": "Ist Bolt.new kostenlos?", "a": "Bolt.new hat einen kostenlosen Plan mit begrenzten Token. Kostenpflichtige Pläne ($20-$50/Monat) bieten mehr Generierungen. Cursor hat einen kostenlosen Plan (2.000 Vervollständigungen); Pro kostet $20/Monat."}, {"q": "Welche Technologien unterstützt Bolt.new?", "a": "Bolt.new generiert hauptsächlich React/Vite Apps mit TypeScript und Tailwind CSS. Es kann auch Node.js-Backends, Supabase-Integrationen und andere Web-Technologien generieren. Für native Mobile-Apps oder sehr spezifische Tech-Stacks ist es weniger geeignet."}, {"q": "Kann Bolt.new Produktionscode erstellen?", "a": "Bolt.new eignet sich gut für MVPs und Prototypen. Für Produktionscode in Enterprise-Umgebungen mit Sicherheitsanforderungen, komplexem State-Management und Skalierbarkeit benötigt man in der Regel Entwicklerüberprüfung und Refactoring. Es ist ein Ausgangspunkt, kein Endprodukt."}, {"q": "Was ist Bolt.new?", "a": "Bolt.new ist ein browserbasierter KI-Full-Stack-Builder von StackBlitz. Beschreibe was du bauen möchtest und erhalte eine komplette Web-App mit Frontend, Backend und Datenbank, die live im Browser läuft."}, {"q": "Was kostet Bolt.new?", "a": "Kostenloses Kontingent mit begrenzten Tokens. Pro kostet $20/Monat. Team-Pläne für kollaborative Projekte verfügbar."}, {"q": "Kann Bolt.new meine App deployen?", "a": "Ja. Bolt.new enthält eigenes Hosting über StackBlitz. Deine App kann sofort veröffentlicht werden, ohne einen separaten Hosting-Anbieter zu konfigurieren."}, {"q": "Welchen Tech-Stack verwendet Bolt.new?", "a": "Bolt.new unterstützt React, Next.js, Vue, Svelte und andere populäre Frameworks. Es verbindet sich mit Supabase für Datenbanken und kann Drittanbieter-APIs integrieren."}]$x$::jsonb
 WHERE slug = 'bolt-new' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Bolt.new?", "a": "Bolt.new — браузерный конструктор ИИ-приложений от StackBlitz. Опишите задачу на обычном языке, и он создаст полноценное веб-приложение с фронтендом, бэкендом и базой данных прямо в браузере без какой-либо локальной настройки."}, {"q": "Bolt.new лучше Cursor?", "a": "Они ориентированы на разных пользователей. Bolt.new — для быстрого прототипирования и не-разработчиков. Cursor — для профессиональных разработчиков с ИИ-помощью в локальной среде. Многие используют Bolt для прототипов, а Cursor — для продакшн-разработки."}]$x$::jsonb
 WHERE slug = 'bolt-new' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Bolt.new vs Cursor — що обрати?", "a": "Bolt.new для швидкого старту веб-застосунку з нуля без налаштування. Cursor для роботи з існуючою кодовою базою і professional розробки. Bolt для прототипів; Cursor для реальних проєктів."}, {"q": "Bolt.new безкоштовний?", "a": "Bolt.new має безкоштовний план з обмеженнями токенів. Про плани від $20/міс. Cursor Free — обмежений; Pro — $20/міс."}, {"q": "Bolt.new vs Replit — різниця?", "a": "Обидва хмарні інструменти розробки. Bolt.new більш орієнтований на генерацію з ШІ. Replit повніший IDE з більшою підтримкою мов і хостингом. Bolt для генерації; Replit для повноцінної хмарної розробки."}]$x$::jsonb
 WHERE slug = 'bolt-new' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Bolt.new מול Cursor — מה לבחור?", "a": "Bolt.new להתחלה מהירה של אפליקציית ווב מאפס ללא הגדרה. Cursor לעבודה עם בסיס קוד קיים ולפיתוח מקצועי. Bolt לאבות-טיפוס; Cursor לפרויקטים אמיתיים."}, {"q": "האם Bolt.new בחינם?", "a": "ל-Bolt.new יש תוכנית חינמית עם מגבלות טוקנים. תוכניות Pro מ-20$/חודש. Cursor Free — מוגבל; Pro — 20$/חודש."}, {"q": "Bolt.new מול Replit — מה ההבדל?", "a": "שניהם כלי פיתוח ענן. Bolt.new ממוקד יותר ביצירת AI. Replit הוא IDE מלא יותר עם תמיכה ב-language נוספות ואירוח. Bolt ליצירה; Replit לפיתוח ענן מלא."}]$x$::jsonb
 WHERE slug = 'bolt-new' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Bolt.new vs Cursor — lequel choisir ?", "a": "Bolt.new pour démarrer rapidement une application web à partir de zéro sans configuration. Cursor pour travailler avec une base de code existante et le développement professionnel. Bolt pour les prototypes ; Cursor pour les vrais projets."}, {"q": "Bolt.new est-il gratuit ?", "a": "Bolt.new a un plan gratuit avec des limites de tokens. Les plans Pro à partir de 20 $/mois. Cursor Free — limité ; Pro — 20 $/mois."}, {"q": "Que peut-on faire avec Bolt.new ?", "a": "Bolt.new génère des applications web : React, Next.js, Vue, backends Express, intégrations Supabase et plus encore. Tout directement dans le navigateur avec déploiement en un clic. Parfait pour les MVPs et prototypes."}, {"q": "Bolt.new vs Replit — quelle est la différence ?", "a": "Les deux sont des outils de développement cloud. Bolt.new est plus orienté vers la génération IA. Replit est un IDE plus complet avec plus de support de langages et d'hébergement. Bolt pour la génération ; Replit pour le développement cloud complet."}, {"q": "Qu'est-ce que Bolt.new ?", "a": "Bolt.new est un constructeur full-stack IA dans le navigateur par StackBlitz. Décrivez ce que vous voulez créer et obtenez une application web complète avec frontend, backend et base de données, fonctionnant en direct dans le navigateur."}, {"q": "Combien coûte Bolt.new ?", "a": "Niveau gratuit avec tokens limités. Pro à $20/mois. Plans équipe disponibles pour les projets collaboratifs."}, {"q": "Bolt.new peut-il déployer mon application ?", "a": "Oui. Bolt.new inclut un hébergement intégré via StackBlitz. Vous pouvez publier votre app instantanément sans configurer un hébergeur séparé."}, {"q": "Quel stack technologique utilise Bolt.new ?", "a": "Bolt.new supporte React, Next.js, Vue, Svelte et d'autres frameworks populaires. Il se connecte à Supabase pour les bases de données et peut intégrer des API tierces."}]$x$::jsonb
 WHERE slug = 'bolt-new' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Bolt.new vs Cursor — qual escolher?", "a": "Bolt.new para iniciar rapidamente uma aplicação web do zero sem configuração. Cursor para trabalhar com uma base de código existente e desenvolvimento profissional. Bolt para protótipos; Cursor para projetos reais."}, {"q": "Bolt.new é gratuito?", "a": "Bolt.new tem plano gratuito com limites de tokens. Planos Pro a partir de $20/mês. Cursor Free — limitado; Pro — $20/mês."}, {"q": "O que é possível fazer com o Bolt.new?", "a": "Bolt.new gera aplicações web: React, Next.js, Vue, backends Express, integrações Supabase e mais. Tudo diretamente no navegador com implantação com um clique. Perfeito para MVPs e protótipos."}, {"q": "Bolt.new vs Replit — qual é a diferença?", "a": "Ambos são ferramentas de desenvolvimento cloud. Bolt.new é mais orientado para geração de IA. Replit é um IDE mais completo com mais suporte de linguagens e hospedagem. Bolt para geração; Replit para desenvolvimento cloud completo."}, {"q": "O que é o Bolt.new?", "a": "O Bolt.new é um construtor full-stack de IA no navegador da StackBlitz. Descreva o que quer criar e obtenha um aplicativo web completo com frontend, backend e banco de dados, rodando ao vivo no navegador."}, {"q": "Quanto custa o Bolt.new?", "a": "Nível gratuito com tokens limitados. Pro custa $20/mês. Planos de equipe disponíveis para projetos colaborativos."}, {"q": "O Bolt.new pode fazer o deploy do meu app?", "a": "Sim. O Bolt.new inclui hospedagem integrada via StackBlitz. Você pode publicar seu app instantaneamente sem configurar um provedor de hospedagem separado."}, {"q": "Qual stack tecnológico o Bolt.new usa?", "a": "O Bolt.new suporta React, Next.js, Vue, Svelte e outros frameworks populares. Conecta-se ao Supabase para bancos de dados e pode integrar APIs de terceiros."}]$x$::jsonb
 WHERE slug = 'bolt-new' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Bubble o Webflow para startups?", "a": "Depende del producto. Si construyes una aplicación SaaS con usuarios, datos y lógica — Bubble. Si construyes el sitio web de marketing de tu startup — Webflow. Muchas startups usan ambas: Webflow para el sitio de marketing y Bubble para el producto."}, {"q": "¿Bubble es gratuito?", "a": "Bubble tiene plan gratuito para desarrollar y probar apps (con subdominio bubble.io). Para lanzar en producción, el plan más económico cuesta $32/mes (Starter). Webflow tiene plan gratuito para 2 proyectos con subdominio webflow.io; planes para sites desde $14/mes."}, {"q": "¿Qué apps famosas se construyeron en Bubble?", "a": "Varias startups notables comenzaron en Bubble: Dividend Finance, Teal (gestión de carrera), varios MVPs de Y Combinator. Bubble es reconocido en el ecosistema no-code como la plataforma más seria para construir productos reales antes de contratar desarrolladores."}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Bubble oder Webflow: Was soll ich wählen?", "a": "Bubble für Web-Apps: Sie brauchen Nutzeraccounts, Datenbank und komplexe Logik — z.B. ein SaaS-Produkt oder Marktplatz. Webflow für Marketing-Websites: Sie brauchen eine schöne, schnelle Website mit CMS aber keine App-Logik."}, {"q": "Ist Bubble kostenlos?", "a": "Bubble hat einen kostenlosen Plan der das Bauen und Testen erlaubt. Kostenpflichtige Pläne ab $29/Monat zum Veröffentlichen ohne Bubble-Branding. Webflow hat einen kostenlosen Plan; kostenpflichtige Pläne ab $18/Monat."}, {"q": "Kann Bubble eine App für den App-Store erstellen?", "a": "Bubble erstellt Web-Apps die im Browser laufen. Für native iOS/Android-Apps können Sie Bubble-Apps als PWA verpacken oder Tools wie BDK Native verwenden. Für echte native Apps sind FlutterFlow oder React Native besser geeignet."}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между Bubble и Webflow?", "a": "Bubble — конструктор no-code приложений: для создания веб-приложений с базами данных, логикой и пользовательскими взаимодействиями. Webflow — конструктор сайтов с фокусом на дизайн и CMS. Bubble строит приложения, Webflow строит сайты."}, {"q": "Bubble подходит для SaaS?", "a": "Да. Bubble — одна из самых популярных платформ для создания SaaS-продуктов без кода. Он управляет авторизацией пользователей, базами данных, рабочими процессами и интеграцией API. Многие финансируемые стартапы используют Bubble как основную платформу."}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Bubble vs Webflow — що обрати для стартапу?", "a": "Bubble для стартапів що будують SaaS або застосунки з бізнес-логікою і базами даних. Webflow для маркетингових сайтів і агентств. Для MVP з функціональністю — Bubble; для красивого сайту — Webflow."}, {"q": "Bubble безкоштовний?", "a": "Bubble має безкоштовний план для розробки. Starter від $32/міс. Webflow безкоштовний для дизайну; Starter від $14/міс."}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Bubble לעומת Webflow – מה לבחור?", "a": "Bubble לאפליקציות web עם לוגיקה ומסד נתונים. Webflow לאתרים ויזואליים ו-CMS. SaaS ו-Web App – Bubble; אתרי שיווק ועיצוב – Webflow."}, {"q": "Bubble חינמי?", "a": "Bubble מציע תוכנית חינמית; Starter ב-$32/חודש. Webflow Starter חינמי; Basic ב-$14/חודש."}, {"q": "Bubble לעומת Glide – מה ההבדל?", "a": "Bubble לאפליקציות web מורכבות. Glide לאפליקציות פשוטות ממקורות Google Sheets. Bubble עוצמתי יותר; Glide מהיר יותר להשקה."}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Bubble vs Webflow — qual escolher?", "a": "Bubble é para construir aplicativos com lógica de negócios complexa. Webflow é para criar sites belos com CMS. Para apps SaaS, Bubble; para sites de marketing de alta qualidade, Webflow."}, {"q": "Bubble é gratuito?", "a": "Bubble tem plano gratuito para desenvolvimento e testes. Planos de produção a partir de $29/mês. Webflow tem plano gratuito limitado; planos de site a partir de $14/mês."}, {"q": "Posso criar um marketplace no Bubble?", "a": "Sim, Bubble é frequentemente usado para criar marketplaces, plataformas de aluguel e outros modelos de negócios complexos. Tem integrações com Stripe para pagamentos e suporte a multiusuários."}]$x$::jsonb
 WHERE slug = 'bubble' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Canva tiene generación de vectores?", "a": "Canva puede generar imágenes con IA pero principalmente en formato raster (PNG). La exportación SVG en Canva es limitada y no siempre de calidad vectorial real. Para vectoriales de calidad — Recraft o Illustrator son más adecuados."}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Canva AI бесплатный?", "a": "Canva предлагает бесплатный план с ограниченными ИИ-функциями. Canva Pro ($15/мес) открывает Magic Media, Magic Write, удаление фона и другие ИИ-инструменты."}, {"q": "Какие ИИ-функции есть у Figma?", "a": "Figma AI (запущен в 2024 году) включает генерацию макетов по текстовым запросам, умное переименование слоёв, создание прототипов и визуальный поиск. Доступен всем пользователям платных планов."}, {"q": "Может ли Canva заменить Figma?", "a": "Нет. Canva и Figma решают разные задачи. Canva — для создания маркетингового контента и презентаций. Figma — для проектирования UI/UX-интерфейсов и прототипов продуктов. Дизайнеры используют Figma, создатели контента — Canva."}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Що таке генерація SVG векторів?", "a": "SVG (Scalable Vector Graphics) — зображення що масштабується без втрати якості. Recraft AI може генерувати зображення у SVG-форматі — ідеально для логотипів, іконок і ілюстрацій що потрібно збільшувати."}, {"q": "Canva AI vs Adobe Firefly — різниця?", "a": "Canva AI вбудований у Canva-редактор для нетехнічних користувачів. Adobe Firefly більш потужний для креативних фахівців і інтегрований з Creative Cloud. Canva для простоти і маркетингу; Firefly для pro-дизайну."}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Recraft לעומת Canva AI?", "a": "Recraft מקצועי יותר ל-Vector ו-Brand Consistency. Canva AI כלי All-in-One לשיווק. Recraft לעיצובנאים; Canva לצוותי שיווק."}, {"q": "Canva Magic Studio – מה זה?", "a": "Canva Magic Studio היא חבילת AI של Canva הכוללת Magic Design, Magic Edit, Magic Eraser, Magic Expand ו-Magic Write."}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Recraft vs Canva AI — lequel est le meilleur ?", "a": "Recraft est spécialisé dans les illustrations vectorielles et les actifs de marque originaux. Canva AI est polyvalent pour tout le contenu marketing. Pour des illustrations de marque uniques → Recraft ; pour le contenu marketing général → Canva."}, {"q": "Canva AI peut-il remplacer un designer graphique ?", "a": "Canva AI peut aider les non-designers à créer du contenu marketing décent rapidement. Mais pour une identité de marque forte, des designs complexes et un travail créatif avancé, un designer professionnel reste nécessaire."}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Recraft vs Canva AI — qual é o melhor?", "a": "Recraft é especializado em ilustrações vetoriais e assets de marca originais. Canva AI é versátil para todo o conteúdo de marketing. Para ilustrações de marca únicas → Recraft; para conteúdo de marketing geral → Canva."}, {"q": "Canva AI pode substituir um designer gráfico?", "a": "Canva AI pode ajudar não-designers a criar conteúdo de marketing decente rapidamente. Mas para uma identidade de marca forte, designs complexos e trabalho criativo avançado, um designer profissional ainda é necessário."}]$x$::jsonb
 WHERE slug = 'canva-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿CapCut o Kling para TikTok?", "a": "Para editar videos de TikTok con templates, música, subtítulos y efectos — CapCut es la herramienta estándar del sector, usada por la mayoría de creadores de TikTok. Kling es para generar clips de video IA que luego podrías editar en CapCut. Son complementarios, no competidores directos."}, {"q": "¿CapCut es gratuito?", "a": "CapCut tiene un plan gratuito muy completo — la mayoría de funciones básicas y muchas IA son gratuitas. Algunas funciones premium requieren CapCut Pro ($9.99/mes). Kling tiene plan gratuito con créditos limitados; planes desde $10/mes."}, {"q": "¿Puede CapCut generar video desde texto?", "a": "CapCut tiene algunas funciones de IA generativa, pero son limitadas comparadas con Kling o Runway. CapCut se centra en edición; Kling en generación. Para texto-a-video de calidad, Kling es significativamente más potente."}, {"q": "¿CapCut es de TikTok/ByteDance?", "a": "Sí. CapCut es propiedad de ByteDance, la misma empresa de TikTok. En algunos países ha habido discusiones regulatorias relacionadas. Para usuarios en EE.UU., esto es un factor a considerar en términos de privacidad de datos."}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "CapCut oder Kling AI: Welches soll ich wählen?", "a": "Es sind verschiedene Tools. CapCut ist ein Video-Editor für bestehende Footage mit KI-Hilfs-Features. Kling AI generiert komplett neue Videos aus Text oder Bildern. Wenn Sie eigenes Footage haben — CapCut. Wenn Sie Videos von Grund auf generieren wollen — Kling."}, {"q": "Ist CapCut kostenlos?", "a": "Ja. CapCut ist kostenlos mit einem großzügigen Funktionsumfang. CapCut Pro ($9,99/Monat) schaltet mehr Effekte, Vorlagen und KI-Features frei. Kling AI hat einen kostenlosen Plan mit täglichen Credits."}, {"q": "Hat CapCut KI-Videoerstellung?", "a": "CapCut hat einen KI-Video-Generator in neueren Versionen, aber er ist weniger leistungsfähig als spezialisierte Tools wie Kling AI oder Runway. CapCut's Stärken liegen bei der Bearbeitung, nicht bei der Generierung."}, {"q": "Ist CapCut von TikTok?", "a": "CapCut ist ein Produkt von ByteDance, demselben Unternehmen das TikTok besitzt. Daher die enge Integration mit TikTok und die Beliebtheit für TikTok-Content-Erstellung. In einigen Ländern gibt es Datenschutzbedenken ähnlich wie bei TikTok."}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между CapCut и Kling AI?", "a": "CapCut — видеоредактор: вы импортируете готовые клипы и монтируете их. Kling AI — видеогенератор: создаёт видео из текстовых запросов или изображений. CapCut — для монтажа, Kling — для генерации."}, {"q": "Может ли CapCut генерировать ИИ-видео?", "a": "У CapCut есть некоторые функции генерации ИИ (Dream), но основная сила — монтаж готовых материалов. Для полноценной генерации видео из текстовых запросов Kling AI, Runway или Pika значительно мощнее."}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "CapCut чи Kling для відео?", "a": "CapCut — редактор для соціальних медіа з ШІ-функціями. Kling — спеціалізований генератор відео. Для монтажу TikTok і Reels — CapCut; для генерації кінематографічного відео — Kling."}, {"q": "CapCut безкоштовний?", "a": "Так. CapCut безкоштовний як на телефоні так і у браузері. Є платна версія з додатковими ШІ-функціями. Kling AI має безкоштовний план; платний від $8,8/міс."}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "CapCut מול Kling AI — מה ההבדל?", "a": "CapCut הוא עורך וידאו עם תכונות AI. Kling AI הוא מחולל וידאו AI מ-prompt. CapCut לעריכת וידאו קיים; Kling ליצירת וידאו חדש מתיאור."}, {"q": "האם CapCut בחינם?", "a": "כן, CapCut חינמי לשימוש בסיסי. CapCut Pro מ-9.99$/חודש לתכונות נוספות. Kling AI חינמי עם 66 קרדיטים/יום; מ-7$/חודש בתשלום."}, {"q": "CapCut ל-TikTok — האם כדאי?", "a": "כן. CapCut מתוכנן לעבוד היטב עם TikTok: תבניות מותאמות, יחסי גובה-רוחב נכונים ועריכה מהירה. פופולרי מאוד בקרב יוצרי TikTok."}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "CapCut vs Kling AI — quelle est la différence ?", "a": "CapCut est un éditeur vidéo avec des fonctionnalités IA. Kling AI est un générateur de vidéo IA de texte/image vers vidéo. CapCut pour éditer votre footage existant ; Kling pour créer de nouvelles vidéos depuis zéro avec l'IA."}, {"q": "CapCut est-il gratuit ?", "a": "CapCut est gratuit avec des fonctionnalités premium. CapCut Pro à partir de 9,99 $/mois. Kling AI à partir de 8 $/mois pour la génération de vidéo."}, {"q": "CapCut est-il disponible en France ?", "a": "Oui. CapCut est disponible en France sur mobile (iOS/Android) et bureau. Notez que CapCut est développé par ByteDance (la société TikTok), ce qui soulève des questions de confidentialité similaires à TikTok."}, {"q": "CapCut peut-il générer des vidéos IA ?", "a": "CapCut a des fonctionnalités de génération IA limitées (avatars IA, effets de style vidéo). Pour la génération complète de texte/image vers vidéo, des outils dédiés comme Kling, Runway ou Pika sont beaucoup plus puissants."}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "CapCut vs Kling AI — para que usar cada um?", "a": "CapCut é um editor de vídeo para quem já tem material filmado e quer editá-lo rapidamente. Kling AI é um gerador de vídeo que cria cenas do zero. Use CapCut para editar; Kling para criar do nada."}, {"q": "CapCut é gratuito?", "a": "Sim, CapCut é gratuito com recursos robustos. CapCut Pro custa cerca de $10/mês para recursos premium. Kling AI tem plano gratuito limitado; planos pagos a partir de $9,99/mês."}, {"q": "CapCut tem inteligência artificial?", "a": "Sim, CapCut tem vários recursos de IA: remoção automática de fundo, legendas automáticas, ajuste de ritmo com a música, efeitos de IA e mais. Não gera vídeo do zero como o Kling, mas tem muita automação."}]$x$::jsonb
 WHERE slug = 'capcut' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Для чего используется Character.AI?", "a": "Character.AI используется для ролевых разговоров с ИИ-персонажами. Пользователи общаются с ИИ-версиями знаменитостей, вымышленных героев, исторических личностей или кастомными ботами. Прежде всего — для развлечения и творческого письма, не для рабочих задач."}, {"q": "ChatGPT лучше Character.AI?", "a": "Для работы, исследований и реальных задач — да, ChatGPT значительно мощнее. Для развлечения, ролевых игр и разговоров с персонажами Character.AI создан специально и имеет большое сообщество. Они служат совершенно разным целям."}]$x$::jsonb
 WHERE slug = 'character-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Character.AI vs ChatGPT — для чого що?", "a": "Character.AI — для розваг, рольових ігор і соціальних сценаріїв. ChatGPT — для роботи, навчання і продуктивності. Якщо ви хочете поговорити з Герміоною Грейнджер — Character.AI; якщо хочете написати резюме — ChatGPT."}, {"q": "Чи безкоштовний Character.AI?", "a": "Так, Character.AI безкоштовний з базовим доступом. Character.AI+ коштує $9,99/міс і дає пріоритетний доступ і швидші відповіді. ChatGPT безкоштовний; Plus $20/міс."}]$x$::jsonb
 WHERE slug = 'character-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Character.AI מול ChatGPT — לשם מה כל אחד?", "a": "Character.AI לבידור, משחקי תפקידים ותרחישים חברתיים. ChatGPT לעבודה, למידה ופרודוקטיביות. אם אתם רוצים לדבר עם הרמיוני גריינג'ר — Character.AI; אם רוצים לכתוב קורות חיים — ChatGPT."}, {"q": "האם Character.AI בחינם?", "a": "כן, Character.AI חינמי עם גישה בסיסית. Character.AI+ עולה 9.99$/חודש ומספק גישה עדיפה ותגובות מהירות יותר. ChatGPT חינמי; Plus 20$/חודש."}]$x$::jsonb
 WHERE slug = 'character-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Es Claude mejor que ChatGPT?", "a": "Depende de la tarea. Claude es generalmente mejor con textos largos y procesa documentos extensos con mayor precisión. ChatGPT tiene más funciones (generación de imágenes, voz, plugins) y un ecosistema más grande. En benchmarks de código compiten — Claude 3.7 lidera en muchos."}, {"q": "¿Qué es gratis, ChatGPT o Claude?", "a": "Ambos tienen planes gratuitos. ChatGPT Free usa GPT-4o mini con acceso limitado a GPT-4o. Claude Free usa Claude 3.5 Haiku con Claude 3.5 Sonnet limitado. Los planes de pago de ambos ($20/mes) desbloquean los mejores modelos con límites más altos."}, {"q": "¿Puede ChatGPT generar imágenes?", "a": "Sí. Los planes ChatGPT Plus y superiores incluyen generación de imágenes con DALL-E 3. Claude no genera imágenes — solo texto y código."}, {"q": "¿Qué IA es mejor para código, ChatGPT o Claude?", "a": "Ambos son excelentes. Claude 3.7 Sonnet con pensamiento extendido lidera en SWE-bench (tareas reales de desarrollo) en 2025. Claude Code está diseñado específicamente para flujos de trabajo de codificación complejos. ChatGPT con intérprete de código destaca en análisis de datos."}]$x$::jsonb
 WHERE slug = 'chatgpt' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Ist Claude besser als ChatGPT?", "a": "Es hängt von der Aufgabe ab. Claude ist bei langen Texten generell besser und verarbeitet umfangreiche Dokumente präziser. ChatGPT hat mehr Funktionen (Bildgenerierung, Sprache, Plugins) und ein größeres Ökosystem. In Code-Benchmarks ist es ein Kopf-an-Kopf-Rennen — Claude 3.7 führt in vielen davon."}, {"q": "Was ist kostenlos — ChatGPT oder Claude?", "a": "Beide haben kostenlose Pläne. ChatGPT Free nutzt GPT-4o mini mit begrenztem GPT-4o-Zugang. Claude Free nutzt Claude 3.5 Haiku mit limitiertem Claude 3.5 Sonnet. Die kostenpflichtigen Pläne beider Dienste ($20/Monat) schalten die besten Modelle mit höheren Limits frei."}, {"q": "Kann ChatGPT Bilder generieren?", "a": "Ja. ChatGPT Plus und höhere Pläne beinhalten Bildgenerierung mit DALL-E 3. Claude generiert keine Bilder — nur Text und Code."}, {"q": "Welche KI ist besser für Code — ChatGPT oder Claude?", "a": "Beide sind ausgezeichnet. Claude 3.7 Sonnet mit erweitertem Denken führt 2025 auf SWE-bench (reale Entwicklungsaufgaben). Claude Code ist speziell für komplexe Coding-Workflows konzipiert. ChatGPT mit Code-Interpreter glänzt bei der Datenanalyse."}]$x$::jsonb
 WHERE slug = 'chatgpt' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Claude лучше ChatGPT?", "a": "Зависит от задачи. Claude в целом лучше справляется с длинными текстами и точнее обрабатывает большие документы. У ChatGPT больше функций (генерация изображений, голос, плагины) и более крупная экосистема. По бенчмаркам кода они конкурируют — Claude 3.7 лидирует во многих."}, {"q": "Что бесплатно — ChatGPT или Claude?", "a": "Оба имеют бесплатные планы. ChatGPT Free использует GPT-4o mini с ограниченным доступом к GPT-4o. Claude Free использует Claude 3.5 Haiku с ограниченным Claude 3.5 Sonnet. Оба платных плана ($20/мес) открывают лучшие модели с более высокими лимитами."}, {"q": "Может ли ChatGPT генерировать изображения?", "a": "Да. Планы ChatGPT Plus и выше включают генерацию изображений DALL-E 3. Claude не генерирует изображения — только текст и код."}]$x$::jsonb
 WHERE slug = 'chatgpt' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "ChatGPT чи Claude — що краще у 2025?", "a": "Залежить від завдання. ChatGPT кращий для багатозадачності, генерації зображень і плагінів. Claude кращий для аналізу тексту, кодування і довгих документів. Більшість просунутих користувачів тримають обидва."}, {"q": "Яка різниця між Claude і ChatGPT для кодування?", "a": "Обидва добре кодують. Claude часто краще розуміє великі кодові бази і дає пояснення. ChatGPT з плагіном Code Interpreter може виконувати код прямо в чаті. Cursor і GitHub Copilot (на базі GPT) популярніші серед розробників."}]$x$::jsonb
 WHERE slug = 'chatgpt' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "ChatGPT או Claude — מה עדיף ב-2025?", "a": "תלוי במשימה. ChatGPT עדיף למולטי-טסקינג, יצירת תמונות ותוספים. Claude עדיף לניתוח טקסט, קוד ומסמכים ארוכים. רוב המשתמשים המתקדמים משתמשים בשניהם."}, {"q": "מה ההבדל בין Claude ל-ChatGPT לקידוד?", "a": "שניהם מצוינים בקוד. Claude לרוב מבין בסיסי קוד גדולים טוב יותר. ChatGPT עם Code Interpreter יכול להריץ קוד ישירות בצ'אט. Cursor ו-GitHub Copilot (מבוסס GPT) פופולריים יותר בקרב מפתחים."}]$x$::jsonb
 WHERE slug = 'chatgpt' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "ChatGPT ou Claude — lequel est le meilleur en 2025 ?", "a": "Cela dépend de la tâche. ChatGPT est meilleur pour le multitâche, la génération d'images et les plugins. Claude est meilleur pour l'analyse de texte, le codage et les longs documents. La plupart des utilisateurs avancés gardent les deux."}, {"q": "Quelle est la différence entre Claude et ChatGPT pour le codage ?", "a": "Les deux codent bien. Claude comprend souvent mieux les grandes bases de code et fournit des explications. ChatGPT avec le plugin Code Interpreter peut exécuter du code directement dans le chat. Cursor et GitHub Copilot (basé sur GPT) sont plus populaires chez les développeurs."}]$x$::jsonb
 WHERE slug = 'chatgpt' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "ChatGPT ou Claude — qual é o melhor em 2025?", "a": "Depende da tarefa. ChatGPT é melhor para multitarefas, geração de imagens e plugins. Claude é melhor para análise de texto, codificação e documentos longos. A maioria dos usuários avançados usa os dois."}, {"q": "Qual é a diferença entre Claude e ChatGPT para programação?", "a": "Ambos programam bem. Claude costuma entender melhor grandes bases de código e fornece explicações. ChatGPT com Code Interpreter pode executar código diretamente no chat. Cursor e GitHub Copilot (baseado em GPT) são mais populares entre desenvolvedores."}]$x$::jsonb
 WHERE slug = 'chatgpt' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Las imágenes de DALL-E 3 son libres de derechos?", "a": "Según los términos de OpenAI, los usuarios de pago tienen derechos sobre las imágenes generadas. Sin embargo, hay debate legal sobre los derechos de autor de imágenes generadas por IA. Para uso comercial con garantías claras — Adobe Firefly (entrenado con contenido con licencia) es la opción más segura legalmente."}, {"q": "¿Qué es ChatGPT Images?", "a": "ChatGPT Images (impulsado por gpt-image-2) es la función de generación de imágenes dentro de ChatGPT. Genera y edita imágenes a partir de prompts de texto con renderizado preciso de texto y subtítulos multilingües."}, {"q": "¿Cuánto cuesta ChatGPT Images?", "a": "Disponible en planes ChatGPT Plus ($20/mes), Pro ($200/mes) y Team. Los usuarios del plan gratuito tienen acceso limitado. El uso de API se factura por tokens a través de gpt-image-2."}, {"q": "¿Qué pasó con DALL-E 3?", "a": "DALL-E 2 y DALL-E 3 fueron retirados en mayo de 2026 y reemplazados por gpt-image-2, que admite resolución de hasta 2K, renderizado de texto multilingüe y seguimiento mejorado de instrucciones."}, {"q": "¿Puede ChatGPT Images editar fotos existentes?", "a": "Sí. ChatGPT Images admite edición de imágenes: sube una imagen y pide a ChatGPT que modifique elementos específicos, cambie fondos, añada objetos o aplique cambios de estilo."}]$x$::jsonb
 WHERE slug = 'chatgpt-images' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "ChatGPT Images vs DALL-E: Ist das dasselbe?", "a": "ChatGPT Images nutzt DALL-E 3 (und neuerdings GPT-4o native Bildgenerierung) als Backend. Der Unterschied ist die Integration: In ChatGPT können Sie Bilder im Kontext des Gesprächs verfeinern und iterieren. DALL-E API direkt ist für Entwickler."}, {"q": "ChatGPT Images für Marketing-Visuals: Ist es gut?", "a": "ChatGPT Images mit GPT-4o ist gut für schnelle Marketing-Konzepte und Ideenfindung. Für finale kommerzielle Produktion empfiehlt sich Adobe Firefly (IP-Sicherheit) oder Midjourney (höchste Qualität). ChatGPT für Entwürfe; spezialisierte Tools für Produktion."}, {"q": "Was ist ChatGPT Images?", "a": "ChatGPT Images (betrieben von gpt-image-2) ist die Bildgenerierungsfunktion in ChatGPT. Es generiert und bearbeitet Bilder aus Textprompts mit präzisem Text-Rendering und mehrsprachigen Bildunterschriften."}, {"q": "Was kostet ChatGPT Images?", "a": "Verfügbar in ChatGPT Plus ($20/Monat), Pro ($200/Monat) und Team-Plänen. Kostenlose Nutzer haben begrenzten Zugang. API-Nutzung wird per Token über gpt-image-2 abgerechnet."}, {"q": "Was ist mit DALL-E 3 passiert?", "a": "DALL-E 2 und DALL-E 3 wurden im Mai 2026 eingestellt und durch gpt-image-2 ersetzt, das Auflösungen bis 2K, mehrsprachiges Text-Rendering und verbesserte Anweisungsfolge unterstützt."}, {"q": "Kann ChatGPT Images bestehende Fotos bearbeiten?", "a": "Ja. ChatGPT Images unterstützt Bildbearbeitung — lade ein Bild hoch und bitte ChatGPT, bestimmte Elemente zu ändern, Hintergründe zu wechseln, Objekte hinzuzufügen oder Stiländerungen vorzunehmen."}]$x$::jsonb
 WHERE slug = 'chatgpt-images' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "ChatGPT Images vs Adobe Firefly — что выбрать?", "a": "ChatGPT Images (powered by DALL-E 3/GPT-5.5) удобен для итеративной генерации в диалоге. Firefly безопаснее для коммерческого использования — обучен на лицензированном контенте. Для коммерческого контента — Firefly, для личного использования — ChatGPT Images."}, {"q": "Что такое ChatGPT Images?", "a": "ChatGPT Images (на базе gpt-image-2) — функция генерации изображений внутри ChatGPT. Создаёт и редактирует изображения по текстовым запросам с точным рендерингом текста и многоязычными подписями."}, {"q": "Что произошло с DALL-E 3?", "a": "DALL-E 2 и DALL-E 3 выведены из эксплуатации в мае 2026 и заменены gpt-image-2, который поддерживает разрешение до 2K, многоязычный рендеринг текста и улучшенное следование инструкциям."}]$x$::jsonb
 WHERE slug = 'chatgpt-images' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "ChatGPT Images vs Adobe Firefly — що обрати?", "a": "ChatGPT Images (DALL-E 3) зручніший для загального використання і входить до Plus. Adobe Firefly кращий для комерційних проєктів завдяки чіткій ліцензії і інтеграції з Creative Cloud. Для повсякденного — ChatGPT; для комерційного — Firefly."}, {"q": "DALL-E 3 можна використовувати комерційно?", "a": "Так. За умовами OpenAI зображення згенеровані через API або ChatGPT можуть використовуватись комерційно. Adobe Firefly також явно комерційно безпечний завдяки навчанню на ліцензованих даних."}, {"q": "Що таке ChatGPT Images?", "a": "ChatGPT Images (на базі gpt-image-2) — функція генерації зображень всередині ChatGPT. Створює та редагує зображення за текстовими запитами з точним рендерингом тексту та багатомовними підписами."}]$x$::jsonb
 WHERE slug = 'chatgpt-images' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "ChatGPT Images לעומת Adobe Firefly?", "a": "DALL-E 3 יצירתי ומבין תיאורים מורכבים. Firefly בטוח מסחרית ומשתלב עם Adobe. יצירה חופשית – DALL-E; עיצוב מקצועי – Firefly."}, {"q": "מה זה ChatGPT Images?", "a": "ChatGPT Images (מופעל על ידי gpt-image-2) הוא תכונת יצירת התמונות בתוך ChatGPT. הוא מייצר ועורך תמונות מפרומפטים טקסטואליים עם רינדור טקסט מדויק וכיתובים רב-לשוניים."}, {"q": "מה קרה ל-DALL-E 3?", "a": "DALL-E 2 ו-DALL-E 3 הופסקו במאי 2026 והוחלפו ב-gpt-image-2, התומך ברזולוציה של עד 2K, רינדור טקסט רב-לשוני ועמידה משופרת בהוראות."}]$x$::jsonb
 WHERE slug = 'chatgpt-images' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "ChatGPT Images est-il inclus dans ChatGPT gratuit ?", "a": "La génération d'images dans ChatGPT est disponible dans le plan gratuit avec des limites. ChatGPT Plus (20 $/mois) offre plus de générations et une priorité d'accès. Adobe Firefly est inclus dans Creative Cloud."}, {"q": "DALL-E 3 est-il sûr pour un usage commercial ?", "a": "DALL-E 3 via ChatGPT permet l'usage commercial du contenu généré selon les conditions d'OpenAI. Adobe Firefly offre des garanties d'indemnisation commerciale plus explicites car il est spécifiquement entraîné sur du contenu sous licence."}, {"q": "Qu'est-ce que ChatGPT Images ?", "a": "ChatGPT Images (propulsé par gpt-image-2) est la fonction de génération d'images dans ChatGPT. Il génère et modifie des images à partir de prompts textuels avec un rendu de texte précis et des légendes multilingues."}, {"q": "Combien coûte ChatGPT Images ?", "a": "Disponible dans les plans ChatGPT Plus ($20/mois), Pro ($200/mois) et Team. Les utilisateurs du plan gratuit ont un accès limité. L'utilisation API est facturée par token via gpt-image-2."}, {"q": "Que s'est-il passé avec DALL-E 3 ?", "a": "DALL-E 2 et DALL-E 3 ont été retirés en mai 2026 et remplacés par gpt-image-2, qui supporte une résolution jusqu'à 2K, le rendu de texte multilingue et un meilleur suivi des instructions."}, {"q": "ChatGPT Images peut-il modifier des photos existantes ?", "a": "Oui. ChatGPT Images prend en charge l'édition d'images : téléchargez une image et demandez à ChatGPT de modifier des éléments spécifiques, changer les arrière-plans, ajouter des objets ou appliquer des changements de style."}]$x$::jsonb
 WHERE slug = 'chatgpt-images' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "ChatGPT Images está incluído no plano gratuito?", "a": "A geração de imagens no ChatGPT está disponível no plano gratuito com limites. ChatGPT Plus ($20/mês) oferece mais gerações e prioridade de acesso. Adobe Firefly está incluído no Creative Cloud."}, {"q": "DALL-E 3 é seguro para uso comercial?", "a": "DALL-E 3 via ChatGPT permite uso comercial do conteúdo gerado conforme os termos da OpenAI. Adobe Firefly oferece garantias de indenização comercial mais explícitas pois é especificamente treinado em conteúdo licenciado."}, {"q": "O que é o ChatGPT Images?", "a": "O ChatGPT Images (alimentado pelo gpt-image-2) é o recurso de geração de imagens dentro do ChatGPT. Gera e edita imagens a partir de prompts de texto com renderização precisa de texto e legendas multilíngues."}, {"q": "Quanto custa o ChatGPT Images?", "a": "Disponível nos planos ChatGPT Plus ($20/mês), Pro ($200/mês) e Team. Usuários do plano gratuito têm acesso limitado. O uso da API é cobrado por token via gpt-image-2."}, {"q": "O que aconteceu com o DALL-E 3?", "a": "O DALL-E 2 e o DALL-E 3 foram descontinuados em maio de 2026 e substituídos pelo gpt-image-2, que suporta resolução de até 2K, renderização de texto multilíngue e melhor seguimento de instruções."}, {"q": "O ChatGPT Images pode editar fotos existentes?", "a": "Sim. O ChatGPT Images suporta edição de imagens — carregue uma imagem e peça ao ChatGPT para modificar elementos específicos, trocar fundos, adicionar objetos ou aplicar mudanças de estilo."}]$x$::jsonb
 WHERE slug = 'chatgpt-images' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Claude лучше ChatGPT?", "a": "Зависит от задачи. Claude в целом лучше справляется с длинными текстами и точнее обрабатывает большие документы. У ChatGPT больше функций (генерация изображений, голос, плагины) и более крупная экосистема. По бенчмаркам кода они конкурируют — Claude 3.7 лидирует во многих."}, {"q": "Что бесплатно — ChatGPT или Claude?", "a": "Оба имеют бесплатные планы. ChatGPT Free использует GPT-4o mini с ограниченным доступом к GPT-4o. Claude Free использует Claude 3.5 Haiku с ограниченным Claude 3.5 Sonnet. Оба платных плана ($20/мес) открывают лучшие модели с более высокими лимитами."}]$x$::jsonb
 WHERE slug = 'claude' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "ChatGPT чи Claude — що краще у 2025?", "a": "Залежить від завдання. ChatGPT кращий для багатозадачності, генерації зображень і плагінів. Claude кращий для аналізу тексту, кодування і довгих документів. Більшість просунутих користувачів тримають обидва."}, {"q": "Чи безкоштовний Claude?", "a": "Так, Claude має безкоштовний план. Claude Pro коштує $20/міс, Claude Max — $100 або $200/міс з розширеними лімітами. ChatGPT також безкоштовний; Plus $20/міс, Pro $200/міс."}, {"q": "Яка різниця між Claude і ChatGPT для кодування?", "a": "Обидва добре кодують. Claude часто краще розуміє великі кодові бази і дає пояснення. ChatGPT з плагіном Code Interpreter може виконувати код прямо в чаті. Cursor і GitHub Copilot (на базі GPT) популярніші серед розробників."}]$x$::jsonb
 WHERE slug = 'claude' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "ChatGPT או Claude — מה עדיף ב-2025?", "a": "תלוי במשימה. ChatGPT עדיף למולטי-טסקינג, יצירת תמונות ותוספים. Claude עדיף לניתוח טקסט, קוד ומסמכים ארוכים. רוב המשתמשים המתקדמים משתמשים בשניהם."}, {"q": "האם Claude בחינם?", "a": "כן, ל-Claude יש תוכנית חינמית. Claude Pro עולה 20$/חודש, Claude Max — 100$ או 200$/חודש. ChatGPT גם חינמי; Plus 20$/חודש, Pro 200$/חודש."}, {"q": "מה ההבדל בין Claude ל-ChatGPT לקידוד?", "a": "שניהם מצוינים בקוד. Claude לרוב מבין בסיסי קוד גדולים טוב יותר. ChatGPT עם Code Interpreter יכול להריץ קוד ישירות בצ'אט. Cursor ו-GitHub Copilot (מבוסס GPT) פופולריים יותר בקרב מפתחים."}]$x$::jsonb
 WHERE slug = 'claude' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "ChatGPT ou Claude — lequel est le meilleur en 2025 ?", "a": "Cela dépend de la tâche. ChatGPT est meilleur pour le multitâche, la génération d'images et les plugins. Claude est meilleur pour l'analyse de texte, le codage et les longs documents. La plupart des utilisateurs avancés gardent les deux."}, {"q": "Claude est-il gratuit ?", "a": "Oui, Claude dispose d'un plan gratuit. Claude Pro coûte 20 $/mois, Claude Max — 100 $ ou 200 $/mois avec des limites étendues. ChatGPT est aussi gratuit ; Plus 20 $/mois, Pro 200 $/mois."}, {"q": "Quelle est la différence entre Claude et ChatGPT pour le codage ?", "a": "Les deux codent bien. Claude comprend souvent mieux les grandes bases de code et fournit des explications. ChatGPT avec le plugin Code Interpreter peut exécuter du code directement dans le chat. Cursor et GitHub Copilot (basé sur GPT) sont plus populaires chez les développeurs."}, {"q": "Claude peut-il générer des images ?", "a": "Claude ne génère pas d'images nativement, mais peut les analyser. ChatGPT avec DALL-E 3 génère des images directement. Pour la génération d'images, utilisez Midjourney, DALL-E ou Stable Diffusion."}]$x$::jsonb
 WHERE slug = 'claude' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "ChatGPT ou Claude — qual é o melhor em 2025?", "a": "Depende da tarefa. ChatGPT é melhor para multitarefas, geração de imagens e plugins. Claude é melhor para análise de texto, codificação e documentos longos. A maioria dos usuários avançados usa os dois."}, {"q": "Claude é gratuito?", "a": "Sim, Claude tem plano gratuito. Claude Pro custa $20/mês, Claude Max — $100 ou $200/mês com limites estendidos. ChatGPT também é gratuito; Plus $20/mês, Pro $200/mês."}, {"q": "Qual é a diferença entre Claude e ChatGPT para programação?", "a": "Ambos programam bem. Claude costuma entender melhor grandes bases de código e fornece explicações. ChatGPT com Code Interpreter pode executar código diretamente no chat. Cursor e GitHub Copilot (baseado em GPT) são mais populares entre desenvolvedores."}, {"q": "Claude consegue gerar imagens?", "a": "Claude não gera imagens nativamente, mas consegue analisá-las. ChatGPT com DALL-E 3 gera imagens diretamente. Para geração de imagens, use Midjourney, DALL-E ou Stable Diffusion."}]$x$::jsonb
 WHERE slug = 'claude' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Claude Code es gratuito?", "a": "Claude Code requiere una suscripción de Claude (Pro $20/mes o Max $100-$200/mes). El uso intensivo de Claude Code consume créditos de API rápidamente. OpenCode es gratuito como herramienta, pero el costo depende del modelo API que uses."}, {"q": "¿OpenCode es tan bueno como Claude Code?", "a": "Claude Code tiene ventaja en calidad de razonamiento al estar optimizado específicamente para Claude 3.7/3.5. OpenCode es más flexible al soportar múltiples modelos. Para la mejor calidad absoluta — Claude Code con Claude Sonnet; para flexibilidad y open-source — OpenCode."}, {"q": "¿Claude Code puede trabajar con cualquier lenguaje de programación?", "a": "Sí. Claude Code entiende prácticamente cualquier lenguaje de programación moderno: Python, JavaScript/TypeScript, Go, Rust, Java, C++, Ruby, etc. Su ventaja es el razonamiento sobre el codebase completo, no solo snippets individuales."}, {"q": "¿Qué es Claude Code?", "a": "Claude Code es la herramienta CLI oficial de Anthropic para ingeniería de software. Funciona en la terminal, lee tu base de código, escribe código, ejecuta comandos, corrige errores y completa tareas de múltiples archivos como agente autónomo."}, {"q": "¿Cuánto cuesta Claude Code?", "a": "Incluido en Claude Pro ($20/mes), Max ($100/mes), Team y Enterprise. El uso se mide por tokens de API consumidos durante las tareas agénticas."}, {"q": "¿En qué se diferencia Claude Code de Cursor?", "a": "Claude Code funciona en la terminal — sin GUI. Está diseñado para desarrolladores que prefieren flujos de trabajo CLI. Cursor es un IDE completo con interfaz visual basado en VS Code."}, {"q": "¿Qué puede hacer Claude Code de forma autónoma?", "a": "Leer y editar archivos, ejecutar comandos de shell, ejecutar pruebas, buscar en la base de código, gestionar git y completar tareas de ingeniería de múltiples pasos con mínimos prompts."}]$x$::jsonb
 WHERE slug = 'claude-code' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "OpenCode vs Claude Code: Welches ist besser?", "a": "Claude Code ist leistungsfähiger für komplexe Aufgaben da es von Anthropic optimiert wurde und den besten Claude-Modell-Zugang hat. OpenCode ist flexibler und kostenlos — ideal wenn Sie verschiedene Modelle testen oder Kosten sparen wollen."}, {"q": "Ist Claude Code kostenlos?", "a": "Claude Code selbst ist kostenlos als CLI-Tool. Sie zahlen für Claude API-Nutzung basierend auf verarbeiteten Tokens. Für intensive Nutzung empfiehlt sich ein Claude Max-Plan ($100/Monat) der API-Nutzung inklusive hat."}, {"q": "Was ist Claude Code?", "a": "Claude Code ist Anthropics offizielles CLI-Tool für Software-Engineering. Es läuft im Terminal, liest die Codebasis, schreibt Code, führt Befehle aus, behebt Bugs und schließt Multi-Datei-Aufgaben als autonomer Agent ab."}, {"q": "Was kostet Claude Code?", "a": "Enthalten in Claude Pro ($20/Monat), Max ($100/Monat), Team und Enterprise. Die Nutzung wird nach API-Tokens gemessen, die während agentischer Aufgaben verbraucht werden."}, {"q": "Wie unterscheidet sich Claude Code von Cursor?", "a": "Claude Code läuft im Terminal — ohne GUI. Es ist für Entwickler gedacht, die CLI-Workflows bevorzugen. Cursor ist eine vollständige IDE mit visueller Oberfläche auf VS Code-Basis."}, {"q": "Was kann Claude Code autonom tun?", "a": "Dateien lesen und bearbeiten, Shell-Befehle ausführen, Tests ausführen, die Codebasis durchsuchen, git verwalten und mehrstufige Engineering-Aufgaben mit minimalem Prompting abschließen."}]$x$::jsonb
 WHERE slug = 'claude-code' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Claude Code?", "a": "Claude Code — агентный CLI-инструмент Anthropic для разработки ПО. В отличие от Copilot, который предлагает отдельные строки, Claude Code может планировать и выполнять многошаговые задачи по всей кодовой базе — редактировать файлы, запускать тесты и коммитить изменения автономно."}, {"q": "Claude Code лучше GitHub Copilot?", "a": "Для сложных многофайловых задач и автономных рабочих процессов Claude Code мощнее. Для встроенных подсказок в реальном времени Copilot удобнее. Многие разработчики используют оба: Copilot для ежедневного кодирования, Claude Code для крупных задач."}, {"q": "Чем Claude Code отличается от Cursor?", "a": "Claude Code работает в терминале — без GUI. Для разработчиков, предпочитающих CLI. Cursor — полноценная IDE с визуальным интерфейсом на базе VS Code."}]$x$::jsonb
 WHERE slug = 'claude-code' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "OpenCode vs Claude Code — що краще?", "a": "Claude Code потужніший для складних завдань бо оптимізований Anthropic і має найкращий доступ до Claude-моделей. OpenCode гнучкіший і безкоштовний — ідеально якщо хочете тестувати різні моделі або заощаджувати."}, {"q": "Claude Code безкоштовний?", "a": "Claude Code CLI безкоштовний. Ви платите за використання Claude API за токенами. Для інтенсивного використання Claude Max ($100/міс) включає більші API-ліміти. OpenCode — безкоштовний, платите лише за API вибраної моделі."}, {"q": "Чим Claude Code відрізняється від Cursor?", "a": "Claude Code працює в терміналі — без GUI. Для розробників, які надають перевагу CLI. Cursor — повноцінна IDE з візуальним інтерфейсом на базі VS Code."}]$x$::jsonb
 WHERE slug = 'claude-code' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "OpenCode לעומת Claude Code – מה עדיף?", "a": "Claude Code חזק יותר עם מיטוב ל-Anthropic. OpenCode גמיש יותר וחינמי. Anthropic Max ל-Claude Code; גמישות – OpenCode."}, {"q": "Claude Code חינמי?", "a": "Claude Code CLI חינמי. משלמים עבור API לפי tokens. שימוש אינטנסיבי – Claude Max ($100/חודש) כולל API usage."}, {"q": "במה Claude Code שונה מ-Cursor?", "a": "Claude Code פועל בטרמינל — ללא ממשק גרפי. הוא מיועד למפתחים המעדיפים זרימות עבודה של CLI. Cursor הוא IDE מלא עם ממשק ויזואלי מבוסס VS Code."}]$x$::jsonb
 WHERE slug = 'claude-code' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "OpenCode vs Claude Code — lequel est le meilleur ?", "a": "Claude Code est plus puissant pour les tâches complexes car optimisé par Anthropic avec le meilleur accès aux modèles Claude. OpenCode est plus flexible et gratuit — idéal pour tester différents modèles ou réduire les coûts."}, {"q": "Claude Code est-il gratuit ?", "a": "Claude Code CLI est gratuit comme outil. Vous payez pour l'utilisation de l'API Claude basée sur les tokens traités. Pour une utilisation intensive, un plan Claude Max (100 $/mois) inclut une utilisation API plus importante."}, {"q": "Qu'est-ce que Claude Code ?", "a": "Claude Code est l'outil CLI officiel d'Anthropic pour le développement logiciel. Il fonctionne dans le terminal, lit votre base de code, écrit du code, exécute des commandes, corrige des bugs et complète des tâches multi-fichiers comme agent autonome."}, {"q": "Combien coûte Claude Code ?", "a": "Inclus dans Claude Pro ($20/mois), Max ($100/mois), Team et Enterprise. L'utilisation est mesurée par les tokens API consommés lors des tâches agentiques."}, {"q": "En quoi Claude Code diffère-t-il de Cursor ?", "a": "Claude Code fonctionne dans le terminal — sans interface graphique. Il est conçu pour les développeurs qui préfèrent les workflows CLI. Cursor est un IDE complet avec interface visuelle basé sur VS Code."}, {"q": "Que peut faire Claude Code de manière autonome ?", "a": "Lire et modifier des fichiers, exécuter des commandes shell, lancer des tests, rechercher dans la base de code, gérer git et accomplir des tâches d'ingénierie en plusieurs étapes avec un minimum de prompts."}]$x$::jsonb
 WHERE slug = 'claude-code' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "OpenCode vs Claude Code — qual é o melhor?", "a": "Claude Code é mais poderoso para tarefas complexas pois é otimizado pela Anthropic com melhor acesso aos modelos Claude. OpenCode é mais flexível e gratuito — ideal para testar diferentes modelos ou reduzir custos."}, {"q": "Claude Code é gratuito?", "a": "Claude Code CLI é gratuito como ferramenta. Você paga pelo uso da API Claude baseado nos tokens processados. Para uso intensivo, um plano Claude Max ($100/mês) inclui maior uso de API."}, {"q": "O que é o Claude Code?", "a": "O Claude Code é a ferramenta CLI oficial da Anthropic para engenharia de software. Funciona no terminal, lê sua base de código, escreve código, executa comandos, corrige bugs e completa tarefas de múltiplos arquivos como agente autônomo."}, {"q": "Quanto custa o Claude Code?", "a": "Incluído no Claude Pro ($20/mês), Max ($100/mês), Team e Enterprise. O uso é medido pelos tokens de API consumidos durante tarefas agênticas."}, {"q": "Como o Claude Code se diferencia do Cursor?", "a": "O Claude Code funciona no terminal — sem interface gráfica. É projetado para desenvolvedores que preferem workflows CLI. O Cursor é um IDE completo com interface visual baseado no VS Code."}, {"q": "O que o Claude Code pode fazer de forma autônoma?", "a": "Ler e editar arquivos, executar comandos shell, rodar testes, pesquisar na base de código, gerenciar git e completar tarefas de engenharia em múltiplas etapas com prompts mínimos."}]$x$::jsonb
 WHERE slug = 'claude-code' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Что такое Claude Design?", "a": "Claude Design — функция генерации UI-дизайнов в Claude, позволяющая описать интерфейс текстом и получить визуальный результат. Это более экспериментальная функция для быстрого прототипирования, не замена профессиональному дизайн-инструменту."}, {"q": "Claude Design заменяет Figma?", "a": "Нет. Claude Design — для быстрой генерации концепций. Figma — для производственного дизайна с компонентами, токенами и handoff. Figma AI улучшает существующий дизайн-рабочий процесс, Claude Design — для итеративного исследования идей."}, {"q": "Можно ли экспортировать в Figma или в код?", "a": "Claude Design генерирует HTML/CSS код дизайнов. Прямой экспорт в Figma недоступен по состоянию на май 2026, но сгенерированный код можно использовать в любом рабочем процессе."}]$x$::jsonb
 WHERE slug = 'claude-design' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Що таке Claude Design?", "a": "Claude Design — AI-інструмент дизайну Anthropic, вбудований у Claude. Генерує UI-макети, презентації, лендінги та візуальні прототипи через діалог — без дизайнерського ПЗ."}, {"q": "Чи можна експортувати у Figma або в код?", "a": "Claude Design генерує HTML/CSS код дизайнів. Прямий експорт у Figma недоступний станом на травень 2026, але згенерований код можна використовувати в будь-якому робочому процесі."}]$x$::jsonb
 WHERE slug = 'claude-design' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Figma Make – מה זה?", "a": "Figma Make הופך עיצובי Figma לקוד React/HTML פונקציונלי. עדיין בשלבי Beta, אך מציע bridge בין עיצוב לפיתוח."}, {"q": "מה זה Claude Design?", "a": "Claude Design הוא כלי עיצוב AI של Anthropic המשולב ב-Claude. הוא מייצר מוקאפים של ממשק משתמש, מצגות, דפי נחיתה ואבות טיפוס ויזואליים דרך שיחה — ללא תוכנת עיצוב."}, {"q": "האם ניתן לייצא ל-Figma או לקוד?", "a": "Claude Design יכול לייצר קוד HTML/CSS לעיצובים. ייצוא ישיר ל-Figma אינו זמין נכון למאי 2026, אך הקוד שנוצר יכול לשמש בכל זרימת עבודה."}]$x$::jsonb
 WHERE slug = 'claude-design' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Clearscope o SurferSEO para SEO de contenido?", "a": "Clearscope es preferido por equipos con escritores no técnicos — su interfaz es más simple y las sugerencias menos abrumadoras. SurferSEO ofrece más funciones y análisis más profundo del SERP. Agencias y equipos técnicos suelen preferir Surfer; equipos de contenido más grandes con muchos escritores prefieren Clearscope."}, {"q": "¿Cuánto cuesta Clearscope?", "a": "Clearscope empieza en $199/mes (Essentials). SurferSEO desde $99/mes. Clearscope es significativamente más caro, pero muchos equipos valoran su simplicidad y calidad de datos para equipos más grandes."}, {"q": "¿Clearscope mejora el ranking?", "a": "Clearscope ayuda a crear contenido más completo y relevante semánticamente, lo que generalmente mejora el ranking. Sin embargo, el SEO depende de muchos factores: backlinks, autoridad de dominio, velocidad del sitio. Clearscope optimiza el factor contenido, no el SEO técnico."}, {"q": "¿Qué es mejor para principiantes, Clearscope o SurferSEO?", "a": "Para equipos con escritores sin experiencia en SEO técnico — Clearscope es más accesible. Para marketers SEO que quieren más datos — SurferSEO. Ambas tienen curvas de aprendizaje razonables."}]$x$::jsonb
 WHERE slug = 'clearscope' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Clearscope vs Surfer SEO: Was ist der Unterschied?", "a": "Beide optimieren Content für Suchmaschinen, aber mit unterschiedlichem Fokus. Clearscope ist einfacher und stärker in Google Docs integriert. Surfer bietet mehr Daten: SERP-Analyse, NLP-Terme und einen KI-Schreibassistenten. Clearscope für Teams die Einfachheit priorisieren; Surfer für Data-driven SEO-Teams."}, {"q": "Wie viel kostet Clearscope?", "a": "Clearscope beginnt ab $189/Monat — teurer als Surfer SEO Essential ($89/Monat). Clearscope positioniert sich als Enterprise-Lösung für größere Teams. Beide haben Demo-Anfragen verfügbar."}, {"q": "Funktioniert Clearscope mit Google Docs?", "a": "Ja. Clearscope hat eine native Google Docs-Integration über ein Add-on. Sie sehen die Keyword-Empfehlungen direkt in Google Docs während Sie schreiben. Das ist einer der Hauptvorteile gegenüber Surfer."}, {"q": "Ist Clearscope für kleine Unternehmen?", "a": "Clearscope ist primär für mittlere bis große Unternehmen und Agenturen konzipiert. Der Startpreis von $189/Monat macht es für Einzelpersonen oder kleine Teams weniger attraktiv. Surfer SEO oder Frase sind für kleinere Budgets besser geeignet."}]$x$::jsonb
 WHERE slug = 'clearscope' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между Clearscope и SurferSEO?", "a": "Оба — ИИ-инструменты оптимизации контента, но с разными сильными сторонами. Clearscope превосходит в оценке контента и анализе глубины темы. SurferSEO предлагает более полную платформу с редактором в реальном времени, исследованием ключевых слов и ИИ-написанием."}, {"q": "Есть ли у Clearscope ИИ-написание?", "a": "Clearscope фокусируется на анализе и оптимизации контента, а не на ИИ-написании. Он оценивает ваш контент и предлагает термины для включения. Для генерации контента лучше подходят SurferSEO (с Surfer AI) или Jasper."}]$x$::jsonb
 WHERE slug = 'clearscope' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Clearscope vs Surfer SEO — що краще?", "a": "Clearscope простіший і має кращу підтримку для великих команд. Surfer SEO ширший за можливостями і дешевший. Для корпоративних команд — Clearscope; для агенцій і самостійних SEO — Surfer."}, {"q": "Скільки коштує Clearscope?", "a": "Clearscope від $189/міс (Essentials). Набагато дорожче ніж Surfer SEO ($99/міс). Але Clearscope орієнтований на корпоративний сегмент з відповідним рівнем підтримки."}]$x$::jsonb
 WHERE slug = 'clearscope' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Clearscope מול Surfer SEO — מה עדיף?", "a": "שניהם כלי אופטימיזציית תוכן מעולים. Clearscope ידוע בדיוק ובפשטות ממשק. Surfer SEO מציע יותר תכונות כולל יצירת AI ואינטגרציות. לצוותים שמחפשים פשטות — Clearscope; לכלי הכל-באחד — Surfer SEO."}, {"q": "כמה עולה Clearscope?", "a": "Clearscope מ-189$/חודש — יקר יותר מ-Surfer SEO. Surfer SEO מ-89$/חודש. Clearscope ממוקד לסוכנויות ועסקים גדולים עם תקציב."}, {"q": "Clearscope עם WordPress — האם עובד?", "a": "כן. Clearscope מציע תוסף WordPress המאפשר ניתוח תוכן ישירות בעורך WordPress. זה אחד היתרונות שלו לבלוגרים ולמנהלי תוכן."}]$x$::jsonb
 WHERE slug = 'clearscope' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Clearscope vs Surfer SEO — lequel est le meilleur ?", "a": "Clearscope est plus simple et avec de meilleurs rapports pour les rédacteurs. Surfer a plus de fonctionnalités à un prix inférieur. Pour des équipes éditoriales avec rédacteurs non techniques, Clearscope ; pour des équipes SEO techniques avec besoin de plus d'outils, Surfer."}, {"q": "Clearscope est-il cher ?", "a": "Clearscope commence à 189 $/mois (Essentials). Surfer SEO à partir de 99 $/mois. Clearscope est nettement plus cher mais apprécié par les grandes équipes de contenu."}, {"q": "Clearscope est-il adapté au contenu en français ?", "a": "Oui. Clearscope prend en charge plusieurs langues dont le français. Les recommandations sont basées sur l'analyse des pages en tête de classement pour votre requête cible en France."}, {"q": "Peut-on utiliser Clearscope sans SEMrush ou Ahrefs ?", "a": "Oui. Clearscope se concentre sur l'optimisation du contenu. Pour la recherche de mots-clés initiale, vous pouvez utiliser Google Search Console gratuitement ou des outils moins chers comme Ubersuggest. Clearscope optimise le contenu ; d'autres outils trouvent les mots-clés."}]$x$::jsonb
 WHERE slug = 'clearscope' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Clearscope vs SurferSEO — qual é o melhor?", "a": "Clearscope tem interface mais limpa e foca exclusivamente na otimização de conteúdo. SurferSEO oferece mais recursos incluindo auditoria de site e integração com editores. Para simplicidade, Clearscope; para mais funcionalidades, SurferSEO."}, {"q": "Clearscope é gratuito?", "a": "Clearscope não tem plano gratuito. Planos a partir de $170/mês. SurferSEO a partir de $89/mês. Ambos são caros em comparação com alternativas como Frase."}, {"q": "Clearscope realmente melhora o ranqueamento?", "a": "Sim, muitos usuários reportam melhorias significativas no ranqueamento ao usar Clearscope. A ferramenta ajuda a cobrir os termos semânticos que o Google espera ver em conteúdo de alta qualidade."}, {"q": "Clearscope vs MarketMuse — qual é a diferença?", "a": "Ambos são ferramentas premium de otimização de conteúdo. MarketMuse tem recursos mais avançados de planejamento estratégico de conteúdo. Clearscope é mais focado e geralmente mais fácil de usar. Preços similares, ambos na faixa premium."}]$x$::jsonb
 WHERE slug = 'clearscope' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Cline?", "a": "Cline es una extensión open-source de VS Code que añade un agente de IA capaz de leer y escribir archivos, ejecutar comandos de terminal, navegar la web y completar tareas complejas de múltiples pasos. A diferencia de Copilot, Cline puede actuar de forma autónoma."}, {"q": "¿Cline es gratuito?", "a": "Cline como extensión es gratuito y open-source. Pagas por los tokens de la API del modelo que elijas (Claude, GPT-4, etc.). GitHub Copilot cuesta $10/mes. Con modelos económicos como DeepSeek, Cline puede ser muy barato."}, {"q": "¿Cline puede reemplazar a Cursor?", "a": "Cline en VS Code ofrece funcionalidad agéntica similar a Cursor. La principal diferencia: Cline te deja en tu editor VS Code existente, mientras que Cursor es un fork de VS Code con IA profundamente integrada."}, {"q": "¿Qué modelos de IA soporta Cline?", "a": "Cline soporta todos los modelos principales: Claude, GPT-4o, Gemini, DeepSeek y modelos locales vía Ollama. Esta flexibilidad es una de sus principales ventajas sobre Copilot."}]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Ist Cline kostenlos?", "a": "Cline selbst ist als VS Code-Erweiterung kostenlos und Open-Source. Die Kosten hängen vom verwendeten Modell ab: bei Ollama mit lokalen Modellen (Llama, Mistral) — vollständig kostenlos. Bei Verwendung der Anthropic oder OpenAI API zahlen Sie für die API-Nutzung. GitHub Copilot kostet $10/Monat."}, {"q": "Kann Cline Claude verwenden?", "a": "Ja. Cline integriert sich mit der Anthropic API, OpenAI, Mistral, Google Gemini und lokalen Modellen über Ollama. Sie können Claude als Modell für Chat und autonome Aufgaben konfigurieren."}, {"q": "Cline vs Aider: Was ist der Unterschied?", "a": "Cline ist eine VS Code-Erweiterung mit grafischer Oberfläche für Entwickler die im Editor bleiben möchten. Aider ist ein Terminal-Tool für Entwickler die die Befehlszeile bevorzugen. Beide sind Open-Source und unterstützen mehrere Modelle. Die Wahl hängt von Ihrem bevorzugten Workflow ab."}, {"q": "Ist es sicher, Cline mit proprietärem Code zu verwenden?", "a": "Wenn Sie lokale Modelle über Ollama verwenden — vollständige Privatsphäre, kein Code verlässt Ihre Maschine. Bei Cloud-API (Anthropic, OpenAI) gelten die Datenschutzrichtlinien des jeweiligen Anbieters. Für sehr sensiblen Code empfehlen sich lokale Modelle oder geprüfte Enterprise-Vereinbarungen."}]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Cline?", "a": "Cline — open-source ИИ-агент для кодирования, работающий внутри VS Code. В отличие от Copilot, который предлагает отдельные строки, Cline может планировать и выполнять сложные многошаговые задачи — создавать файлы, выполнять команды и вносить изменения по всей кодовой базе автономно."}, {"q": "Cline против Cursor — в чём разница?", "a": "Оба — ИИ-инструменты для кодирования, но Cline — расширение VS Code (вы сохраняете свой редактор), а Cursor — полный форк VS Code с более глубокой интеграцией ИИ. Cline использует ваш собственный API-ключ, Cursor включает доступ к модели в подписке. У Cursor более полированный опыт, у Cline — больше гибкости."}]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Cline vs GitHub Copilot — що краще?", "a": "Cline безкоштовний і відкритий з більшою гнучкістю моделей і агентними можливостями. Copilot зручніший і більш зрілий. Для Open-Source гнучкості — Cline; для стабільного щоденного помічника — Copilot."}, {"q": "Cline безкоштовний?", "a": "Cline розширення безкоштовне. Ви платите за API моделі: Claude API, OpenAI API або локальні моделі через Ollama безкоштовно. GitHub Copilot — від $10/міс."}, {"q": "Cline vs Cursor — що обрати?", "a": "Cline — розширення VS Code; ви залишаєтесь у VS Code. Cursor — окремий редактор. Cline безкоштовніший; Cursor має більш глибоку агентну інтеграцію. Для залишатись у VS Code — Cline; для повного ШІ-редактора — Cursor."}]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Cline מול GitHub Copilot — מה עדיף?", "a": "Cline חינמי ופתוח עם גמישות מודל גדולה יותר ויכולות סוכנתיות. Copilot נוח ובוגר יותר. לגמישות Open-Source — Cline; לעוזר יומיומי יציב — Copilot."}, {"q": "האם Cline בחינם?", "a": "תוסף Cline חינמי. אתם משלמים עבור API: Claude API, OpenAI API או חינמית דרך מודלים מקומיים ב-Ollama. GitHub Copilot — מ-10$/חודש."}, {"q": "Cline מול Cursor — מה לבחור?", "a": "Cline הוא תוסף VS Code; אתם נשארים ב-VS Code. Cursor הוא עורך נפרד. Cline חינמי יותר; ל-Cursor יש אינטגרציה סוכנתית עמוקה יותר. להישאר ב-VS Code — Cline; לעורך AI מלא — Cursor."}]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Cline vs GitHub Copilot — lequel est le meilleur ?", "a": "Cline est gratuit et open-source avec plus de flexibilité de modèles et de capacités agentiques. Copilot est plus pratique et plus mature. Pour la flexibilité open-source, Cline ; pour un assistant quotidien stable, Copilot."}, {"q": "Cline est-il gratuit ?", "a": "L'extension Cline est gratuite. Vous payez pour l'API du modèle : API Claude, API OpenAI ou localement via Ollama gratuitement. GitHub Copilot — à partir de 10 $/mois."}, {"q": "Qu'est-ce que Cline ?", "a": "Cline (anciennement Claude Dev) est un agent IA open-source pour VS Code. Il peut lire et écrire des fichiers de manière autonome, exécuter des commandes terminal et apporter des modifications à la base de code. Supporte Claude, GPT-4 et d'autres modèles."}, {"q": "Cline vs Cursor — lequel choisir ?", "a": "Cline est une extension VS Code ; vous restez dans VS Code. Cursor est un éditeur séparé. Cline est moins cher ; Cursor a une intégration agentique plus profonde. Pour rester dans VS Code, Cline ; pour un éditeur IA complet, Cursor."}]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Cline vs GitHub Copilot — qual é o melhor?", "a": "Cline é gratuito e open-source com mais flexibilidade de modelos e capacidades agênticas. Copilot é mais conveniente e maduro. Para flexibilidade open-source, Cline; para um assistente diário estável, Copilot."}, {"q": "Cline é gratuito?", "a": "A extensão Cline é gratuita. Você paga pela API do modelo: API Claude, API OpenAI ou localmente via Ollama gratuitamente. GitHub Copilot — a partir de $10/mês."}, {"q": "O que é Cline?", "a": "Cline (anteriormente Claude Dev) é um agente de IA open-source para VS Code. Ele pode ler e escrever arquivos autonomamente, executar comandos de terminal e fazer alterações na base de código. Suporta Claude, GPT-4 e outros modelos."}, {"q": "Cline vs Cursor — qual escolher?", "a": "Cline é uma extensão do VS Code; você permanece no VS Code. Cursor é um editor separado. Cline é mais barato; Cursor tem integração agêntica mais profunda. Para ficar no VS Code, Cline; para um editor de IA completo, Cursor."}]$x$::jsonb
 WHERE slug = 'cline' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿ComfyUI o AUTOMATIC1111 para principiantes?", "a": "AUTOMATIC1111 es mucho más accesible para principiantes — interfaz web familiar con pestañas y sliders. ComfyUI tiene una curva de aprendizaje más pronunciada con su sistema de nodos. Para empezar con Stable Diffusion — AUTOMATIC1111 (o Forge, su fork mejorado); para flujos avanzados — ComfyUI."}, {"q": "¿ComfyUI es gratuito?", "a": "Sí. ComfyUI es completamente open-source y gratuito. AUTOMATIC1111 también es gratuito y open-source. Ambos requieren hardware propio (GPU Nvidia recomendada) o pueden usarse en servicios cloud como Google Colab o RunPod a precios por hora."}, {"q": "¿Qué es Forge (SD Web UI Forge)?", "a": "Forge es un fork de AUTOMATIC1111 optimizado para mayor velocidad y menor uso de VRAM. Mantiene la misma interfaz familiar pero con mejor rendimiento. Para usuarios de AUTOMATIC1111 que quieren mejor velocidad sin aprender ComfyUI — Forge es la mejor opción intermedia."}, {"q": "¿ComfyUI puede usar modelos FLUX?", "a": "Sí. ComfyUI fue la primera interfaz en soportar FLUX.1 y sigue siendo la más flexible para flujos de trabajo con FLUX. AUTOMATIC1111/Forge también soporta FLUX. Para flujos FLUX avanzados con nodos — ComfyUI es la opción preferida de la comunidad."}]$x$::jsonb
 WHERE slug = 'comfyui' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "ComfyUI vs Automatic1111: Was soll ich wählen?", "a": "Für Einsteiger — Automatic1111: einfachere Oberfläche, mehr Tutorials, leichter zu verstehen. Für Fortgeschrittene — ComfyUI: mächtiger, schneller, flexibler für komplexe Workflows. Viele Power-User beginnen mit A1111 und wechseln zu ComfyUI."}, {"q": "Ist ComfyUI kostenlos?", "a": "Ja. Beide sind Open-Source und kostenlos. Sie benötigen eigene Hardware (GPU mit mindestens 6-8 GB VRAM empfohlen) oder Cloud-Dienste. Die einzigen Kosten sind Strom und ggf. Cloud-Computing."}, {"q": "Was ist ein Node-Graph in ComfyUI?", "a": "ComfyUI verwendet ein visuelles Node-basiertes System: Jeder Schritt der Bildgenerierung (Modell laden, Text encodieren, Sampling, Decoding) ist ein Node. Sie verbinden Nodes mit Kabeln um den Workflow zu definieren. Das gibt maximale Kontrolle über jeden Aspekt."}, {"q": "Kann ComfyUI Flux-Modelle nutzen?", "a": "Ja. ComfyUI hat exzellente Flux-Unterstützung und viele veröffentlichte Flux-Workflows. ComfyUI ist für Flux oft besser geeignet als Automatic1111 da es flexibler mit verschiedenen Modell-Architekturen umgeht."}]$x$::jsonb
 WHERE slug = 'comfyui' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "ComfyUI vs Automatic1111 — в чём разница?", "a": "ComfyUI — нодовый редактор для создания кастомных пайплайнов генерации. Automatic1111 (WebUI) — традиционный веб-интерфейс для Stable Diffusion. ComfyUI мощнее для сложных рабочих процессов, Automatic1111 проще для начинающих."}, {"q": "ComfyUI быстрее Automatic1111?", "a": "Как правило — да. ComfyUI более эффективно управляет памятью GPU и может быть значительно быстрее для сложных задач. Для простой генерации разница небольшая."}, {"q": "ComfyUI сложно освоить?", "a": "Да. Нодовый интерфейс требует понимания пайплайна SD: сэмплеры, энкодеры, декодеры, VAE. Для начинающих Automatic1111 или Invoke AI более дружественны. Но ComfyUI стоит изучить для продвинутых рабочих процессов."}, {"q": "Работает ли ComfyUI с FLUX?", "a": "Да. ComfyUI отлично работает с FLUX.1 [schnell] и [dev]. Многие сложные FLUX-рабочие процессы (LoRA, ControlNet) созданы именно в ComfyUI."}]$x$::jsonb
 WHERE slug = 'comfyui' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "ComfyUI vs Automatic1111 — що обрати?", "a": "ComfyUI потужніший і ефективніший для просунутих воркфлоу. Automatic1111 простіший для початківців з більшим числом туторіалів. Для складних пайплайнів і продуктивності — ComfyUI; для простого старту — Automatic1111."}, {"q": "ComfyUI безкоштовний?", "a": "Обидва безкоштовні і відкриті. Вам потрібна відеокарта (NVIDIA рекомендована) або можна запускати хмарно. ComfyUI і Automatic1111 запускаються локально безкоштовно."}]$x$::jsonb
 WHERE slug = 'comfyui' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "ComfyUI vs Automatic1111 — lequel choisir ?", "a": "ComfyUI est pour les utilisateurs avancés voulant un contrôle maximal via des workflows en nœuds. Automatic1111 est plus facile pour les débutants et la communauté est plus grande. Débutants → Automatic1111 ; utilisateurs avancés voulant des workflows complexes → ComfyUI."}, {"q": "ComfyUI est-il gratuit ?", "a": "Oui. ComfyUI est entièrement gratuit et open-source. Vous avez besoin d'un GPU compatible et d'un modèle Stable Diffusion. Automatic1111 est aussi gratuit et open-source."}, {"q": "ComfyUI peut-il fonctionner sans GPU ?", "a": "ComfyUI peut fonctionner sur CPU mais très lentement. Pour une utilisation pratique, un GPU NVIDIA avec 6+ Go VRAM est recommandé. Des services cloud comme Google Colab permettent d'utiliser ComfyUI sans GPU local."}, {"q": "Quelle est la différence entre ComfyUI et Stable Diffusion ?", "a": "Stable Diffusion est le modèle IA. ComfyUI et Automatic1111 sont des interfaces pour utiliser ce modèle. ComfyUI utilise une approche de nœuds visuels ; Automatic1111 utilise une interface web traditionnelle."}]$x$::jsonb
 WHERE slug = 'comfyui' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "ComfyUI vs Automatic1111 — qual escolher?", "a": "ComfyUI é para usuários avançados que querem controle máximo via workflows em nós. Automatic1111 é mais fácil para iniciantes e a comunidade é maior. Iniciantes → Automatic1111; usuários avançados com workflows complexos → ComfyUI."}, {"q": "ComfyUI é gratuito?", "a": "Sim. ComfyUI é totalmente gratuito e open-source. Você precisa de uma GPU compatível e um modelo Stable Diffusion. Automatic1111 também é gratuito e open-source."}, {"q": "ComfyUI pode funcionar sem GPU?", "a": "ComfyUI pode funcionar em CPU mas muito lentamente. Para uso prático, uma GPU NVIDIA com 6+ GB VRAM é recomendada. Serviços em nuvem como Google Colab permitem usar o ComfyUI sem GPU local."}, {"q": "Qual é a diferença entre ComfyUI e Stable Diffusion?", "a": "Stable Diffusion é o modelo de IA. ComfyUI e Automatic1111 são interfaces para usar esse modelo. ComfyUI usa uma abordagem de nós visuais; Automatic1111 usa uma interface web tradicional."}]$x$::jsonb
 WHERE slug = 'comfyui' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Elicit o Consensus para investigación académica?", "a": "Elicit es mejor para procesar grandes volúmenes de papers — extrae datos estructurados y hace revisiones sistemáticas. Consensus es mejor para preguntas específicas sobre evidencia — te dice qué porcentaje de estudios apoyan una afirmación. Para revisar literatura — Elicit; para verificar claims — Consensus."}, {"q": "¿Consensus inventa resultados?", "a": "Consensus está diseñado para citar papers reales y mostrar sus conclusiones — no las inventa. Sin embargo, como toda IA, puede malinterpretar o simplificar matices. Siempre verifica las fuentes originales para investigación seria. Consensus indica cuándo no hay consenso claro sobre una pregunta."}]$x$::jsonb
 WHERE slug = 'consensus' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Elicit vs Consensus: Was ist der Unterschied?", "a": "Elicit ist für systematische Literatur-Reviews konzipiert: Es extrahiert strukturierte Daten aus Papers für tiefe Analysen. Consensus gibt schnelle evidenzbasierte Antworten mit Konsensmessung. Elicit für Forscher; Consensus für schnelle wissenschaftliche Antworten."}, {"q": "Was bedeutet 'Konsensmessung' bei Consensus?", "a": "Consensus zeigt für jede Forschungsfrage ob die Studienlage überwiegend zustimmend, ablehnend oder gemischt ist. Ein 'hoher Konsens' bedeutet viele Studien stimmen überein. Das hilft Ihnen schnell einzuschätzen wie gut eine Aussage durch Forschung gestützt wird."}]$x$::jsonb
 WHERE slug = 'consensus' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между Elicit и Consensus?", "a": "Elicit создан для систематических обзоров — извлекает структурированные данные из статей для мета-анализа. Consensus создан для быстрых вопросов и ответов — синтезирует выводы в ответы на понятном языке со счётчиком консенсуса. Elicit — для глубоких рабочих процессов, Consensus — для быстрых ответов."}]$x$::jsonb
 WHERE slug = 'consensus' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Elicit vs Consensus — яка різниця?", "a": "Elicit — потужний інструмент для автоматизації систематичних оглядів і витягування даних. Consensus — простіший пошук наукового консенсусу з візуальним індикатором. Elicit для глибоких досліджень; Consensus для швидких перевірок тверджень."}, {"q": "Consensus для медичних рішень — надійний?", "a": "Consensus допомагає зрозуміти загальні наукові тенденції але не замінює медичні консультації. Для клінічних рішень консультуйтесь з фахівцями і первинними джерелами."}]$x$::jsonb
 WHERE slug = 'consensus' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Elicit לעומת Consensus – מה ההבדל?", "a": "Elicit מיועד לחקירה עמוקה ולניתוח כמויות גדולות של מאמרים. Consensus מיועד לשאלות מהירות על קונצנזוס מדעי. Elicit לחוקרים; Consensus לאישור טענות מדעיות."}, {"q": "Consensus מדויק?", "a": "Consensus מציג נתונים מ-PubMed וממקורות אקדמיים אחרים. הוא שימושי כנקודת פתיחה אך לא תחליף לקריאת המאמרים המלאים. מומלץ לאמת ממצאים קריטיים ישירות."}]$x$::jsonb
 WHERE slug = 'consensus' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Elicit vs Consensus — lequel est le meilleur ?", "a": "Elicit est meilleur pour la recherche académique approfondie et l'extraction de données de papers. Consensus est meilleur pour comprendre rapidement ce que la science dit sur un sujet. Chercheurs en revue de littérature → Elicit ; curiosité scientifique rapide → Consensus."}, {"q": "Consensus est-il fiable ?", "a": "Consensus s'appuie sur des articles peer-reviewed publiés. La qualité dépend de la littérature existante. Pour les domaines bien étudiés, Consensus est fiable. Pour des sujets émergents ou peu étudiés, les sources peuvent être limitées."}]$x$::jsonb
 WHERE slug = 'consensus' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Elicit vs Consensus — qual é a diferença?", "a": "Elicit é para extração sistemática de dados de papers — mais técnico e completo. Consensus é para entender rapidamente se a ciência suporta uma afirmação — mais acessível. Para revisões de literatura, Elicit; para verificação de fatos científicos, Consensus."}, {"q": "Consensus funciona com estudos em português?", "a": "Consensus foca principalmente em papers em inglês do PubMed e Semantic Scholar. Para literatura científica em português, é necessário usar outras ferramentas."}]$x$::jsonb
 WHERE slug = 'consensus' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Continue.dev es gratuito?", "a": "Continue.dev es completamente open-source y gratuito como extensión. El costo depende del modelo que uses: si usas Ollama con modelos locales (Llama, Mistral) — completamente gratuito. Si usas la API de Anthropic o OpenAI — pagas por el uso de la API. GitHub Copilot cuesta $10/mes."}, {"q": "¿Continue.dev puede usar Claude?", "a": "Sí. Continue.dev se integra con la API de Anthropic, OpenAI, Mistral, Google Gemini y modelos locales via Ollama. Puedes configurar Claude como el modelo para chat y autocompletado, pagando directamente a Anthropic por el uso de API."}, {"q": "¿Continue.dev soporta JetBrains?", "a": "Continue.dev tiene plugins para VS Code y JetBrains IDEs. GitHub Copilot también soporta ambos. Para usuarios de IntelliJ, PyCharm, etc. — ambas herramientas están disponibles."}]$x$::jsonb
 WHERE slug = 'continue-dev' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Что такое Continue.dev?", "a": "Continue.dev — open-source плагин для VS Code и JetBrains, добавляющий ИИ-функции: автодополнение, чат и редактирование. Уникальная особенность — поддержка любой модели: Claude, GPT-4, Gemini или локальные через Ollama."}, {"q": "Continue.dev так же хорош, как Copilot?", "a": "С сильными моделями (Claude Sonnet 4.6, GPT-5.5) — качество сравнимо. Copilot более отполирован и прост в использовании. Continue.dev выигрывает в гибкости и стоимости при использовании локальных моделей."}]$x$::jsonb
 WHERE slug = 'continue-dev' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Що таке Continue.dev?", "a": "Continue.dev — відкритий ШІ-помічник для кодування у VS Code і JetBrains. Він працює як GitHub Copilot але ви самі вибираєте модель — від OpenAI, Anthropic, локальних Ollama-моделей або інших провайдерів. Сам інструмент безкоштовний."}, {"q": "GitHub Copilot vs Continue.dev — хто виграє?", "a": "Copilot більш зрілий з кращою IDE-інтеграцією і стабільнішою продуктивністю. Continue.dev гнучкіший, безкоштовний і більш орієнтований на конфіденційність. Для максимальної продуктивності — Copilot; для відкритих рішень — Continue.dev."}]$x$::jsonb
 WHERE slug = 'continue-dev' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "מה זה Continue.dev?", "a": "Continue.dev הוא עוזר AI לכתיבת קוד Open Source ל-VS Code ו-JetBrains. עובד כמו Copilot אך אתם בוחרים את המודל – OpenAI, Anthropic, Ollama ועוד."}, {"q": "Continue.dev לעומת GitHub Copilot?", "a": "Copilot בוגר עם ביצועים עקביים. Continue.dev גמיש, חינמי ומכבד פרטיות. Copilot לביצועים מקסימליים; Continue.dev למפתחים שרוצים גמישות ופרטיות."}]$x$::jsonb
 WHERE slug = 'continue-dev' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Copy.ai oder Jasper für Marketing?", "a": "Jasper ist besser für große Teams mit Brand-Voice-Anforderungen und komplexen Workflows. Copy.ai ist kostengünstiger und hat einen großzügigen kostenlosen Plan — ideal für Solopreneure und kleinere Teams. Für Enterprise-Content-Marketing — Jasper; für individuelle Nutzung — Copy.ai."}, {"q": "Ist Copy.ai kostenlos?", "a": "Ja. Copy.ai hat einen kostenlosen Plan mit begrenzten Projekten und Wörtern. Kostenpflichtige Pläne starten ab $49/Monat (Starter). Jasper beginnt ab $49/Monat (Creator) ohne kostenlosen Plan."}, {"q": "Kann Copy.ai auf Deutsch texten?", "a": "Ja. Copy.ai unterstützt über 25 Sprachen inklusive Deutsch. Die Qualität ist für Deutsch gut, aber für hochwertigen deutschsprachigen Marketing-Content empfiehlt sich immer ein natives Review."}]$x$::jsonb
 WHERE slug = 'copy-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Semrush vs Copy.ai — это сравнение разных инструментов?", "a": "Да. Semrush — SEO-платформа для анализа данных, исследования ключевых слов и аудита сайтов. Copy.ai — ИИ-генератор контента для написания текстов. Они решают разные задачи, хотя оба используются в контент-маркетинге."}, {"q": "Нужны ли оба инструмента?", "a": "Для контент-маркетинга — да: Semrush находит ключевые слова и темы для контента, Copy.ai помогает его написать быстро. Многие маркетинговые команды используют оба в связке."}]$x$::jsonb
 WHERE slug = 'copy-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Copy.ai чи Jasper для малого бізнесу?", "a": "Copy.ai краще для малого бізнесу: дешевший і простіший. Jasper кращий для маркетингових команд що потребують консистентного брендового голосу. Для соло-підприємців — Copy.ai; для команд — Jasper."}, {"q": "Copy.ai безкоштовний?", "a": "Copy.ai має безкоштовний план. Платні плани від $49/міс. Jasper від $49/міс без безкоштовного плану (тільки пробний)."}, {"q": "Що краще — Copy.ai чи ChatGPT?", "a": "Copy.ai має готові шаблони для маркетингу що швидко дають структурований результат. ChatGPT гнучкіший але потребує більше роботи з промптами. Для маркетингових шаблонів — Copy.ai; для всього іншого — ChatGPT."}]$x$::jsonb
 WHERE slug = 'copy-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Copy.ai מול Jasper — מה עדיף?", "a": "Copy.ai זול יותר ומתאים לשימוש אישי ולצוותים קטנים. Jasper חזק יותר לצוותי שיווק גדולים עם Brand Voice. לתחילת דרך — Copy.ai; לשיווק ארגוני — Jasper."}, {"q": "האם Copy.ai בחינם?", "a": "ל-Copy.ai יש תוכנית חינמית נדיבה עם 2000 מילים/חודש. Starter מ-49$/חודש. ל-Jasper אין תוכנית חינמית; Creator מ-49$/חודש."}]$x$::jsonb
 WHERE slug = 'copy-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Copy.ai ou Jasper — lequel choisir ?", "a": "Copy.ai est meilleur pour les textes courts et les solopreneurs avec un budget limité. Jasper est meilleur pour les équipes marketing produisant du contenu long format avec une voix de marque. Débutants et petits budgets → Copy.ai ; équipes marketing avancées → Jasper."}, {"q": "Copy.ai est-il gratuit ?", "a": "Copy.ai a un plan gratuit avec des limites. Les plans payants à partir de 49 $/mois. Jasper à partir de 49 $/mois (Creator) sans plan gratuit permanent."}, {"q": "Copy.ai vs ChatGPT — lequel est le meilleur pour le marketing ?", "a": "Copy.ai a des modèles marketing prêts à l'emploi qui guident la rédaction. ChatGPT est plus flexible mais nécessite plus de prompts. Pour du contenu marketing structuré, Copy.ai ; pour une utilisation flexible générale, ChatGPT."}]$x$::jsonb
 WHERE slug = 'copy-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Copy.ai ou Jasper — qual é melhor para marketing?", "a": "Copy.ai é melhor para geração rápida de textos de marketing a custo menor. Jasper é melhor para equipes maiores que precisam de consistência de marca e fluxos de trabalho avançados. Para uso individual, Copy.ai; para equipes, Jasper."}, {"q": "Copy.ai é gratuito?", "a": "Copy.ai tem plano gratuito generoso. Planos pagos a partir de $49/mês. Jasper a partir de $49/mês sem plano gratuito, apenas teste."}, {"q": "Copy.ai vs ChatGPT — qual é a diferença?", "a": "Copy.ai tem templates específicos de marketing prontos para uso. ChatGPT é mais versátil mas requer prompts mais detalhados. Para textos de marketing estruturados, Copy.ai é mais eficiente; para uso geral, ChatGPT é mais flexível."}, {"q": "Jasper é melhor que Copy.ai?", "a": "Depende do caso de uso. Jasper é melhor para equipes maiores e consistência de marca. Copy.ai é melhor para uso individual e custo-benefício. Ambos são bons; a escolha depende do tamanho da equipe e orçamento."}]$x$::jsonb
 WHERE slug = 'copy-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Was ist Coursera Coach?", "a": "Coursera Coach ist Coursera's KI-Lernassistent der direkt in Kurse integriert ist. Er kann Kurs-Inhalte erklären, Fragen zu Lektionen beantworten, Quiz-Vorbereitung helfen und bei Aufgaben Guidance geben. Er ist in Coursera Plus-Plänen verfügbar."}, {"q": "Coursera Coach vs Khanmigo: Wer ist besser für Studenten?", "a": "Für Hochschul- und Berufsausbildungs-Kurse — Coursera Coach (direkt im Kurs). Für Schulfächer und Khan Academy-Content — Khanmigo. Beide haben ihren Platz: Coursera für professionelle Weiterbildung; Khanmigo für schulische Grundfächer."}, {"q": "Ist Coursera Coach kostenlos?", "a": "Coursera Coach ist in Coursera Plus ($59/Monat oder $399/Jahr) enthalten. Einzelne Kurse auf Coursera können kostenlos auditiert werden aber ohne vollen Zugang zu Coach-Features. Khanmigo kostet $4/Monat."}, {"q": "Kann Coursera Coach auf Deutsch helfen?", "a": "Coursera Coach versteht Deutsch und kann auf Deutsch antworten. Viele Coursera-Kurse sind jedoch auf Englisch. Für deutschsprachige Kurse und German-Language-Support funktioniert Coach gut, aber die Kurs-Qualität hängt vom verfügbaren deutschen Content ab."}]$x$::jsonb
 WHERE slug = 'coursera-coach' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Coursera Coach vs Khanmigo — для кого?", "a": "Coursera Coach встроен в Coursera и помогает с профессиональными онлайн-курсами. Khanmigo — ИИ-репетитор Khan Academy для школьников и студентов по общеобразовательным предметам. Разные платформы, разные аудитории."}, {"q": "Coursera Coach бесплатный?", "a": "Coursera Coach включён в Coursera Plus ($59/мес или $399/год). Отдельной подписки на Coach нет. Khanmigo — $9/мес как дополнение к бесплатной Khan Academy."}]$x$::jsonb
 WHERE slug = 'coursera-coach' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Coursera Coach vs Khanmigo — яка різниця?", "a": "Coursera Coach прив'язаний до курсів Coursera для дорослих учнів. Khanmigo — педагогічний ШІ-репетитор для K-12 учнів на Khan Academy. Coursera для професійного навчання; Khanmigo для шкільного і базового навчання."}, {"q": "Coursera Coach для підготовки до іспитів?", "a": "Так. Coursera Coach може допомагати з матеріалом курсу включно з підготовкою до іспитів і вікторин у межах платформи Coursera. Він знає зміст вашого конкретного курсу."}]$x$::jsonb
 WHERE slug = 'coursera-coach' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Coursera Coach לעומת Khanmigo?", "a": "Coursera Coach ל-learners בקורסי Coursera. Khanmigo לתלמידים בחומר בית-ספרי. Coursera לאנשי מקצוע; Khanmigo לתלמידים ובגרויות."}, {"q": "Coursera Coach חינמי?", "a": "Coursera Coach כלול ב-Coursera Plus ($59/חודש) ובקורסים פרטיים. Khanmigo ב-$9/חודש."}, {"q": "Coursera לישראל – האם יש תוכן בעברית?", "a": "Coursera באנגלית בעיקר עם כתוביות מתורגמות לחלק מהקורסים. Khanmigo באנגלית; Khan Academy מציע חלק מהתוכן בעברית."}]$x$::jsonb
 WHERE slug = 'coursera-coach' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Zed o VS Code para desarrollo?", "a": "Zed es significativamente más rápido que VS Code — lanzamiento instantáneo, sin lag en archivos grandes. VS Code tiene ecosistema de extensiones mucho mayor. Cursor está basado en VS Code. Para velocidad pura — Zed; para mayor ecosistema — VS Code o Cursor."}, {"q": "¿Zed es gratuito?", "a": "Zed es gratuito y open-source. Las funciones de IA (Zed AI) usan la API de Anthropic o pueden configurarse con otros modelos. Cursor tiene plan gratuito con 2.000 autocompletados; Pro ($20/mes) para uso ilimitado."}, {"q": "¿Zed está disponible en Windows?", "a": "Zed empezó como exclusivo de macOS pero lanzó soporte para Linux. El soporte para Windows está en desarrollo activo pero puede no estar completamente estable. Cursor está disponible en macOS, Windows y Linux."}, {"q": "¿Qué es Cursor Composer?", "a": "Cursor Composer (ahora llamado Cursor Agent) es la función más potente de Cursor — permite describir en lenguaje natural cambios que afectan múltiples archivos simultáneamente y Cursor los implementa. Es la diferencia clave frente a otros editores con IA que solo trabajan en el archivo activo."}, {"q": "¿Qué es Cursor?", "a": "Cursor es un IDE nativo de IA basado en VS Code. Le da al AI contexto completo de tu base de código y puede editar múltiples archivos, ejecutar comandos y completar tareas de principio a fin como agente."}, {"q": "¿Cuánto cuesta Cursor?", "a": "Plan Hobby gratuito con solicitudes limitadas. Pro es $20/mes (500 solicitudes rápidas). Business es $40/usuario/mes con SSO y funciones de equipo."}, {"q": "¿Es seguro usar Cursor?", "a": "Cursor ofrece un Modo de Privacidad que deshabilita el almacenamiento de código en sus servidores. Los planes Enterprise incluyen controles adicionales y conformidad SOC 2."}, {"q": "¿Qué modelos usa Cursor?", "a": "Cursor usa Claude Opus 4.7, GPT-4o y modelos fine-tuned propios para autocompletado. Puedes cambiar modelos por solicitud en la configuración."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Zed vs Cursor: Was ist besser?", "a": "Cursor ist ausgereifter für KI-Coding: stärkere Agenten-Features, Multi-File-Editing und bessere Chat-Integration. Zed ist schneller und hat einzigartige native Multiplayer-Kollaboration. Für KI-Coding — Cursor; für Performance und Zusammenarbeit — Zed."}, {"q": "Ist Zed kostenlos?", "a": "Zed ist kostenlos und Open-Source. KI-Features in Zed nutzen Claude und können API-Kosten verursachen. Cursor hat einen kostenlosen Plan mit begrenzten Anfragen; Pro ab $20/Monat."}, {"q": "Kann Zed VS Code-Extensions verwenden?", "a": "Nein. Zed ist kein VS Code-Fork und verwendet keine VS Code-Extensions. Zed hat sein eigenes Extension-System das wächst aber noch deutlich kleiner als das VS Code-Ökosystem ist."}, {"q": "Zed für macOS: Ist es gut optimiert?", "a": "Zed wurde ursprünglich für macOS entwickelt und ist dort am besten optimiert. Es nutzt macOS-native APIs für maximale Performance. Linux-Support ist verfügbar; Windows-Support ist in Entwicklung."}, {"q": "Was ist Cursor?", "a": "Cursor ist eine KI-native IDE auf Basis von VS Code. Die KI bekommt vollen Kontext deiner Codebasis, kann mehrere Dateien bearbeiten, Terminal-Befehle ausführen und Aufgaben autonom erledigen."}, {"q": "Was kostet Cursor?", "a": "Kostenloser Hobby-Plan mit begrenzten Anfragen. Pro kostet $20/Monat (500 schnelle Anfragen). Business kostet $40/Nutzer/Monat mit SSO und Team-Funktionen."}, {"q": "Ist Cursor sicher für meinen Code?", "a": "Cursor bietet einen Datenschutzmodus, der die Code-Speicherung auf ihren Servern deaktiviert. Enterprise-Pläne umfassen zusätzliche Datenkontrolle und SOC 2-Konformität."}, {"q": "Welche Modelle verwendet Cursor?", "a": "Cursor verwendet Claude Opus 4.7, GPT-4o und eigene fine-tuned Modelle für die Autovervollständigung. Das Modell kann pro Anfrage in den Einstellungen gewechselt werden."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Cursor лучше GitHub Copilot?", "a": "Cursor в целом обеспечивает более мощную ИИ-помощь — контекст всей кодовой базы и многофайловое редактирование в Composer мощнее встроенных подсказок Copilot. Но Copilot поддерживает больше IDE и имеет корпоративные функции. Cursor — выбор для индивидуальных разработчиков, которые хотят лучший ИИ-опыт."}, {"q": "Cursor бесплатный?", "a": "Cursor имеет бесплатный план Hobby с ограниченными запросами (2000 дополнений/мес). Plan Pro — $20/мес с неограниченными дополнениями и 500 быстрыми запросами Claude/GPT-4. Business — $40/пользователь/мес."}, {"q": "Cursor использует Claude или GPT-4?", "a": "Cursor поддерживает несколько ИИ-моделей: Claude 3.5 Sonnet, GPT-4o и собственные дообученные модели Cursor. Пользователи Pro могут выбирать модель. Claude 3.5 Sonnet обычно рекомендуется для сложных задач кодирования."}, {"q": "Можно использовать GitHub Copilot и Cursor вместе?", "a": "Да, но они будут значительно перекрываться. Большинство разработчиков выбирают один основной инструмент. Cursor обычно предпочтителен за более мощные функции, а Copilot остаётся для команд с корпоративными рабочими процессами GitHub."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Zed vs Cursor — що краще?", "a": "Cursor більш зрілий для ШІ-кодування: сильніші агентні функції, багатофайлове редагування і краща інтеграція чату. Zed швидший і має унікальну нативну мультиплеєрну колаборацію. Для ШІ-кодування — Cursor; для швидкості і колаборації — Zed."}, {"q": "Zed безкоштовний?", "a": "Zed безкоштовний і відкритий. ШІ-функції у Zed використовують Claude і можуть коштувати за API. Cursor має безкоштовний план з обмеженими запитами; Pro від $20/міс."}, {"q": "Zed підтримує VS Code-розширення?", "a": "Ні. Zed — не fork VS Code і не використовує VS Code-розширення. У Zed є власна система розширень що зростає але ще значно менша ніж екосистема VS Code."}, {"q": "Zed для macOS оптимізований?", "a": "Zed спочатку розроблявся для macOS і там найкраще оптимізований. Використовує нативні macOS API для максимальної продуктивності. Linux-підтримка доступна; Windows-підтримка в розробці."}, {"q": "Що таке Cursor?", "a": "Cursor — AI-нативна IDE на базі VS Code. AI отримує повний контекст кодової бази, редагує кілька файлів, виконує команди в терміналі та виконує завдання автономно."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Zed לעומת Cursor – מה עדיף?", "a": "Cursor בוגר יותר עם Agentic Features חזקים. Zed מהיר יותר עם Multiplayer ייחודי. AI Coding – Cursor; ביצועים ושיתוף – Zed."}, {"q": "Zed חינמי?", "a": "Zed חינמי ו-Open Source. AI Features ב-Zed עשויים לדרוש API. Cursor מציע תוכנית חינמית; Pro ב-$20/חודש."}, {"q": "Zed Extensions – האם יש?", "a": "Zed לא תואם ל-VS Code Extensions. יש ל-Zed system Extensions משלו שעדיין קטן ממערכת VS Code. גדל בהדרגה."}, {"q": "Zed ל-macOS – כמה מוטב?", "a": "Zed פותח במקור ל-macOS ומשתמש ב-Metal API לביצועים מיטביים. Linux נתמך; Windows בפיתוח."}, {"q": "מה זה Cursor?", "a": "Cursor הוא IDE מבוסס AI שנבנה על VS Code. ה-AI מקבל הקשר מלא של קוד הפרויקט, יכול לערוך מספר קבצים, להריץ פקודות טרמינל ולהשלים משימות באופן אוטונומי."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Zed vs Cursor — lequel est le meilleur ?", "a": "Cursor est plus mature pour le codage IA : meilleures fonctionnalités agentiques, édition multi-fichiers et meilleure intégration chat. Zed est plus rapide et a une collaboration multiplayer native unique. Pour le codage IA → Cursor ; pour les performances et la collaboration → Zed."}, {"q": "Zed est-il gratuit ?", "a": "Zed est gratuit et open-source. Les fonctionnalités IA dans Zed utilisent Claude et peuvent entraîner des coûts API. Cursor a un plan gratuit avec des requêtes limitées ; Pro à partir de 20 $/mois."}, {"q": "Zed peut-il utiliser des extensions VS Code ?", "a": "Non. Zed n'est pas un fork de VS Code et n'utilise pas les extensions VS Code. Zed a son propre système d'extensions qui croît mais est encore bien plus petit que l'écosystème VS Code."}, {"q": "Zed est-il optimisé pour macOS ?", "a": "Zed a été développé à l'origine pour macOS et y est le mieux optimisé. Il utilise les APIs natives macOS pour des performances maximales. Le support Linux est disponible ; le support Windows est en développement."}, {"q": "Qu'est-ce que Cursor ?", "a": "Cursor est un IDE natif IA basé sur VS Code. Il donne à l'IA un contexte complet de votre base de code, peut modifier plusieurs fichiers, exécuter des commandes terminal et accomplir des tâches de bout en bout comme un agent."}, {"q": "Combien coûte Cursor ?", "a": "Plan Hobby gratuit avec requêtes limitées. Pro à $20/mois (500 requêtes rapides). Business à $40/utilisateur/mois avec SSO et fonctionnalités d'équipe."}, {"q": "Cursor est-il sûr pour mon code ?", "a": "Cursor propose un Mode Confidentialité qui désactive le stockage du code sur leurs serveurs. Les plans Enterprise incluent des contrôles de données supplémentaires et la conformité SOC 2."}, {"q": "Quels modèles utilise Cursor ?", "a": "Cursor utilise Claude Opus 4.7, GPT-4o et ses propres modèles fine-tuned pour l'autocomplétion. Vous pouvez changer de modèle par requête dans les paramètres."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Zed vs Cursor — qual é o melhor?", "a": "Cursor é mais maduro para codificação com IA: melhores funcionalidades agênticas, edição multi-arquivo e melhor integração de chat. Zed é mais rápido e tem colaboração multiplayer nativa única. Para codificação com IA → Cursor; para desempenho e colaboração → Zed."}, {"q": "Zed é gratuito?", "a": "Zed é gratuito e open-source. As funcionalidades de IA no Zed usam Claude e podem ter custos de API. Cursor tem plano gratuito com consultas limitadas; Pro a partir de $20/mês."}, {"q": "Zed pode usar extensões do VS Code?", "a": "Não. Zed não é um fork do VS Code e não usa extensões do VS Code. Zed tem seu próprio sistema de extensões que está crescendo mas ainda é muito menor que o ecossistema VS Code."}, {"q": "Zed é otimizado para macOS?", "a": "Zed foi desenvolvido originalmente para macOS e está melhor otimizado lá. Usa as APIs nativas do macOS para desempenho máximo. Suporte ao Linux está disponível; suporte ao Windows está em desenvolvimento."}, {"q": "O que é o Cursor?", "a": "O Cursor é um IDE nativo de IA baseado no VS Code. Ele dá à IA contexto completo da sua base de código, pode editar múltiplos arquivos, executar comandos no terminal e completar tarefas do início ao fim como um agente."}, {"q": "Quanto custa o Cursor?", "a": "Plano Hobby gratuito com solicitações limitadas. Pro custa $20/mês (500 solicitações rápidas). Business custa $40/usuário/mês com SSO e recursos de equipe."}, {"q": "O Cursor é seguro para meu código?", "a": "O Cursor oferece um Modo de Privacidade que desativa o armazenamento de código em seus servidores. Os planos Enterprise incluem controles de dados adicionais e conformidade com SOC 2."}, {"q": "Quais modelos o Cursor usa?", "a": "O Cursor usa Claude Opus 4.7, GPT-4o e seus próprios modelos fine-tuned para autocompletar. Você pode mudar de modelo por solicitação nas configurações."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿DeepL es mejor que Google Translate?", "a": "Para la mayoría de los idiomas europeos — sí. DeepL produce traducciones más naturales y precisas, especialmente en alemán, francés, español y polaco. Google Translate soporta más idiomas (133 vs. 31 en DeepL), pero DeepL supera en calidad para los idiomas que soporta."}, {"q": "¿DeepL es gratuito?", "a": "DeepL tiene un plan gratuito con 500.000 caracteres/mes y 3 documentos/mes. DeepL Pro empieza desde $8.74/mes (Starter). Grammarly también tiene plan gratuito; Grammarly Premium cuesta $12/mes."}, {"q": "¿DeepL es bueno para el español?", "a": "Sí. El soporte para español de DeepL es excelente — produce traducciones muy naturales entre inglés y español. Muchos traductores profesionales usan DeepL como punto de partida y refinan el resultado."}]$x$::jsonb
 WHERE slug = 'deepl' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "DeepL oder Google Translate: Welches ist besser?", "a": "DeepL gilt allgemein als qualitativ hochwertiger als Google Translate, besonders für europäische Sprachen. Die Übersetzungen klingen natürlicher und erfassen Nuancen besser. Für einfache alltägliche Übersetzungen ist Google Translate ausreichend; für professionelle oder komplexe Texte ist DeepL überlegen."}, {"q": "Ist DeepL kostenlos?", "a": "DeepL hat einen kostenlosen Plan mit begrenzten Übersetzungen (bis zu 5.000 Zeichen pro Übersetzung ohne Dokument-Upload). DeepL Pro beginnt ab $10,49/Monat mit unbegrenzten Übersetzungen, API-Zugang und Dokument-Uploads. Grammarly hat einen kostenlosen Plan; Premium ab $12/Monat."}, {"q": "Kann DeepL PDFs übersetzen?", "a": "Ja. DeepL Pro kann PDFs, Word-Dokumente, PowerPoint-Dateien und andere Dokumente übersetzen und dabei die Formatierung erhalten. Der kostenlose Plan unterstützt keine Dokument-Uploads."}]$x$::jsonb
 WHERE slug = 'deepl' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Может ли DeepL улучшить мои тексты?", "a": "DeepL Write (отдельный инструмент от DeepL Translate) улучшает тексты на английском и немецком, переформулируя предложения для ясности и стиля. Менее комплексен, чем Grammarly для проверки грамматики, но силён в переформулировках."}, {"q": "Что точнее — DeepL или Google Переводчик?", "a": "DeepL стабильно превосходит Google Переводчик по точности и естественности, особенно для европейских языков. Google Переводчик поддерживает больше языков (100+ против 31 у DeepL), но качество DeepL для поддерживаемых языков выше."}]$x$::jsonb
 WHERE slug = 'deepl' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "DeepL чи Google Translate — що точніше?", "a": "DeepL загалом точніший особливо для європейських мов. Google Translate покриває більше мов (100+) і кращий для рідкісних мов. Для якісного перекладу з/на основні мови — DeepL; для рідкісних мов — Google Translate."}, {"q": "DeepL безкоштовний?", "a": "DeepL має безкоштовний план з обмеженнями. DeepL Pro від €10,99/міс. Grammarly безкоштовний для базових функцій; Premium від $12/міс."}, {"q": "DeepL Write vs Grammarly — різниця?", "a": "DeepL Write покращує текст у тій самій мові і дуже добрий для стилю і природності. Grammarly потужніший для комплексного граматичного і стилістичного аналізу. Для природного переформулювання — DeepL Write; для комплексної перевірки — Grammarly."}]$x$::jsonb
 WHERE slug = 'deepl' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "DeepL או Google Translate — מה מדויק יותר?", "a": "DeepL בדרך כלל מדויק יותר, במיוחד לשפות אירופאיות. Google Translate מכסה יותר שפות (100+) ועדיף לשפות נדירות. לתרגום איכותי בשפות עיקריות — DeepL; לשפות נדירות — Google Translate."}, {"q": "האם DeepL בחינם?", "a": "ל-DeepL יש תוכנית חינמית עם מגבלות. DeepL Pro מ-10.99€/חודש. Grammarly חינמי לתכונות בסיסיות; Premium מ-12$/חודש."}, {"q": "DeepL Write מול Grammarly — מה ההבדל?", "a": "DeepL Write משפר טקסט באותה שפה ומצוין לסגנון וטבעיות. Grammarly חזק יותר לניתוח דקדוקי וסגנותי מקיף. לניסוח מחדש טבעי — DeepL Write; לבדיקה מקיפה — Grammarly."}]$x$::jsonb
 WHERE slug = 'deepl' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "DeepL ou Google Translate — lequel est le plus précis ?", "a": "DeepL est généralement plus précis, surtout pour les langues européennes. Google Translate couvre plus de langues (100+) et est meilleur pour les langues rares. Pour une traduction de qualité vers/depuis les principales langues, DeepL ; pour les langues rares, Google Translate."}, {"q": "DeepL est-il gratuit ?", "a": "DeepL a un plan gratuit avec des limites. DeepL Pro à partir de 10,99 €/mois. Grammarly est gratuit pour les fonctions de base ; Premium à partir de 12 $/mois."}, {"q": "DeepL Write vs Grammarly — quelle est la différence ?", "a": "DeepL Write améliore le texte dans la même langue et est très bon pour le style et la fluidité. Grammarly est plus puissant pour l'analyse grammaticale et stylistique complète. Pour une reformulation naturelle, DeepL Write ; pour une vérification complète, Grammarly."}, {"q": "DeepL supporte-t-il le français ?", "a": "Oui. DeepL offre une excellente prise en charge du français. La qualité de traduction vers et depuis le français est parmi les meilleures, notamment pour les paires FR-EN et FR-DE."}]$x$::jsonb
 WHERE slug = 'deepl' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "DeepL ou Google Tradutor — qual é mais preciso?", "a": "DeepL é geralmente mais preciso, especialmente para idiomas europeus. Google Tradutor cobre mais idiomas (100+) e é melhor para idiomas raros. Para tradução de qualidade de/para os principais idiomas, DeepL; para idiomas raros, Google Tradutor."}, {"q": "DeepL é gratuito?", "a": "DeepL tem plano gratuito com limites. DeepL Pro a partir de €10,99/mês. Grammarly é gratuito para funções básicas; Premium a partir de $12/mês."}, {"q": "DeepL Write vs Grammarly — qual é a diferença?", "a": "DeepL Write melhora o texto no mesmo idioma e é muito bom para estilo e fluência. Grammarly é mais poderoso para análise gramatical e estilística completa. Para reformulação natural, DeepL Write; para verificação completa, Grammarly."}, {"q": "DeepL suporta português?", "a": "Sim. DeepL oferece excelente suporte ao português. A qualidade da tradução para e do português está entre as melhores, especialmente para os pares PT-EN e PT-ES."}]$x$::jsonb
 WHERE slug = 'deepl' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "DeepSeek лучше ChatGPT?", "a": "DeepSeek R1 соответствует или превосходит GPT-o1 по бенчмаркам рассуждений и математики — за долю стоимости. Для чистого текстового рассуждения и кода DeepSeek конкурентоспособен с лучшими моделями. У ChatGPT больше функций (изображения, голос, плагины) и лучшая экосистема."}, {"q": "DeepSeek безопасен для использования?", "a": "DeepSeek — китайская компания. Некоторые организации опасаются конфиденциальности данных по китайскому законодательству. Веса модели открыты и могут запускаться локально. Государственные органы США и некоторые компании ограничили его использование."}, {"q": "Что такое DeepSeek R1?", "a": "DeepSeek R1 — модель рассуждений DeepSeek, выпущенная в январе 2025 года. Использует цепочное рассуждение, аналогичное OpenAI o1, и достигла сопоставимых бенчмарков. Она потрясла индустрию ИИ, показав производительность фронтирных моделей при значительно меньших затратах."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "DeepSeek vs ChatGPT — яка різниця?", "a": "DeepSeek — китайська відкрита модель, яка безкоштовно конкурує з GPT-4 у математиці та кодуванні. ChatGPT — американська закрита модель від OpenAI з більш широкою екосистемою. DeepSeek кращий по ціні/якості; ChatGPT кращий для готових рішень."}, {"q": "Чи безпечний DeepSeek?", "a": "DeepSeek — китайська компанія, що викликає питання щодо конфіденційності даних. Корпоративні та чутливі дані вводити в DeepSeek API не рекомендується. Для приватного використання — розгортайте локально через Ollama."}, {"q": "DeepSeek R1 чи GPT-4 для кодування?", "a": "DeepSeek R1 показує конкурентні результати з GPT-4 у бенчмарках кодування. Для практичного кодування різниця мінімальна. DeepSeek кращий по вартості; ChatGPT зручніший у IDE-інтеграції через GitHub Copilot."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "DeepSeek מול ChatGPT — מה ההבדל?", "a": "DeepSeek הוא מודל סיני פתוח שמתחרה ב-GPT-4 במתמטיקה ובקוד בחינם. ChatGPT הוא מודל אמריקאי סגור מ-OpenAI עם מערכת-אקולוגית רחבה יותר. DeepSeek עדיף ביחס עלות/ביצועים; ChatGPT עדיף לפתרונות מוכנים."}, {"q": "האם DeepSeek בטוח?", "a": "DeepSeek היא חברה סינית, מה שמעלה שאלות לגבי פרטיות הנתונים. לא מומלץ להזין נתונים ארגוניים או רגישים ב-DeepSeek API. לשימוש פרטי — פרסו מקומית דרך Ollama."}, {"q": "DeepSeek R1 או GPT-4 לקוד?", "a": "DeepSeek R1 מציג תוצאות תחרותיות עם GPT-4 בבנצ'מרקים של קוד. ההבדל המעשי מינימלי. DeepSeek עדיף בעלות; ChatGPT נוח יותר לאינטגרציית IDE דרך GitHub Copilot."}]$x$::jsonb
 WHERE slug = 'deepseek' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Descript o Adobe Podcast para podcasters principiantes?", "a": "Adobe Podcast (Enhance Speech) es más simple — subes el audio, lo mejoras y listo. Descript es más potente pero requiere más aprendizaje. Para empezar con mejora básica — Adobe Podcast; para producción profesional de podcasts con edición completa — Descript."}, {"q": "¿Descript es gratuito?", "a": "Descript tiene un plan gratuito con 1 hora de transcripción al mes. El plan Creator ($24/mes) ofrece más funciones. Adobe Podcast (Enhance Speech) es gratuito en beta. El acceso completo requiere suscripción a Adobe Creative Cloud."}, {"q": "¿Qué hace Overdub de Descript?", "a": "Overdub es la función de clonación de voz de Descript. Entrenas un modelo con tu voz y puedes reemplazar o añadir palabras en tu grabación de audio sin volver a grabar — el resultado suena como tú. Es útil para correcciones rápidas sin sesiones de grabación adicionales."}]$x$::jsonb
 WHERE slug = 'descript' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Для чего используется Descript?", "a": "Descript — редактор аудио и видео, где монтаж ведётся через текстовый транскрипт. Используется для подкастов, видеоконтента и записей экрана. Ключевые функции: автоматическое транскрибирование, удаление слов-паразитов, Overdub (клонирование голоса ИИ) и запись экрана."}]$x$::jsonb
 WHERE slug = 'descript' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Descript vs Adobe Podcast — яка різниця?", "a": "Descript — повний редактор подкастів і відео з транскрибуванням і монтажем через текст. Adobe Podcast — простий онлайн-інструмент для покращення якості аудіо. Descript для повного виробництва; Adobe Podcast для швидкого покращення запису."}, {"q": "Descript безкоштовний?", "a": "Descript має безкоштовний план з обмеженнями (1 година транскрипції/міс). Creator від $24/міс. Adobe Podcast Enhance безкоштовний; повна Adobe Podcast у Creative Cloud ($54,99/міс)."}]$x$::jsonb
 WHERE slug = 'descript' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Descript או Adobe Podcast – מה עדיף?", "a": "Descript הוא עורך פודקאסט ווידאו מלא עם תמלול, עריכת טקסט וכלי AI. Adobe Podcast מתמחה בשיפור איכות שמע. ל-Descript ביצועים ולאינטגרציה עם Adobe – Podcast."}, {"q": "האם Descript חינמי?", "a": "Descript מציע תוכנית חינמית עם 1 שעת תמלול לחודש. Creator ב-$24/חודש. Adobe Podcast חינמי לשימוש בסיסי; Creative Cloud ב-$54.99/חודש."}]$x$::jsonb
 WHERE slug = 'descript' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Descript vs Adobe Podcast — lequel est le meilleur ?", "a": "Descript est un éditeur audio/vidéo complet — idéal pour les podcasters qui veulent tout en un. Adobe Podcast Enhance est excellent pour améliorer rapidement la qualité audio. Pour la production complète de podcast → Descript ; pour améliorer des enregistrements → Adobe Podcast."}, {"q": "Descript peut-il éditer des vidéos ?", "a": "Oui. Descript édite aussi bien l'audio que la vidéo via une transcription textuelle. Vous supprimez un mot dans le texte et la vidéo est coupée à cet endroit. C'est révolutionnaire pour les interviews et les tutoriels vidéo."}]$x$::jsonb
 WHERE slug = 'descript' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Descript vs Adobe Podcast — qual escolher?", "a": "Descript é mais completo para edição de podcast e vídeo. Adobe Podcast é melhor para melhoria de qualidade de áudio. Para edição completa, Descript; para melhorar qualidade de áudio de gravações domésticas, Adobe Podcast."}, {"q": "Descript é gratuito?", "a": "Descript tem plano gratuito com 1 hora de transcrição por mês. Planos pagos a partir de $24/mês. Adobe Podcast Enhance é gratuito com uso limitado; o Adobe Podcast completo requer assinatura Creative Cloud."}, {"q": "O que é Descript Overdub?", "a": "Overdub é uma função do Descript que cria um clone de voz digital do apresentador. Você pode corrigir erros no áudio digitando o texto correto — Descript gera o áudio com sua própria voz."}]$x$::jsonb
 WHERE slug = 'descript' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Що таке Devin AI?", "a": "Devin від Cognition — перший автономний ШІ-розробник. Він може самостійно читати завдання, писати код, запускати тести, виправляти помилки і відкривати Pull Requests. Позиціонується як перший ШІ-«програміст» а не просто асистент."}, {"q": "Чи Devin замінить розробників?", "a": "Devin автоматизує рутинні завдання і може прискорити роботу. Але для складних архітектурних рішень і нетипових завдань він потребує нагляду. Poки що він доповнює розробників, а не замінює їх."}, {"q": "Devin vs GitHub Copilot — різниця?", "a": "GitHub Copilot — асистент що допомагає розробнику писати код. Devin — автономний агент що самостійно виконує завдання. Copilot вимагає участі людини; Devin працює самостійно над задачами."}]$x$::jsonb
 WHERE slug = 'devin' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "מה זה Devin AI?", "a": "Devin מ-Cognition הוא מפתח AI אוטונומי ראשון. הוא יכול לקרוא משימות, לכתוב קוד, להריץ בדיקות, לתקן שגיאות ולפתוח Pull Requests באופן עצמאי. ממוצב כ'מתכנת AI' ראשון לא רק עוזר."}, {"q": "האם Devin יחליף מפתחים?", "a": "Devin מאטמט משימות שגרתיות ויכול להאיץ עבודה. אבל להחלטות ארכיטקטורה מורכבות ומשימות לא-שגרתיות הוא דורש פיקוח. כרגע הוא משלים מפתחים, לא מחליף."}, {"q": "Devin מול GitHub Copilot — מה ההבדל?", "a": "GitHub Copilot הוא עוזר שעוזר למפתח לכתוב קוד. Devin הוא סוכן אוטונומי שמבצע משימות באופן עצמאי. Copilot דורש השתתפות אנושית; Devin עובד עצמאית על משימות."}]$x$::jsonb
 WHERE slug = 'devin' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Duolingo Max vale la pena?", "a": "Duolingo Max añade dos funciones sobre Super Duolingo: Roleplay (práctica de conversación IA en situaciones reales) y Explain My Answer (la IA explica por qué una respuesta es correcta o incorrecta). Para aprendizaje serio de idiomas que ya usa Duolingo regularmente — vale la pena."}]$x$::jsonb
 WHERE slug = 'duolingo-max' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Duolingo Max vs Duolingo Plus: Was ist der Unterschied?", "a": "Duolingo Plus entfernt Werbung und bietet Offline-Modus. Duolingo Max ($13,99/Monat) fügt KI-Features hinzu: 'Explain My Answer' (KI erklärt Fehler) und 'Roleplay' (KI-Konversationsübungen). Max ist teurer aber bietet echten KI-Mehrwert."}]$x$::jsonb
 WHERE slug = 'duolingo-max' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Photomath vs Duolingo Max — это разные инструменты?", "a": "Да, полностью разные. Photomath — решатель математических задач по фото. Duolingo Max — премиум-уровень языкового приложения с ИИ. Photomath для математики, Duolingo для языков."}, {"q": "Duolingo Max стоит своих денег?", "a": "Duolingo Max добавляет Roleplay (ролевые сценарии с ИИ) и Explain My Answer (объяснения ошибок). Для серьёзного изучения языка — хорошее дополнение. Базовый Duolingo бесплатен и эффективен для начального уровня."}]$x$::jsonb
 WHERE slug = 'duolingo-max' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Duolingo Max — що нового порівняно зі звичайним Duolingo?", "a": "Duolingo Max додає Explain My Answer (ШІ пояснює чому відповідь правильна/неправильна) і Roleplay (розмовна практика з ШІ у сценаріях реального життя). Доступний для підписки Max."}]$x$::jsonb
 WHERE slug = 'duolingo-max' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Photomath לעומת Duolingo Max – מה ההבדל?", "a": "שניהם כלי חינוך AI אך לתחומים שונים. Photomath למתמטיקה; Duolingo Max ללימוד שפות. לפי צרכיכם."}, {"q": "Duolingo Max שווה את המחיר?", "a": "Duolingo Max מוסיף Roleplay ו-Explain My Answer שהם שיפור ניכר ל-Plus. אם אתם משתמשים ב-Duolingo באופן יומיומי – כן, שווה. לשימוש מזדמן – Plus מספיק."}]$x$::jsonb
 WHERE slug = 'duolingo-max' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Photomath vs Duolingo Max — pour quoi utiliser lequel ?", "a": "Ce sont des outils pour des objectifs complètement différents. Photomath pour apprendre et résoudre des mathématiques. Duolingo Max pour apprendre des langues avec des fonctionnalités IA. Il n'y a pas de comparaison directe."}, {"q": "Duolingo Max est-il disponible pour le français ?", "a": "Duolingo Max est disponible pour l'apprentissage du français (pour les anglophones) et pour l'anglais (pour les francophones). La disponibilité varie selon la paire de langues."}]$x$::jsonb
 WHERE slug = 'duolingo-max' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Photomath vs Duolingo Max — qual usar?", "a": "São ferramentas para fins diferentes. Photomath é para resolver problemas de matemática. Duolingo Max é para aprender idiomas. Use ambos se precisar das duas coisas."}, {"q": "Duolingo Max em português?", "a": "Duolingo Max (com recursos de IA) está disponível para aprender inglês e espanhol a partir do português, entre outros idiomas. Verifique a disponibilidade dos cursos específicos no aplicativo."}]$x$::jsonb
 WHERE slug = 'duolingo-max' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Suno o ElevenLabs para crear contenido de audio?", "a": "Son herramientas para propósitos completamente distintos. Suno crea música: canciones con instrumentación y letra. ElevenLabs convierte texto en voz hablada realista. Si necesitas música — Suno; si necesitas voz narrada — ElevenLabs."}, {"q": "¿Puede Suno crear voz hablada?", "a": "Suno genera voces cantadas dentro de canciones, no locución o narración. Para texto a voz realista — ElevenLabs, Murf o Play.ht. Para canciones con voz cantada — Suno."}, {"q": "¿Se puede usar la música de Suno en videos de YouTube?", "a": "Con el plan de pago de Suno (Pro o Premier) obtienes derechos comerciales. El plan gratuito tiene restricciones de uso comercial. Verifica los términos actuales antes de monetizar contenido. ElevenLabs tiene políticas similares según el plan."}, {"q": "¿ElevenLabs puede generar música?", "a": "ElevenLabs está especializado en síntesis de voz y clonación, no en generación de música instrumental. Para música — usa Suno o Udio. Para voz — ElevenLabs es el estándar de calidad."}]$x$::jsonb
 WHERE slug = 'elevenlabs' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Suno oder ElevenLabs: Was ist der Unterschied?", "a": "Suno generiert Musik und Songs mit Gesang. ElevenLabs generiert gesprochene Sprache und Voiceovers. Das sind grundlegend verschiedene Anwendungsfälle. Für Musik und Jingles — Suno; für Voiceovers und TTS — ElevenLabs."}, {"q": "Kann Suno deutsche Songs erstellen?", "a": "Ja. Suno kann Songs in deutschen Texten generieren. Geben Sie deutschen Liedtext in Custom Lyrics ein oder beschreiben Sie den Stil auf Deutsch. Die Qualität deutschsprachiger Songs ist gut, für Englisch aber noch konsistenter."}, {"q": "Ist Suno kostenlos?", "a": "Suno hat einen kostenlosen Plan mit 50 Credits/Tag (ca. 10 Songs). Pro ab $10/Monat (500 Credits), Premier ab $30/Monat. ElevenLabs hat einen kostenlosen Plan; Starter ab $5/Monat."}, {"q": "Kann ElevenLabs Musik generieren?", "a": "ElevenLabs fokussiert auf Text-zu-Sprache und Stimmen — keine Musik-Generierung. Für Musik nutzen Sie Suno oder Udio. ElevenLabs hat jedoch Sound Effects generierung als separate Funktion."}]$x$::jsonb
 WHERE slug = 'elevenlabs' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Speechify vs ElevenLabs — в чём разница?", "a": "Speechify — читалка вслух: для личного потребления контента. ElevenLabs — студия синтеза речи: для создания аудиоконтента и разработки приложений. Speechify слушает чужой контент, ElevenLabs создаёт свой."}, {"q": "ElevenLabs лучше Speechify для создания подкастов?", "a": "Для создания подкастов — ElevenLabs. Для прослушивания подкастов и статей — Speechify. ElevenLabs создаёт реалистичный синтез для производства, Speechify воспроизводит контент для личного потребления."}]$x$::jsonb
 WHERE slug = 'elevenlabs' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Suno לעומת ElevenLabs – מה ההבדל?", "a": "Suno יוצר מוזיקה שלמה עם מנגינה ומילים. ElevenLabs ממיר טקסט לדיבור בקולות AI. שניהם שונים לחלוטין – Suno למוזיקה, ElevenLabs לנרטיב ודיבור."}, {"q": "האם Suno חינמי?", "a": "Suno מציע תוכנית חינמית עם 50 שירים ליום. Pro ב-$10/חודש. ElevenLabs חינמי עם 10,000 תווים לחודש; Starter ב-$5/חודש."}, {"q": "האם ElevenLabs תומך בעברית?", "a": "כן, ElevenLabs תומך בעברית עם איכות גבוהה. ניתן ליצור שכפול קולי בעברית ולהמיר טקסט עברי לדיבור טבעי."}]$x$::jsonb
 WHERE slug = 'elevenlabs' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Suno vs ElevenLabs — quelle est la différence ?", "a": "Suno génère de la musique complète avec mélodie et paroles. ElevenLabs génère des voix réalistes pour la narration. Ce sont des outils très différents : Suno pour la création musicale ; ElevenLabs pour la voix off et la narration."}, {"q": "Suno est-il gratuit ?", "a": "Suno a un plan gratuit avec 50 chansons par jour. Pro à partir de 10 $/mois. ElevenLabs a un plan gratuit avec 10 000 caractères/mois ; payants à partir de 5 $/mois."}, {"q": "ElevenLabs peut-il générer de la musique ?", "a": "ElevenLabs se spécialise dans la génération de voix, pas de musique. Pour la musique IA, Suno, Udio et d'autres outils dédiés sont bien meilleurs."}, {"q": "Peut-on utiliser Suno pour la musique de fond de vidéos ?", "a": "Oui. Suno génère de la musique originale que vous pouvez utiliser en fond sonore pour vos vidéos (avec un plan payant pour les droits commerciaux). C'est une alternative à des bibliothèques comme Epidemic Sound."}]$x$::jsonb
 WHERE slug = 'elevenlabs' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Suno vs ElevenLabs — qual é a diferença?", "a": "Suno gera músicas completas com instrumentos e vocal cantado. ElevenLabs gera fala realista para narração e dublagem. São ferramentas de áudio diferentes: Suno para música; ElevenLabs para voz falada."}, {"q": "Suno pode criar música em português?", "a": "Sim, Suno pode gerar músicas com letras em português. Você pode especificar o idioma e o estilo musical. A qualidade das letras em português é boa, mas pode ter nuances menos precisas que em inglês."}, {"q": "ElevenLabs pode cantar?", "a": "ElevenLabs é focado em fala, não em canto. Para criar voz cantada, Suno é mais adequado. ElevenLabs tem recursos limitados de entonação que podem simular certo ritmo, mas não é um gerador de música."}, {"q": "ElevenLabs tem plano gratuito?", "a": "Sim, ElevenLabs tem plano gratuito com 10.000 caracteres por mês — suficiente para testar. Planos pagos a partir de $5/mês para uso comercial."}]$x$::jsonb
 WHERE slug = 'elevenlabs' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Elicit o Consensus para investigación académica?", "a": "Elicit es mejor para procesar grandes volúmenes de papers — extrae datos estructurados y hace revisiones sistemáticas. Consensus es mejor para preguntas específicas sobre evidencia — te dice qué porcentaje de estudios apoyan una afirmación. Para revisar literatura — Elicit; para verificar claims — Consensus."}, {"q": "¿Elicit es gratuito?", "a": "Elicit tiene un plan gratuito con acceso limitado. El plan Plus ($12/mes) ofrece más créditos para búsqueda y extracción. Consensus tiene un plan gratuito limitado; el plan Premium ($9.99/mes) desbloquea todas las funciones de búsqueda científica."}, {"q": "¿Qué bases de datos usa Elicit?", "a": "Elicit usa principalmente Semantic Scholar, que indexa más de 200 millones de papers académicos de múltiples disciplinas. También se integra con otras fuentes. La cobertura es amplia pero puede no incluir papers muy recientes o de acceso restringido."}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Elicit vs Consensus: Was ist der Unterschied?", "a": "Elicit ist für systematische Literatur-Reviews konzipiert: Es extrahiert strukturierte Daten aus Papers für tiefe Analysen. Consensus gibt schnelle evidenzbasierte Antworten mit Konsensmessung. Elicit für Forscher; Consensus für schnelle wissenschaftliche Antworten."}, {"q": "Ist Elicit kostenlos?", "a": "Elicit hat einen kostenlosen Plan mit begrenzten Papier-Analysen. Plus ab $12/Monat. Consensus hat einen kostenlosen Plan; Premium ab $11,99/Monat. Beide haben kostenlose Testphasen."}, {"q": "Kann Elicit auf Deutsch arbeiten?", "a": "Elicit analysiert primär englischsprachige wissenschaftliche Papers da die meisten Studien auf Englisch veröffentlicht werden. Die Oberfläche ist auf Englisch. Für deutschsprachige Forschungsliteratur gibt es weniger Unterstützung."}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Elicit?", "a": "Elicit — ИИ-ассистент для исследований, разработанный для систематических обзоров литературы. Ищет в академических базах данных, отбирает статьи по релевантности и извлекает структурированные данные в таблицы — автоматизируя наиболее трудоёмкие части академических исследований."}, {"q": "В чём разница между Elicit и Consensus?", "a": "Elicit создан для систематических обзоров — извлекает структурированные данные из статей для мета-анализа. Consensus создан для быстрых вопросов и ответов — синтезирует выводы в ответы на понятном языке со счётчиком консенсуса. Elicit — для глубоких рабочих процессов, Consensus — для быстрых ответов."}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Elicit vs Consensus — яка різниця?", "a": "Elicit — потужний інструмент для автоматизації систематичних оглядів і витягування даних. Consensus — простіший пошук наукового консенсусу з візуальним індикатором. Elicit для глибоких досліджень; Consensus для швидких перевірок тверджень."}, {"q": "Elicit безкоштовний?", "a": "Elicit має безкоштовний план з обмеженнями. Plus від $12/міс. Consensus безкоштовний з базовими функціями; Premium від $9,99/міс."}, {"q": "Elicit замінює PubMed?", "a": "Ні. PubMed — вичерпна база даних медичної літератури. Elicit використовує Semantic Scholar і інші бази як джерела. Для повного покриття медичної літератури PubMed незамінний; Elicit прискорює аналіз знайдених статей."}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Elicit לעומת Consensus – מה ההבדל?", "a": "Elicit מיועד לחקירה עמוקה ולניתוח כמויות גדולות של מאמרים. Consensus מיועד לשאלות מהירות על קונצנזוס מדעי. Elicit לחוקרים; Consensus לאישור טענות מדעיות."}, {"q": "האם Elicit חינמי?", "a": "Elicit מציע גישה חינמית מוגבלת. Plus ב-$12/חודש. Consensus מציע תוכנית חינמית; Premium ב-$9.99/חודש."}, {"q": "Elicit לעומת Google Scholar – מה עדיף?", "a": "Google Scholar הוא מנוע חיפוש למאמרים. Elicit ממיר את המחקרים לסיכומים ומחלץ נתונים. שניהם משלימים – חפשו ב-Scholar, נתחו ב-Elicit."}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Elicit vs Consensus — lequel est le meilleur ?", "a": "Elicit est meilleur pour la recherche académique approfondie et l'extraction de données de papers. Consensus est meilleur pour comprendre rapidement ce que la science dit sur un sujet. Chercheurs en revue de littérature → Elicit ; curiosité scientifique rapide → Consensus."}, {"q": "Elicit est-il gratuit ?", "a": "Elicit a un plan gratuit avec des limites. Les plans payants à partir de 12 $/mois. Consensus a un plan gratuit ; Premium à partir de 8,99 $/mois."}, {"q": "Elicit peut-il analyser des articles en français ?", "a": "Elicit indexe principalement la littérature scientifique anglophone. Pour la recherche en langue française, les résultats peuvent être limités. La plupart de la recherche scientifique internationale est publiée en anglais."}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Elicit vs Consensus — qual é a diferença?", "a": "Elicit é para extração sistemática de dados de papers — mais técnico e completo. Consensus é para entender rapidamente se a ciência suporta uma afirmação — mais acessível. Para revisões de literatura, Elicit; para verificação de fatos científicos, Consensus."}, {"q": "Elicit é gratuito?", "a": "Elicit tem plano gratuito com 5.000 créditos. Planos pagos a partir de $10/mês. Consensus tem plano gratuito; planos pagos a partir de $9,99/mês."}, {"q": "Elicit pode substituir o processo de revisão sistemática?", "a": "Elicit automatiza partes do processo mas não substitui completamente. Ele acelera a triagem e extração de dados, mas a interpretação e síntese ainda requerem julgamento especializado humano."}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Figma AI puede generar código?", "a": "Figma tiene Dev Mode que muestra código CSS, iOS y Android de los diseños. También hay plugins como Figma to Code. Figma AI está desarrollando capacidades de generación de código más directas. Claude genera código desde cero; Figma convierte diseños existentes a código."}]$x$::jsonb
