UPDATE tools SET faq = $x$[{"q": "Kann Figma AI einen ganzen Screen generieren?", "a": "Figma AI kann erste Wireframe-Entwürfe und Komponenten-Varianten generieren. Für vollständige Screen-Generierung aus Text sind spezialisierte Tools wie UXpilot oder Uizard leistungsfähiger. Figma AI ist stärker als Produktivitäts-Boost im bestehenden Workflow."}, {"q": "Figma AI vs Adobe Firefly für Design: Was ist besser?", "a": "Sie lösen verschiedene Probleme. Figma AI unterstützt UI/UX-Design-Workflows mit Wireframes und Komponenten. Adobe Firefly generiert Bilder für Design-Assets. Für UI-Design — Figma AI; für Bildgenerierung in Design-Projekten — Firefly."}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Какие ИИ-функции есть у Figma?", "a": "Figma AI (запущен в 2024 году) включает генерацию макетов по текстовым запросам, умное переименование слоёв, создание прототипов и визуальный поиск. Доступен всем пользователям платных планов."}, {"q": "Может ли Canva заменить Figma?", "a": "Нет. Canva и Figma решают разные задачи. Canva — для создания маркетингового контента и презентаций. Figma — для проектирования UI/UX-интерфейсов и прототипов продуктов. Дизайнеры используют Figma, создатели контента — Canva."}]$x$::jsonb
