UPDATE tools SET faq = $x$[{"q": "Claude для дизайну vs Figma AI — що обрати?", "a": "Claude кращий для стратегічних дизайн-обговорень, документації і генерації коду. Figma AI кращий для безпосередньої роботи всередині Figma. Використовуйте Claude для мислення і документації; Figma AI для виконання у дизайн-файлах."}, {"q": "Figma AI безкоштовний?", "a": "Деякі функції Figma AI включені у платні плани Figma. Professional від $15/редактор/міс. Claude має безкоштовний план; Pro від $20/міс."}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Claude לעיצוב לעומת Figma AI?", "a": "Claude מצוין לתכנון, משוב ותיעוד. Figma AI פועל בתוך Figma ליצירת Mockups ו-Wireframes. Claude ל-UX Thinking; Figma AI לביצוע בכלי."}, {"q": "Figma AI כמה עולה?", "a": "Figma AI כלול בתוכניות Figma; Professional מ-$15/editor/חודש. Claude Pro ב-$20/חודש."}, {"q": "Figma Make – מה זה?", "a": "Figma Make הופך עיצובי Figma לקוד React/HTML פונקציונלי. עדיין בשלבי Beta, אך מציע bridge בין עיצוב לפיתוח."}]$x$::jsonb
