UPDATE tools SET faq = $x$[{"q": "Claude vs Figma AI pour le design — quelle est la différence ?", "a": "Claude génère du code de design (React, CSS) à partir de descriptions. Figma AI génère des composants visuels directement dans Figma. Pour les développeurs créant des interfaces en code → Claude ; pour les designers travaillant visuellement → Figma AI."}, {"q": "Figma AI est-il inclus dans Figma ?", "a": "Oui. Les fonctionnalités IA de Figma sont intégrées dans l'application. Certaines fonctionnalités IA avancées peuvent nécessiter un plan payant. Figma a un plan gratuit ; Professional à partir de 15 $/éditeur/mois."}]$x$::jsonb
