UPDATE tools SET faq = $x$[{"q": "¿Fireflies puede integrarse con Salesforce?", "a": "Sí. Fireflies tiene integración directa con Salesforce, HubSpot y otros CRM. Puede crear automáticamente notas de llamada en el CRM después de cada reunión, sincronizar resúmenes y actualizar deals. Esta integración es una de las razones principales por las que equipos de ventas lo prefieren."}]$x$::jsonb
 WHERE slug = 'fireflies-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Otter AI vs Fireflies AI: Was ist der Unterschied?", "a": "Otter ist stärker bei präziser Echtzeit-Transkription und einfacher Benutzeroberfläche. Fireflies ist stärker bei CRM-Integration, Sales-Intelligence und automatischen Meeting-Zusammenfassungen mit Aktionspunkten. Für Transkription — Otter; für Sales-Teams — Fireflies."}, {"q": "Fireflies AI für Verkaufs-Teams: Lohnt es sich?", "a": "Ja. Fireflies hat spezifische Sales-Features: Call-Analyse, Deal-Tracking-Integration, CRM-Sync und Coaching-Einblicke. Für Sales-Teams die jedes Meeting automatisch in CRM-Updates und Follow-up-Aktionen umwandeln wollen ist es sehr wertvoll."}]$x$::jsonb
 WHERE slug = 'fireflies-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Otter.ai vs Fireflies.ai — в чём разница?", "a": "Оба транскрибируют встречи, но с разными акцентами. Otter.ai известен высокой точностью транскрипции в реальном времени и интеграцией с Salesforce. Fireflies.ai предлагает более широкую языковую поддержку, аналитику разговоров и больше CRM-интеграций."}, {"q": "Точность Fireflies.ai хороша?", "a": "Fireflies.ai обеспечивает хорошую точность транскрипции для большинства языков. Otter.ai традиционно лидирует по точности для английского языка. На акцентах и технической лексике оба могут ошибаться."}]$x$::jsonb
 WHERE slug = 'fireflies-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Otter.ai vs Fireflies.ai — яка різниця?", "a": "Otter.ai сильніший для транскрипції в реальному часі і особистої продуктивності. Fireflies.ai кращий для команд продажів з CRM-інтеграціями і пошуком по зустрічах. Otter для особистого використання; Fireflies для командного і продажового."}, {"q": "Ці інструменти записують без дозволу?", "a": "Обидва боти просять дозвіл перед входом у зустріч. Otter.ai і Fireflies.ai видимі для всіх учасників. Завжди повідомляйте учасників що зустріч записується — це вимога законодавства у більшості країн."}, {"q": "Fireflies.ai підтримує українську мову?", "a": "Fireflies.ai підтримує транскрипцію кількох мов але якість для української може бути нижчою ніж для англійської. Перевіряйте актуальні мовні можливості на сайті Fireflies."}]$x$::jsonb
 WHERE slug = 'fireflies-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Otter.ai לעומת Fireflies.ai – מה ההבדל?", "a": "שניהם מתמללים פגישות, אך Otter.ai מדגיש תמלול חי ב-Zoom. Fireflies.ai מדגיש אוטומציה – שולח סיכומים ל-CRM ויוצר פריטי פעולה. Otter לתמלול; Fireflies לאינטגרציה עסקית."}, {"q": "Fireflies.ai לצוותי מכירות – האם זה שווה?", "a": "כן. Fireflies.ai מתאים מאוד לצוותי מכירות – תיעוד שיחות, אינטגרציה עם Salesforce ו-HubSpot, ויצירת פריטי פעולה אוטומטית. חוסך שעות תיעוד ידני שבועיות."}]$x$::jsonb
 WHERE slug = 'fireflies-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Otter.ai vs Fireflies.ai — lequel est le meilleur ?", "a": "Otter.ai est meilleur pour la transcription en temps réel et les notes de réunion simples. Fireflies est meilleur pour l'intelligence de réunion avancée et les intégrations CRM. Individus et petites équipes → Otter ; équipes de vente avec CRM → Fireflies."}, {"q": "Fireflies peut-il rejoindre automatiquement les réunions ?", "a": "Oui. Fireflies a un bot (Fred) qui rejoint automatiquement vos réunions Zoom, Teams et Google Meet. Vous n'avez rien à faire — Fred enregistre, transcrit et génère un résumé automatiquement après chaque réunion."}]$x$::jsonb
 WHERE slug = 'fireflies-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Otter AI vs Fireflies AI — qual é o melhor?", "a": "Otter AI é melhor para transcrição individual e reuniões de equipe gerais. Fireflies AI é melhor para equipes de vendas com análise de conversa. Para uso geral, Otter; para vendas e CS, Fireflies."}, {"q": "Fireflies AI pode participar de reuniões automaticamente?", "a": "Sim, Fireflies AI pode ser configurado para entrar automaticamente nas reuniões de acordo com seu calendário. Ele aparece como participante e transcreve a reunião inteira."}]$x$::jsonb
 WHERE slug = 'fireflies-ai' AND lang = 'pt';

