UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Pine Script ?", "a": "Pine Script est le langage de programmation propriétaire de TradingView pour créer des indicateurs et systèmes de trading personnalisés. Vous pouvez écrire et backtester vos propres indicateurs techniques. La communauté partage des milliers d'indicateurs Pine Script gratuitement."}, {"q": "Finchat pour les actions françaises — est-il efficace ?", "a": "Finchat couvre les marchés internationaux incluant les actions françaises (CAC40). La profondeur de l'analyse IA peut être moindre pour les petites capitalisations françaises que pour les grandes entreprises américaines où plus de documentation est disponible."}]$x$::jsonb
