UPDATE tools SET faq = $x$[{"q": "¿FlutterFlow o React Native para apps móviles?", "a": "FlutterFlow es no-code — mucho más rápido para empezar sin programar. React Native requiere conocimientos de JavaScript pero da más control. FlutterFlow para MVPs rápidos y no-técnicos; React Native para equipos de desarrollo con control total. FlutterFlow puede exportar código Flutter si necesitas."}, {"q": "¿FlutterFlow es gratuito?", "a": "FlutterFlow tiene plan gratuito con funciones básicas. Los planes de pago empiezan desde $30/mes (Standard) para publicar en app stores y acceder a más funciones. Bubble tiene plan gratuito; producción desde $32/mes."}, {"q": "¿Pueden publicarse apps de FlutterFlow en App Store?", "a": "Sí. FlutterFlow genera código Flutter real que puedes compilar y publicar en App Store (iOS) y Play Store (Android). Bubble web apps pueden funcionar en móvil pero no se publican como apps nativas en tiendas de apps."}, {"q": "¿FlutterFlow o Adalo para apps móviles sin código?", "a": "FlutterFlow usa Flutter (más moderno) y produce apps de mayor calidad y rendimiento. Adalo es más fácil para principiantes. FlutterFlow tiene mayor curva de aprendizaje pero mejor resultado final — especialmente para apps complejas con Firebase."}]$x$::jsonb
 WHERE slug = 'flutterflow' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "FlutterFlow vs React Native: Was ist besser?", "a": "FlutterFlow generiert Flutter-Code für native iOS/Android-Apps ohne tiefe Programmierkenntnisse. React Native erfordert JavaScript-Kenntnisse aber ist flexibler. FlutterFlow für schnellere Entwicklung; React Native für Entwickler mit JS-Erfahrung."}, {"q": "Ist FlutterFlow kostenlos?", "a": "FlutterFlow hat einen kostenlosen Plan mit eingeschränkten Features. Standard ab $30/Monat, Pro ab $70/Monat. Das Code-Export-Feature ist in kostenpflichtigen Plänen enthalten. Bubble hat einen kostenlosen Plan; ab $29/Monat zum Veröffentlichen."}, {"q": "Kann FlutterFlow in den App Store veröffentlichen?", "a": "Ja. FlutterFlow kann direkt in den Apple App Store und Google Play Store veröffentlichen. Das ist einer der größten Vorteile gegenüber Bubble das primär Web-Apps produziert."}, {"q": "FlutterFlow für Startups: Ist es gut?", "a": "FlutterFlow ist ausgezeichnet für Startups die eine mobile App schnell launchen wollen. Sie können einen MVP in Wochen statt Monaten bauen. Der Code-Export bedeutet kein Vendor Lock-in — Sie können die Entwicklung später mit Entwicklern weiterführen."}]$x$::jsonb
 WHERE slug = 'flutterflow' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между FlutterFlow и Bubble?", "a": "FlutterFlow создаёт нативные мобильные приложения (iOS и Android) на Flutter — выводит настоящий Flutter-код. Bubble создаёт веб-приложения со сложной логикой и базами данных, доступные через браузер. FlutterFlow — для мобильных, Bubble — для веб-приложений."}, {"q": "Может ли FlutterFlow экспортировать код?", "a": "Да. FlutterFlow может экспортировать готовый к продакшну код Flutter/Dart на GitHub или скачать локально. Можно начать визуально и продолжить разработку в коде — вы не привязаны к платформе."}]$x$::jsonb
 WHERE slug = 'flutterflow' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "FlutterFlow vs React Native — яка різниця?", "a": "FlutterFlow — visual builder для Flutter без написання коду. React Native — framework де потрібно писати JavaScript код. FlutterFlow швидший для старту без програмування; React Native гнучкіший для розробників."}, {"q": "FlutterFlow безкоштовний?", "a": "FlutterFlow має безкоштовний план без публікації. Standard від $30/міс. Bubble безкоштовний для розробки; Starter від $32/міс."}, {"q": "FlutterFlow для iOS — підходить?", "a": "Так. FlutterFlow будує нативні iOS-застосунки через Flutter. Вам потрібен Mac і Apple Developer акаунт ($99/рік) для публікації в App Store."}]$x$::jsonb
 WHERE slug = 'flutterflow' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "FlutterFlow vs Bubble — lequel est le meilleur ?", "a": "FlutterFlow est pour les applications mobiles natives (iOS/Android). Bubble est pour les applications web. Si vous ciblez mobile → FlutterFlow ; si vous ciblez web → Bubble."}, {"q": "FlutterFlow est-il gratuit ?", "a": "FlutterFlow a un plan gratuit avec des limitations. Standard à partir de 30 $/mois. Bubble a un plan gratuit ; Personal à partir de 32 $/mois."}, {"q": "Le code Flutter de FlutterFlow est-il réutilisable ?", "a": "Oui. FlutterFlow peut exporter du code Flutter que des développeurs peuvent modifier et continuer. C'est un avantage important par rapport à Bubble dont le code n'est pas exportable."}, {"q": "FlutterFlow nécessite-t-il des compétences en code ?", "a": "Non. FlutterFlow est no-code pour la plupart des fonctionnalités. Pour des fonctionnalités très personnalisées, vous pouvez ajouter du code Dart personnalisé. La plupart des apps peuvent être créées sans aucune programmation."}]$x$::jsonb
 WHERE slug = 'flutterflow' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "FlutterFlow vs Bubble — qual escolher?", "a": "FlutterFlow é para apps móveis nativos. Bubble é para aplicativos web. Se precisa de um app nas lojas, FlutterFlow; se precisa de um produto web, Bubble."}, {"q": "FlutterFlow é gratuito?", "a": "FlutterFlow tem plano gratuito com funcionalidades limitadas. Planos pagos a partir de $30/mês. Bubble tem plano gratuito para desenvolvimento; produção a partir de $29/mês."}, {"q": "FlutterFlow gera código Flutter real?", "a": "Sim, FlutterFlow gera código Dart/Flutter que você pode exportar e continuar desenvolvendo no seu IDE favorito. Esta é uma grande vantagem — você não fica preso na plataforma."}, {"q": "FlutterFlow pode criar apps para web também?", "a": "Sim, Flutter e FlutterFlow podem criar apps para web, iOS, Android e desktop. No entanto, para sites de marketing e web apps complexos, Webflow ou Bubble podem ser mais adequados."}]$x$::jsonb
 WHERE slug = 'flutterflow' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Flux es mejor que Midjourney?", "a": "Depende del caso. Midjourney V7 sigue siendo superior en calidad artística consistente y fotorrealismo extremo. FLUX.1 Pro compite directamente y tiene ventajas en adherencia al prompt y control técnico. Para arte general — Midjourney; para control y uso via API — Flux."}, {"q": "¿Qué es FLUX.1?", "a": "FLUX.1 es la familia de modelos de generación de imágenes de Black Forest Labs (fundadores de Stable Diffusion). Incluye variantes: [schnell] (rápido, libre), [dev] (calidad alta, open-weights) y [pro] (la mejor calidad, API). Es el principal competidor open-source de Midjourney en 2025."}, {"q": "¿Cómo accedo a FLUX sin Discord?", "a": "Flux está disponible en Replicate (pago por uso), fal.ai, API de Black Forest Labs, ComfyUI (local) y muchas plataformas de imágenes IA. Midjourney requiere Discord o su web app."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Flux vs Midjourney: Was ist besser?", "a": "Midjourney führt bei künstlerischer Qualität und ästhetischer Ausgereiftheit. Flux (Black Forest Labs) ist stärker beim Fotorealismus und kostenlos als Open-Weights-Modell verfügbar. Für kreative Kunst — Midjourney; für fotorealistische Bilder und API-Integration — Flux."}, {"q": "Ist Flux kostenlos?", "a": "Flux.1 Schnell und Flux.1 Dev sind Open-Source und können kostenlos lokal betrieben werden. Flux Pro und Flux 1.1 Pro sind über APIs wie Replicate, fal.ai oder Together AI verfügbar mit Pay-per-Image-Preisen. Midjourney kostet ab $10/Monat."}, {"q": "Kann Flux lokal ausgeführt werden?", "a": "Ja. Flux.1 Dev und Flux.1 Schnell können lokal mit ComfyUI oder ähnlichen Tools ausgeführt werden. Sie benötigen eine leistungsstarke GPU (mindestens 8 GB VRAM). Das macht Flux praktisch kostenlos für technische Nutzer."}, {"q": "Welches Modell ist besser für Logos?", "a": "Weder Midjourney noch Flux sind ideal für Logos da sie keine Vektorgrafiken ausgeben. Für Logos sind spezialisierte Tools wie Looka, Recraft oder Adobe Illustrator besser geeignet. Für Konzept-Moodboards und visuelle Inspiration sind beide gut."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Flux vs Midjourney — что лучше?", "a": "Midjourney V7 превосходит по художественному качеству и эстетике. Flux (FLUX.1) превосходит по реализму фотографий, точному следованию тексту в изображении и возможности локального запуска. Выбор зависит от задачи: Midjourney для арта, Flux для реалистичного контента."}, {"q": "Flux бесплатный?", "a": "FLUX.1 [schnell] — самая быстрая версия — доступна бесплатно с открытой лицензией через Hugging Face и ComfyUI. FLUX.1 [dev] — для некоммерческого использования. FLUX.1 [pro] — через API с оплатой за использование."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Midjourney מול Flux — מה עדיף?", "a": "Midjourney ידוע באיכות אמנותית וקהילה חזקה. Flux (Black Forest Labs) מציע ביצועים תחרותיים ופריסה גמישה יותר. לתמונות אמנותיות ולאסתטיקה — Midjourney; לגמישות מפתחים — Flux."}, {"q": "Flux מול Stable Diffusion — מה ההבדל?", "a": "Flux מ-Black Forest Labs — נוצר על ידי חלק ממייסדי Stable Diffusion. Flux מציע איכות תמונה גבוהה יותר ממודלי Stable Diffusion הבסיסיים. שניהם פתוחים ונתמכים על ידי קהילת ComfyUI."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Midjourney vs Flux — qual é o melhor?", "a": "Midjourney tem qualidade artística superior e é mais fácil de usar via Discord. Flux oferece mais controle técnico e é open-source. Para uso criativo, Midjourney; para integração em produtos e uso técnico, Flux."}, {"q": "Flux é realmente open-source?", "a": "Sim, Flux.1 da Black Forest Labs é open-source. Os modelos Schnell (gratuito) e Dev estão disponíveis para uso não comercial. O modelo Pro é mais restritivo."}, {"q": "Flux vs Stable Diffusion — qual é a diferença?", "a": "Flux é mais novo e gera imagens de melhor qualidade que versões antigas do Stable Diffusion. Stable Diffusion tem um ecossistema maior com mais ferramentas e modelos customizados. Para qualidade, Flux; para flexibilidade e comunidade, Stable Diffusion."}]$x$::jsonb
 WHERE slug = 'flux' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Framer AI genera el código real del sitio?", "a": "Sí. Framer AI genera el diseño real del sitio — no es un mockup sino un sitio publicable directamente. Genera código React que se compila y sirve. Puedes editar el resultado visualmente o en código si tienes conocimientos técnicos."}]$x$::jsonb
