UPDATE tools SET faq = $x$[{"q": "Framer AI vs Webflow: Wer gewinnt für Landing-Pages?", "a": "Framer gewinnt für schnelle, animierte Landing-Pages. Webflow ist besser wenn die Landing-Page Teil einer größeren Content-Strategie mit CMS ist. Für kreative Einzel-Landing-Pages — Framer; für mehrseitige Websites mit CMS — Webflow."}]$x$::jsonb
