UPDATE tools SET faq = $x$[{"q": "Что такое Framer AI?", "a": "Framer AI — конструктор сайтов, где вы описываете свой сайт в тексте, и ИИ создаёт полноценный, стилизованный сайт. Затем можно редактировать дизайн визуально, добавлять CMS-контент и публиковать на живой URL с собственным доменом."}, {"q": "Может ли Canva создать сайт?", "a": "У Canva есть базовая функция конструктора сайтов, но она ограничена по сравнению с Framer или Webflow. Сайтам Canva не хватает продвинутых анимаций, функциональности CMS и контроля дизайна. Canva — для графики, Framer — для настоящих сайтов."}]$x$::jsonb
