UPDATE tools SET faq = $x$[{"q": "¿Qué es Frase y para qué sirve?", "a": "Frase es una herramienta de IA para creación de contenido SEO. Analiza el contenido del top 10 para una palabra clave, genera briefings automáticos y ayuda a escribir y optimizar el artículo. Es más específica que SEMrush: se centra en crear contenido que rankea, no en análisis técnico SEO."}, {"q": "¿Frase vs SurferSEO: cuál es mejor?", "a": "Ambas son herramientas de optimización de contenido. Frase destaca en la investigación de SERP y generación de briefings; SurferSEO es más fuerte en la puntuación de contenido en tiempo real. Muchos profesionales del contenido prefieren Frase por su capacidad de resumir lo que cubre la competencia."}, {"q": "¿Frase es gratuito?", "a": "Frase ofrece una prueba gratuita de 5 días. Los planes de pago empiezan desde $45/mes (Solo). SEMrush tiene una prueba gratuita limitada; los planes de pago desde $139.95/mes."}, {"q": "¿Puede Frase reemplazar a SEMrush?", "a": "No. Frase es una herramienta de contenido; SEMrush es una suite SEO completa. Frase no tiene análisis de backlinks, auditoría técnica o seguimiento de rankings. Son complementarias: SEMrush para encontrar oportunidades, Frase para ejecutar el contenido."}]$x$::jsonb
 WHERE slug = 'frase' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Frase?", "a": "Frase ist ein SEO-Content-Tool das SERP-Ergebnisse analysiert, Content-Briefs generiert und einen KI-Schreibassistenten für die Artikel-Erstellung bietet. Es hilft, Artikel zu erstellen die thematisch vollständig sind und bessere Chancen haben zu ranken."}, {"q": "Ist Frase günstiger als SEMrush?", "a": "Ja. Frase beginnt ab $15/Monat (Solo) bis $115/Monat (Team). SEMrush beginnt ab $139,95/Monat. Frase ist spezialisierter auf Content-Erstellung; SEMrush ist eine vollständige SEO-Suite."}, {"q": "Frase vs Surfer SEO: Was ist besser?", "a": "Beide sind Content-Optimierungstools. Frase ist stärker bei der automatischen Content-Brief-Generierung und dem Fragen-Recherche-Feature. Surfer SEO hat einen detaillierteren Echtzeit-Content-Score. Viele Teams testen beide in einer Testphase."}, {"q": "Kann Frase deutschen Content optimieren?", "a": "Ja. Frase analysiert Google-SERPs für jede Sprache inklusive Deutsch. Sie geben Ihr deutsches Keyword ein und Frase analysiert, was auf den Top-Ergebnisseiten zu finden ist."}]$x$::jsonb
 WHERE slug = 'frase' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Frase чи Surfer SEO — яка різниця?", "a": "Обидва фокусуються на контенті. Frase сильніший у дослідженні і автоматичній генерації структури. Surfer SEO сильніший у точній on-page оптимізації і підрахунку термінів. Багато авторів використовують обидва."}, {"q": "Frase безкоштовний?", "a": "Frase має безкоштовний пробний період. Solo план — $15/міс, Basic — $45/міс, Team — $115/міс. SEMrush від $139,95/міс."}, {"q": "Чи замінює Frase SEMrush?", "a": "Ні. Frase замінює тільки частину SEMrush — контентну. Для ключових слів, зворотних посилань, аудиту і PPC вам все одно потрібен SEMrush або Ahrefs. Frase і SEMrush доповнюють одне одного."}]$x$::jsonb
 WHERE slug = 'frase' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Frase מול SEMrush — מה לבחור?", "a": "Frase מתמחה ביצירת תוכן ואופטימיזציה on-page. SEMrush הוא חבילת SEO מלאה. לכותבי תוכן SEO — Frase; לניהול SEO מקיף — SEMrush."}, {"q": "כמה עולה Frase?", "a": "Frase מ-14.99$/חודש (Solo) עד 44.99$/חודש (Basic) ו-114.99$/חודש (Team). SEMrush מ-139.95$/חודש. Frase הרבה יותר זול."}, {"q": "האם Frase AI טוב לכתיבה?", "a": "Frase AI מצוין ליצירת קווי מתאר לתוכן ופסקאות ממוקדות-SEO. לתוכן ברמה גבוהה דרושה עריכה אנושית. לכותבי תוכן שרוצים מחקר-ויצירה-אופטימיזציה בכלי אחד — Frase היא אפשרות מצוינת."}, {"q": "Frase מול Surfer SEO — מה ההבדל?", "a": "שניהם כלי אופטימיזציית תוכן. Frase חזקה יותר ביצירת AI ובמחקר שאלות. Surfer SEO חזק יותר בציון תוכן ובניתוח גורמי דירוג. רבים משתמשים בשניהם יחד."}]$x$::jsonb
 WHERE slug = 'frase' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Frase vs SEMrush — quelle est la différence ?", "a": "Frase se spécialise dans la recherche et la rédaction de contenu : il crée des briefs et aide à rédiger des articles SEO. SEMrush est une suite SEO complète. Si vous produisez du contenu SEO, Frase ; si vous gérez du SEO complet, SEMrush."}, {"q": "Frase est-il gratuit ?", "a": "Frase a un plan Solo à 15 $/mois, Basic à 45 $/mois. SEMrush à partir de 139,95 $/mois. Frase est bien moins cher pour la création de contenu."}, {"q": "Frase vs Surfer SEO — lequel est le meilleur ?", "a": "Les deux optimisent le contenu basé sur les données SERP. Frase est meilleur pour les briefs de contenu et la recherche initiale. Surfer est meilleur pour l'optimisation en temps réel pendant la rédaction. Beaucoup d'équipes utilisent les deux en séquence."}, {"q": "Frase génère-t-il du contenu IA ?", "a": "Oui. Frase dispose d'un outil de rédaction IA qui génère des ébauches basées sur les données SERP. Il est conçu pour la rédaction SEO, avec des suggestions intégrées de mots-clés et de structure basées sur ce qui se classe."}]$x$::jsonb
 WHERE slug = 'frase' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Frase vs SEMrush — qual escolher?", "a": "Frase é focado em criação e otimização de conteúdo a um preço acessível. SEMrush é uma suite SEO completa para análise técnica, backlinks e PPC. Para conteúdo, Frase; para SEO abrangente, SEMrush."}, {"q": "Frase é gratuito?", "a": "Frase tem teste gratuito. Planos pagos a partir de $15/mês (Solo). SEMrush tem versão gratuita limitada; Pro a partir de $139,95/mês."}, {"q": "Frase AI é bom para escrever?", "a": "Frase AI é adequado para gerar rascunhos orientados por SEO rapidamente. Para conteúdo mais criativo e matizado, Jasper ou ChatGPT podem ser melhores. Frase se destaca na análise de SERPs e briefings de conteúdo."}, {"q": "Frase vs SurferSEO — qual é a diferença?", "a": "Ambos ajudam na otimização de conteúdo. Frase tem melhor pesquisa e resumo de conteúdo de concorrentes. SurferSEO tem melhor pontuação de conteúdo em tempo real e recursos de auditoria de site. Frase é geralmente mais barato."}]$x$::jsonb
 WHERE slug = 'frase' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Gamma o Prezi para presentaciones educativas?", "a": "Prezi puede ser más memorable para presentaciones donde la estructura espacial ayuda a entender relaciones entre conceptos (mapas mentales, timelines). Gamma es más rápido para crear y mejor para texto e imágenes generados por IA. Para profesores con poco tiempo — Gamma; para presentaciones educativas visuales únicas — Prezi."}, {"q": "¿Gamma puede hacer el efecto zoom de Prezi?", "a": "No. Gamma genera presentaciones con estilo de slides tradicional mejoradas con diseño IA. El zoom dinámico espacial es la característica distintiva de Prezi y no está replicado en Gamma. Para narrativa con zoom — Prezi es único en el mercado."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Gamma vs Prezi: Was ist besser?", "a": "Gamma ist besser für schnelle KI-generierte Präsentationen mit modernem Design. Prezi ist einzigartiger mit seinem zoombaren Canvas-Ansatz der Zusammenhänge visuell darstellt. Gamma für Geschwindigkeit und Einfachheit; Prezi für nicht-lineares Storytelling."}, {"q": "Kann Gamma auf Deutsch Präsentationen erstellen?", "a": "Ja. Gamma versteht deutsche Prompts und erstellt Präsentationen auf Deutsch. Geben Sie Ihren Prompt auf Deutsch ein und Gamma generiert deutschsprachige Folien mit passenden Layouts."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между Gamma и Notion AI?", "a": "Gamma — генератор презентаций: создаёт визуальные слайд-колоды из текстовых запросов. Notion AI — ассистент внутри Notion для написания, суммирования и запросов к документам. Gamma создаёт презентации, Notion AI улучшает ведение заметок и управление знаниями."}, {"q": "Gamma подходит для бизнеса?", "a": "Да. Gamma используется для продажных колод, клиентских презентаций, питчей инвесторам, внутренних отчётов и обучающих материалов. Аналитика просмотров (кто открыл колоду, сколько времени провёл на каждой карточке) особенно полезна для продаж."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Gamma чи Prezi — що краще?", "a": "Gamma краще для швидких ШІ-презентацій із сучасним дизайном. Prezi унікальний з його зумуючим canvas-підходом що показує зв'язки. Gamma для швидкості і простоти; Prezi для нелінійного сторітелінгу."}, {"q": "Gamma може створювати презентації українською?", "a": "Так. Gamma розуміє українські промпти і створює презентації. Введіть запит українською і Gamma згенерує слайди з відповідним контентом і макетами."}, {"q": "Gamma vs PowerPoint — в чому різниця?", "a": "Gamma генерує презентації з ШІ і публікує їх як веб-сторінки. PowerPoint — традиційний офлайн-редактор з повним контролем над дизайном. Gamma для швидкого старту; PowerPoint для точного контролю."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Gamma לעומת Prezi – מה עדיף?", "a": "Gamma מהיר יותר עם AI generation ומצגות web. Prezi ייחודי עם Canvas zooming. Gamma לעיצוב מהיר; Prezi להצגה חיה מרשימה."}, {"q": "Gamma תומך בעברית?", "a": "כן, Gamma מבין פרומפטים בעברית. שימו לב שה-RTL של עברית עשוי לדרוש התאמות ידניות בפריסת השקפים."}]$x$::jsonb
