UPDATE tools SET faq = $x$[{"q": "Gamma vs Prezi — qual é o melhor?", "a": "Gamma é melhor para apresentações geradas rapidamente por IA com design moderno. Prezi é único com sua abordagem de canvas com zoom que ilustra conexões visualmente. Gamma para rapidez; Prezi para storytelling não-linear."}, {"q": "Gamma consegue criar apresentações em português?", "a": "Sim. Gamma entende prompts em português e cria apresentações em português. Digite seu prompt em português e o Gamma gera slides com conteúdo em português."}]$x$::jsonb
 WHERE slug = 'gamma' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Gemini лучше ChatGPT в 2026 году?", "a": "На задачах Google Workspace Gemini Ultra — лучший выбор. По общим бенчмаркам GPT-4o и Gemini 2.0 Ultra конкурируют. У ChatGPT больше функций (генерация изображений, голос, интерпретатор кода) и более крупная сторонняя экосистема. Gemini побеждает для пользователей Google, ChatGPT — для общего использования."}, {"q": "Gemini бесплатный?", "a": "Да. Gemini бесплатен с доступом к Gemini 1.5 Flash. Google AI Pro ($19.99/мес) открывает Gemini 2.0 Ultra и интеграцию с Google Workspace."}, {"q": "В чём разница между Gemini и Google Bard?", "a": "Bard — исходное название ИИ-чатбота Google, переименованного в Gemini в феврале 2024 года. Это один и тот же продукт — ребрендинг сопровождался значительным улучшением возможностей модели."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Gemini чи ChatGPT — що краще?", "a": "Для користувачів Google Workspace — Gemini, адже він інтегрований у Gmail, Docs і Drive. Для загального використання — ChatGPT з більшою екосистемою. Для кодування — обидва сильні; Gemini 2.5 Pro входить до найкращих у бенчмарках."}, {"q": "Чи безкоштовний Gemini?", "a": "Так, Gemini безкоштовний. Gemini Advanced (Gemini 2.5 Pro) включений у Google One AI Premium за $19,99/міс. ChatGPT безкоштовний; Plus $20/міс."}, {"q": "Чим відрізняється Gemini від Google Bard?", "a": "Bard — старіша назва. Google перейменував його на Gemini у лютому 2024 разом із оновленням моделей. Gemini 2.5 Pro значно потужніший за оригінальний Bard."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Gemini או ChatGPT — מה עדיף?", "a": "למשתמשי Google Workspace — Gemini, כי הוא משולב ב-Gmail, Docs ו-Drive. לשימוש כללי — ChatGPT עם מערכת-אקולוגית גדולה יותר. לקוד — שניהם חזקים; Gemini 2.5 Pro נמצא בין המובילים בבנצ'מרקים."}, {"q": "האם Gemini בחינם?", "a": "כן, Gemini חינמי. Gemini Advanced (Gemini 2.5 Pro) כלול ב-Google One AI Premium ב-19.99$/חודש. ChatGPT חינמי; Plus 20$/חודש."}, {"q": "מה ההבדל בין Gemini ל-Google Bard?", "a": "Bard הוא השם הישן. Google שינתה את השם ל-Gemini בפברואר 2024 יחד עם עדכון המודלים. Gemini 2.5 Pro חזק בהרבה מה-Bard המקורי."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Amazon Q Developer es gratuito?", "a": "Amazon Q Developer tiene un plan gratuito con 50 respuestas de chat y análisis de código al mes. El plan Pro ($19/usuario/mes) desbloquea uso ilimitado. GitHub Copilot tiene plan Individual ($10/mes) y Business ($19/usuario/mes). Copilot tiene prueba gratuita de 30 días; Q Developer tiene tier gratuito permanente."}, {"q": "¿Amazon Q puede reemplazar a GitHub Copilot?", "a": "Para proyectos AWS — Q Developer tiene ventaja por su profundo conocimiento del ecosistema Amazon. Para proyectos no-AWS — GitHub Copilot es más completo y versátil. Para equipos mixtos o proyectos multi-cloud — Copilot es la opción más segura."}, {"q": "¿Amazon Q Developer habla español?", "a": "Amazon Q Developer puede responder en español cuando se le hace la pregunta en español. Sin embargo, la mayor parte de su documentación de entrenamiento es en inglés, por lo que las respuestas técnicas suelen ser más precisas en inglés."}, {"q": "¿Qué IDEs soporta Amazon Q Developer?", "a": "Amazon Q Developer está integrado en VS Code, JetBrains IDEs (IntelliJ, PyCharm, etc.), AWS Cloud9, AWS Lambda console y la CLI de AWS. GitHub Copilot tiene soporte en más IDEs, incluyendo Visual Studio, Neovim y Xcode."}]$x$::jsonb
 WHERE slug = 'github-copilot' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Amazon Q Developer vs GitHub Copilot: Was ist besser?", "a": "Für AWS-Entwickler ist Amazon Q Developer überlegen: es kennt AWS-Services, CloudFormation und Best Practices tief. Für allgemeine Entwicklung ist GitHub Copilot breiter nutzbar mit besserem IDE-Support. AWS-fokussierte Teams — Amazon Q; allgemeine Entwicklung — Copilot."}, {"q": "Ist Amazon Q Developer kostenlos?", "a": "Amazon Q Developer hat einen kostenlosen Plan mit 50 Konversationen und 1.000 Code-Empfehlungen/Monat. Pro ab $19/Benutzer/Monat. GitHub Copilot Individual ab $10/Monat; Business ab $19/Benutzer/Monat."}, {"q": "Was kann Amazon Q Developer?", "a": "Amazon Q Developer kann Code vervollständigen, Fehler debuggen, Code erklären, AWS-Infrastruktur generieren (CloudFormation, CDK), Sicherheitslücken scannen und beheben, und Ihnen bei AWS-Best-Practices helfen."}, {"q": "GitHub Copilot für Deutschland: Gibt es Datenschutzoptionen?", "a": "GitHub Copilot Business und Enterprise haben erweiterte Datenschutz-Einstellungen: Code-Snippets werden nicht für Training verwendet und kein Code-Sharing mit Dritten. Für DSGVO-Compliance empfiehlt sich die Enterprise-Version mit spezifischen Datenschutz-Kontrollen."}]$x$::jsonb
 WHERE slug = 'github-copilot' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Cursor лучше GitHub Copilot?", "a": "Cursor в целом обеспечивает более мощную ИИ-помощь — контекст всей кодовой базы и многофайловое редактирование в Composer мощнее встроенных подсказок Copilot. Но Copilot поддерживает больше IDE и имеет корпоративные функции. Cursor — выбор для индивидуальных разработчиков, которые хотят лучший ИИ-опыт."}, {"q": "Можно использовать GitHub Copilot и Cursor вместе?", "a": "Да, но они будут значительно перекрываться. Большинство разработчиков выбирают один основной инструмент. Cursor обычно предпочтителен за более мощные функции, а Copilot остаётся для команд с корпоративными рабочими процессами GitHub."}]$x$::jsonb
 WHERE slug = 'github-copilot' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Amazon Q Developer vs GitHub Copilot — що краще?", "a": "Для AWS-розробників Amazon Q Developer перевершує: він знає AWS-сервіси, CloudFormation і best practices глибоко. Для загальної розробки GitHub Copilot ширше застосовується з кращою IDE-підтримкою. AWS-команди — Amazon Q; загальна розробка — Copilot."}, {"q": "Amazon Q Developer безкоштовний?", "a": "Amazon Q Developer має безкоштовний план з 50 розмовами і 1000 рекомендаціями коду/міс. Pro від $19/користувач/міс. GitHub Copilot Individual від $10/міс; Business від $19/міс."}, {"q": "GitHub Copilot і захист даних?", "a": "GitHub Copilot Business і Enterprise мають розширені налаштування конфіденційності: сніпети коду не використовуються для навчання і не передаються третім сторонам. Enterprise версія краща для відповідності корпоративним вимогам."}]$x$::jsonb
 WHERE slug = 'github-copilot' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Amazon Q Developer לעומת GitHub Copilot?", "a": "לפיתוח AWS – Amazon Q עדיף. לפיתוח כללי – GitHub Copilot רחב יותר. צוותי AWS – Amazon Q; פיתוח כללי – Copilot."}, {"q": "Amazon Q Developer חינמי?", "a": "Amazon Q מציע Free Tier עם 50 שיחות ו-1,000 המלצות/חודש; Pro ב-$19/משתמש/חודש. GitHub Copilot Individual ב-$10/חודש."}, {"q": "GitHub Copilot לישראל – פרטיות נתונים?", "a": "Copilot Business ו-Enterprise מציעים הגדרות פרטיות מורחבות. עבור קוד חסוי ורגיש, מומלץ להפעיל 'Do not match' ו-Org settings."}]$x$::jsonb
 WHERE slug = 'github-copilot' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Amazon Q Developer vs GitHub Copilot — lequel est le meilleur ?", "a": "Pour les développeurs AWS, Amazon Q Developer est supérieur : il connaît profondément les services AWS, CloudFormation et les bonnes pratiques. Pour le développement général, GitHub Copilot est plus largement utilisable. Équipes AWS → Amazon Q ; développement général → Copilot."}, {"q": "Amazon Q Developer est-il gratuit ?", "a": "Amazon Q Developer a un plan gratuit avec 50 conversations et 1 000 recommandations de code/mois. Pro à partir de 19 $/utilisateur/mois. GitHub Copilot Individual à partir de 10 $/mois ; Business à partir de 19 $/utilisateur/mois."}, {"q": "Que peut faire Amazon Q Developer ?", "a": "Amazon Q Developer peut compléter du code, déboguer des erreurs, expliquer du code, générer une infrastructure AWS (CloudFormation, CDK), scanner les failles de sécurité et les corriger, et vous aider avec les bonnes pratiques AWS."}, {"q": "GitHub Copilot et la conformité RGPD ?", "a": "GitHub Copilot Business et Enterprise ont des paramètres de confidentialité avancés : les extraits de code ne sont pas utilisés pour l'entraînement et pas de partage de code avec des tiers. Pour la conformité RGPD, la version Enterprise avec des contrôles de confidentialité spécifiques est recommandée."}]$x$::jsonb
 WHERE slug = 'github-copilot' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Amazon Q Developer vs GitHub Copilot — qual é o melhor?", "a": "Para desenvolvedores AWS, Amazon Q Developer é superior: conhece profundamente os serviços AWS, CloudFormation e boas práticas. Para desenvolvimento geral, GitHub Copilot é mais amplamente utilizável. Equipes AWS → Amazon Q; desenvolvimento geral → Copilot."}, {"q": "Amazon Q Developer é gratuito?", "a": "Amazon Q Developer tem plano gratuito com 50 conversas e 1.000 sugestões de código/mês. Pro a partir de $19/usuário/mês. GitHub Copilot Individual a partir de $10/mês; Business a partir de $19/usuário/mês."}, {"q": "O que o Amazon Q Developer pode fazer?", "a": "Amazon Q Developer pode completar código, depurar erros, explicar código, gerar infraestrutura AWS (CloudFormation, CDK), escanear falhas de segurança e corrigi-las, e ajudar com boas práticas AWS."}, {"q": "GitHub Copilot e conformidade com LGPD?", "a": "GitHub Copilot Business e Enterprise têm configurações avançadas de privacidade: trechos de código não são usados para treinamento e não há compartilhamento com terceiros. Para conformidade com LGPD, a versão Enterprise com controles específicos de privacidade é recomendada."}]$x$::jsonb
 WHERE slug = 'github-copilot' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Что такое Glide?", "a": "Glide — no-code платформа, которая превращает Google Sheets, Excel или Airtable данные в мобильные приложения. Подключаете таблицу, выбираете макет и получаете рабочее приложение без кода. Предназначена для простых сценариев: директорий, порталов, трекеров инвентаря и внутренних инструментов."}, {"q": "В чём разница между Glide и Bubble?", "a": "Glide быстро превращает таблицы в простые приложения и предназначен для нетехнических пользователей. Bubble — полноценный конструктор no-code веб-приложений, обрабатывающий сложную логику, базы данных и рабочие процессы. Glide быстрее для простых приложений, Bubble мощнее для сложных продуктов."}]$x$::jsonb
 WHERE slug = 'glide' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Glide vs Adalo — яка різниця?", "a": "Glide простіший і будує з існуючих даних (Sheets, Airtable). Adalo більш гнучкий для кастомних мобільних застосунків з власною базою даних. Glide для швидкого старту з даними; Adalo для нативних мобільних застосунків."}, {"q": "Glide безкоштовний?", "a": "Glide має безкоштовний план для тестування. Starter від $49/міс. Bubble має безкоштовний план; Starter від $32/міс."}, {"q": "Bubble vs Glide — яка різниця?", "a": "Bubble — потужна no-code платформа для складних застосунків. Glide — простіший конструктор що перетворює таблиці у застосунки. Bubble для SaaS і складних продуктів; Glide для внутрішніх інструментів з існуючими даними."}]$x$::jsonb
 WHERE slug = 'glide' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Google Stitch?", "a": "Google Stitch es una herramienta de Google para generar prototipos de UI de Android desde descripciones de texto. Genera layouts con componentes Material Design 3 y puede exportarlos para continuar en Android Studio o Figma. Está orientada a desarrolladores Android que necesitan prototipar rápidamente sin diseñador."}, {"q": "¿Google Stitch está disponible para iOS?", "a": "Google Stitch está principalmente orientado a Android y Material Design. Para diseño iOS con IA — herramientas como Uizard, Framer AI o simplemente Figma con plugins son más apropiadas. La especialización Android/Material Design es tanto la fortaleza como la limitación de Stitch."}, {"q": "¿Google Stitch genera código?", "a": "Google Stitch puede exportar diseños que se integran en el flujo de desarrollo Android con Android Studio. La generación de código directamente está en evolución. El valor principal es la generación rápida de prototipos visuales, no necesariamente código de producción final."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Что такое Google Stitch?", "a": "Google Stitch — экспериментальный ИИ-инструмент от Google для генерации UI-дизайнов из текстовых описаний или скетчей. Использует Gemini для интерпретации запросов и создания интерфейсов. Доступен в Google Labs как превью-версия."}, {"q": "Figma AI или Google Stitch — что зрелее?", "a": "Figma AI значительно зрелее и встроен в производственный рабочий процесс миллионов дизайнеров. Google Stitch — экспериментальный инструмент, находящийся в ранней стадии разработки. Для профессиональных проектов выбирайте Figma AI."}, {"q": "Экспортирует ли Google Stitch в Figma?", "a": "Google Stitch может экспортировать дизайны для дальнейшего редактирования. Конкретные форматы экспорта зависят от текущей версии инструмента, находящегося в активной разработке."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Що таке Google Stitch?", "a": "Google Stitch — ШІ-інструмент від Google для генерації UI-компонентів і прототипів. Він дозволяє описати інтерфейс і отримати готовий код або дизайн. Частина Google-екосистеми для розробників."}, {"q": "Google Stitch vs v0 by Vercel — різниця?", "a": "Обидва генерують UI з описів. v0 спеціалізується на React/Tailwind компонентах. Google Stitch більш орієнтований на Google-екосистему і Android. v0 для веб-фронтенду; Google Stitch для Google/Android."}, {"q": "Figma безкоштовний?", "a": "Figma має безкоштовний план (Starter) з обмеженнями. Professional від $15/редактор/міс. ШІ-функції включені залежно від плану."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Google Stitch לעומת Figma AI?", "a": "Google Stitch ממוקד ב-Android ו-Material Design. Figma AI בתוך הסטנדרט העיצובי. לפיתוח Android – Stitch; לעיצוב כללי – Figma AI."}, {"q": "Google Stitch חינמי?", "a": "Google Stitch זמין לגישה מוקדמת. בדקו את Google Labs לפרטים עדכניים על גישה ותמחור."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Google Stitch vs Figma AI — quelle est la différence ?", "a": "Google Stitch est un outil de prototypage rapide de Google pour générer des maquettes avec IA. Figma AI est IA intégrée dans le standard de l'industrie pour le design professionnel. Pour des prototypes rapides → Stitch ; pour le design professionnel → Figma."}, {"q": "Google Stitch est-il disponible pour tout le monde ?", "a": "Google Stitch est en accès limité / preview. Vérifiez la disponibilité actuelle sur le site de Google Labs. Figma est largement disponible avec un plan gratuit."}, {"q": "Google Stitch génère-t-il du code ?", "a": "Google Stitch se concentre sur la génération visuelle de maquettes. Pour la génération de code à partir de designs, des outils comme Figma vers code, v0 ou les fonctionnalités de développement Figma sont plus adaptés."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Google Stitch vs Figma AI — qual é a diferença?", "a": "Google Stitch é uma ferramenta de prototipagem rápida do Google para gerar mockups com IA. Figma AI é IA integrada no padrão da indústria para design profissional. Para protótipos rápidos → Stitch; para design profissional → Figma."}, {"q": "Google Stitch está disponível para todos?", "a": "Google Stitch está em acesso limitado/preview. Verifique a disponibilidade atual no site do Google Labs. Figma está amplamente disponível com plano gratuito."}, {"q": "Google Stitch gera código?", "a": "Google Stitch se concentra na geração visual de mockups. Para geração de código a partir de designs, ferramentas como v0 ou as funcionalidades de desenvolvimento do Figma são mais adequadas."}]$x$::jsonb
 WHERE slug = 'google-stitch' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Veo 3 es el mejor generador de video IA?", "a": "Veo 3 es considerado el modelo de mayor calidad en 2025 según evaluaciones independientes, especialmente en realismo y generación de audio sincronizado. Sin embargo, el acceso es limitado (Gemini Ultra, $249.99/mes, o Google Flow para cineastas). Kling 2.0, Runway y Sora compiten en el tier superior."}, {"q": "¿Cómo accedo a Google Veo 3?", "a": "Veo 3 está disponible en: Gemini Ultra ($249.99/mes, incluye Google One AI Premium), Google Flow (herramienta para cineastas, acceso selectivo) y VideoFX (waitlist). Es el modelo de acceso más restringido entre los principales generadores de video."}, {"q": "¿Veo 3 genera audio además de video?", "a": "Sí. Esta es la capacidad más novedosa de Veo 3 — genera audio sincronizado automáticamente con el video: efectos de sonido ambientales, diálogos de personajes y música. Ningún otro modelo principal hace esto de forma nativa con la misma calidad."}]$x$::jsonb
 WHERE slug = 'google-veo-3' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Google Veo 3?", "a": "Google Veo 3 ist Googles fortschrittlichstes KI-Video-Generierungsmodell (2025). Es erstellt hochwertige Videos aus Text-Beschreibungen und kann als erstes Modell seiner Klasse synchrones Audio generieren — Hintergrundgeräusche, Musik und sogar Dialoge."}, {"q": "Wie komme ich zu Veo 3?", "a": "Veo 3 ist über Google AI Ultra ($249,99/Monat), Google Flow (Googles Film-Tool) und Vertex AI für Entwickler verfügbar. Der breite öffentliche Zugang ist stufenweise ausgerollt."}, {"q": "Google Veo 3 vs Runway: Qualitätsvergleich?", "a": "Veo 3 produziert beeindruckende Ergebnisse die mit Runway Gen-4 konkurrieren. Der Hauptvorteil von Veo 3 ist Audio-Generierung — kein anderes KI-Video-Tool kann das. Runway hat mehr professionelle Kontrollen und ist ausgereifter als Produktionsplattform."}, {"q": "Kann Veo 3 Audio generieren?", "a": "Ja. Das ist Veo 3's bahnbrechendes Feature. Es generiert nicht nur das Video, sondern auch synchronen Sound — Umgebungsgeräusche, Musik und Dialoge passend zur Szene. Das ist ein erheblicher Vorteil gegenüber allen anderen KI-Video-Generatoren."}]$x$::jsonb
 WHERE slug = 'google-veo-3' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Google Veo 3?", "a": "Google Veo 3 — последняя модель генерации ИИ-видео от Google, представленная на Google I/O 2025. Создаёт высококачественное видео с синхронизированным нативным аудио — диалогом, фоновыми звуками и музыкой — из текстовых запросов. Доступна через подписку Google AI Ultra и инструмент VideoFX."}]$x$::jsonb
 WHERE slug = 'google-veo-3' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Google Veo 3 vs Runway — яка різниця?", "a": "Veo 3 новіший і може перевершувати Runway за якістю і нативним аудіо. Runway більш доступний і зрілий. Veo 3 для найвищої якості; Runway для стабільного professional workflow."}, {"q": "Де доступний Google Veo 3?", "a": "Google Veo 3 доступний через Google AI Ultra підписку ($249,99/міс) і через Vertex AI для підприємств. Широкий доступ поступово розширюється."}, {"q": "Veo 3 генерує звук разом з відео?", "a": "Так. Це ключова особливість Veo 3 — він генерує відео з нативним аудіо в одному кроці. Діалоги, фонові звуки і музика синхронізовані з відео одразу без окремого звукового редагування."}, {"q": "Google Flow — що це?", "a": "Google Flow — платформа для кіновиробництва на базі ШІ що інтегрує Veo 3 для генерації відео, Imagen для зображень і інструменти для повного workflow від сценарію до фінального відео."}]$x$::jsonb
 WHERE slug = 'google-veo-3' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Google Veo 3 מול Runway — מה עדיף?", "a": "Veo 3 חדישות ומוביל בשילוב שמע. Runway בוגר ובעל שימוש מסחרי מוכח. לתכונות השמע החדשות — Veo 3; לשימוש מקצועי יציב — Runway."}, {"q": "כמה עולה Google Veo 3?", "a": "Veo 3 זמין ב-Google One AI Premium (19.99$/חודש) ודרך Google AI Studio. Runway מ-15$/חודש."}, {"q": "Veo 3 יוצר שמע אמיתי?", "a": "כן. Veo 3 מייצר שמע מציאותי כולל דיאלוג, צלילי סביבה ומוסיקה — תכונה ייחודית שמבדילה אותו מרוב מחוללי הוידאו."}, {"q": "Veo 3 מול Sora מ-OpenAI — מה ההבדל?", "a": "Sora מ-OpenAI ו-Veo 3 מ-Google הם המחוללים המובילים ביצירת וידאו AI. Veo 3 ייחודי בשילוב שמע. שניהם עדיין חדשים ומתפתחים."}]$x$::jsonb
 WHERE slug = 'google-veo-3' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Google Veo 3 vs Runway — lequel est le meilleur ?", "a": "Veo 3 est techniquement impressionnant avec sa génération sonore unique. Mais Runway est plus accessible et établi. Pour la pointe technologique, Veo 3 ; pour l'accès pratique maintenant, Runway."}, {"q": "Quand Google Veo 3 sera-t-il disponible ?", "a": "Veo 3 est accessible via Google AI Ultra (249,99 $/mois) et certains produits Google. La disponibilité s'élargit progressivement. Runway est disponible immédiatement à partir de 15 $/mois."}, {"q": "Veo 3 génère-t-il aussi du son ?", "a": "Oui. C'est la fonctionnalité révolutionnaire de Veo 3 : il génère des vidéos avec audio synchronisé, incluant son ambiant, effets sonores et même des dialogues. Aucun autre outil de génération vidéo grand public ne fait cela aussi bien."}, {"q": "Veo 3 vs Sora — lequel est le meilleur ?", "a": "Les deux sont en haut de gamme. Veo 3 a l'avantage de la génération sonore. Sora peut produire des vidéos très longues et cohérentes. Les deux nécessitent des abonnements premium. Runway reste l'option la plus pratique pour la plupart des créateurs."}]$x$::jsonb
 WHERE slug = 'google-veo-3' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Google Veo 3 vs Runway — qual é o melhor?", "a": "Google Veo 3 tem qualidade superior e o diferencial único de gerar áudio sincronizado. Runway é mais acessível e tem mais ferramentas de edição. Para máxima qualidade, Veo 3; para acesso imediato com ferramentas completas, Runway."}, {"q": "Google Veo 3 está disponível?", "a": "Google Veo 3 está disponível via Google Flow e DeepMind, com acesso expandindo gradualmente. Runway está totalmente disponível com plano gratuito imediatamente."}, {"q": "Google Veo 3 consegue gerar áudio?", "a": "Sim, este é o diferencial do Veo 3. Ele gera vídeo com áudio sincronizado: música, efeitos sonoros e até diálogos de personagens, tornando-o único entre os geradores de vídeo de IA."}, {"q": "Veo 3 vs Sora — qual é a diferença?", "a": "Veo 3 do Google inclui geração de áudio integrada. Sora da OpenAI foca em qualidade cinematográfica visual. Ambos são de ponta; Veo 3 tem vantagem com o componente de áudio."}]$x$::jsonb
 WHERE slug = 'google-veo-3' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Grammarly puede traducir texto?", "a": "Grammarly no es una herramienta de traducción — está diseñada para mejorar texto ya escrito en inglés. Para traducción, usa DeepL o Google Translate. Son herramientas fundamentalmente diferentes."}]$x$::jsonb
 WHERE slug = 'grammarly' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Grammarly für Deutsch — ist das gut?", "a": "Grammarly ist primär für Englisch optimiert. Die Unterstützung für Deutsch und andere Sprachen ist begrenzt und weniger präzise als für Englisch. Für deutschsprachige Texte sind LanguageTool oder native Korrekturtools bessere Alternativen."}]$x$::jsonb
 WHERE slug = 'grammarly' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "DeepL Write vs Grammarly — різниця?", "a": "DeepL Write покращує текст у тій самій мові і дуже добрий для стилю і природності. Grammarly потужніший для комплексного граматичного і стилістичного аналізу. Для природного переформулювання — DeepL Write; для комплексної перевірки — Grammarly."}]$x$::jsonb
 WHERE slug = 'grammarly' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "DeepL Write מול Grammarly — מה ההבדל?", "a": "DeepL Write משפר טקסט באותה שפה ומצוין לסגנון וטבעיות. Grammarly חזק יותר לניתוח דקדוקי וסגנותי מקיף. לניסוח מחדש טבעי — DeepL Write; לבדיקה מקיפה — Grammarly."}]$x$::jsonb
 WHERE slug = 'grammarly' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "DeepL Write vs Grammarly — quelle est la différence ?", "a": "DeepL Write améliore le texte dans la même langue et est très bon pour le style et la fluidité. Grammarly est plus puissant pour l'analyse grammaticale et stylistique complète. Pour une reformulation naturelle, DeepL Write ; pour une vérification complète, Grammarly."}]$x$::jsonb
