UPDATE tools SET faq = $x$[{"q": "DeepL Write vs Grammarly — qual é a diferença?", "a": "DeepL Write melhora o texto no mesmo idioma e é muito bom para estilo e fluência. Grammarly é mais poderoso para análise gramatical e estilística completa. Para reformulação natural, DeepL Write; para verificação completa, Grammarly."}]$x$::jsonb
 WHERE slug = 'grammarly' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Что такое Grok AI?", "a": "Grok — ИИ-ассистент xAI, встроенный в X (Twitter). Имеет доступ в реальном времени к постам X и трендовым темам, что уникально для разведки в соцсетях. Grok 3 (2025) — фронтирная модель, конкурирующая с GPT-4o по бенчмаркам рассуждений."}, {"q": "Grok бесплатный?", "a": "Grok входит в X Premium ($8/мес) и X Premium+ ($16/мес). Отдельное приложение Grok с расширенными функциями доступно за $30/мес. Полностью бесплатной версии нет."}, {"q": "Grok 3 лучше GPT-4?", "a": "Grok 3 конкурирует с GPT-4o по бенчмаркам рассуждений и математики и лидирует в некоторых задачах STEM. Для общего использования, кодирования и экосистемных функций GPT-4o всё ещё имеет преимущества. Главный дифференциатор Grok — доступ в реальном времени к X/Twitter."}]$x$::jsonb
 WHERE slug = 'grok' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Grok vs ChatGPT — яка різниця?", "a": "Grok від xAI має реальний доступ до X і є менш обмеженим. ChatGPT від OpenAI має кращу екосистему і є стандартом галузі. Для X-даних і менших обмежень — Grok; для роботи і розробки — ChatGPT."}, {"q": "Скільки коштує Grok?", "a": "Grok доступний у X Premium ($8/міс) і Premium+ ($22/міс на iOS, $40 на веб). Самостійний застосунок Grok є безкоштовним з обмеженнями. ChatGPT Plus — $20/міс, Pro — $200/міс."}, {"q": "Grok 3 vs GPT-4o — що сильніше?", "a": "Grok 3 Thinking конкурує з GPT-4o у математиці та науці. Обидві моделі на передньому краї. Для більшості практичних завдань різниця мінімальна. Grok має перевагу в актуальних даних з X."}]$x$::jsonb
 WHERE slug = 'grok' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Grok מול ChatGPT — מה ההבדל?", "a": "Grok מ-xAI עם גישה בזמן אמת ל-X ופחות מוגבל. ChatGPT מ-OpenAI עם מערכת-אקולוגית טובה יותר וסטנדרט תעשייתי. לנתוני X ופחות הגבלות — Grok; לעבודה ופיתוח — ChatGPT."}, {"q": "כמה עולה Grok?", "a": "Grok זמין ב-X Premium (8$/חודש) ו-Premium+ (22$/חודש ב-iOS, 40$ באינטרנט). האפליקציה העצמאית Grok חינמית עם הגבלות. ChatGPT Plus — 20$/חודש, Pro — 200$/חודש."}, {"q": "Grok 3 מול GPT-4o — מה חזק יותר?", "a": "Grok 3 Thinking מתחרה עם GPT-4o במתמטיקה ובמדע. שני המודלים בחזית. להבדלים מעשיים — מינימלי. ל-Grok יתרון בנתוני X עדכניים."}]$x$::jsonb
 WHERE slug = 'grok' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Hemingway Editor?", "a": "Hemingway Editor es una herramienta de escritura que resalta texto difícil de leer. Usa colores para indicar frases demasiado largas (amarillo/rojo), voz pasiva (verde), adverbios (azul) y alternativas más simples (morado). El objetivo es escritura directa y clara."}, {"q": "¿Hemingway Editor es gratuito?", "a": "Hemingway Editor web es gratuito con funciones básicas. La app de escritorio (Mac/Windows) cuesta un pago único de $19.99. Grammarly tiene plan gratuito; Grammarly Premium cuesta $12/mes."}, {"q": "¿Hemingway Editor corrige gramática?", "a": "Hemingway Editor detecta algunos problemas gramaticales pero su enfoque principal es la legibilidad y claridad, no la corrección gramatical completa. Para corrección gramatical profunda, Grammarly es más potente."}, {"q": "¿Cuándo usar Hemingway Editor y cuándo Grammarly?", "a": "Úsalos juntos para lo mejor de ambos mundos. Grammarly primero para corrección gramatical y ortográfica, luego Hemingway para simplificar y hacer el texto más directo. Muchos escritores de contenido web siguen este flujo de dos pasos."}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Hemingway Editor oder Grammarly: Welches ist besser?", "a": "Sie lösen unterschiedliche Probleme. Grammarly findet Grammatikfehler und gibt allgemeine Schreibvorschläge. Hemingway macht Ihren Schreibstil klarer und direkter. Viele Autoren nutzen beide: Grammarly für Korrektheit, Hemingway für Lesbarkeit."}, {"q": "Ist Hemingway Editor kostenlos?", "a": "Hemingway Editor hat eine kostenlose Web-Version auf hemingwayapp.com. Die Desktop-App kostet $19,99 (einmalige Zahlung, keine Abonnement). Grammarly hat einen kostenlosen Plan; Premium ab $12/Monat."}, {"q": "Was bedeutet 'Lesbarkeits-Klasse' im Hemingway Editor?", "a": "Der Hemingway Editor gibt Ihrem Text eine Lesbarkeitsklasse basierend auf dem Flesch-Kincaid-Grade-Level. Klasse 6-8 ist ideal für die meisten Web-Inhalte und breite Publikumsansprache. Akademische Texte können höher sein. Ziel ist nicht Klasse 1, sondern das richtige Niveau für Ihre Zielgruppe."}, {"q": "Kann Hemingway Editor auf Deutsch genutzt werden?", "a": "Hemingway Editor funktioniert mit deutschen Texten, ist jedoch primär für englische Texte optimiert. Die Lesbarkeitsregeln (Satzlänge, Adverb-Erkennung) funktionieren auch auf Deutsch, aber die Sprachregeln sind nicht so präzise wie für Englisch kalibriert."}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что делает Hemingway Editor?", "a": "Hemingway Editor анализирует ваш текст на читаемость. Выделяет длинные предложения, пассивный залог, сложные слова и лишние наречия — с цветовой кодировкой по серьёзности. Присваивает оценку читаемости по уровню образования. Цель — чёткое, прямое и лёгкое для чтения письмо."}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Hemingway Editor чи Grammarly — що краще?", "a": "Вони вирішують різні задачі. Grammarly виявляє граматичні помилки і дає загальні поради. Hemingway робить стиль чіткішим і прямішим. Багато авторів використовують обидва: Grammarly для точності, Hemingway для читабельності."}, {"q": "Hemingway Editor безкоштовний?", "a": "Hemingway Editor безкоштовний на hemingwayapp.com. Десктопний застосунок коштує $19,99 (одноразово, без підписки). Grammarly безкоштовний; Premium від $12/міс."}, {"q": "Що означає «рівень читабельності» у Hemingway?", "a": "Hemingway дає рівень читабельності за шкалою Flesch-Kincaid. Рівень 6-8 ідеальний для більшості веб-контенту і широкої аудиторії. Мета — не рівень 1, а відповідний рівень для вашої цільової аудиторії."}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Hemingway Editor או Grammarly — מה עדיף?", "a": "הם פותרים בעיות שונות. Grammarly מוצא שגיאות דקדוק ומספק הצעות כלליות. Hemingway הופך את הסגנון לברור וישיר יותר. סופרים רבים משתמשים בשניהם: Grammarly לדיוק, Hemingway לקריאות."}, {"q": "האם Hemingway Editor בחינם?", "a": "ל-Hemingway Editor יש גרסת ווב חינמית ב-hemingwayapp.com. אפליקציית שולחן העבודה עולה 19.99$ (תשלום חד פעמי, ללא מנוי). Grammarly חינמי; Premium מ-12$/חודש."}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Hemingway Editor ou Grammarly — lequel est le meilleur ?", "a": "Ils résolvent des problèmes différents. Grammarly trouve les erreurs de grammaire et donne des conseils généraux. Hemingway rend votre style plus clair et direct. Beaucoup d'auteurs utilisent les deux : Grammarly pour la précision, Hemingway pour la lisibilité."}, {"q": "Hemingway Editor est-il gratuit ?", "a": "Hemingway Editor est gratuit sur hemingwayapp.com. L'application de bureau coûte 19,99 $ (paiement unique, pas d'abonnement). Grammarly est gratuit ; Premium à partir de 12 $/mois."}, {"q": "Que signifie le 'niveau de lisibilité' dans Hemingway ?", "a": "Hemingway donne un niveau de lisibilité basé sur le score Flesch-Kincaid. Le niveau 6-8 est idéal pour la plupart des contenus web et un large public. L'objectif n'est pas le niveau 1, mais le bon niveau pour votre public cible."}, {"q": "Hemingway Editor fonctionne-t-il en français ?", "a": "Hemingway Editor analyse aussi les textes français, mais est principalement optimisé pour l'anglais. Les règles de lisibilité (longueur des phrases, détection des adverbes) fonctionnent partiellement pour d'autres langues."}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Hemingway Editor ou Grammarly — qual é o melhor?", "a": "Eles resolvem problemas diferentes. Grammarly encontra erros de gramática e dá conselhos gerais. Hemingway torna seu estilo mais claro e direto. Muitos autores usam os dois: Grammarly para precisão, Hemingway para legibilidade."}, {"q": "Hemingway Editor é gratuito?", "a": "Hemingway Editor é gratuito em hemingwayapp.com. O aplicativo desktop custa $19,99 (pagamento único, sem assinatura). Grammarly é gratuito; Premium a partir de $12/mês."}, {"q": "O que significa o 'nível de legibilidade' no Hemingway?", "a": "Hemingway dá um nível de legibilidade baseado na pontuação Flesch-Kincaid. O nível 6-8 é ideal para a maioria dos conteúdos web e um público amplo. O objetivo não é o nível 1, mas o nível certo para seu público-alvo."}, {"q": "Hemingway Editor funciona em português?", "a": "Hemingway Editor analisa textos em português, mas é principalmente otimizado para inglês. As regras de legibilidade (comprimento das frases, detecção de advérbios) funcionam parcialmente para outros idiomas."}]$x$::jsonb
 WHERE slug = 'hemingway-editor' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Hex o Jupyter Notebooks para análisis de datos?", "a": "Hex es una versión colaborativa y más potente de Jupyter — añade SQL nativo, visualizaciones drag-and-drop, publicación como apps y colaboración en tiempo real. Para análisis individual exploratorio — Jupyter es suficiente y gratuito. Para equipos de datos que necesitan compartir y publicar — Hex."}, {"q": "¿Hex es gratuito?", "a": "Hex tiene un plan gratuito para proyectos personales con funciones limitadas. Los planes de pago empiezan desde $24/mes (Team). Looker Studio es completamente gratuito. Hex está orientado a equipos de datos; Looker Studio a marketing y business."}, {"q": "¿Qué lenguajes soporta Hex?", "a": "Hex soporta SQL (para cualquier base de datos) y Python. Puedes combinar celdas SQL y Python en el mismo notebook, lo que lo hace muy flexible para análisis que requieren tanto consultas de BD como procesamiento de datos con Python."}, {"q": "¿Hex puede conectarse a BigQuery?", "a": "Sí. Hex se conecta a BigQuery, Snowflake, Databricks, Redshift, PostgreSQL y muchos otros data warehouses. Looker Studio también conecta a BigQuery de forma nativa. Ambas son buenas opciones para análisis sobre BigQuery; Hex ofrece más capacidad de transformación con código."}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Hex?", "a": "Hex ist eine kollaborative Datenplattform die Notebooks (SQL + Python) mit App-Publishing kombiniert. Data-Teams schreiben Analysen in Hex-Notebooks und veröffentlichen sie als interaktive Dashboards für nicht-technische Stakeholder — ohne separates BI-Tool."}, {"q": "Hex vs Databricks: Was ist der Unterschied?", "a": "Hex ist ein kollaboratives Notebook-Tool mit App-Publishing. Databricks ist eine vollständige Data Lakehouse-Plattform für Enterprise-Scale Data Engineering und ML. Hex für kollaborative Analyse-Teams; Databricks für groß angelegte Daten-Infrastruktur."}, {"q": "Ist Hex kostenlos?", "a": "Hex hat einen kostenlosen Plan für individuelle Nutzer mit begrenzten Projekten. Team-Pläne beginnen ab $24/Benutzer/Monat. Looker Studio ist vollständig kostenlos."}, {"q": "Hex vs Jupyter Notebooks: Was ist besser?", "a": "Jupyter ist kostenlos und Open-Source aber erfordert lokale Installation und hat wenig eingebaute Kollaboration. Hex ist Cloud-basiert, kollaborativ und fügt App-Publishing ohne zusätzliche Tools hinzu. Hex für Teams; Jupyter für individuelle lokale Entwicklung."}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Hex?", "a": "Hex — коллаборативная дата-платформа, объединяющая SQL-ноутбуки, Python и no-code графики в одном рабочем пространстве. Дата-команды используют её для анализа данных и создания интерактивных дата-приложений. Hex Magic (ИИ) пишет SQL и Python из естественного языка и автоматически генерирует визуализации."}, {"q": "В чём разница между Looker Studio и Hex?", "a": "Looker Studio создаёт drag-and-drop визуальные дашборды — инструмент отчётности для бизнес-пользователей. Hex — дата-ноутбук и конструктор приложений для дата-команд, работающих в SQL и Python. Looker Studio — read-only визуальная отчётность, Hex — интерактивный анализ и вычисления."}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Hex vs Jupyter Notebook — яка різниця?", "a": "Jupyter — локальний відкритий ноутбук для розробки. Hex — хмарна платформа де ноутбуки перетворюються на живі застосунки і дашборди для ділення з командою. Hex значно зручніший для командної роботи."}, {"q": "Hex безкоштовний?", "a": "Hex має безкоштовний план для індивідуального використання. Team від $24/місяць/користувач. Looker Studio повністю безкоштовний."}, {"q": "Hex підтримує Python і SQL?", "a": "Так. Hex підтримує Python, SQL і R в одному ноутбуці. Ви можете змішувати клітинки SQL і Python у одному документі і результати автоматично передаються між ними."}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Hex לעומת Looker Studio – מה עדיף?", "a": "Hex מיועד לצוותי Data Science שרוצים Notebooks שיתופיים. Looker Studio מיועד לדשבורדים עסקיים. Hex לניתוח עמוק; Looker Studio לדשבורדי KPI."}, {"q": "Hex חינמי?", "a": "Hex מציע תוכנית חינמית לעד 3 משתמשים; Team ב-$24/משתמש/חודש. Looker Studio חינמי לחלוטין."}, {"q": "Hex לעומת Jupyter Notebooks?", "a": "Hex הוא Jupyter בענן עם שיתוף, ניהול גרסאות ועיצוב יפה יותר. Jupyter מקומי חינמי ומאפשר שליטה מלאה. Hex לצוותים; Jupyter לאנשים בודדים."}, {"q": "Hex תומך ב-dbt?", "a": "כן, Hex מתאים היטב ל-dbt עם חיבור לנתוני dbt ישירות. Hex ו-dbt יחד הם stack פופולרי בצוותי Data."}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Hex vs Looker Studio — lequel est le meilleur ?", "a": "Hex est pour les data scientists et analystes techniques créant des analyses complexes. Looker Studio est pour les équipes non techniques créant des dashboards simples. Analytique avancée avec code → Hex ; rapports marketing simples → Looker Studio."}, {"q": "Hex est-il gratuit ?", "a": "Hex a un plan gratuit pour les projets personnels. Team à partir de 24 $/utilisateur/mois. Looker Studio est entièrement gratuit."}, {"q": "Hex supporte-t-il Python ?", "a": "Oui. Hex supporte Python et SQL dans des notebooks collaboratifs. Vous pouvez utiliser des bibliothèques Python comme pandas, numpy et plotly directement dans Hex."}, {"q": "Hex AI peut-il écrire du SQL automatiquement ?", "a": "Oui. Hex AI Magic génère du SQL à partir de descriptions en langage naturel. Vous décrivez ce que vous voulez analyser et Hex génère la requête SQL correspondante."}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Hex vs Looker Studio — qual escolher?", "a": "Hex é para equipes técnicas de dados que precisam de análise exploratória com código. Looker Studio é para dashboards de negócios sem código. Para data science e análise técnica, Hex; para relatórios de negócios, Looker Studio."}, {"q": "Hex é gratuito?", "a": "Hex tem plano gratuito para uso individual com projetos limitados. Planos de equipe a partir de $24/mês por usuário. Looker Studio é completamente gratuito."}, {"q": "Hex suporta Python?", "a": "Sim, Hex suporta Python e SQL. Você pode misturar células Python e SQL em um mesmo notebook, o que é muito útil para análises que combinam transformações de dados e visualizações."}]$x$::jsonb
 WHERE slug = 'hex' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿HeyGen o Synthesia para videos de formación?", "a": "Synthesia está más orientado a formación corporativa y eLearning — tiene más integraciones con LMS y flujos de trabajo de L&D. HeyGen es mejor para videos de marketing personalizados y clonación de voz/avatar. Para formación interna a escala — Synthesia; para marketing con avatar propio — HeyGen."}, {"q": "¿Cuánto cuesta HeyGen?", "a": "HeyGen tiene un plan gratuito con 1 crédito de video (aprox. 1 minuto). Los planes de pago empiezan desde $29/mes (Creator). Synthesia empieza desde $29/mes (Starter) con 10 minutos de video al mes."}, {"q": "¿Puede HeyGen clonar mi voz?", "a": "Sí. HeyGen ofrece clonación de voz — grabas unos minutos de audio y el sistema crea una voz IA que suena como tú. También puedes crear un avatar de video que sincronice con tu voz clonada. Es una de sus funciones más populares."}, {"q": "¿Son legales los avatares de IA?", "a": "HeyGen y Synthesia requieren consentimiento explícito para crear avatares de personas reales. Las plataformas tienen políticas de uso aceptable que prohíben la creación de deepfakes no autorizados. Usar avatares con consentimiento para marketing propio o formación corporativa es completamente legal."}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "HeyGen vs Synthesia: Was ist der Unterschied?", "a": "HeyGen ist stärker bei Video-Übersetzung und interaktiven Avataren für Echtzeit-Anwendungen. Synthesia hat mehr Avatare und ist stärker für Enterprise-Trainingsvideos und E-Learning. HeyGen für Video-Lokalisierung; Synthesia für skalierbare Unternehmenskommunikation."}, {"q": "Kann HeyGen Videos übersetzen?", "a": "Ja. HeyGen Video Translation ist eines der besten Tools für Video-Lokalisierung. Es übersetzt nicht nur den Audio sondern synchronisiert auch die Lippenbewegungen auf die neue Sprache. 40+ Sprachen werden unterstützt."}, {"q": "Wie viel kostet HeyGen?", "a": "HeyGen beginnt ab $29/Monat (Creator) mit 15 Credits pro Monat. Synthesia beginnt ab $29/Monat (Starter) mit 10 Videos pro Monat. Für Enterprise-Nutzung haben beide benutzerdefinierte Preise."}, {"q": "Sind KI-Avatar-Videos überzeugend?", "a": "Moderne KI-Avatare von HeyGen und Synthesia sind für professionelle Präsentationen und E-Learning überzeugend. Sie sind ideal für Schulungsvideos, Produktdemos und interne Kommunikation. Für emotionale Marketingvideos die menschliche Verbindung erfordern sind echte Kameras noch besser."}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между HeyGen и Synthesia?", "a": "HeyGen лидирует по переводу видео (дублированию с синхронизацией губ на 175+ языках) и качеству аватаров. Synthesia лидирует по корпоративным функциям, соответствию требованиям и интеграции LMS для корпоративного обучения. HeyGen — для маркетинга, Synthesia — для L&D-команд."}, {"q": "Может ли HeyGen клонировать мой голос?", "a": "Да. HeyGen может клонировать ваш голос и создать ИИ-аватар, который выглядит и звучит как вы, из короткой записи. Используется для перевода видео — ваш аватар говорит на других языках вашим клонированным голосом."}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "HeyGen чи Synthesia для корпоративних відео?", "a": "Synthesia краще для корпоративного навчання і HR: більше аватарів, мов і enterprise-функцій. HeyGen краще для маркетингу і продажових відео де потрібна персоналізація. Для L&D — Synthesia; для маркетингу — HeyGen."}, {"q": "HeyGen безкоштовний?", "a": "HeyGen має безкоштовний план з 1 хвилиною відео/міс. Платні від $29/міс. Synthesia від $29/міс; Enterprise за запитом."}, {"q": "HeyGen Video Translate — як це працює?", "a": "Ви завантажуєте відео → HeyGen автоматично перекладає мову, синтезує голос схожий на оригінальний і синхронізує рухи губ. Результат — відео що виглядає як оригінально знятий на іншій мові."}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "HeyGen מול Synthesia לוידאו ארגוני?", "a": "Synthesia עדיף לאימון ארגוני ו-HR: יותר אווטרים, שפות ותכונות enterprise. HeyGen עדיף לשיווק ולמכירות שדורשים פרסונליזציה. ל-L&D — Synthesia; לשיווק — HeyGen."}, {"q": "האם HeyGen בחינם?", "a": "HeyGen מציע תוכנית חינמית עם דקה אחת של וידאו/חודש. תוכניות בתשלום מ-29$/חודש. Synthesia מ-29$/חודש; Enterprise על פי בקשה."}, {"q": "HeyGen Video Translate — כיצד עובד?", "a": "מעלים וידאו → HeyGen מתרגם אוטומטית, מסנתז קול דומה למקורי ומסנכרן תנועות השפתיים. התוצאה — וידאו שנראה כאילו צולם מלכתחילה בשפה האחרת."}]$x$::jsonb
 WHERE slug = 'heygen' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "HeyGen vs Synthesia — lequel est le meilleur ?", "a": "HeyGen est meilleur pour le clonage vocal, la traduction vidéo et la valeur globale. Synthesia est meilleur pour la formation d'entreprise et les intégrations LMS. Créateurs et petites équipes → HeyGen ; formation d'entreprise → Synthesia."}, {"q": "Combien coûte HeyGen ?", "a": "HeyGen à partir de 29 $/mois (Creator). Synthesia à partir de 29 $/mois (Starter). Les prix sont similaires, mais HeyGen offre souvent plus de fonctionnalités au même prix."}, {"q": "HeyGen peut-il traduire des vidéos en français ?", "a": "Oui. HeyGen traduit les vidéos dans de nombreuses langues dont le français, avec synchronisation labiale. Vous téléchargez votre vidéo en anglais et HeyGen crée une version française avec votre avatar qui parle français."}]$x$::jsonb
