UPDATE tools SET faq = $x$[{"q": "HeyGen vs Synthesia — qual escolher?", "a": "HeyGen tem avatares de melhor qualidade e mais recursos de marketing. Synthesia é mais adequado para treinamento corporativo e e-learning. Para marketing e conteúdo viral, HeyGen; para treinamento corporativo, Synthesia."}, {"q": "HeyGen é gratuito?", "a": "HeyGen tem plano gratuito com 1 vídeo por mês. Planos pagos a partir de $29/mês. Synthesia tem demonstração gratuita; planos pagos a partir de $29/mês."}, {"q": "HeyGen pode criar avatar de si mesmo?", "a": "Sim, HeyGen permite criar um avatar personalizado do seu rosto e voz com apenas alguns minutos de gravação. Este recurso está disponível nos planos pagos."}]$x$::jsonb
