UPDATE tools SET faq = $x$[{"q": "¿NotebookLM o Humata para PDFs?", "a": "NotebookLM es más potente para análisis profundo con múltiples documentos y genera Audio Overviews. Humata está más enfocado en Q&A rápido sobre PDFs individuales para contextos empresariales. Para investigación con múltiples fuentes — NotebookLM; para preguntas sobre documentos en contexto de negocio — Humata."}, {"q": "¿Humata es gratuito?", "a": "Humata tiene un plan gratuito con 60 páginas de PDF/mes. El plan Student ($1.99/mes) y Team ($9.99/usuario/mes) ofrecen más capacidad. NotebookLM de Google es gratuito con límites generosos — la opción más económica para análisis de documentos."}]$x$::jsonb
 WHERE slug = 'humata' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "NotebookLM vs Humata — для чего каждый?", "a": "Оба анализируют PDF-документы через ИИ. NotebookLM бесплатен и имеет уникальные функции (аудиообзоры). Humata ориентирован на корпоративное использование с точными цитатами и командным доступом."}, {"q": "Сколько стоит Humata?", "a": "Humata предлагает бесплатный план с 60 страницами в месяц. Student — $9.99/мес (200 страниц). Expert — $49/мес (неограниченно). Дороже NotebookLM, но с дополнительными корпоративными функциями."}]$x$::jsonb
 WHERE slug = 'humata' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "NotebookLM vs Humata — яка різниця?", "a": "NotebookLM від Google безкоштовний з унікальним Audio Overview. Humata платний з кращою обробкою великих обсягів документів. Для особистого використання — NotebookLM; для корпоративного аналізу документів — Humata."}]$x$::jsonb
 WHERE slug = 'humata' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "NotebookLM לעומת Humata – מה עדיף?", "a": "NotebookLM חינמי ומציע Audio Overview ייחודי. Humata מתאים יותר לניתוח מסמכים מקצועיים ארוכים. NotebookLM לחינוך ומחקר כללי; Humata לניתוח מסמכים עסקיים ומשפטיים."}, {"q": "Humata חינמי?", "a": "Humata מציע תוכנית חינמית עם 60 עמודים. Student ב-$1.99/חודש; Pro ב-$9.99/חודש. NotebookLM חינמי לחלוטין."}]$x$::jsonb
