UPDATE tools SET faq = $x$[{"q": "NotebookLM vs Humata — lequel est le meilleur pour les PDFs ?", "a": "NotebookLM est plus polyvalent (plusieurs sources, audio, Google Docs). Humata se concentre sur la précision des citations PDF. Pour l'analyse multi-source, NotebookLM ; pour la précision dans un seul document important, Humata."}, {"q": "Humata est-il bon pour les contrats en français ?", "a": "Humata peut analyser des contrats en français. La qualité d'analyse dépend de la complexité du document. Pour les contrats très complexes, un avis juridique professionnel reste nécessaire."}]$x$::jsonb
