UPDATE tools SET faq = $x$[{"q": "NotebookLM vs Humata — qual escolher?", "a": "NotebookLM é mais versátil e gratuito, ótimo para pesquisa e estudo. Humata é mais focado em documentos corporativos e técnicos com referências precisas. Para uso acadêmico e gratuito, NotebookLM; para análise corporativa de documentos, Humata."}, {"q": "Humata tem precisão em documentos jurídicos?", "a": "Humata é frequentemente usado para análise de contratos e documentos jurídicos. Sempre verifique as referências exatas que ele fornece, pois documentos jurídicos requerem precisão total."}]$x$::jsonb
 WHERE slug = 'humata' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Ideogram es mejor que Midjourney para texto en imágenes?", "a": "Sí, claramente. Ideogram es el modelo líder para renderizar texto dentro de imágenes con precisión. Midjourney históricamente ha tenido problemas con texto — letras incorrectas, deformadas. Ideogram 3.0 genera texto tipográfico muy fiel al prompt. Para cualquier imagen con texto — Ideogram."}, {"q": "¿Ideogram es gratuito?", "a": "Sí. Ideogram tiene un plan gratuito con 10 generaciones lentas por día (o 25 prioritarias/semana). Los planes de pago (Basic $8/mes, Plus $20/mes) ofrecen más generaciones y acceso prioritario."}, {"q": "¿Qué puede hacer Ideogram que Midjourney no puede?", "a": "Ideogram sobresale en: texto tipográfico en imágenes, colores específicos de marca, estilos de diseño gráfico (carteles, logos). Midjourney supera en arte fotorrealista de alta complejidad y estilos artísticos únicos."}, {"q": "¿Puede Ideogram crear logos profesionales?", "a": "Ideogram puede generar conceptos de logos con texto integrado de forma precisa, algo que otros modelos hacen mal. Sin embargo, los logos de IA no son vectoriales — necesitas un diseñador o herramienta de vectorización para logos profesionales listos para imprimir."}]$x$::jsonb
 WHERE slug = 'ideogram' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Warum ist Ideogram gut für Text in Bildern?", "a": "Ideogram wurde speziell trainiert, lesbaren Text in Bilder zu integrieren. Das ist eine bekannte Schwäche anderer KI-Bildgeneratoren. Ideogram 3 kann Schriftzüge, Slogans und kurze Texte präzise und ästhetisch ansprechend darstellen."}, {"q": "Ist Ideogram kostenlos?", "a": "Ideogram hat einen kostenlosen Plan mit einem täglichen Budget von 10 slow-priority Generierungen. Kostenpflichtige Pläne beginnen ab $8/Monat (Basic) für mehr Generierungen und Priorität. Midjourney beginnt ab $10/Monat."}, {"q": "Ideogram vs Midjourney: Welches ist besser für Poster?", "a": "Für Poster mit Text — eindeutig Ideogram. Für rein visuelle, textfreie Poster — Midjourney liefert ausgereiftere künstlerische Qualität. Für Social-Media-Posts mit Typografie — Ideogram. Für Konzeptkunst und komplexe Illustrationen — Midjourney."}, {"q": "Kann Ideogram auf Deutsch text rendern?", "a": "Ja. Ideogram kann Text in verschiedenen Sprachen darunter Deutsch rendern. Die Qualität ist bei Lateinschrift (Deutsch, Englisch, Spanisch) am besten. Prüfen Sie das Ergebnis für wichtige Texte — KI-generierter Text sollte immer überprüft werden."}]$x$::jsonb
 WHERE slug = 'ideogram' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Ideogram чи Midjourney для логотипів?", "a": "Ideogram значно краще справляється з текстом на зображеннях — ідеально для логотипів і маркетингових матеріалів де потрібен читабельний текст. Midjourney кращий для художніх ілюстрацій без тексту."}, {"q": "Ideogram безкоштовний?", "a": "Так. Ideogram має безкоштовний план з обмеженою кількістю генерацій. Basic від $8/міс. Midjourney від $10/міс без безкоштовного плану."}]$x$::jsonb
 WHERE slug = 'ideogram' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Ideogram מול Midjourney — מה עדיף?", "a": "Ideogram מוביל בשילוב טקסט מדויק בתמונות. Midjourney מוביל באיכות אמנותית כוללת. לפוסטרים ולוגואים עם טקסט — Ideogram; לאמנות ולצילום — Midjourney."}, {"q": "האם Ideogram בחינם?", "a": "ל-Ideogram יש תוכנית חינמית עם 10 תמונות/יום. Basic מ-8$/חודש. Midjourney מ-10$/חודש ללא תוכנית חינמית."}, {"q": "מה זה Ideogram 2.0?", "a": "Ideogram 2.0 הוא המודל החדש של Ideogram עם שיפורי איכות משמעותיים ברנדרינג טקסט, ריאליזם ועיבוד סגנון. הוא משמש כבסיס לתוכניות הבתשלום."}]$x$::jsonb
 WHERE slug = 'ideogram' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Ideogram vs Midjourney — lequel est le meilleur pour le rendu de texte ?", "a": "Ideogram est nettement meilleur pour intégrer du texte lisible dans les images. C'est l'une de ses fonctionnalités phares. Midjourney a du mal à rendre du texte précis. Pour les designs avec du texte, Ideogram est clairement supérieur."}, {"q": "Ideogram est-il gratuit ?", "a": "Ideogram a un plan gratuit généreux avec des crédits quotidiens. Les plans payants à partir de 8 $/mois pour plus de générations. Midjourney à partir de 10 $/mois sans plan gratuit permanent."}, {"q": "Ideogram est-il bon pour les logos ?", "a": "Ideogram est idéal pour les concepts de logos car il peut rendre du texte lisible dans les designs. Mais pour des logos professionnels finaux, vous aurez besoin d'un logiciel vectoriel comme Illustrator pour la mise à l'échelle. Ideogram est excellent pour la conceptualisation."}, {"q": "Ideogram vs DALL-E 3 — lequel est le meilleur ?", "a": "Les deux gèrent bien le rendu de texte mieux que Midjourney. DALL-E 3 est accessible via ChatGPT. Ideogram a son propre plan gratuit. Pour les affiches et le design avec texte, les deux sont bons ; testez les deux pour votre style."}]$x$::jsonb
 WHERE slug = 'ideogram' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Ideogram vs Midjourney — qual é o melhor?", "a": "Ideogram é superior para imagens com texto legível. Midjourney é superior para qualidade artística geral. Para logos e banners com texto, Ideogram; para arte e fotorrealismo, Midjourney."}, {"q": "Ideogram é gratuito?", "a": "Sim, Ideogram tem plano gratuito com gerações limitadas por dia. Planos pagos a partir de $8/mês. Midjourney começa em $10/mês sem plano gratuito permanente."}, {"q": "Ideogram consegue criar logos?", "a": "Sim, Ideogram é excelente para criar logos e identidades visuais, especialmente quando precisam incluir texto legível. Para logos profissionais, combine Ideogram com ferramentas de design vetorial."}, {"q": "Ideogram 2.0 vs Ideogram 1.0 — qual é a diferença?", "a": "Ideogram 2.0 tem qualidade de imagem significativamente melhorada, melhor renderização de texto e geração de fotos mais realistas. Ideogram 3.0 (mais recente) melhorou ainda mais a precisão e qualidade geral."}]$x$::jsonb
 WHERE slug = 'ideogram' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Copy.ai o Jasper para marketing?", "a": "Copy.ai es mejor para copias cortas y equipos pequeños con presupuesto ajustado. Jasper es más potente para equipos de contenido que producen a escala con brand voice configurado. Para startups y freelancers — Copy.ai; para equipos de marketing maduros — Jasper."}, {"q": "¿Jasper es mejor que ChatGPT para marketing?", "a": "Jasper está especialmente diseñado para marketing — tiene plantillas de marketing, brand voice y flujos de trabajo integrados. ChatGPT es más versátil pero requiere más configuración para marketing. Para equipos de marketing dedicados, Jasper ahorra tiempo; para uso general, ChatGPT ofrece más flexibilidad."}]$x$::jsonb
 WHERE slug = 'jasper' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Copy.ai oder Jasper für Marketing?", "a": "Jasper ist besser für große Teams mit Brand-Voice-Anforderungen und komplexen Workflows. Copy.ai ist kostengünstiger und hat einen großzügigen kostenlosen Plan — ideal für Solopreneure und kleinere Teams. Für Enterprise-Content-Marketing — Jasper; für individuelle Nutzung — Copy.ai."}, {"q": "Jasper vs ChatGPT für Content-Erstellung?", "a": "Jasper ist speziell für Marketing-Content optimiert mit vorgefertigten Vorlagen und Brand-Voice. ChatGPT ist vielseitiger aber erfordert mehr Prompt-Arbeit. Für Marketing-Teams — Jasper; für flexible allgemeine Content-Arbeit — ChatGPT."}]$x$::jsonb
 WHERE slug = 'jasper' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Jasper AI стоит своих денег в 2026 году?", "a": "Jasper стоит того для команд контента из 3+ человек, где критична согласованность бренда. Обучение голосу бренда и командные функции оправдывают более высокую цену. Для отдельных создателей Claude, ChatGPT или Writesonic предлагают сопоставимое качество написания по более низкой цене."}, {"q": "Есть ли у Jasper SEO-инструменты?", "a": "Jasper интегрируется с Surfer SEO для оптимизации контента. Эта комбинация — Jasper для написания, Surfer для оптимизации — популярна среди команд контент-маркетинга. Jasper сам по себе не включает SEO-анализ, Surfer нужно добавлять отдельно."}]$x$::jsonb
 WHERE slug = 'jasper' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Copy.ai чи Jasper для малого бізнесу?", "a": "Copy.ai краще для малого бізнесу: дешевший і простіший. Jasper кращий для маркетингових команд що потребують консистентного брендового голосу. Для соло-підприємців — Copy.ai; для команд — Jasper."}]$x$::jsonb
