UPDATE tools SET faq = $x$[{"q": "Copy.ai ou Jasper — lequel choisir ?", "a": "Copy.ai est meilleur pour les textes courts et les solopreneurs avec un budget limité. Jasper est meilleur pour les équipes marketing produisant du contenu long format avec une voix de marque. Débutants et petits budgets → Copy.ai ; équipes marketing avancées → Jasper."}, {"q": "Jasper peut-il écrire en français ?", "a": "Oui. Jasper prend en charge le français parmi ses 30+ langues. La qualité est meilleure en anglais, mais le français est bien supporté. Vérifiez toujours le contenu généré pour un français naturel et précis."}]$x$::jsonb
