UPDATE tools SET faq = $x$[{"q": "Copy.ai ou Jasper — qual é melhor para marketing?", "a": "Copy.ai é melhor para geração rápida de textos de marketing a custo menor. Jasper é melhor para equipes maiores que precisam de consistência de marca e fluxos de trabalho avançados. Para uso individual, Copy.ai; para equipes, Jasper."}, {"q": "Jasper é melhor que Copy.ai?", "a": "Depende do caso de uso. Jasper é melhor para equipes maiores e consistência de marca. Copy.ai é melhor para uso individual e custo-benefício. Ambos são bons; a escolha depende do tamanho da equipe e orçamento."}]$x$::jsonb
 WHERE slug = 'jasper' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Julius AI puede construir modelos predictivos?", "a": "Julius AI puede hacer análisis estadísticos y regresiones básicas, pero no está diseñado para construir modelos predictivos de producción. Akkio está específicamente hecho para crear modelos de predicción (churn, conversión, forecasting) listos para integrar en sistemas de negocio."}]$x$::jsonb
 WHERE slug = 'julius-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Akkio vs Julius AI: Was ist der Unterschied?", "a": "Akkio ist für prädiktive Machine-Learning-Modelle: Sie trainieren ein Modell das zukünftige Ereignisse vorhersagt. Julius AI ist für explorative Analyse: Sie stellen Fragen an bestehende Daten und erhalten sofort Insights. Akkio für Vorhersagen; Julius für Analyse."}, {"q": "Julius AI für Excel-Daten: Funktioniert das?", "a": "Ja. Julius AI akzeptiert Excel und CSV-Uploads. Sie können direkt Excel-Dateien hochladen und in natürlicher Sprache Fragen stellen: 'Was ist der Umsatztrend pro Quartal?' oder 'Welches Produkt hat die höchste Marge?'"}]$x$::jsonb
 WHERE slug = 'julius-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Julius AI?", "a": "Julius AI — инструмент разговорного анализа данных. Загружаете CSV-файлы, подключаете базы данных или Google Sheets, затем задаёте вопросы на обычном языке. Julius пишет и запускает анализ, генерирует графики и объясняет результаты на простом языке — без SQL или кода."}, {"q": "В чём разница между Julius AI и ChatGPT для данных?", "a": "Julius AI специально создан для анализа данных с постоянными загрузками файлов, выполнением кода и генерацией графиков, оптимизированными для задач с данными. ChatGPT с инструментом анализа данных делает аналогичные вещи, но более универсально. У Julius более чистый UX, ориентированный на данные."}]$x$::jsonb
 WHERE slug = 'julius-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Akkio vs Julius AI — яка різниця?", "a": "Akkio будує прогнозні ML-моделі без коду для бізнес-прогнозування. Julius AI аналізує наявні дані через розмову і генерує візуалізації. Akkio для прогнозування; Julius для пізнавальної аналітики."}, {"q": "Julius AI vs ChatGPT Advanced Data Analysis?", "a": "Julius AI спеціалізується на аналізі даних. ChatGPT Advanced Data Analysis (раніше Code Interpreter) схожий але більш загальний. Julius AI часто швидший і зручніший для даних; ChatGPT краще для змішаних завдань."}, {"q": "Julius AI vs ChatGPT для аналізу даних — яка різниця?", "a": "Julius AI спеціалізований для даних: завантажте файл і отримуйте аналіз. ChatGPT більш загальний і має обмежені можливості роботи з файлами. Для аналізу даних Julius AI зручніший; для загальних задач — ChatGPT."}, {"q": "Julius AI безкоштовний?", "a": "Julius AI має безкоштовний план з обмеженим числом повідомлень. Pro від $20/міс. Looker Studio повністю безкоштовний."}, {"q": "Julius AI може писати SQL?", "a": "Так. Julius AI може генерувати SQL-запити і виконувати їх проти ваших даних. Він також пояснює що робить SQL і інтерпретує результати."}]$x$::jsonb
 WHERE slug = 'julius-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Akkio לעומת Julius AI?", "a": "Akkio לבניית מודלי ML ולחיזוי. Julius AI לניתוח נתונים ויצירת גרפים. Akkio ל-ML; Julius לניתוח ו-EDA."}, {"q": "Julius AI לעברית?", "a": "Julius AI יכול לעבד נתונים עבריים (UTF-8) ולענות על שאלות. ממשק באנגלית אך ניתן לשאול בעברית על נתונים עבריים."}]$x$::jsonb
 WHERE slug = 'julius-ai' AND lang = 'he';

