UPDATE tools SET faq = $x$[{"q": "Coursera Coach vs Khanmigo: Wer ist besser für Studenten?", "a": "Für Hochschul- und Berufsausbildungs-Kurse — Coursera Coach (direkt im Kurs). Für Schulfächer und Khan Academy-Content — Khanmigo. Beide haben ihren Platz: Coursera für professionelle Weiterbildung; Khanmigo für schulische Grundfächer."}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Khanmigo?", "a": "Khanmigo — ИИ-репетитор Khan Academy на базе GPT-4. Использует сократовский метод — задаёт наводящие вопросы, а не даёт ответы — для понимания концепций студентами. Охватывает математику, естественные науки, историю и гуманитарные предметы. Бесплатен для студентов в США."}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Coursera Coach vs Khanmigo — яка різниця?", "a": "Coursera Coach прив'язаний до курсів Coursera для дорослих учнів. Khanmigo — педагогічний ШІ-репетитор для K-12 учнів на Khan Academy. Coursera для професійного навчання; Khanmigo для шкільного і базового навчання."}, {"q": "Khanmigo безкоштовний?", "a": "Khanmigo доступний безкоштовно для учнів через Khan Academy. Є також платний план для батьків і вчителів. Coursera Coach включений у підписки Coursera Plus."}, {"q": "Khanmigo vs ChatGPT для навчання?", "a": "Khanmigo спеціально оптимізований для навчання — направляє учня до відповіді через запитання. ChatGPT відразу дає відповідь. Для реального навчання і розуміння — Khanmigo; для швидкої перевірки — ChatGPT."}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Coursera Coach לעומת Khanmigo?", "a": "Coursera Coach ל-learners בקורסי Coursera. Khanmigo לתלמידים בחומר בית-ספרי. Coursera לאנשי מקצוע; Khanmigo לתלמידים ובגרויות."}, {"q": "Coursera לישראל – האם יש תוכן בעברית?", "a": "Coursera באנגלית בעיקר עם כתוביות מתורגמות לחלק מהקורסים. Khanmigo באנגלית; Khan Academy מציע חלק מהתוכן בעברית."}, {"q": "Khanmigo לבגרויות ישראליות?", "a": "Khanmigo יכול לעזור בחומר בגרות מתמטיקה, מדעים ואנגלית. עבור בגרויות בעברית הייעודיות לישראל – מומלץ לבדוק תאימות."}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Coursera Coach vs Khanmigo — lequel est le meilleur ?", "a": "Coursera Coach est meilleur pour l'apprentissage professionnel et les cours universitaires en ligne. Khanmigo est meilleur pour l'aide aux devoirs scolaires avec une pédagogie socratique. Formation professionnelle → Coursera Coach ; aide aux devoirs scolaires → Khanmigo."}, {"q": "Khanmigo est-il disponible en français ?", "a": "Khanmigo est principalement disponible en anglais. Khan Academy a du contenu en français mais Khanmigo lui-même est limité pour le français. Pour une aide aux devoirs en français, des alternatives comme Claude ou ChatGPT peuvent être utilisés directement."}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Coursera Coach vs Khanmigo — qual é o melhor?", "a": "Coursera Coach é melhor para aprendizado profissional e cursos universitários online. Khanmigo é melhor para ajuda com tarefas escolares com pedagogia socrática. Formação profissional → Coursera Coach; ajuda com tarefas escolares → Khanmigo."}, {"q": "Khanmigo está disponível em português?", "a": "Khanmigo está principalmente disponível em inglês. Khan Academy tem conteúdo em português mas o Khanmigo em si é limitado para o português. Para ajuda com tarefas em português, alternativas como Claude ou ChatGPT podem ser usadas diretamente."}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Kling AI o Runway para generación de video?", "a": "Kling 2.0 es más competitivo en generación texto-a-video con videos más largos y menor costo. Runway es más completo como suite de producción: combina generación con edición avanzada. Para generación de clips — Kling; para producción integral — Runway."}, {"q": "¿Cuánto cuesta Kling AI?", "a": "Kling AI tiene un plan gratuito con créditos limitados. Los planes de pago empiezan desde $10/mes (Standard con 660 créditos). Runway empieza desde $12/mes (Standard) con 625 créditos al mes."}, {"q": "¿Kling puede generar videos de 3 minutos?", "a": "Sí. Kling 2.0 puede generar videos de hasta 3 minutos, significativamente más que los 4-16 segundos típicos de otros modelos. Runway Gen-3 Alpha genera hasta 10 segundos por clip. Para contenido más largo, Kling tiene ventaja."}, {"q": "¿Es Kling AI mejor que Sora?", "a": "Kling 2.0 es competitivo con Sora en calidad de movimiento y física. Sora tiene mayor acceso controlado (solo usuarios de ChatGPT Pro y Plus). Kling ofrece acceso más democrático con su tier gratuito. En benchmarks independientes, compiten en el top tier de generadores de video en 2025."}]$x$::jsonb
 WHERE slug = 'kling-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Kling AI vs Runway: Welches ist besser?", "a": "Kling AI bietet hervorragendes Preis-Leistungs-Verhältnis mit einem großzügigen kostenlosen Plan. Runway ist ausgereifter mit mehr professionellen Steuerungsmöglichkeiten. Für gelegentliche Nutzung und Budget-Bewusstsein — Kling; für professionelle Video-Produktion — Runway."}, {"q": "Ist Kling AI kostenlos?", "a": "Ja. Kling hat einen kostenlosen Plan mit täglichen Credits für Standard-Qualitäts-Videos. Pro-Pläne starten ab ca. $15/Monat für höhere Qualität und mehr Credits. Runway beginnt ab $15/Monat (Standard)."}, {"q": "Wie lang können Kling AI Videos sein?", "a": "Kling generiert standardmäßig 5-10 Sekunden Videos. Mit Pro-Plänen können Videos bis zu 3 Minuten Länge durch Aneinanderreihung von Clips generiert werden. Runway generiert standardmäßig 4-16 Sekunden pro Clip."}, {"q": "Kann Kling AI aus einem Foto ein Video machen?", "a": "Ja. Kling's Image-to-Video-Funktion kann ein statisches Foto animieren und lebensechte Bewegungen hinzufügen. Das ist eine der populärsten Anwendungen — Familienfotos oder Portraits zum Leben erwecken."}]$x$::jsonb
 WHERE slug = 'kling-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Kling AI лучше Runway в 2026 году?", "a": "Зависит от приоритетов. Runway Gen-4.5 лидирует по качеству бенчмаркам и предлагает многомодельную подписку. Kling 3.0 предлагает лучшую ценность — больше бесплатных кредитов, нативное 4K и более низкую цену. Для профессионалов — Runway, для соотношения цена/качество — Kling."}, {"q": "Можно использовать Kling AI бесплатно?", "a": "Да. Kling AI предлагает 66 бесплатных кредитов ежедневно — самый щедрый бесплатный уровень среди качественных генераторов ИИ-видео. Бесплатный пробный период Runway даёт 125 одноразовых кредитов без обновления."}, {"q": "Kling AI поддерживает 4K?", "a": "Да. Kling 3.0 (февраль 2026 года) поддерживает нативный вывод 4K с инструментом раскадровки для покадрового управления камерой и встроенной генерацией аудио с синхронизацией губ."}]$x$::jsonb
 WHERE slug = 'kling-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Kling AI безкоштовний?", "a": "Kling AI має безкоштовний план з обмеженими кредитами. Платні плани від $8,8/міс. Runway має безкоштовний план; Standard від $15/міс."}, {"q": "Яка максимальна тривалість відео у Kling?", "a": "Kling AI генерує відео до 3 хвилин (через послідовні кліпи). Одиничний кліп до 10 секунд у вищих планах. Runway — до 16 секунд за один генерацію."}]$x$::jsonb
 WHERE slug = 'kling-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Kling AI מול Runway — מה עדיף?", "a": "Kling AI מציע ערך טוב יותר לכסף עם תוכנית חינמית נדיבה יותר. Runway מוביל בכלי עריכה מתקדמים ואמון מסחרי. לניסיון חינמי — Kling; לשימוש מקצועי — Runway."}, {"q": "Kling AI בחינם?", "a": "כן, Kling AI מציע 66 קרדיטים/יום חינם. תוכניות בתשלום מ-7$/חודש. Runway מציע 125 קרדיטים בחינם; Standard מ-15$/חודש."}, {"q": "כמה זמן לוקח ל-Kling לייצר וידאו?", "a": "Kling מייצר וידאו של 5-10 שניות תוך 2-5 דקות בדרך כלל. הזמן תלוי בעומס השרת. Runway Gen-3 לרוב מהיר יותר לסרטים קצרים."}]$x$::jsonb
 WHERE slug = 'kling-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Kling AI vs Runway — lequel est le meilleur ?", "a": "Kling AI offre une meilleure valeur et une qualité comparable à Runway Gen-3. Runway est plus établi avec plus de fonctionnalités avancées. Pour le rapport qualité-prix, Kling ; pour la production professionnelle avec un contrôle avancé, Runway."}, {"q": "Combien coûte Kling AI ?", "a": "Kling AI à partir de 8 $/mois (Standard). Runway à partir de 15 $/mois (Standard). Kling est bien moins cher pour des capacités similaires."}, {"q": "Kling AI peut-il générer des vidéos longues ?", "a": "Kling génère des vidéos jusqu'à 3 minutes (avec le plan Pro). Pour des vidéos plus longues, vous générez des segments et les assemblez. Runway est similaire en termes de longueur maximale par génération."}, {"q": "Kling AI est-il disponible en France ?", "a": "Oui. Kling AI est accessible globalement via son site web. Les paiements sont disponibles via des méthodes de paiement internationales standard. Certaines fonctionnalités peuvent avoir des délais de déploiement régional."}]$x$::jsonb
 WHERE slug = 'kling-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Kling AI vs Runway — qual é o melhor?", "a": "Kling AI gera vídeos mais longos com ótima qualidade de movimento. Runway tem ferramentas de edição mais avançadas e melhor qualidade visual geral. Para vídeos longos e narrativos, Kling; para produção criativa profissional, Runway."}, {"q": "Kling AI é gratuito?", "a": "Kling AI tem plano gratuito com créditos limitados. Planos pagos a partir de $9,99/mês. Runway tem plano gratuito limitado; planos pagos a partir de $15/mês."}, {"q": "Kling AI é de qual empresa?", "a": "Kling AI é desenvolvido pela Kuaishou Technology, empresa chinesa de tecnologia conhecida pelo aplicativo de vídeo curto Kwai."}, {"q": "Kling vs Sora — qual é a diferença?", "a": "Kling AI está disponível publicamente com plano gratuito. Sora da OpenAI tem acesso limitado e foca em vídeos de alta qualidade cinematográfica. Para acesso imediato, Kling; para máxima qualidade, Sora quando disponível."}]$x$::jsonb
 WHERE slug = 'kling-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Koyfin es gratuito?", "a": "Sí. Koyfin tiene un plan gratuito muy completo con acceso a estados financieros, métricas de valoración y datos macroeconómicos. El plan Pro ($49/mes) añade datos más avanzados y mayor personalización. Es una de las mejores alternativas gratuitas a Bloomberg para inversores fundamentales."}, {"q": "¿Koyfin vs Tikr para análisis fundamental?", "a": "Koyfin tiene mejor interfaz y dashboards más visuales. Tikr tiene más datos históricos y profundidad de datos financieros. Koyfin es más popular entre inversores individuales por su experiencia de usuario; Tikr entre analistas que necesitan datos más detallados. Ambas son excelentes alternativas gratuitas a Bloomberg."}, {"q": "¿Koyfin tiene datos de renta fija?", "a": "Koyfin tiene datos de bonos del tesoro y algunos datos de tipos de interés. Para análisis profundo de renta fija — Bloomberg Terminal sigue siendo el estándar profesional. Koyfin es excelente para renta variable; más limitado para renta fija institucional."}]$x$::jsonb
 WHERE slug = 'koyfin' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Koyfin vs Bloomberg: Was ist der Unterschied?", "a": "Bloomberg Terminal kostet etwa $25.000/Jahr und ist der professionelle Standard in der Finanzbranche. Koyfin bietet ähnliche Fundamentaldaten und Makro-Dashboards ab $59/Monat. Für professionelle Investoren ohne Bloomberg-Budget ist Koyfin eine ausgezeichnete Alternative."}, {"q": "Ist Koyfin kostenlos?", "a": "Koyfin hat einen kostenlosen Plan mit begrenzten Features. Plus ab $59/Monat, Pro ab $199/Monat. TradingView hat einen kostenlosen Plan; Essential ab $14,95/Monat."}, {"q": "Koyfin für Aktienscreening: Ist es gut?", "a": "Ja. Koyfin hat einen leistungsstarken Aktienscreener mit hunderten fundamentalen und technischen Filtern. Sie können Aktien nach KGV, Wachstumsrate, Dividende, geografischer Region und vielen anderen Kriterien screenen."}]$x$::jsonb
 WHERE slug = 'koyfin' AND lang = 'de';

