 WHERE slug = 'koyfin' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Koyfin vs Bloomberg — яка різниця?", "a": "Bloomberg Terminal коштує близько $25 000/рік і є професійним стандартом у фінансах. Koyfin пропонує схожі фундаментальні дані і макро-дашборди від $59/міс. Для інвесторів без бюджету Bloomberg — Koyfin відмінна альтернатива."}, {"q": "Koyfin безкоштовний?", "a": "Koyfin має безкоштовний план з обмеженими функціями. Plus від $59/міс, Pro від $199/міс. TradingView має безкоштовний план; Essential від $14,95/міс."}]$x$::jsonb
