UPDATE tools SET faq = $x$[{"q": "¿Qué hace especial a Krea AI?", "a": "Krea AI tiene una función única: generación en tiempo real. Mientras escribes el prompt o dibocas en el canvas, la imagen se actualiza instantáneamente con cada cambio. Esta experiencia iterativa y visual es completamente diferente al ciclo de espera de Midjourney u otros generadores."}, {"q": "¿Krea AI es gratuito?", "a": "Krea AI tiene un plan gratuito con generaciones limitadas. Los planes de pago empiezan desde $24/mes (Standard) con mayor resolución y generaciones ilimitadas. Midjourney no tiene plan gratuito; desde $10/mes."}, {"q": "¿Krea AI puede generar video?", "a": "Sí. Krea AI tiene función de generación de video además de imágenes. También puede hacer image-to-video y tiene herramientas de upscaling de video. La suite es más completa que solo generación de imágenes."}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Krea AI?", "a": "Krea AI ist ein KI-Kreativtool mit einzigartiger Echtzeit-Canvas-Funktion: Sie zeichnen oder platzieren Elemente und KI generiert sofort live ein Bild basierend auf Ihrer Skizze. Außerdem bietet Krea leistungsstarkes Upscaling und Bildverbesserung."}, {"q": "Krea AI vs Midjourney: Was ist einzigartiger?", "a": "Krea's Echtzeit-Canvas ist einzigartig — kein anderes Tool der Klasse bietet live KI-Generierung während Sie zeichnen. Midjourney führt bei statischer Bild-Qualität und künstlerischer Ausgereiftheit. Krea für interaktive kreative Exploration; Midjourney für finale Qualität."}, {"q": "Ist Krea AI kostenlos?", "a": "Krea hat einen kostenlosen Plan mit begrenzten täglichen Generierungen. Pro ab $35/Monat für unbegrenzte Nutzung. Midjourney ab $10/Monat."}, {"q": "Krea AI Upscaling: Wie gut ist es?", "a": "Krea's Upscaler ist einer der besten verfügbaren — er erhöht nicht nur die Auflösung sondern verbessert Details und Schärfe erheblich. Für professionelle Bildveredelung ist Krea's Upscaling tool eine der besten Optionen auf dem Markt."}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Krea AI vs Midjourney — в чём разница?", "a": "Krea AI предлагает уникальную генерацию в реальном времени и усиление изображений. Midjourney V7 превосходит по художественному качеству и эстетике финальных результатов. Krea — для интерактивного процесса, Midjourney — для лучших результатов."}, {"q": "Krea AI бесплатный?", "a": "Да. Krea AI предлагает бесплатный план с ограниченными генерациями в реальном времени. Starter — $24/мес, Pro — $96/мес для профессиональных объёмов."}, {"q": "Что такое генерация в реальном времени в Krea?", "a": "Real-time generation — уникальная функция Krea: рисуете скетч или перемещаете слайдер, и ИИ мгновенно обновляет изображение. Это делает итерацию значительно быстрее, чем ожидание каждой генерации в Midjourney."}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Krea AI vs Midjourney — яка різниця?", "a": "Krea AI орієнтований на інтерактивну генерацію в реальному часі: малюйте і бачте ШІ-результат миттєво. Midjourney орієнтований на найвищу художню якість фінального результату. Krea для ітерації; Midjourney для якості."}, {"q": "Krea AI безкоштовний?", "a": "Krea AI має безкоштовний план з обмеженнями. Платні плани від $24/міс. Midjourney від $10/міс; немає безкоштовного плану."}, {"q": "Що таке генерація в реальному часі?", "a": "У Krea AI ви малюєте ескіз або вводите елементи і ШІ показує рендер вашого зображення миттєво — без очікування. Ви бачите результат у реальному часі і можете редагувати. Це відрізняється від черги промптів Midjourney."}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Krea AI לעומת Midjourney – מה עדיף?", "a": "Krea מצוין לעריכה אינטראקטיבית ו-Upscaling. Midjourney הסטנדרט לאיכות אמנות AI. Krea לעריכה וגמישות; Midjourney לאיכות אמנות."}, {"q": "Krea AI חינמי?", "a": "Krea מציע תוכנית חינמית מוגבלת; Basic מ-$10/חודש. Midjourney מ-$10/חודש; לא מציע תוכנית חינמית."}, {"q": "Krea AI Real-time – איך זה עובד?", "a": "Krea Real-time מציג תמונה AI בזמן ציור ב-Canvas. מאפשר לראות שינויים מיידיים בתוצאת ה-AI ולהתאים בהתאם."}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Krea AI vs Midjourney — quelle est la différence ?", "a": "Krea AI se distingue par sa génération en temps réel et ses fonctionnalités d'idéation créative. Midjourney est le standard pour l'art IA de haute qualité avec une communauté massive. Pour l'exploration créative en temps réel → Krea ; pour la qualité artistique finale → Midjourney."}, {"q": "Krea AI est-il gratuit ?", "a": "Krea AI a un plan gratuit avec des crédits limités. Les plans payants à partir de 10 $/mois. Midjourney à partir de 10 $/mois sans plan gratuit permanent."}, {"q": "Krea AI peut-il améliorer des images existantes ?", "a": "Oui. Krea AI dispose d'outils d'upscaling et d'amélioration d'images qui augmentent la résolution et améliorent la qualité des images existantes. C'est une fonctionnalité utile pour améliorer des images générées ou des photos."}, {"q": "Krea AI Real-Time — comment ça fonctionne ?", "a": "Krea AI Real-Time montre la génération IA en direct pendant que vous dessinez ou modifiez votre prompt. L'image se met à jour en quelques secondes à chaque modification. C'est révolutionnaire pour l'idéation créative rapide."}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Krea AI vs Midjourney — qual é a diferença?", "a": "Krea AI se destaca pela geração em tempo real e funcionalidades de ideação criativa. Midjourney é o padrão para arte de IA de alta qualidade com comunidade enorme. Para exploração criativa em tempo real → Krea; para qualidade artística final → Midjourney."}, {"q": "Krea AI é gratuito?", "a": "Krea AI tem plano gratuito com créditos limitados. Planos pagos a partir de $10/mês. Midjourney a partir de $10/mês sem plano gratuito permanente."}, {"q": "Krea AI pode aprimorar imagens existentes?", "a": "Sim. Krea AI tem ferramentas de upscaling e aprimoramento que aumentam a resolução e melhoram a qualidade de imagens existentes. É uma funcionalidade útil para melhorar imagens geradas ou fotos."}, {"q": "Krea AI Real-Time — como funciona?", "a": "Krea AI Real-Time mostra a geração de IA ao vivo enquanto você desenha ou modifica seu prompt. A imagem se atualiza em segundos a cada modificação. É revolucionário para ideação criativa rápida."}]$x$::jsonb
 WHERE slug = 'krea-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Leonardo AI tiene plan gratuito?", "a": "Sí. Leonardo AI tiene un plan gratuito muy generoso con 150 tokens diarios (cada imagen cuesta 1-8 tokens según el modelo y resolución). Esto permite generar decenas de imágenes al día sin pagar. Los planes de pago (desde $12/mes) añaden tokens ilimitados y funciones avanzadas."}, {"q": "¿Leonardo AI es bueno para principiantes?", "a": "Leonardo AI tiene más funciones que Nano Banana, pero tiene una interfaz razonablemente accesible. El plan gratuito generoso lo hace ideal para experimentar. Para principiantes absolutos — Nano Banana es más simple; para principiantes que quieren aprender más — Leonardo AI con su plan gratuito es excelente."}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Для чего используется Leonardo.ai?", "a": "Leonardo.ai — платформа генерации ИИ-изображений, популярная среди разработчиков игр, концепт-художников и дизайнеров. Предлагает дообучение на кастомных наборах изображений, редактор холста, генерацию движения и функции эталонных персонажей для поддержания согласованности в серии изображений."}, {"q": "Leonardo.ai лучше Stable Diffusion?", "a": "Leonardo.ai построен поверх Stable Diffusion, но добавляет кураторский платформенный опыт, дообученные модели, лучший UI и функции сообщества. Для пользователей, не желающих настраивать локальный Stable Diffusion, Leonardo предлагает аналогичные возможности с гораздо меньшей технической настройкой."}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Leonardo AI vs Midjourney — різниця?", "a": "Leonardo AI дає більше контролю через кастомні моделі і LoRA; підходить для геймдеву і послідовних стилів. Midjourney виробляє якісніший вихідний продукт з меншими зусиллями. Для контролю і геймдеву — Leonardo; для якості — Midjourney."}, {"q": "Leonardo AI безкоштовний?", "a": "Leonardo AI має безкоштовний план з 150 токенів/день. Платні плани від $12/міс. Nano Banana — перевірте поточне ціноутворення на офіційному сайті."}, {"q": "Що таке LoRA у Leonardo AI?", "a": "LoRA (Low-Rank Adaptation) — техніка тонкого налаштування що дозволяє навчати модель на невеликому наборі зображень для відтворення конкретного стилю або персонажа. Leonardo AI підтримує завантаження і використання LoRA-моделей."}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Nano Banana לעומת Leonardo AI?", "a": "Nano Banana מתמקד בפשטות ובמהירות. Leonardo AI מקיף יותר עם כלים מקצועיים. Nano Banana למשתמשים מזדמנים; Leonardo AI לאנשי מקצוע יצירתיים."}, {"q": "Leonardo AI חינמי?", "a": "Leonardo AI מציע 150 tokens יומיים חינם; Apprentice מ-$12/חודש. בדקו את אתר Nano Banana לפרטי מחיר עדכניים."}, {"q": "מה ייחודי ב-Leonardo AI Consistency?", "a": "Leonardo AI מאפשר יצירת Characters עקביים בין תמונות – חשוב לקומיקס, סטוריבורד ו-Character Design. Character Consistency Tool שומר על מראה אחיד."}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Nano Banana vs Leonardo AI — lequel est le meilleur ?", "a": "Leonardo AI est plus établi avec plus de fonctionnalités, une communauté plus grande et un plan gratuit généreux. Nano Banana est une alternative plus récente. Pour une plateforme éprouvée → Leonardo AI."}, {"q": "Leonardo AI est-il bon pour les illustrations de jeux ?", "a": "Oui. Leonardo AI est particulièrement apprécié pour les actifs de jeux : personnages cohérents, textures, icônes et environnements. Le fine-tuning permet de maintenir un style visuel cohérent sur plusieurs générations."}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Nano Banana vs Leonardo AI — qual é o melhor?", "a": "Leonardo AI é mais estabelecido com mais funcionalidades, comunidade maior e plano gratuito generoso. Nano Banana é uma alternativa mais recente. Para uma plataforma consolidada → Leonardo AI."}, {"q": "Leonardo AI é bom para ilustrações de jogos?", "a": "Sim. Leonardo AI é particularmente apreciado para assets de jogos: personagens consistentes, texturas, ícones e ambientes. O fine-tuning permite manter um estilo visual consistente em múltiplas gerações."}]$x$::jsonb
 WHERE slug = 'leonardo-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Lindy?", "a": "Lindy es una plataforma de agentes de IA para automatización personal y empresarial. Permite crear 'Lindys' (agentes) que gestionan correos, programan reuniones, califican leads y ejecutan flujos de trabajo de forma autónoma. Diseñado para usuarios no técnicos."}, {"q": "¿Lindy es gratuito?", "a": "Lindy tiene un plan gratuito con funciones limitadas. Los planes de pago empiezan desde $49/mes. Copilot Studio tiene 25.000 mensajes gratuitos; licencias empresariales desde $200/mes."}, {"q": "¿Lindy puede gestionar mi correo electrónico?", "a": "Sí. Lindy conecta tu Gmail o Outlook y puede clasificar, responder o reenviar correos según tus instrucciones. Puede calificar leads entrantes o responder preguntas frecuentes automáticamente."}, {"q": "¿Lindy vs Zapier: cuál es mejor para automatización?", "a": "Son enfoques diferentes. Zapier conecta aplicaciones mediante triggers y acciones simples. Lindy usa IA para tomar decisiones contextualmente — el agente decide cómo responder basándose en el contenido, no solo en reglas fijas. Para automatización inteligente — Lindy; para integraciones simples — Zapier."}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Lindy?", "a": "Lindy ist eine KI-Agenten-Plattform für persönliche und geschäftliche Automatisierung. Sie ermöglicht die Erstellung von 'Lindys' (Agenten), die E-Mails verwalten, Meetings planen, Leads qualifizieren und Workflows autonom ausführen. Für nicht-technische Nutzer konzipiert."}, {"q": "Ist Lindy kostenlos?", "a": "Lindy hat einen kostenlosen Plan mit begrenzten Funktionen. Kostenpflichtige Pläne beginnen ab $49/Monat. Copilot Studio beinhaltet 25.000 kostenlose Nachrichten; Enterprise-Lizenzen ab $200/Monat."}, {"q": "Kann Lindy meine E-Mails verwalten?", "a": "Ja. Lindy verbindet Ihr Gmail oder Outlook und kann E-Mails klassifizieren, beantworten oder weiterleiten gemäß Ihren Anweisungen. Es kann eingehende Leads qualifizieren oder häufig gestellte Fragen automatisch beantworten."}, {"q": "Lindy vs Zapier: Welches ist besser für Automatisierung?", "a": "Das sind unterschiedliche Ansätze. Zapier verbindet Anwendungen durch einfache Trigger und Aktionen. Lindy verwendet KI für kontextuelle Entscheidungen — der Agent entscheidet basierend auf dem Inhalt, nicht nur festen Regeln. Für intelligente Automatisierung — Lindy; für einfache Integrationen — Zapier."}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Lindy AI?", "a": "Lindy — платформа ИИ-ассистентов, создающая личных и бизнес-агентов. Агенты могут управлять электронной почтой, подготавливать встречи, обновлять CRM, проводить исследования и обрабатывать клиентскую поддержку. Подключаете Lindy к своим приложениям (Gmail, Slack, Salesforce) и определяете рабочие процессы."}, {"q": "В чём разница между Lindy и Zapier?", "a": "Zapier автоматизирует фиксированные, основанные на правилах рабочие процессы между приложениями. Lindy использует ИИ для обработки переменных ситуаций — чтения писем, принятия решений, контекстного ответа. Zapier лучше для предсказуемой автоматизации, Lindy — когда задачи требуют суждения и естественного языка."}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Що таке Lindy AI?", "a": "Lindy — платформа для побудови персональних ШІ-агентів без коду. Агенти Lindy можуть управляти email, планувати зустрічі, відповідати клієнтам і автоматизувати повторювані завдання. Позиціонується як «ШІ-асистент що справді діє»."}, {"q": "Lindy vs Zapier — різниця?", "a": "Lindy фокусується на агентах — ШІ що приймає рішення і діє самостійно. Zapier — детерміновані автоматизації типу якщо-то. Lindy більш гнучкий для завдань де потрібно розуміння; Zapier більш надійний для структурованих потоків."}, {"q": "Lindy безпечний для корпоративного використання?", "a": "Lindy надає стандартні засоби захисту але не має корпоративних сертифікацій рівня Microsoft. Для regulated-галузей з суворими вимогами Copilot Studio з Azure-бекендом безпечніший."}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "מה זה Lindy AI?", "a": "Lindy הוא פלטפורמה לבניית סוכני AI אישיים ללא קוד. סוכני Lindy יכולים לנהל אימייל, לתזמן פגישות, לענות ללקוחות ולאטמט משימות חוזרות. ממוצב כ'עוזר AI שבאמת פועל'."}, {"q": "Lindy מול Zapier — מה ההבדל?", "a": "Lindy מתמקד בסוכנים — AI שמקבל החלטות ופועל באופן עצמאי. Zapier הוא אוטומציות דטרמיניסטיות מסוג אם-אז. Lindy גמיש יותר למשימות שדורשות הבנה; Zapier אמין יותר לזרימות מובנות."}, {"q": "האם Lindy בטוח לשימוש ארגוני?", "a": "Lindy מספק אמצעי אבטחה סטנדרטיים אבל אין לו אישורים ארגוניים ברמת Microsoft. לתעשיות רגולטוריות עם דרישות מחמירות, Copilot Studio עם Azure backend בטוח יותר."}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Lindy AI ?", "a": "Lindy est une plateforme pour créer des agents IA personnels sans code. Les agents Lindy peuvent gérer les emails, planifier des réunions, répondre aux clients et automatiser les tâches répétitives. Il est positionné comme un 'assistant IA qui agit vraiment'."}, {"q": "Lindy AI est-il gratuit ?", "a": "Lindy a un plan gratuit avec des limites. Les plans payants dépendent du nombre d'actions. Microsoft Copilot Studio à partir de 200 $/mois."}, {"q": "Lindy vs Zapier — quelle est la différence ?", "a": "Lindy se concentre sur les agents — des IA qui prennent des décisions et agissent de manière autonome. Zapier automatise des flux déterministes de type si-alors. Lindy est plus flexible pour les tâches nécessitant une compréhension ; Zapier plus fiable pour les flux structurés."}, {"q": "Lindy est-il sûr pour une utilisation en entreprise ?", "a": "Lindy fournit des protections standard mais n'a pas les certifications d'entreprise au niveau Microsoft. Pour les secteurs réglementés aux exigences strictes, Copilot Studio avec backend Azure est plus sûr."}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "O que é Lindy AI?", "a": "Lindy é uma plataforma para criar agentes de IA pessoais sem código. Os agentes Lindy podem gerenciar emails, agendar reuniões, responder clientes e automatizar tarefas repetitivas. É posicionado como um 'assistente de IA que realmente age'."}, {"q": "Lindy AI é gratuito?", "a": "Lindy tem um plano gratuito com limites. Os planos pagos dependem do número de ações. Microsoft Copilot Studio a partir de $200/mês."}, {"q": "Lindy vs Zapier — qual é a diferença?", "a": "Lindy foca em agentes — IAs que tomam decisões e agem autonomamente. Zapier automatiza fluxos determinísticos do tipo se-então. Lindy é mais flexível para tarefas que requerem compreensão; Zapier é mais confiável para fluxos estruturados."}, {"q": "Lindy é seguro para uso corporativo?", "a": "Lindy fornece proteções padrão, mas não tem as certificações corporativas no nível Microsoft. Para setores regulamentados com requisitos rigorosos, o Copilot Studio com backend Azure é mais seguro."}]$x$::jsonb
 WHERE slug = 'lindy' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Что такое Looka?", "a": "Looka — ИИ-сервис создания логотипов и фирменного стиля. Введите название компании и предпочтения, и Looka создаст десятки вариантов логотипов с помощью ИИ. Вы настраиваете выбранный логотип и скачиваете брендовые активы, включая векторные файлы, коды цветов и шрифты."}, {"q": "Может ли Canva создать профессиональный логотип?", "a": "Конструктор логотипов Canva может создавать логотипы с помощью ИИ, но для полноценного профессионального фирменного стиля с векторными файлами и руководством Looka более специализирован. Логотипы Canva подходят для простых случаев, Looka лучше, когда нужен полный брендовый пакет."}]$x$::jsonb
 WHERE slug = 'looka' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Looka чи Canva для логотипу?", "a": "Looka спеціалізується на логотипах і дає кращі результати для брендингу. Canva ширша але логотипи часто виглядають менш унікально. Для серйозного брендингу — Looka; для простого і дешевого логотипу — Canva."}, {"q": "Скільки коштує Looka?", "a": "Looka: Basic логотип $20 (PNG), Premium пакет $65 (всі формати), Brand Kit $80 (всі бренд-матеріали). Canva безкоштовний; Pro $15/міс."}]$x$::jsonb
 WHERE slug = 'looka' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Looka מול Canva AI לעיצוב לוגו?", "a": "Looka מתמחה ספציפית בלוגואים ובמיתוג עסקי. Canva AI כלי כללי שגם עושה לוגואים. ללוגו מקצועי עם חבילת מיתוג — Looka; לעיצוג כולל — Canva."}, {"q": "כמה עולה Looka?", "a": "Looka מציע קניה חד-פעמית: Basic Logo 20$, Premium Logo 65$, Brand Kit 96$. Canva Pro מ-15$/חודש."}]$x$::jsonb
 WHERE slug = 'looka' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Looker Studio o Tableau para marketing?", "a": "Looker Studio para marketing digital es excelente — integración nativa con Google Analytics, Ads y Search Console, completamente gratuito. Tableau es más potente para análisis complejo con datos de múltiples fuentes. Para reportes de marketing de Google — Looker Studio; para análisis BI empresarial avanzado — Tableau."}, {"q": "¿Looker Studio es gratuito?", "a": "Sí. Looker Studio es completamente gratuito para individuos y equipos. Google ofrece hasta 1.000 informes gratuitos. Looker Studio Pro ($9/usuario/mes) añade funciones de colaboración empresarial. Tableau empieza desde $75/usuario/mes."}, {"q": "¿Looker Studio vs Google Data Studio?", "a": "Son el mismo producto. Google Data Studio fue renombrado a Looker Studio en 2022. Looker Studio sigue siendo la herramienta gratuita de reportes de Google, con las mismas funciones de siempre más nuevas integraciones."}]$x$::jsonb
 WHERE slug = 'looker-studio' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Looker Studio vs Tableau: Was ist besser?", "a": "Looker Studio (kostenlos) ist ideal für Google-Ökosystem-Daten und einfache Marketing-Dashboards. Tableau ist leistungsfähiger für komplexe Unternehmensanalysen aber kostet ab $75/Benutzer/Monat. Für kleine Teams und Marketing — Looker Studio; für Enterprise-BI — Tableau."}, {"q": "Ist Looker Studio wirklich kostenlos?", "a": "Ja. Looker Studio ist vollständig kostenlos für Einzelnutzer. Looker Studio Pro kostet $9/Benutzer/Monat und fügt erweiterte Verwaltungs- und Kollaborations-Features für Teams hinzu."}, {"q": "Looker Studio vs Power BI: Was ist besser?", "a": "Beide sind starke Dashboard-Tools. Looker Studio ist kostenlos und Google-zentriert. Power BI ($10/Benutzer/Monat) ist tiefer in Microsoft 365 integriert und leistungsfähiger für komplexe Datenmodelle. Im Google-Ökosystem — Looker Studio; im Microsoft-Ökosystem — Power BI."}]$x$::jsonb
 WHERE slug = 'looker-studio' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Looker Studio бесплатный?", "a": "Да. Looker Studio полностью бесплатен без ограничений на дашборды, отчёты или объём данных. Подключается к 800+ источникам данных. Есть платные функции Looker Studio Pro для корпоративного управления, но основной продукт бесплатен."}, {"q": "Сколько стоит Tableau?", "a": "Tableau Viewer — $15/пользователь/мес, Explorer — $42/пользователь/мес, Creator — $75/пользователь/мес. Корпоративные цены варьируются. Tableau значительно дороже альтернатив, но широко считается золотым стандартом для сложной корпоративной аналитики."}, {"q": "Looker Studio так же мощен, как Tableau?", "a": "Для большинства задач бизнес-отчётности Looker Studio достаточен. Tableau имеет преимущества для очень больших наборов данных, сложных вычислений, продвинутого статистического анализа и корпоративного управления. Looker Studio хорошо справляется с обычными BI-дашбордами, Tableau — для продвинутых дата-команд."}]$x$::jsonb
 WHERE slug = 'looker-studio' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Looker Studio vs Power BI — яка різниця?", "a": "Looker Studio безкоштовний і відмінний для Google-екосистеми. Power BI потужніший для Microsoft-середовищ і enterprise аналітики. Обидва мають ШІ-функції. Для Google — Looker Studio; для Microsoft — Power BI."}, {"q": "Looker Studio безкоштовний?", "a": "Так. Looker Studio (раніше Data Studio) повністю безкоштовний. Tableau починається від $75/користувач/міс (Creator). Power BI безкоштовний для базового використання; Premium від $10/користувач/міс."}, {"q": "Looker Studio для e-commerce?", "a": "Так. Looker Studio популярний для e-commerce аналітики: GA4, Google Ads, Search Console. Є безліч готових шаблонів для e-commerce дашбордів. Для інтеграції з Facebook Ads або іншими платформами потрібні сторонні конектори."}]$x$::jsonb
 WHERE slug = 'looker-studio' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Looker Studio לעומת Tableau – מה עדיף?", "a": "Looker Studio חינמי ומצוין לאינטגרציה עם Google. Tableau מקצועי יותר ועוצמתי לנתונים מורכבים. לעסקים קטנים וסטארטאפים – Looker Studio; לEnterprise – Tableau."}, {"q": "Looker Studio חינמי לחלוטין?", "a": "כן, Looker Studio חינמי לחלוטין לשימוש בסיסי. Tableau Creator ב-$75/משתמש/חודש; Viewer ב-$15/חודש."}, {"q": "מה ההבדל בין Looker ו-Looker Studio?", "a": "Looker Studio (לשעבר Data Studio) הוא כלי BI חינמי ל-דשבורדים. Looker (נרכש ע\"י Google) הוא פלטפורמת BI מלאה Enterprise בתשלום. שני מוצרים שונים תחת מותג Google."}]$x$::jsonb
 WHERE slug = 'looker-studio' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Looker Studio vs Tableau — lequel est le meilleur ?", "a": "Looker Studio est gratuit et parfait pour les équipes marketing avec des données Google. Tableau est plus puissant pour les analyses complexes d'entreprise. Petites équipes et données Google → Looker Studio ; entreprises avec BI avancée → Tableau."}, {"q": "Looker Studio est-il vraiment gratuit ?", "a": "Oui. Looker Studio est entièrement gratuit. Vous payez uniquement pour les sources de données si elles sont payantes (ex : BigQuery). Tableau AI à partir de 75 $/utilisateur/mois."}, {"q": "Looker Studio se connecte-t-il à des sources de données non-Google ?", "a": "Oui. Looker Studio se connecte à des centaines de sources via des connecteurs natifs et des partenaires (Salesforce, HubSpot, PostgreSQL, etc.). Certains connecteurs tiers sont payants."}]$x$::jsonb
 WHERE slug = 'looker-studio' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Looker Studio vs Tableau — qual escolher?", "a": "Looker Studio é gratuito e ótimo para dados Google. Tableau é mais poderoso para análise complexa de dados corporativos. Para dashboards de marketing Google, Looker Studio; para BI corporativo avançado, Tableau."}, {"q": "Looker Studio é realmente gratuito?", "a": "Sim, Looker Studio é totalmente gratuito para uso. Looker Studio Pro custa $9/usuário/mês para recursos extras corporativos. Tableau começa em $15/usuário/mês."}, {"q": "Looker Studio pode substituir o Tableau?", "a": "Para casos de uso de marketing digital e relatórios Google, sim. Para análise complexa de grandes volumes de dados corporativos com múltiplas fontes, Tableau ainda oferece mais capacidade."}]$x$::jsonb
 WHERE slug = 'looker-studio' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Что такое Lovable?", "a": "Lovable (ранее GPT Engineer) — конструктор ИИ-приложений, где вы описываете желаемое и он генерирует полноценное веб-приложение на React/TypeScript. В отличие от no-code инструментов, производит реальный код. Разработчики могут редактировать код напрямую или продолжать общаться с ИИ для внесения изменений."}, {"q": "Lovable лучше Bubble для не-разработчиков?", "a": "Bubble в целом лучше для не-разработчиков, желающих создавать без написания кода. Lovable генерирует реальный код, который, несмотря на впечатляющий вид, может требовать знания разработчика для отладки и поддержки. Для нетехнических основателей визуальный редактор Bubble доступнее."}, {"q": "Может ли Lovable создавать full-stack приложения?", "a": "Да. Lovable может подключаться к Supabase для базы данных и авторизации, генерируя full-stack приложения с React-фронтендом и PostgreSQL-бэкендом. Популярен для быстрого создания SaaS-прототипов и MVP."}]$x$::jsonb
 WHERE slug = 'lovable' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Lovable vs Bolt.new — яка різниця?", "a": "Обидва ШІ-генератори застосунків. Lovable більш орієнтований на повноцінні веб-застосунки з Supabase-інтеграцією. Bolt.new також сильний для фронтенду. Обидва генерують реальний код."}, {"q": "Lovable безкоштовний?", "a": "Lovable має безкоштовний план з обмеженнями. Starter від $20/міс. Bubble має безкоштовний план; Starter від $32/міс."}]$x$::jsonb
 WHERE slug = 'lovable' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Lovable לעומת Bubble – מה עדיף?", "a": "Lovable מהיר יותר לפרוטוטייפ ומייצר קוד אמיתי. Bubble בוגר יותר לאפליקציות production. Lovable ל-MVP וגיחוש; Bubble לאפליקציות ו-SaaS רציניים."}, {"q": "Lovable חינמי?", "a": "Lovable מציע תוכנית חינמית עם 5 הודעות ליום; Starter ב-$20/חודש. Bubble מציע תוכנית חינמית; Starter ב-$32/חודש."}, {"q": "Lovable לעומת Bolt.new – מה ההבדל?", "a": "שניהם בונים אפליקציות web עם AI. Lovable ממוקד יותר ב-full-stack עם backend. Bolt.new חזק יותר ב-frontend מהיר. שניהם מתחרים ישירים."}]$x$::jsonb
 WHERE slug = 'lovable' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Luma AI es gratuito?", "a": "Luma AI tiene un plan gratuito con 30 generaciones de video al mes. Los planes de pago empiezan desde $29.99/mes (Plus, 100 generaciones). Runway tiene plan gratuito (125 créditos) y planes desde $12/mes."}, {"q": "¿Qué más hace Luma AI además de video?", "a": "Luma AI también tiene capacidades de 3D: puede crear escenas 3D y objetos en 3D desde fotos o video usando NeRF (Neural Radiance Fields). Esta funcionalidad 3D es única y complementa la generación de video para producción creativa."}, {"q": "¿Luma AI vs Kling AI?", "a": "Luma Dream Machine y Kling 2.0 son competidores directos en calidad. Kling permite videos más largos (hasta 3 min); Dream Machine produce clips más cortos pero con calidad cinematográfica muy consistente. Ambos son excelentes opciones en el top tier de generación de video en 2025."}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Luma AI vs Runway: Welches ist besser?", "a": "Runway ist insgesamt ausgereifter mit mehr professionellen Kontrollmöglichkeiten. Luma AI (Dream Machine) ist günstiger und hat ausgezeichnete Kamera-Bewegungen. Luma für kosteneffiziente Produktion; Runway für maximale professionelle Kontrolle."}, {"q": "Was ist Luma Dream Machine?", "a": "Luma Dream Machine ist Luma AI's Video-Generierungsmodell. Es erstellt Videos aus Text oder Bildern mit besonders flüssigen Kamerabewegungen. Dream Machine 1.6 hat gegenüber der ersten Version erhebliche Qualitätsverbesserungen gebracht."}, {"q": "Was macht Luma AI ursprünglich?", "a": "Luma AI begann als 3D-Capture-Tool: Sie filmen ein Objekt mit Ihrem Smartphone und Luma erstellt ein fotorealistisches 3D-NeRF-Modell. Diese Technologie wird für AR, Produktvisualisierung und Gaming genutzt. Dream Machine ist eine spätere Ergänzung."}, {"q": "Wie viel kostet Luma AI?", "a": "Luma AI hat einen kostenlosen Plan mit 30 monatlichen Video-Generierungen. Kostenpflichtige Pläne beginnen ab $29,99/Monat (Plus) für 120 Generierungen. Runway beginnt ab $15/Monat. Beide haben API-Preise für Entwickler."}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Luma AI чи Runway?", "a": "Luma AI цікавий для 3D-захоплення і Dream Machine відео. Runway — повноцінна відео-платформа з більше інструментами. Для 3D і базових відео — Luma; для повного відео-workflow — Runway."}, {"q": "Luma Dream Machine безкоштовний?", "a": "Luma Dream Machine має безкоштовний план з обмеженнями. Платні плани від $29,99/міс. Runway: безкоштовний план з 125 кредитами; від $15/міс."}, {"q": "Що таке NeRF і чим відомий Luma AI?", "a": "NeRF (Neural Radiance Fields) — технологія для захоплення 3D-об'єктів з фото і відео. Luma AI спростив NeRF: знімете об'єкт телефоном → отримуєте 3D-модель. Популярно для ігор, доповненої реальності і 3D-дизайну."}, {"q": "Luma AI для ігрових асетів?", "a": "Так. Luma AI популярний у геймдев-спільноті для захоплення реальних об'єктів і перетворення їх у 3D-моделі. Зручний для швидкого прототипування ігрових асетів."}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Luma AI מול Runway — מה עדיף?", "a": "Luma AI מוביל בריאליזם פיזיקלי ותנועת מצלמה. Runway מוביל בשליטה מתקדמת ובכלי עריכה. לסצנות ריאליסטיות — Luma; לשליטה ועריכה — Runway."}, {"q": "Luma Dream Machine בחינם?", "a": "Luma AI מציע 30 יצירות/חודש בחינם. Plus מ-29.99$/חודש. Runway מציע 125 קרדיטים חינמיים; Standard מ-15$/חודש."}, {"q": "Luma AI לתלת-ממד — מה זה?", "a": "Luma AI התחילה בצילום תלת-ממדי (NeRF — Neural Radiance Fields) מסרטי וידאו. ה-Dream Machine הוא מוצר יצירת הוידאו שלהם, שמנצל ידע בפיזיקת תלת-ממד."}, {"q": "Luma Ray 2 מול Sora — מה ההבדל?", "a": "Sora מ-OpenAI נגיש לחברי ChatGPT Pro. Luma Ray 2 זמין לרוב המשתמשים. שניהם ברמה גבוהה. Sora ידוע באיכות גבוהה במיוחד; Luma Ray 2 זמין ומוכח בשטח."}]$x$::jsonb
 WHERE slug = 'luma-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Make и Microsoft Copilot Studio — одно и то же?", "a": "Нет, это совершенно разные инструменты. Make (бывший Integromat) — платформа автоматизации рабочих процессов между SaaS-сервисами. Copilot Studio — конструктор чат-ботов и ИИ-агентов от Microsoft. Make автоматизирует процессы, Copilot Studio строит разговорных агентов."}, {"q": "Make дешевле Copilot Studio?", "a": "Да. Make начинается от $9/мес (10 000 операций). Copilot Studio стоит от $200/мес за 25 000 сообщений и требует Microsoft 365 для полной интеграции. Make значительно доступнее для малого бизнеса."}, {"q": "Можно ли использовать Make с Microsoft?", "a": "Да. Make интегрируется с Microsoft 365, Teams, Outlook и SharePoint через готовые коннекторы. Для базовой автоматизации Microsoft-процессов Make работает хорошо. Copilot Studio нужен для разговорных интерфейсов."}]$x$::jsonb
 WHERE slug = 'make' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Zapier vs Make — що краще?", "a": "Zapier простіший і має більше готових конекторів. Make потужніший і набагато дешевший для складних сценаріїв. Для нетехнічних команд — Zapier; для технічних команд з бюджетними обмеженнями — Make."}, {"q": "Zapier безкоштовний?", "a": "Zapier має безкоштовний план з 100 завдань/міс і однокроковими Zaps. Платні плани від $19,99/міс. Make безкоштовний до 1000 операцій/міс; платні від $9/міс."}, {"q": "Make vs n8n — яка різниця?", "a": "Make hosted-сервіс з красивим інтерфейсом. n8n відкритий і безкоштовний при self-hosting. Make для команд що хочуть хмарне рішення; n8n для технічних команд з контролем над даними."}]$x$::jsonb
 WHERE slug = 'make' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Zapier לעומת Make – מה עדיף?", "a": "Zapier פשוט יותר ומציע יותר אינטגרציות. Make זול יותר ועוצמתי יותר לתרחישים מורכבים. לפשטות – Zapier; לחיסכון וגמישות – Make."}, {"q": "Make לעומת n8n – מה עדיף?", "a": "Make קל יותר לשימוש. n8n מתאים יותר לצוותים טכניים שרוצים self-hosting ושליטה מלאה. n8n חינמי ב-self-hosting; Make מציע תוכנית ענן נוחה."}]$x$::jsonb
 WHERE slug = 'make' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Zapier vs Make — lequel est le meilleur ?", "a": "Zapier est plus simple et a plus d'intégrations. Make est plus puissant et moins cher pour les scénarios complexes. Débutants et non-techniques → Zapier ; équipes techniques avec des automatisations complexes → Make."}, {"q": "Zapier est-il gratuit ?", "a": "Zapier a un plan gratuit avec 100 tâches/mois et 5 Zaps. Les plans payants à partir de 29,99 $/mois. Make a un plan gratuit avec 1 000 opérations/mois ; payants à partir de 9 $/mois."}, {"q": "Make peut-il remplacer Zapier complètement ?", "a": "Make peut remplacer la plupart des cas d'usage Zapier, souvent pour moins cher. Les seules limitations sont certaines intégrations rares disponibles dans Zapier mais pas encore dans Make. Pour la grande majorité des automatisations, Make est une alternative complète."}]$x$::jsonb
 WHERE slug = 'make' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Zapier AI vs Make — qual é o melhor?", "a": "Zapier é mais fácil e tem mais integrações. Make é mais poderoso e mais barato para automações complexas. Para simplicidade e muitas integrações, Zapier; para flexibilidade e custo-benefício, Make."}, {"q": "Zapier é gratuito?", "a": "Zapier tem plano gratuito com 100 tarefas por mês e 5 Zaps. Planos pagos a partir de $19,99/mês. Make tem plano gratuito com 1.000 operações; pagos a partir de $9/mês."}, {"q": "Make vs n8n — qual é mais fácil?", "a": "Make é geralmente mais fácil que n8n para iniciantes. n8n oferece mais flexibilidade e é gratuito na auto-hospedagem. Para facilidade de uso, Make; para controle máximo e auto-hospedagem, n8n."}]$x$::jsonb
 WHERE slug = 'make' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Manus es gratuito?", "a": "Manus tuvo acceso por invitación limitado en su lanzamiento. El acceso completo requiere suscripción de pago. AutoGPT es open-source y gratuito como herramienta, aunque requiere APIs de modelos de IA (OpenAI, Anthropic) que tienen su propio costo."}, {"q": "¿Los agentes IA son seguros?", "a": "Los agentes IA como AutoGPT y Manus pueden ejecutar código, navegar la web y realizar acciones. Esto requiere precaución — siempre revisar los permisos antes de dar acceso a datos sensibles o sistemas críticos. Para experimentación — entornos aislados; para producción — revisión humana de acciones críticas."}, {"q": "¿Qué es Manus?", "a": "Manus es un agente de IA autónomo de Monica.im que puede completar tareas complejas de forma independiente: navegar por la web, escribir y ejecutar código, gestionar archivos y rellenar formularios sin instrucciones paso a paso."}, {"q": "¿Cuánto cuesta Manus?", "a": "Manus está actualmente en beta solo por invitación. Una lista de espera está disponible en manus.im. Los precios para el lanzamiento general no han sido anunciados."}, {"q": "¿Qué puede hacer Manus de forma autónoma?", "a": "Manus puede investigar temas en la web, escribir y ejecutar código, gestionar hojas de cálculo, rellenar formularios, crear apps móviles y web, todo desde una sola instrucción de alto nivel."}, {"q": "¿En qué se diferencia Manus de otros agentes de IA?", "a": "Manus opera con un entorno persistente similar a un escritorio: puede abrir navegadores, ejecutar terminales y gestionar archivos como un asistente humano. La mayoría de agentes solo generan texto; Manus realmente ejecuta tareas."}]$x$::jsonb
 WHERE slug = 'manus' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "AutoGPT vs Manus: Welches ist einfacher?", "a": "Manus ist deutlich einfacher: kein Setup, direkt nutzbar im Browser. AutoGPT erfordert technisches Setup (Python, API-Keys, Installation). Manus für sofortige Nutzung; AutoGPT für technische Nutzer die Agenten-Systeme verstehen und anpassen wollen."}, {"q": "Manus vs ChatGPT: Was ist der Unterschied?", "a": "ChatGPT ist ein Konversations-KI ohne autonome Handlungsfähigkeit (außer mit Plugins). Manus ist ein autonomer Agent der Aufgaben selbstständig über mehrere Schritte ausführt: browsen, Code schreiben, Dateien erstellen. Manus für autonome Aufgaben; ChatGPT für Konversation und Analyse."}, {"q": "Was ist Manus?", "a": "Manus ist ein autonomer KI-Agent von Monica.im, der komplexe Aufgaben selbstständig erledigt: im Web surfen, Code schreiben und ausführen, Dateien verwalten und Formulare ausfüllen — ohne Schritt-für-Schritt-Anleitung."}, {"q": "Was kostet Manus?", "a": "Manus befindet sich derzeit in einer geschlossenen Beta per Einladung. Eine Warteliste ist auf manus.im verfügbar. Preise für den allgemeinen Release wurden noch nicht bekanntgegeben."}, {"q": "Was kann Manus autonom tun?", "a": "Manus kann Themen im Web recherchieren, Code schreiben und ausführen, Tabellen verwalten, Formulare ausfüllen und Mobile- sowie Web-Apps erstellen — alles aus einer einzigen übergeordneten Anweisung."}, {"q": "Wie unterscheidet sich Manus von anderen KI-Agenten?", "a": "Manus arbeitet in einer persistenten Desktop-ähnlichen Umgebung — es kann Browser öffnen, Terminals ausführen und Dateien verwalten wie ein menschlicher Assistent. Die meisten Agenten generieren nur Text; Manus führt Aufgaben tatsächlich aus."}]$x$::jsonb
 WHERE slug = 'manus' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Manus AI?", "a": "Manus — автономный ИИ-агент, разработанный в Китае, который может независимо выполнять сложные задачи: просматривать веб, писать код, управлять файлами и реализовывать многошаговые планы. В отличие от чатботов, Manus совершает действия, а не просто отвечает на вопросы."}, {"q": "Copilot Studio бесплатный?", "a": "Copilot Studio требует подписки Microsoft 365. Включает 25 000 генеративных сообщений ИИ в месяц на тенант на платных планах. Доступны дополнительные пакеты сообщений. Модель ценообразования сложная — свяжитесь с Microsoft для корпоративного ценообразования."}, {"q": "Может ли Manus заменить человеческий труд?", "a": "Manus может автоматизировать многие рабочие процессы исследований, анализа и выполнения задач, ранее требовавшие человеческих усилий. Однако он лучше всего работает для чётко определённых задач с ясными целями. Сложные суждения, деликатные решения и творческая работа по-прежнему выигрывают от человеческого контроля."}]$x$::jsonb
 WHERE slug = 'manus' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "AutoGPT vs Manus — яка різниця?", "a": "AutoGPT — відкритий дослідницький проєкт для побудови ШІ-агентів. Manus — готовий комерційний ШІ-агент для делегування завдань. AutoGPT для розробників і дослідників; Manus для кінцевих користувачів що хочуть делегувати роботу."}, {"q": "Що таке Manus AI?", "a": "Manus — китайський ШІ-агент від Monica.im що може автономно виконувати завдання: пошук в інтернеті, написання коду, аналіз даних і підготовку документів. Позиціонується як ШІ-агент що завершує проєкти самостійно."}, {"q": "Чи безпечно довіряти завдання ШІ-агентам?", "a": "ШІ-агенти можуть робити помилки і потребують перевірки. Починайте з низькоризикових завдань. Завжди перевіряйте вихідні дані для важливої роботи. Не надавайте агентам доступу до критичних систем без відповідних засобів безпеки."}, {"q": "Що таке Manus?", "a": "Manus — автономний AI-агент від Monica.im, який самостійно виконує складні завдання: переглядає веб, пише та запускає код, керує файлами і заповнює форми без покрокових інструкцій."}]$x$::jsonb
 WHERE slug = 'manus' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "AutoGPT לעומת Manus?", "a": "AutoGPT Framework לפיתוח Agents. Manus מוצר מוכן לביצוע משימות. AutoGPT למפתחים; Manus לאנשי עסקים."}, {"q": "Manus AI – מה הוא יכול לעשות?", "a": "Manus יכול לחפש אינטרנט, לנתח נתונים, לכתוב קוד, לייצר דוחות ולבצע משימות מורכבות אוטונומית. נחשב לאחד מה-AI Agents הגנרליים החזקים."}, {"q": "מה זה Manus?", "a": "Manus הוא סוכן AI אוטונומי מ-Monica.im שיכול להשלים משימות מורכבות באופן עצמאי: גלישה באינטרנט, כתיבה והרצת קוד, ניהול קבצים ומילוי טפסים ללא הוראות שלב-אחר-שלב."}]$x$::jsonb
 WHERE slug = 'manus' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "AutoGPT vs Manus — quelle est la différence ?", "a": "AutoGPT est un framework open-source pour construire des agents IA — plus technique. Manus est un agent IA commercial prêt à l'emploi — plus accessible. Développeurs voulant personnaliser des agents → AutoGPT ; utilisateurs voulant déléguer des tâches → Manus."}, {"q": "Manus AI est-il disponible en France ?", "a": "Manus est accessible globalement. L'interface est principalement en anglais. Pour l'utiliser avec des contenus en français, il comprend le français mais les résultats peuvent être variables selon les tâches."}, {"q": "Qu'est-ce que Manus ?", "a": "Manus est un agent IA autonome de Monica.im qui peut accomplir des tâches complexes de manière indépendante : naviguer sur le web, écrire et exécuter du code, gérer des fichiers et remplir des formulaires sans instructions étape par étape."}, {"q": "Combien coûte Manus ?", "a": "Manus est actuellement en bêta fermée sur invitation. Une liste d'attente est disponible sur manus.im. Les tarifs pour la sortie générale n'ont pas encore été annoncés."}, {"q": "Que peut faire Manus de manière autonome ?", "a": "Manus peut rechercher des sujets sur le web, écrire et exécuter du code, gérer des feuilles de calcul, remplir des formulaires et créer des applications mobiles et web — le tout depuis une seule instruction de haut niveau."}, {"q": "En quoi Manus diffère-t-il des autres agents IA ?", "a": "Manus fonctionne avec un environnement de bureau persistant — il peut ouvrir des navigateurs, exécuter des terminaux et gérer des fichiers comme un assistant humain. La plupart des agents ne font que générer du texte ; Manus exécute réellement les tâches."}]$x$::jsonb
 WHERE slug = 'manus' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "AutoGPT vs Manus — qual é a diferença?", "a": "AutoGPT é um framework open-source para construir agentes de IA — mais técnico. Manus é um agente de IA comercial pronto para usar — mais acessível. Desenvolvedores que querem personalizar agentes → AutoGPT; usuários que querem delegar tarefas → Manus."}, {"q": "Manus AI está disponível no Brasil?", "a": "Manus é acessível globalmente. A interface é principalmente em inglês. Para usá-lo com conteúdo em português, ele entende português mas os resultados podem variar conforme as tarefas."}, {"q": "O que é o Manus?", "a": "O Manus é um agente de IA autônomo da Monica.im que pode completar tarefas complexas de forma independente: navegar na web, escrever e executar código, gerenciar arquivos e preencher formulários sem instruções passo a passo."}, {"q": "Quanto custa o Manus?", "a": "O Manus está atualmente em beta fechado por convite. Uma lista de espera está disponível em manus.im. Os preços para o lançamento geral ainda não foram anunciados."}, {"q": "O que o Manus pode fazer de forma autônoma?", "a": "O Manus pode pesquisar tópicos na web, escrever e executar código, gerenciar planilhas, preencher formulários e criar apps mobile e web — tudo a partir de uma única instrução de alto nível."}, {"q": "Como o Manus se diferencia de outros agentes de IA?", "a": "O Manus opera com um ambiente persistente semelhante a um desktop — pode abrir navegadores, executar terminais e gerenciar arquivos como um assistente humano. A maioria dos agentes apenas gera texto; o Manus realmente executa tarefas."}]$x$::jsonb
 WHERE slug = 'manus' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Что такое Meta AI?", "a": "Meta AI — бесплатный ИИ-ассистент от Meta, встроенный в WhatsApp, Instagram, Facebook и Messenger. Работает на модели Llama 4. Позволяет отвечать на вопросы, генерировать изображения и помогать с задачами прямо в социальных сетях."}, {"q": "Meta AI лучше ChatGPT?", "a": "ChatGPT значительно мощнее как самостоятельный инструмент — более продвинутые рассуждения, широкий набор функций и постоянная память. Meta AI выигрывает по удобству доступа: он прямо в WhatsApp, не нужно переключаться между приложениями."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "¿Es Microsoft Copilot lo mismo que ChatGPT?", "a": "No exactamente. Microsoft Copilot usa modelos de OpenAI (GPT-4o) pero está integrado en productos Microsoft con acceso a Bing Search. ChatGPT es el producto directo de OpenAI. Copilot gratuito incluye generación de imágenes; ChatGPT Plus ($20/mes) tiene más funciones avanzadas."}, {"q": "¿Microsoft Copilot es gratuito?", "a": "Sí. Microsoft Copilot tiene un plan gratuito con acceso web, generación de imágenes (100/día) y GPT-4o. Microsoft 365 Copilot para empresas requiere licencia adicional desde $30/usuario/mes."}, {"q": "¿Microsoft Copilot puede generar imágenes gratis?", "a": "Sí. Copilot web incluye generación de imágenes con DALL-E 3 gratuitamente (hasta 100 por día). Esta es una de sus principales ventajas frente al plan gratuito de ChatGPT."}, {"q": "¿Qué es Microsoft Copilot?", "a": "Microsoft Copilot es el asistente de IA de Microsoft integrado en Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge y Bing. Usa GPT-4o para asistir con tareas en todo el ecosistema Microsoft."}, {"q": "¿Cuánto cuesta Microsoft Copilot?", "a": "Gratis en Windows y Bing. Microsoft 365 Copilot para empresas cuesta $30/usuario/mes añadido a una suscripción Microsoft 365. Los PC Copilot+ incluyen funciones de IA adicionales en el dispositivo."}, {"q": "¿Qué puede hacer Microsoft Copilot en Excel?", "a": "Copilot en Excel puede generar fórmulas, crear tablas dinámicas, resumir datos, crear gráficos y responder preguntas sobre tu hoja de cálculo en lenguaje natural."}, {"q": "¿Microsoft Copilot es lo mismo que GitHub Copilot?", "a": "No. Microsoft Copilot es un asistente de IA de propósito general para Windows y apps M365. GitHub Copilot es un producto separado enfocado en la compleción de código en github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Ist Microsoft Copilot dasselbe wie ChatGPT?", "a": "Nicht genau. Microsoft Copilot verwendet OpenAI-Modelle (GPT-4o), ist aber in Microsoft-Produkte mit Bing-Suchzugang integriert. ChatGPT ist OpenAIs Direktprodukt. Kostenloser Copilot beinhaltet Bildgenerierung; ChatGPT Plus ($20/Monat) hat mehr erweiterte Funktionen."}, {"q": "Ist Microsoft Copilot kostenlos?", "a": "Ja. Microsoft Copilot hat einen kostenlosen Plan mit Webzugang, Bildgenerierung (100/Tag) und GPT-4o. Microsoft 365 Copilot für Unternehmen erfordert eine zusätzliche Lizenz ab $30/Benutzer/Monat."}, {"q": "Kann Microsoft Copilot kostenlos Bilder generieren?", "a": "Ja. Copilot Web beinhaltet kostenlose Bildgenerierung mit DALL-E 3 (bis zu 100 pro Tag). Das ist einer seiner wichtigsten Vorteile gegenüber dem kostenlosen ChatGPT-Plan."}, {"q": "Was ist Microsoft Copilot?", "a": "Microsoft Copilot ist Microsofts KI-Assistent, der in Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge und Bing integriert ist. Er verwendet GPT-4o, um bei Aufgaben im gesamten Microsoft-Ökosystem zu helfen."}, {"q": "Was kostet Microsoft Copilot?", "a": "Kostenlos in Windows und Bing. Microsoft 365 Copilot für Unternehmen kostet $30/Nutzer/Monat zusätzlich zu einem Microsoft 365-Abonnement. Copilot+ PCs enthalten zusätzliche On-Device-KI-Funktionen."}, {"q": "Was kann Microsoft Copilot in Excel?", "a": "Copilot in Excel kann Formeln erstellen, Pivot-Tabellen anlegen, Daten zusammenfassen, Diagramme erstellen und Fragen zur Tabellenkalkulation in natürlicher Sprache beantworten."}, {"q": "Ist Microsoft Copilot dasselbe wie GitHub Copilot?", "a": "Nein. Microsoft Copilot ist ein Allzweck-KI-Assistent für Windows und M365-Apps. GitHub Copilot ist ein separates Produkt für Code-Vervollständigung auf github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между Microsoft Copilot и ChatGPT?", "a": "Microsoft Copilot встроен в экосистему Microsoft 365 (Word, Excel, Teams) и работает на основе GPT. ChatGPT — автономный продукт OpenAI с более широким набором функций: GPTs, Deep Research, Sora, Canvas. Copilot — выбор для корпоративных пользователей Microsoft, ChatGPT — для универсальных задач."}, {"q": "Microsoft Copilot бесплатный?", "a": "Microsoft Copilot доступен бесплатно через браузер Edge и сайт copilot.microsoft.com. Copilot Pro ($20/мес) добавляет приоритетный доступ к GPT-4o и интеграцию с Microsoft 365 приложениями."}, {"q": "Лучше ли ChatGPT, чем Microsoft Copilot?", "a": "ChatGPT предлагает больше функций и более свежие возможности (Deep Research, Sora, Memory). Copilot выигрывает у пользователей Microsoft 365 благодаря глубокой интеграции в привычные приложения. Для корпоративного использования с Microsoft — Copilot, для универсальных задач — ChatGPT."}, {"q": "Что умеет Microsoft Copilot в Excel?", "a": "Copilot в Excel создаёт формулы, сводные таблицы, диаграммы, анализирует данные и отвечает на вопросы о таблицах на естественном языке."}, {"q": "Microsoft Copilot — это то же самое что GitHub Copilot?", "a": "Нет. Microsoft Copilot — универсальный AI-ассистент для Windows и приложений M365. GitHub Copilot — отдельный продукт для дополнения кода и разработки на github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Microsoft Copilot та ChatGPT — в чому різниця?", "a": "Microsoft Copilot побудований на моделях OpenAI (GPT-4) і вбудований у Microsoft 365. ChatGPT — прямий продукт OpenAI з більш широкою незалежною екосистемою. Для Microsoft 365 — Copilot; для загального ШІ — ChatGPT."}, {"q": "Чи Microsoft Copilot безкоштовний?", "a": "Базовий Copilot у Windows і Edge безкоштовний. Microsoft 365 Copilot для підприємств коштує $30/користувач/міс. Copilot+ PC — апаратна функція для нових пристроїв."}, {"q": "Microsoft Copilot для Excel — що він вміє?", "a": "Copilot в Excel може аналізувати дані, будувати формули, створювати зведені таблиці і пропонувати графіки. Він розуміє природну мову: «покажи мені продажі за Q1 у розрізі регіонів» — і Excel генерує потрібну аналітику."}, {"q": "Microsoft Copilot і GitHub Copilot — це одне й те саме?", "a": "Ні. Microsoft Copilot — універсальний AI-асистент для Windows і додатків M365. GitHub Copilot — окремий продукт для доповнення коду на github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Microsoft Copilot ו-ChatGPT — מה ההבדל?", "a": "Microsoft Copilot בנוי על מודלי OpenAI (GPT-4) ומשולב ב-Microsoft 365. ChatGPT הוא מוצר ישיר של OpenAI עם מערכת-אקולוגית עצמאית רחבה יותר. ל-Microsoft 365 — Copilot; ל-AI כללי — ChatGPT."}, {"q": "האם Microsoft Copilot בחינם?", "a": "Copilot בסיסי ב-Windows וב-Edge חינמי. Microsoft 365 Copilot לארגונים עולה 30$/משתמש/חודש. Copilot+ PC הוא תכונת חומרה למכשירים חדשים."}, {"q": "Microsoft Copilot ב-Excel — מה הוא יכול?", "a": "Copilot ב-Excel יכול לנתח נתונים, לבנות נוסחאות, ליצור טבלאות ציר ולהציע גרפים. הוא מבין שפה טבעית: 'הצג לי מכירות Q1 לפי אזור' — ו-Excel מייצר את הניתוח הנדרש."}, {"q": "האם Microsoft Copilot זהה ל-GitHub Copilot?", "a": "לא. Microsoft Copilot הוא עוזר AI כללי ל-Windows ואפליקציות M365. GitHub Copilot הוא מוצר נפרד המתמקד בהשלמת קוד ב-github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Microsoft Copilot et ChatGPT — quelle est la différence ?", "a": "Microsoft Copilot est construit sur les modèles OpenAI (GPT-4) et intégré dans Microsoft 365. ChatGPT est le produit direct d'OpenAI avec un écosystème indépendant plus large. Pour Microsoft 365, Copilot ; pour l'IA générale, ChatGPT."}, {"q": "Microsoft Copilot est-il gratuit ?", "a": "Le Copilot de base dans Windows et Edge est gratuit. Microsoft 365 Copilot pour les entreprises coûte 30 $/utilisateur/mois. Copilot+ PC est une fonctionnalité matérielle pour les nouveaux appareils."}, {"q": "Microsoft Copilot pour Excel — que peut-il faire ?", "a": "Copilot dans Excel peut analyser des données, créer des formules, générer des tableaux croisés dynamiques et suggérer des graphiques. Il comprend le langage naturel : 'montre-moi les ventes du T1 par région' — et Excel génère l'analyse requise."}, {"q": "Qu'est-ce que Microsoft Copilot ?", "a": "Microsoft Copilot est l'assistant IA de Microsoft intégré dans Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge et Bing. Il utilise GPT-4o pour assister avec les tâches dans tout l'écosystème Microsoft."}, {"q": "Combien coûte Microsoft Copilot ?", "a": "Gratuit dans Windows et Bing. Microsoft 365 Copilot pour les entreprises coûte $30/utilisateur/mois en supplément d'un abonnement Microsoft 365. Les PC Copilot+ incluent des fonctionnalités IA supplémentaires sur l'appareil."}, {"q": "Que peut faire Microsoft Copilot dans Excel ?", "a": "Copilot dans Excel peut générer des formules, créer des tableaux croisés dynamiques, résumer des données, créer des graphiques et répondre à des questions sur votre feuille de calcul en langage naturel."}, {"q": "Microsoft Copilot est-il la même chose que GitHub Copilot ?", "a": "Non. Microsoft Copilot est un assistant IA polyvalent pour Windows et les applications M365. GitHub Copilot est un produit séparé axé sur la complétion de code sur github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Microsoft Copilot e ChatGPT — qual é a diferença?", "a": "Microsoft Copilot é construído sobre os modelos OpenAI (GPT-4) e integrado ao Microsoft 365. ChatGPT é o produto direto da OpenAI com um ecossistema independente maior. Para Microsoft 365, Copilot; para IA geral, ChatGPT."}, {"q": "Microsoft Copilot é gratuito?", "a": "O Copilot básico no Windows e Edge é gratuito. Microsoft 365 Copilot para empresas custa $30/usuário/mês. Copilot+ PC é um recurso de hardware para novos dispositivos."}, {"q": "Microsoft Copilot no Excel — o que ele faz?", "a": "Copilot no Excel pode analisar dados, criar fórmulas, gerar tabelas dinâmicas e sugerir gráficos. Ele entende linguagem natural: 'mostre as vendas do T1 por região' — e o Excel gera a análise necessária."}, {"q": "O que é o Microsoft Copilot?", "a": "O Microsoft Copilot é o assistente de IA da Microsoft integrado ao Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge e Bing. Usa GPT-4o para auxiliar com tarefas em todo o ecossistema Microsoft."}, {"q": "Quanto custa o Microsoft Copilot?", "a": "Grátis no Windows e Bing. O Microsoft 365 Copilot para empresas custa $30/usuário/mês além da assinatura Microsoft 365. PCs Copilot+ incluem recursos de IA adicionais no dispositivo."}, {"q": "O que o Microsoft Copilot pode fazer no Excel?", "a": "O Copilot no Excel pode gerar fórmulas, criar tabelas dinâmicas, resumir dados, criar gráficos e responder perguntas sobre sua planilha em linguagem natural."}, {"q": "O Microsoft Copilot é o mesmo que o GitHub Copilot?", "a": "Não. O Microsoft Copilot é um assistente de IA de uso geral para Windows e apps M365. O GitHub Copilot é um produto separado focado em conclusão de código em github.com/features/copilot."}]$x$::jsonb
 WHERE slug = 'microsoft-copilot' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Midjourney o Krea para diseño de producto?", "a": "Para concepto de producto con máxima calidad artística — Midjourney. Para exploración rápida e iterativa donde necesitas ver múltiples variaciones en tiempo real — Krea. Muchos diseñadores de producto usan Krea para exploración rápida y Midjourney para renders finales."}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Krea AI vs Midjourney: Was ist einzigartiger?", "a": "Krea's Echtzeit-Canvas ist einzigartig — kein anderes Tool der Klasse bietet live KI-Generierung während Sie zeichnen. Midjourney führt bei statischer Bild-Qualität und künstlerischer Ausgereiftheit. Krea für interaktive kreative Exploration; Midjourney für finale Qualität."}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Flux vs Midjourney — что лучше?", "a": "Midjourney V7 превосходит по художественному качеству и эстетике. Flux (FLUX.1) превосходит по реализму фотографий, точному следованию тексту в изображении и возможности локального запуска. Выбор зависит от задачи: Midjourney для арта, Flux для реалистичного контента."}, {"q": "Flux бесплатный?", "a": "FLUX.1 [schnell] — самая быстрая версия — доступна бесплатно с открытой лицензией через Hugging Face и ComfyUI. FLUX.1 [dev] — для некоммерческого использования. FLUX.1 [pro] — через API с оплатой за использование."}, {"q": "Midjourney имеет бесплатный план?", "a": "Нет. Midjourney убрал бесплатный пробный период. Минимальный план Basic — $10/мес (~200 изображений). Flux в версии schnell — бесплатен."}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Krea AI vs Midjourney — яка різниця?", "a": "Krea AI орієнтований на інтерактивну генерацію в реальному часі: малюйте і бачте ШІ-результат миттєво. Midjourney орієнтований на найвищу художню якість фінального результату. Krea для ітерації; Midjourney для якості."}, {"q": "Що таке генерація в реальному часі?", "a": "У Krea AI ви малюєте ескіз або вводите елементи і ШІ показує рендер вашого зображення миттєво — без очікування. Ви бачите результат у реальному часі і можете редагувати. Це відрізняється від черги промптів Midjourney."}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Krea AI לעומת Midjourney – מה עדיף?", "a": "Krea מצוין לעריכה אינטראקטיבית ו-Upscaling. Midjourney הסטנדרט לאיכות אמנות AI. Krea לעריכה וגמישות; Midjourney לאיכות אמנות."}, {"q": "Midjourney לעברית – האם הפרומפטים עובדים?", "a": "Midjourney מבין פרומפטים באנגלית בעיקר. תרגמו פרומפטים לאנגלית לתוצאות מיטביות. הוספת עברית לפרומפט עשויה לעבוד אך לא מיטבי."}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Krea AI vs Midjourney — quelle est la différence ?", "a": "Krea AI se distingue par sa génération en temps réel et ses fonctionnalités d'idéation créative. Midjourney est le standard pour l'art IA de haute qualité avec une communauté massive. Pour l'exploration créative en temps réel → Krea ; pour la qualité artistique finale → Midjourney."}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Krea AI vs Midjourney — qual é a diferença?", "a": "Krea AI se destaca pela geração em tempo real e funcionalidades de ideação criativa. Midjourney é o padrão para arte de IA de alta qualidade com comunidade enorme. Para exploração criativa em tempo real → Krea; para qualidade artística final → Midjourney."}]$x$::jsonb
 WHERE slug = 'midjourney' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Mistral Le Chat?", "a": "Le Chat es el asistente de IA de Mistral AI, empresa francesa fundada en 2023. Usa los modelos Mistral, que son open-weights y pueden usarse localmente o vía API a precios significativamente menores que OpenAI."}, {"q": "¿Mistral Le Chat es gratuito?", "a": "Sí. Le Chat tiene un plan gratuito generoso. La versión Pro ($14.99/mes) desbloquea más contexto y velocidad. La API de Mistral es significativamente más barata que OpenAI para modelos comparables."}, {"q": "¿Son los modelos de Mistral de código abierto?", "a": "Mistral publica sus modelos como open-weights — los pesos son libres para descargar y usar. Puedes ejecutar Mistral 7B o Mixtral localmente con Ollama u otras herramientas. Esto los diferencia de OpenAI y Anthropic."}, {"q": "¿Mistral Le Chat habla bien español?", "a": "Sí. Mistral fue entrenado con énfasis en idiomas europeos y tiene excelente soporte para español, francés, alemán e italiano. Para tareas en español, la calidad es competitiva con ChatGPT."}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Mistral Le Chat?", "a": "Le Chat ist der KI-Assistent von Mistral AI, einem 2023 gegründeten französischen Unternehmen. Es verwendet Mistral-Modelle, die Open-Weights sind und lokal oder über API zu deutlich niedrigeren Preisen als OpenAI genutzt werden können."}, {"q": "Ist Mistral Le Chat kostenlos?", "a": "Ja. Le Chat hat einen großzügigen kostenlosen Plan. Die Pro-Version ($14,99/Monat) schaltet mehr Kontext und Geschwindigkeit frei. Die Mistral-API ist erheblich günstiger als OpenAI für vergleichbare Modelle."}, {"q": "Sind Mistral-Modelle Open-Source?", "a": "Mistral veröffentlicht seine Modelle als Open-Weights — die Gewichte können frei heruntergeladen und genutzt werden. Sie können Mistral 7B oder Mixtral lokal mit Ollama oder anderen Tools ausführen. Das unterscheidet sie von OpenAI und Anthropic."}, {"q": "Spricht Mistral Le Chat gut Deutsch?", "a": "Ja. Mistral wurde mit Schwerpunkt auf europäischen Sprachen trainiert und hat ausgezeichnete Unterstützung für Deutsch, Französisch, Spanisch und Italienisch. Für Aufgaben auf Deutsch ist die Qualität mit ChatGPT konkurrenzfähig."}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Mistral Le Chat?", "a": "Le Chat — бесплатный ИИ-ассистент от французской компании Mistral AI. Работает на собственных моделях Mistral (Mistral Large, Mixtral). Позиционируется как европейская альтернатива ChatGPT с акцентом на конфиденциальность и работу с европейскими языками."}, {"q": "Le Chat бесплатный?", "a": "Да, базовый Le Chat бесплатен. Pro-план ($19.99/мес) добавляет расширенный доступ, больший контекст и приоритетную обработку."}, {"q": "Можно ли использовать модели Mistral локально?", "a": "Да. Mistral публикует большинство своих моделей с открытым исходным кодом — их можно запустить локально через Ollama, LM Studio или через API. Это главное преимущество перед ChatGPT, который полностью закрыт."}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Mistral Le Chat vs ChatGPT — яка різниця?", "a": "Mistral — французька компанія з відкритими моделями і сильними конфіденційністю даних. ChatGPT від OpenAI (США) має більшу екосистему. Для GDPR-вимог і ЄС — Mistral; для максимальної екосистеми — ChatGPT."}, {"q": "Чи Mistral Le Chat безкоштовний?", "a": "Так, Le Chat безкоштовний. Mistral Pro коштує $14,99/міс. API — за токенами, дешевший за OpenAI. ChatGPT безкоштовний; Plus $20/міс."}, {"q": "Чи Mistral справді відкритий?", "a": "Деякі моделі Mistral відкриті (Mistral 7B, Mixtral, Mistral NeMo). Mistral Large — закрита комерційна модель. Відкриті моделі можна розгортати локально через Ollama або HuggingFace."}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Mistral Le Chat מול ChatGPT — מה ההבדל?", "a": "Mistral הוא חברה צרפתית עם מודלים פתוחים ופרטיות נתונים חזקה. ChatGPT מ-OpenAI (ארה\"ב) עם מערכת-אקולוגית גדולה יותר. לדרישות GDPR ואיחוד אירופי — Mistral; למערכת-אקולוגית מרבית — ChatGPT."}, {"q": "האם Mistral Le Chat בחינם?", "a": "כן, Le Chat חינמי. Mistral Pro עולה 14.99$/חודש. API — לפי טוקנים, זול מ-OpenAI. ChatGPT חינמי; Plus 20$/חודש."}, {"q": "האם Mistral באמת פתוח?", "a": "חלק ממודלי Mistral פתוחים (Mistral 7B, Mixtral, Mistral NeMo). Mistral Large הוא מודל מסחרי סגור. מודלים פתוחים ניתנים לפריסה מקומית דרך Ollama או HuggingFace."}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Mistral Le Chat vs ChatGPT — quelle est la différence ?", "a": "Mistral est une société française avec des modèles ouverts et une forte confidentialité des données. ChatGPT d'OpenAI (États-Unis) dispose d'un plus grand écosystème. Pour les exigences RGPD et l'UE, Mistral ; pour l'écosystème maximal, ChatGPT."}, {"q": "Mistral Le Chat est-il gratuit ?", "a": "Oui, Le Chat est gratuit. Mistral Pro coûte 14,99 $/mois. L'API est facturée par token, moins chère qu'OpenAI. ChatGPT est gratuit ; Plus 20 $/mois."}, {"q": "Mistral est-il vraiment open-source ?", "a": "Certains modèles Mistral sont ouverts (Mistral 7B, Mixtral, Mistral NeMo). Mistral Large est un modèle commercial fermé. Les modèles ouverts peuvent être déployés localement via Ollama ou HuggingFace."}, {"q": "Mistral pour le codage — est-il adapté ?", "a": "Oui. Mistral Large 2 et Codestral (modèle spécialisé pour le code) affichent d'excellents résultats. Codestral est supporté dans Continue.dev et d'autres IDEs. Excellent rapport qualité-prix pour le codage."}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Mistral Le Chat vs ChatGPT — qual é a diferença?", "a": "Mistral é uma empresa francesa com modelos abertos e forte privacidade de dados. ChatGPT da OpenAI (EUA) tem um ecossistema maior. Para requisitos GDPR e UE, Mistral; para o maior ecossistema, ChatGPT."}, {"q": "Mistral Le Chat é gratuito?", "a": "Sim, Le Chat é gratuito. Mistral Pro custa €14,99/mês. A API é cobrada por token, mais barata que a OpenAI. ChatGPT é gratuito; Plus $20/mês."}, {"q": "Mistral é realmente open-source?", "a": "Alguns modelos Mistral são abertos (Mistral 7B, Mixtral, Mistral NeMo). Mistral Large é um modelo comercial fechado. Os modelos abertos podem ser implantados localmente via Ollama ou HuggingFace."}, {"q": "Mistral para programação — é adequado?", "a": "Sim. Mistral Large 2 e Codestral (modelo especializado em código) apresentam excelentes resultados. Codestral é suportado no Continue.dev e outros IDEs. Excelente custo-benefício para programação."}]$x$::jsonb
 WHERE slug = 'mistral-le-chat' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Motion o Reclaim para gestión de tiempo con IA?", "a": "Motion reorganiza activamente todo tu día — es más agresivo y completo, planificando cada tarea. Reclaim es más sutil: protege bloques de tiempo sin reorganizar todo. Motion es mejor para profesionales con muchas tareas cambiantes; Reclaim para quienes quieren proteger hábitos y tiempo de enfoque."}, {"q": "¿Motion es gratuito?", "a": "Motion no tiene plan gratuito permanente, solo prueba de 7 días. Los planes de pago empiezan desde $34/mes (Individual). Reclaim AI tiene un plan gratuito con funciones básicas; planes de pago desde $10/mes."}, {"q": "¿Motion puede gestionar proyectos de equipo?", "a": "Sí. Motion tiene funciones de gestión de proyectos de equipo — asignar tareas, gestionar deadlines y coordinar workload entre miembros. La IA planifica el trabajo de cada persona según su disponibilidad real en el calendario. Es más potente que Reclaim para gestión de proyectos."}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Motion vs Reclaim AI: Welches ist besser?", "a": "Motion ist ein vollständiges Produktivitäts-System mit Projektmanagement und KI-Scheduling. Reclaim ist spezifischer: Es schützt Fokuszeiten und optimiert Ihren bestehenden Google-Kalender. Motion für vollständige Planung; Reclaim für intelligente Kalender-Optimierung."}, {"q": "Wie viel kostet Motion?", "a": "Motion kostet ab $19/Monat (Individual) oder $12/Monat bei jährlicher Zahlung. Reclaim AI hat einen kostenlosen Plan; kostenpflichtige Pläne ab $10/Monat. Beide bieten kostenlose Testphasen."}, {"q": "Funktioniert Reclaim mit Google Kalender?", "a": "Ja. Reclaim AI ist primär für Google Kalender entwickelt und integriert sich tief. Es schützt Fokuszeiten, plant Habits ein und optimiert Meeting-Scheduling automatisch. Outlook-Integration ist ebenfalls verfügbar."}, {"q": "Kann Motion Teamprojekte verwalten?", "a": "Ja. Motion hat Team-Features: gemeinsame Projektplanung, Task-Zuweisung und Team-Kalender. Es plant Aufgaben automatisch basierend auf Verfügbarkeit und Priorität für das gesamte Team."}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Motion vs Reclaim.ai — в чём разница?", "a": "Motion — ИИ-планировщик задач и проектов: управляет задачами и автоматически планирует их в календаре. Reclaim.ai — умный помощник по расписанию: защищает время для важных дел в Google Календаре. Motion сложнее и дороже, Reclaim — проще и доступнее."}, {"q": "Motion стоит своих денег?", "a": "Motion стоит $34/мес (ежемесячно) или $19/мес (ежегодно). Пользователи, которым Motion подходит, отмечают значительный рост продуктивности. Для фрилансеров и специалистов с большим количеством задач — обоснованная инвестиция."}, {"q": "Работает ли Motion с Google Календарём?", "a": "Да. Motion интегрируется с Google Календарём и Outlook. Он читает существующие события и планирует задачи вокруг них. Reclaim.ai также работает с Google Календарём."}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Motion vs Reclaim.ai — яка різниця?", "a": "Motion повністю перепланує ваш день навколо завдань і дедлайнів. Reclaim.ai захищає існуючий час і додає розумні звички у ваш Google Calendar. Motion для тих хто хоче повну автоматизацію планування; Reclaim для захисту часу."}, {"q": "Motion безкоштовний?", "a": "Motion не має безкоштовного плану. Individual від $34/міс (щомісячно) або $19/міс (щорічно). Reclaim.ai має безкоштовний план; Starter від $10/міс."}, {"q": "Motion vs Todoist — яка різниця?", "a": "Todoist — традиційний task manager де ви самі вирішуєте коли робити завдання. Motion автоматично планує коли виконати кожне завдання виходячи з дедлайнів і доступного часу. Motion для автоматичного планування; Todoist для структурованих списків."}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Motion vs Reclaim AI — lequel est le meilleur ?", "a": "Motion est meilleur pour la planification automatique complète de vos tâches. Reclaim est meilleur pour protéger votre temps et équilibrer réunions et travail profond. Planification automatique complète → Motion ; protection du temps de travail → Reclaim."}, {"q": "Motion est-il cher ?", "a": "Motion coûte 34 $/mois (Individual) ou 20 $/mois en plan annuel. C'est cher, mais les utilisateurs rapportent économiser plusieurs heures de planification par semaine. Reclaim à partir de 10 $/mois."}, {"q": "Motion fonctionne-t-il avec Google Calendar ?", "a": "Oui. Motion s'intègre avec Google Calendar et Microsoft Outlook. Il lit vos réunions existantes et planifie vos tâches dans les créneaux disponibles. La synchronisation est bidirectionnelle."}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Motion vs Reclaim AI — qual escolher?", "a": "Motion é mais poderoso para gestão de tarefas e priorização automática. Reclaim AI é melhor para proteger tempo para hábitos e trabalho focado. Para gestão completa de agenda, Motion; para proteger tempo de foco, Reclaim."}, {"q": "Motion é gratuito?", "a": "Motion não tem plano gratuito. Planos a partir de $19/mês (Individual). Reclaim AI tem plano gratuito; planos pagos a partir de $10/mês."}, {"q": "Motion funciona com Google Calendar?", "a": "Sim, Motion sincroniza com Google Calendar e Outlook. Ele gerencia seus compromissos existentes e adiciona blocos de tempo para tarefas automaticamente."}]$x$::jsonb
 WHERE slug = 'motion' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Es legal clonar una voz con IA?", "a": "Clonar tu propia voz es completamente legal. Clonar la voz de otra persona sin su consentimiento explícito viola los términos de ElevenLabs y Murf, y puede tener consecuencias legales. Ambas plataformas requieren declarar que tienes los derechos sobre la voz que clonas."}, {"q": "¿Qué es Murf AI?", "a": "Murf AI es un generador de voz profesional de IA para crear voiceovers. Ofrece más de 200 voces en 20+ idiomas con calidad de estudio para e-learning, videos explicativos, presentaciones y anuncios."}, {"q": "¿Cuánto cuesta Murf AI?", "a": "Plan gratuito con 10 minutos de generación. Creator es $29/mes, Business es $99/mes, Enterprise es precio personalizado. La facturación anual da ~33% de descuento."}, {"q": "¿En qué se diferencia Murf AI de ElevenLabs?", "a": "Murf AI es un estudio completo de producción de voz: editor de guiones, sincronización de diapositivas, música. ElevenLabs se centra en clonación de voz, agentes de voz en tiempo real y acceso API para desarrolladores."}, {"q": "¿Admite Murf AI la clonación de voz?", "a": "Sí. La clonación de voz está disponible en los planes Business y Enterprise, permitiendo a los equipos crear voces de marca consistentes en todo su contenido."}]$x$::jsonb
 WHERE slug = 'murf-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "ElevenLabs vs Murf AI: Welches ist besser?", "a": "ElevenLabs hat die natürlichste Stimmqualität und das beste Voice Cloning. Murf AI hat ein vollständigeres Studio-Interface mit Video-Synchronisation und ist einfacher für nicht-technische Nutzer. Für höchste Stimmqualität und API — ElevenLabs; für vollständige Voiceover-Produktion — Murf."}, {"q": "Wie viel kostet Murf AI?", "a": "Murf AI beginnt ab $29/Monat (Basic) mit 60 Minuten Voice-Generierung. Pro ab $99/Monat mit unbegrenzter Generierung. ElevenLabs beginnt ab $5/Monat (Starter) für 30.000 Zeichen. ElevenLabs ist günstiger für den Einstieg."}, {"q": "Kann Murf AI deutsche Stimmen?", "a": "Ja. Murf AI unterstützt deutsche Stimmen in verschiedenen Altersgruppen und Stilen. Die Qualität ist professionell für E-Learning und Unternehmens-Content. ElevenLabs hat ebenfalls ausgezeichnete deutsche Stimmen."}, {"q": "Was ist besser für Hörbücher?", "a": "ElevenLabs ist die bevorzugte Wahl für Hörbücher dank der natürlichsten Stimm-Qualität und Voice Cloning. Sie können Ihre eigene Stimme klonen oder aus premium Stimmen wählen. Murf ist gut für Hörbücher aber ElevenLabs führt bei Natürlichkeit."}, {"q": "Was ist Murf AI?", "a": "Murf AI ist ein professioneller KI-Stimmgenerator für Voiceovers. Er bietet 200+ Stimmen in 20+ Sprachen in Studioqualität für E-Learning, Erklärvideos, Präsentationen und Werbung."}, {"q": "Was kostet Murf AI?", "a": "Kostenloser Plan mit 10 Minuten Generierung. Creator kostet $29/Monat, Business $99/Monat, Enterprise auf Anfrage. Jahresabrechnung spart ~33%."}, {"q": "Wie unterscheidet sich Murf AI von ElevenLabs?", "a": "Murf AI ist ein vollständiges Voiceover-Studio: Skript-Editor, Folien-Synchronisation, Musik. ElevenLabs fokussiert sich auf Stimmklonen, Echtzeit-Sprach-Agenten und Entwickler-API-Zugang."}, {"q": "Unterstützt Murf AI das Klonen von Stimmen?", "a": "Ja. Stimmklonen ist in Business- und Enterprise-Plänen verfügbar, sodass Teams markenkonsistente Stimmen für alle Inhalte erstellen können."}]$x$::jsonb
 WHERE slug = 'murf-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Сколько стоит Murf AI?", "a": "Murf предлагает бесплатный план с 10 минутами генерации голоса. Plan Creator — $29/мес (2 часа/мес), Business — $99/мес (8 часов/мес), Enterprise — индивидуальные цены."}, {"q": "Чем Murf AI отличается от ElevenLabs?", "a": "Murf AI — это полная студия озвучки: редактор скриптов, синхронизация со слайдами, музыка. ElevenLabs фокусируется на клонировании голоса, голосовых агентах и доступе через API для разработчиков."}]$x$::jsonb
 WHERE slug = 'murf-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "ElevenLabs чи Murf AI?", "a": "ElevenLabs кращий за якістю голосу і для розробників через API. Murf кращий для нетехнічних команд що роблять корпоративні відео та тренінги. Для якості і розробки — ElevenLabs; для корпоративного контенту — Murf."}, {"q": "Murf AI безкоштовний?", "a": "Murf має безкоштовний план з 10 хвилинами аудіо. Від $29/міс. ElevenLabs безкоштовний до 10 000 символів/міс; від $5/міс."}, {"q": "Чим Murf AI відрізняється від ElevenLabs?", "a": "Murf AI зосереджується на професійному виробництві войсоверів із повноцінним студійним інтерфейсом — редактором скриптів, синхронізацією слайдів, музикою. ElevenLabs орієнтований на клонування голосу, агентів реального часу та API для розробників."}]$x$::jsonb
 WHERE slug = 'murf-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "ElevenLabs מול Murf AI — מה לבחור?", "a": "ElevenLabs מוביל באיכות קול ו-voice cloning. Murf AI מוביל בסטודיו לייצור voiceover נוח. ElevenLabs למפתחים ולאיכות מרבית; Murf ליוצרי תוכן שצריכים עריכה פשוטה."}, {"q": "כמה עולה Murf AI?", "a": "Murf AI מ-29$/חודש (Basic) ל-99$/חודש (Enterprise). ElevenLabs מציע 10K תווים חינם; Starter מ-5$/חודש. ElevenLabs זול יותר לתוכן קצר."}, {"q": "במה Murf AI שונה מ-ElevenLabs?", "a": "Murf AI מתמקד בייצור ווויסאובר מקצועי עם ממשק סטודיו מלא — עורך סקריפטים, סנכרון שקופיות, מוזיקה. ElevenLabs מתמקד בשיבוט קול, סוכני קול בזמן אמת וגישת API למפתחים."}]$x$::jsonb
 WHERE slug = 'murf-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Murf AI est-il gratuit ?", "a": "Murf AI a un plan gratuit avec 10 minutes de voix. Pro à partir de 29 $/mois. ElevenLabs a un plan gratuit avec 10 000 caractères/mois ; payants à partir de 5 $/mois."}, {"q": "Qu'est-ce que Murf AI ?", "a": "Murf AI est un générateur de voix IA professionnel pour créer des voix off. Il propose 200+ voix dans 20+ langues avec une sortie qualité studio pour le e-learning, les vidéos explicatives, les présentations et les publicités."}, {"q": "Combien coûte Murf AI ?", "a": "Murf AI propose un plan gratuit avec 10 minutes de génération vocale. Creator est à 29$/mois, Business à 99$/mois et Enterprise sur devis. La facturation annuelle offre environ 33% de réduction."}, {"q": "En quoi Murf AI est-il différent d'ElevenLabs ?", "a": "Murf AI se concentre sur la production de voix off professionnelle avec une interface studio complète — éditeur de script, synchronisation de diapositives, musique. ElevenLabs se concentre sur le clonage vocal, les agents vocaux en temps réel et l'accès API pour les développeurs."}, {"q": "Murf AI prend-il en charge le clonage vocal ?", "a": "Oui. Murf AI prend en charge le clonage vocal personnalisé dans les plans Business et Enterprise, permettant aux équipes de créer des voix de marque cohérentes pour tout leur contenu."}]$x$::jsonb
 WHERE slug = 'murf-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "ElevenLabs vs Murf AI — qual escolher?", "a": "ElevenLabs tem a melhor qualidade de voz e mais recursos técnicos. Murf AI é mais simples e tem editor de vídeo integrado. Para qualidade máxima, ElevenLabs; para criação de conteúdo simples com vídeo, Murf."}, {"q": "Murf AI tem português?", "a": "Murf AI tem vozes em português, mas a qualidade em português não é tão boa quanto em inglês. ElevenLabs geralmente tem melhor qualidade para português brasileiro."}, {"q": "O que é o Murf AI?", "a": "O Murf AI é um gerador de voz IA profissional para criar narrações. Oferece mais de 200 vozes em 20+ idiomas com saída em qualidade de estúdio para e-learning, vídeos explicativos, apresentações e anúncios."}, {"q": "Quanto custa o Murf AI?", "a": "O Murf AI tem um plano gratuito com 10 minutos de geração de voz. Creator custa $29/mês, Business $99/mês e Enterprise sob consulta. A cobrança anual oferece ~33% de desconto."}, {"q": "Como o Murf AI é diferente do ElevenLabs?", "a": "O Murf AI foca na produção profissional de voz off com interface completa de estúdio — editor de script, sincronização de slides, música. O ElevenLabs foca em clonagem de voz, agentes de voz em tempo real e acesso via API para desenvolvedores."}, {"q": "O Murf AI suporta clonagem de voz?", "a": "Sim. O Murf AI suporta clonagem de voz personalizada nos planos Business e Enterprise, permitindo que equipes criem vozes de marca consistentes em todo o seu conteúdo."}]$x$::jsonb
 WHERE slug = 'murf-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Что такое n8n?", "a": "n8n — open-source платформа автоматизации рабочих процессов с визуальным редактором. Поддерживает 400+ интеграций, может работать self-hosted или в облаке. Позиционируется как мощная альтернатива Zapier/Make для технических пользователей."}, {"q": "В чём разница n8n и Copilot Studio?", "a": "n8n — универсальная платформа автоматизации для технических пользователей с акцентом на кастомные интеграции. Copilot Studio — конструктор корпоративных чат-ботов и агентов, глубоко интегрированный в Microsoft 365. Разные задачи."}, {"q": "n8n сложнее Zapier?", "a": "n8n требует больше технических знаний, чем Zapier, но предлагает значительно больше гибкости: JavaScript-код в узлах, self-hosting, сложная условная логика. Для разработчиков — мощный выбор."}]$x$::jsonb
 WHERE slug = 'n8n' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "n8n vs Zapier — що краще?", "a": "n8n дешевший і гнучкіший особливо для розробників і self-hosted розгортання. Zapier простіший для нетехнічних користувачів і має більше готових інтеграцій. n8n для технічних команд; Zapier для бізнес-користувачів."}, {"q": "n8n безкоштовний?", "a": "n8n Self-hosted повністю безкоштовний і відкритий. n8n Cloud від $24/міс. Microsoft Copilot Studio від $200/міс або $0,01 за повідомлення."}, {"q": "n8n vs Make (Integromat) — що обрати?", "a": "n8n і Make схожі за можливостями. n8n кращий для self-hosted і максимальної гнучкості. Make має красивіший візуальний інтерфейс і більше готових шаблонів. Обидва дешевші ніж Zapier."}]$x$::jsonb
 WHERE slug = 'n8n' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "n8n מול Zapier — מה עדיף?", "a": "n8n זול וגמיש יותר במיוחד למפתחים ולפריסה self-hosted. Zapier פשוט יותר למשתמשים לא-טכניים ויש לו יותר אינטגרציות מוכנות. n8n לצוותים טכניים; Zapier למשתמשי עסקים."}, {"q": "האם n8n בחינם?", "a": "n8n Self-hosted חינמי לחלוטין ופתוח. n8n Cloud מ-24$/חודש. Microsoft Copilot Studio מ-200$/חודש."}, {"q": "n8n מול Make (Integromat) — מה לבחור?", "a": "n8n ו-Make דומים ביכולות. n8n עדיף ל-self-hosted ולגמישות מרבית. ל-Make ממשק ויזואלי יפה יותר ויותר תבניות מוכנות. שניהם זולים מ-Zapier."}]$x$::jsonb
 WHERE slug = 'n8n' AND lang = 'he';

