UPDATE tools SET faq = $x$[{"q": "Nano Banana vs Leonardo AI — qual é o melhor?", "a": "Leonardo AI é mais estabelecido com mais funcionalidades, comunidade maior e plano gratuito generoso. Nano Banana é uma alternativa mais recente. Para uma plataforma consolidada → Leonardo AI."}, {"q": "Nano Banana é gratuito?", "a": "Verifique o site atual do Nano Banana para preços atualizados. Leonardo AI tem plano gratuito com 150 tokens por dia; pagos a partir de $12/mês."}, {"q": "Nano Banana para que tipos de imagens?", "a": "Nano Banana se especializa em certos tipos de geração criativa. Visite o site para ver casos de uso e exemplos atuais a fim de determinar se atende às suas necessidades."}]$x$::jsonb
