UPDATE tools SET faq = $x$[{"q": "¿Perplexity o NotebookLM para investigación?", "a": "Perplexity busca en internet en tiempo real — ideal para temas actuales y preguntas sobre el mundo. NotebookLM trabaja solo con documentos que tú cargas — ideal para analizar material específico con citas precisas. Perplexity para investigar el mundo; NotebookLM para analizar tu propio material."}, {"q": "¿NotebookLM es gratuito?", "a": "Sí. NotebookLM de Google es gratuito con hasta 50 fuentes por notebook y 500.000 palabras por fuente. NotebookLM Plus está disponible con Google One AI Premium ($19.99/mes). Perplexity tiene plan gratuito; Pro ($20/mes) desbloquea modelos avanzados y más búsquedas."}, {"q": "¿NotebookLM puede generar podcasts?", "a": "Sí. La función Audio Overview de NotebookLM genera automáticamente un podcast conversacional entre dos voces IA que discuten el contenido de tus documentos. Es una de las funciones más innovadoras — convierte papers académicos o informes en contenido de audio fácil de consumir."}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Kann NotebookLM YouTube-Videos analysieren?", "a": "Ja. NotebookLM akzeptiert YouTube-Video-Links als Quellen und transkribiert den Inhalt automatisch. Sie können dann Fragen zum Video-Inhalt stellen. Das ist ein einzigartiges Feature das Perplexity nicht hat."}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Perplexity vs NotebookLM — в чём разница?", "a": "Perplexity ищет в интернете и возвращает ответы со свежими источниками. NotebookLM анализирует только ваши загруженные документы. Perplexity для поиска информации, NotebookLM для анализа своих материалов."}, {"q": "NotebookLM бесплатный?", "a": "Да. NotebookLM бесплатен с неограниченными ноутбуками. NotebookLM Plus ($19.99/мес) добавляет больше аудиообзоров и приоритетный доступ. Perplexity бесплатен с 5 Pro-поисками в день; Perplexity Pro — $20/мес."}, {"q": "Что такое Audio Overview в NotebookLM?", "a": "NotebookLM может превращать загруженные документы в аудио-подкаст формата «два ведущих обсуждают тему». Это уникальная функция для изучения материалов в удобном формате."}, {"q": "Перплексити точнее Гугла?", "a": "Perplexity приводит источники для каждого утверждения, что упрощает проверку. Но как любой ИИ, он может ошибаться или галлюцинировать. Используйте для исследований, проверяйте критически важные факты."}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "NotebookLM може читати мої PDF?", "a": "Так. NotebookLM аналізує PDF, Google Docs, веб-сторінки і YouTube відео. Він відповідає на запитання виключно на основі ваших джерел і завжди вказує звідки взята інформація."}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Perplexity לעומת NotebookLM – מה ההבדל?", "a": "Perplexity מחפש מידע באינטרנט בזמן אמת. NotebookLM עובד רק עם המסמכים שהעלאתם. Perplexity לחיפוש עדכני; NotebookLM לניתוח עמוק של מקורות ספציפיים."}, {"q": "האם NotebookLM חינמי?", "a": "כן, NotebookLM חינמי לחלוטין. NotebookLM Plus זמין ב-Google One AI Premium ב-$19.99/חודש. Perplexity חינמי; Pro ב-$20/חודש."}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Perplexity vs NotebookLM — qual usar?", "a": "Perplexity é para pesquisa na web em tempo real. NotebookLM é para analisar seus próprios documentos. Para informações atuais da web, Perplexity; para trabalhar com seus documentos e materiais, NotebookLM."}, {"q": "NotebookLM pode criar podcasts?", "a": "Sim, este é um recurso único do NotebookLM. Ele pode gerar um podcast de áudio de dois apresentadores discutindo o conteúdo dos seus documentos. É surpreendentemente natural e informativo."}]$x$::jsonb
 WHERE slug = 'notebooklm' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Notion AI o ChatGPT para productividad?", "a": "Notion AI está integrado directamente en tu espacio de trabajo — sin cambiar de ventana, con contexto de tus documentos. ChatGPT es más potente en razonamiento general pero sin integración con tu base de conocimiento. Para trabajar sobre tus documentos existentes — Notion AI; para tareas de IA general — ChatGPT."}, {"q": "¿Notion AI es gratuito?", "a": "Notion AI es un add-on de pago: $10/usuario/mes añadido al plan de Notion (que empieza gratuito). Zapier AI está incluido en los planes de Zapier, que empieza desde $19.99/mes. Notion AI para un solo usuario sale a $10/mes extra sobre tu plan actual."}, {"q": "¿Qué puede hacer Notion AI?", "a": "Notion AI puede: resumir páginas largas, redactar documentos desde prompts, responder preguntas sobre tu base de datos de Notion, traducir texto, corregir gramática, extraer tareas pendientes de reuniones y generar tablas. Todo sin salir de Notion."}, {"q": "¿Qué es Notion AI?", "a": "Notion AI es un asistente de IA integrado directamente en Notion. Puede escribir, resumir, traducir y responder preguntas usando el contenido de tu espacio de trabajo como contexto."}, {"q": "¿Cuánto cuesta Notion AI?", "a": "Notion AI es un complemento a $10/miembro/mes (facturación anual) en cualquier plan de Notion. Incluido en los planes Plus, Business y Enterprise desde 2026."}, {"q": "¿Qué es Notion Developer Platform 3.5?", "a": "Notion Developer Platform 3.5 (mayo 2026) añade Workers runtime para funciones serverless, Sync API para datos en tiempo real y Webhooks para automatización basada en eventos, convirtiendo Notion en una plataforma programable."}, {"q": "¿Puede Notion AI acceder a internet?", "a": "Notion AI responde preguntas usando el contenido de tu espacio de trabajo. Para datos en tiempo real, usa integraciones conectadas en lugar de navegar directamente por internet."}]$x$::jsonb
 WHERE slug = 'notion-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Notion AI vs ChatGPT: Was ist besser?", "a": "Notion AI ist nativ in Notion integriert und arbeitet mit Ihren vorhandenen Dokumenten. ChatGPT ist ein eigenständiger Assistent ohne Ihre Dokument-Basis. Notion AI für bestehende Notion-Nutzer; ChatGPT für allgemeine KI-Aufgaben außerhalb von Notion."}, {"q": "Was kostet Notion AI?", "a": "Notion AI ist ein Add-on für $10/Benutzer/Monat zusätzlich zum Notion-Plan. Zapier hat eine kostenlose Version mit 100 Aufgaben/Monat; kostenpflichtige Pläne ab $29,99/Monat."}, {"q": "Kann Zapier KI-Workflows erstellen?", "a": "Ja. Zapier hat KI-Funktionen: AI-gestützte Zap-Generierung, Formatter mit KI und AI-Steps in Workflows. Sie können KI-Verarbeitung als Schritt in Automationen einbauen — z.B. E-Mail-Inhalt zusammenfassen und in Notion speichern."}, {"q": "Notion AI für Teams: Ist es gut?", "a": "Ja. Notion AI ist besonders wertvoll für Teams die Notion als zentrales Wissens-Hub nutzen. Es kann Meeting-Notizen automatisch zusammenfassen, Action Items extrahieren und Dokumente übersetzen — direkt in Ihren bestehenden Workflows."}, {"q": "Was ist Notion AI?", "a": "Notion AI ist ein KI-Assistent, der direkt in Notion integriert ist. Er kann schreiben, zusammenfassen, übersetzen und Fragen beantworten, wobei der Inhalt deines Arbeitsbereichs als Kontext dient."}, {"q": "Was ist Notion Developer Platform 3.5?", "a": "Notion Developer Platform 3.5 (Mai 2026) fügt Workers Runtime für serverlose Funktionen, Sync API für Echtzeit-Daten und Webhooks für ereignisgesteuerte Automatisierung hinzu — und macht Notion zu einer programmierbaren Plattform."}, {"q": "Kann Notion AI auf das Internet zugreifen?", "a": "Notion AI beantwortet Fragen aus dem Inhalt deines Arbeitsbereichs. Für Echtzeit-Webdaten werden verbundene Integrationen verwendet, kein direktes Internet-Browsen."}]$x$::jsonb
 WHERE slug = 'notion-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между Notion AI и Zapier AI?", "a": "Notion AI — ИИ-ассистент внутри Notion для создания и улучшения контента в вашем рабочем пространстве. Zapier AI ориентирован на автоматизацию — он использует ИИ для улучшения автоматизации рабочих процессов между приложениями. Notion AI — для работы со знаниями, Zapier AI — для автоматизации процессов."}, {"q": "Notion AI стоит своих денег?", "a": "Для активных пользователей Notion, которые регулярно пишут, Notion AI ($10/мес дополнительно) полезен для суммирования, перевода, переписывания и вопросов по документам. Если вам нужен ИИ-ассистент вне Notion, Claude или ChatGPT предлагают сопоставимые возможности за ту же цену."}, {"q": "Есть ли у Notion автоматизация?", "a": "В Notion есть базовые встроенные автоматизации (триггеры кнопок, автоматизации баз данных). Для сложных межприложных рабочих процессов используйте Zapier или Make с интеграцией Notion. Notion AI обрабатывает контент, Zapier — внешние подключения к приложениям."}, {"q": "Что такое Notion Developer Platform 3.5?", "a": "Notion Developer Platform 3.5 (май 2026) добавляет Workers runtime для серверлесс-функций, Sync API для данных в реальном времени и Webhooks для событийной автоматизации — превращая Notion в программируемую платформу."}]$x$::jsonb
 WHERE slug = 'notion-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Notion AI vs ChatGPT — що краще для нотаток?", "a": "Notion AI кращий якщо ви вже у Notion: він знає ваші документи і може з ними працювати. ChatGPT потужніший загально але не має доступу до ваших нотаток. Для Notion-команд — Notion AI; для загального ШІ — ChatGPT."}, {"q": "Notion AI безкоштовний?", "a": "Notion AI Plus — $16/міс/учасника (щорічно) або $20/міс щомісячно, додатково до базового Notion. Zapier має безкоштовний план; AI-функції у платних планах від $19,99/міс."}, {"q": "Що таке Notion Developer Platform 3.5?", "a": "Notion Developer Platform 3.5 (травень 2026) додає Workers runtime для серверлесс-функцій, Sync API для даних у реальному часі та Webhooks для подієвої автоматизації — перетворюючи Notion на програмовану платформу."}]$x$::jsonb
 WHERE slug = 'notion-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Notion AI לעומת Zapier AI – מה ההבדל?", "a": "Notion AI הוא עוזר כתיבה ועריכה בתוך Notion. Zapier AI הוא פלטפורמת אוטומציה שמוסיפה AI לזרימות עבודה בין אפליקציות. Notion למסמכים וידע; Zapier לאוטומציה."}, {"q": "כמה עולה Notion AI?", "a": "Notion AI עולה $10/משתמש/חודש בנוסף לתוכנית Notion הבסיסית. Zapier מציע תוכנית חינמית; תוכניות בתשלום מ-$19.99/חודש."}, {"q": "מה זה Notion Developer Platform 3.5?", "a": "Notion Developer Platform 3.5 (מאי 2026) מוסיף Workers runtime לפונקציות serverless, Sync API לנתונים בזמן אמת ו-Webhooks לאוטומציה מבוססת אירועים — והופך את Notion לפלטפורמה תכנותית."}]$x$::jsonb
 WHERE slug = 'notion-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Notion AI vs Zapier AI — quelle est la différence ?", "a": "Notion AI vous aide à créer et gérer du contenu dans Notion. Zapier AI automatise des workflows entre différentes applications. Notion AI pour la productivité documentaire ; Zapier AI pour l'automatisation de processus."}, {"q": "Notion AI est-il inclus dans Notion ?", "a": "Notion AI est un add-on à 10 $/utilisateur/mois en plus de l'abonnement Notion. Zapier a un plan gratuit ; AI Power-Ups sont disponibles dans les plans payants à partir de 29,99 $/mois."}, {"q": "Notion AI peut-il accéder à Internet ?", "a": "Non. Notion AI travaille uniquement avec le contenu de votre espace Notion. Il ne peut pas rechercher sur internet. Pour des recherches web, des outils comme Perplexity ou ChatGPT sont nécessaires."}, {"q": "Qu'est-ce que Notion AI ?", "a": "Notion AI est un assistant IA intégré directement dans Notion. Il peut écrire, résumer, traduire et répondre à des questions en utilisant le contenu de votre espace de travail comme contexte."}, {"q": "Combien coûte Notion AI ?", "a": "Notion AI est un module complémentaire à $10/membre/mois (facturation annuelle) pour tout plan Notion. Inclus dans les plans Plus, Business et Enterprise depuis 2026."}, {"q": "Qu'est-ce que Notion Developer Platform 3.5 ?", "a": "Notion Developer Platform 3.5 (mai 2026) ajoute Workers runtime pour les fonctions serverless, Sync API pour les données en temps réel et Webhooks pour l'automatisation événementielle — transformant Notion en plateforme programmable."}]$x$::jsonb
 WHERE slug = 'notion-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Notion AI vs Zapier AI — qual usar?", "a": "Notion AI é para trabalhar com conteúdo e documentos dentro do Notion. Zapier AI é para automação inteligente entre aplicativos. Para criar e editar no Notion, use Notion AI; para automatizar fluxos entre ferramentas, use Zapier AI."}, {"q": "Notion AI é gratuito?", "a": "Notion AI custa $10/usuário/mês adicionais ao plano Notion. Notion tem plano gratuito, mas Notion AI é pago. Zapier tem plano gratuito com automações limitadas; planos pagos incluem recursos de IA."}, {"q": "Notion AI suporta português?", "a": "Sim, Notion AI funciona bem em português. Você pode pedir resumos, melhorias de texto e geração de conteúdo em português diretamente."}, {"q": "O que é o Notion AI?", "a": "O Notion AI é um assistente de IA integrado diretamente no Notion. Pode escrever, resumir, traduzir e responder perguntas usando o conteúdo do seu espaço de trabalho como contexto."}, {"q": "Quanto custa o Notion AI?", "a": "O Notion AI é um complemento a $10/membro/mês (cobrança anual) para qualquer plano do Notion. Incluído nos planos Plus, Business e Enterprise desde 2026."}, {"q": "O que é o Notion Developer Platform 3.5?", "a": "O Notion Developer Platform 3.5 (maio de 2026) adiciona Workers runtime para funções serverless, Sync API para dados em tempo real e Webhooks para automação baseada em eventos — transformando o Notion em uma plataforma programável."}, {"q": "O Notion AI pode acessar a internet?", "a": "O Notion AI responde perguntas usando o conteúdo do seu espaço de trabalho. Para dados da web em tempo real, usa integrações conectadas em vez de navegar diretamente na internet."}]$x$::jsonb
 WHERE slug = 'notion-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Qué es OpenCode?", "a": "OpenCode es un agente de código de terminal open-source inspirado en Claude Code. Funciona con múltiples modelos de IA (Claude, GPT-4, modelos locales) y puede realizar tareas de desarrollo autónomas: leer código, hacer cambios, ejecutar tests. Es la alternativa open-source más directa a Claude Code."}, {"q": "¿OpenCode es tan bueno como Claude Code?", "a": "Claude Code tiene ventaja en calidad de razonamiento al estar optimizado específicamente para Claude 3.7/3.5. OpenCode es más flexible al soportar múltiples modelos. Para la mejor calidad absoluta — Claude Code con Claude Sonnet; para flexibilidad y open-source — OpenCode."}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist OpenCode?", "a": "OpenCode ist ein Open-Source Terminal-KI-Coding-Assistent ähnlich Claude Code oder Aider. Er unterstützt mehrere Modelle (OpenAI, Anthropic, Ollama) und arbeitet direkt im Terminal für agentenhafte Coding-Aufgaben."}, {"q": "OpenCode vs Claude Code: Welches ist besser?", "a": "Claude Code ist leistungsfähiger für komplexe Aufgaben da es von Anthropic optimiert wurde und den besten Claude-Modell-Zugang hat. OpenCode ist flexibler und kostenlos — ideal wenn Sie verschiedene Modelle testen oder Kosten sparen wollen."}, {"q": "OpenCode für lokale Modelle: Ist das möglich?", "a": "Ja. OpenCode unterstützt lokale Modelle über Ollama. Das ermöglicht komplett private Coding-Assistance ohne Cloud-Upload. Die Qualität hängt vom lokalen Modell ab — für beste Ergebnisse sind große Modelle (70B+) empfehlenswert."}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Що таке OpenCode?", "a": "OpenCode — відкритий термінальний ШІ-помічник для кодування схожий на Claude Code або Aider. Підтримує кілька моделей (OpenAI, Anthropic, Ollama) і працює прямо в терміналі для агентних завдань кодування."}, {"q": "OpenCode vs Claude Code — що краще?", "a": "Claude Code потужніший для складних завдань бо оптимізований Anthropic і має найкращий доступ до Claude-моделей. OpenCode гнучкіший і безкоштовний — ідеально якщо хочете тестувати різні моделі або заощаджувати."}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "מה זה OpenCode?", "a": "OpenCode הוא עוזר קוד Terminal פתוח בדומה ל-Claude Code. תומך במודלים מרובים – OpenAI, Anthropic, Ollama."}, {"q": "OpenCode לעומת Claude Code – מה עדיף?", "a": "Claude Code חזק יותר עם מיטוב ל-Anthropic. OpenCode גמיש יותר וחינמי. Anthropic Max ל-Claude Code; גמישות – OpenCode."}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que OpenCode ?", "a": "OpenCode est un assistant de codage IA terminal open-source similaire à Claude Code ou Aider. Il supporte plusieurs modèles (OpenAI, Anthropic, Ollama) et travaille directement dans le terminal pour des tâches de codage agentiques."}, {"q": "OpenCode vs Claude Code — lequel est le meilleur ?", "a": "Claude Code est plus puissant pour les tâches complexes car optimisé par Anthropic avec le meilleur accès aux modèles Claude. OpenCode est plus flexible et gratuit — idéal pour tester différents modèles ou réduire les coûts."}, {"q": "OpenCode pour les modèles locaux — est-ce possible ?", "a": "Oui. OpenCode supporte les modèles locaux via Ollama. Cela permet une assistance au codage entièrement privée sans envoi dans le cloud. La qualité dépend du modèle local — pour les meilleurs résultats, de grands modèles (70B+) sont recommandés."}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "O que é o OpenCode?", "a": "OpenCode é um assistente de codificação com IA no terminal open-source similar ao Claude Code ou Aider. Suporta múltiplos modelos (OpenAI, Anthropic, Ollama) e trabalha diretamente no terminal para tarefas de codificação agênticas."}, {"q": "OpenCode vs Claude Code — qual é o melhor?", "a": "Claude Code é mais poderoso para tarefas complexas pois é otimizado pela Anthropic com melhor acesso aos modelos Claude. OpenCode é mais flexível e gratuito — ideal para testar diferentes modelos ou reduzir custos."}, {"q": "OpenCode para modelos locais — é possível?", "a": "Sim. OpenCode suporta modelos locais via Ollama. Isso permite assistência de codificação totalmente privada sem enviar dados para a nuvem. A qualidade depende do modelo local — para melhores resultados, modelos grandes (70B+) são recomendados."}]$x$::jsonb
 WHERE slug = 'opencode' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Otter AI transcribe en español?", "a": "Otter AI está principalmente optimizado para inglés. La transcripción en español existe pero con menor precisión. Whisper tiene soporte nativo multilingüe y transcribe en español con buena calidad. Para reuniones en español — Whisper (API o local) puede ser más preciso."}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Whisper vs Otter AI: Was ist der Unterschied?", "a": "Whisper ist ein Transkriptions-Modell für Entwickler und technische Nutzer. Otter AI ist ein fertiges Business-Tool für Meeting-Transkription mit Kollaborations-Features. Whisper für technische Integration; Otter für sofort nutzbare Business-Lösung."}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Otter.ai vs Fireflies.ai — в чём разница?", "a": "Оба транскрибируют встречи, но с разными акцентами. Otter.ai известен высокой точностью транскрипции в реальном времени и интеграцией с Salesforce. Fireflies.ai предлагает более широкую языковую поддержку, аналитику разговоров и больше CRM-интеграций."}, {"q": "Otter.ai бесплатный?", "a": "Да. Otter.ai предлагает бесплатный план с 600 минутами транскрипции в месяц и 3 импортами. Pro — $17/мес. Fireflies.ai также имеет бесплатный план с ограниченным хранилищем транскрипций."}, {"q": "Работает ли Otter.ai в Google Meet?", "a": "Да. Otter.ai интегрируется с Google Meet, Zoom и Teams. Автоматически входит в запланированные встречи и начинает транскрипцию."}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Whisper vs Otter.ai — для чого що?", "a": "Whisper — відкрита технологія для розробників і технічних команд що хочуть транскрипцію у власних продуктах. Otter.ai — готовий продукт для бізнес-команд що хочуть зручну транскрипцію нарад без розробки."}, {"q": "Otter.ai для Zoom нарад?", "a": "Так. Otter.ai безпосередньо інтегрується з Zoom і автоматично транскрибує наради. OtterPilot приєднується до нарад як учасник і робить нотатки в реальному часі."}, {"q": "Otter.ai vs Fireflies.ai — яка різниця?", "a": "Otter.ai сильніший для транскрипції в реальному часі і особистої продуктивності. Fireflies.ai кращий для команд продажів з CRM-інтеграціями і пошуком по зустрічах. Otter для особистого використання; Fireflies для командного і продажового."}, {"q": "Otter.ai безкоштовний?", "a": "Otter.ai має безкоштовний план з 600 хвилин/міс транскрипції. Pro $16,99/міс. Fireflies.ai безкоштовний з обмеженнями; Pro $18/міс."}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Whisper לעומת Otter.ai?", "a": "Whisper Open Source API לפיתוחים. Otter.ai מוצר מוכן לשימוש לפגישות. Whisper למפתחים; Otter.ai לאנשי עסקים."}, {"q": "Otter.ai לעברית?", "a": "Otter.ai בעיקרו לאנגלית. תמיכה בעברית מוגבלת. לתמלול עברי מדויק – Whisper API עם מודלים מקומיים עדיף."}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Whisper vs Otter.ai — quelle est la différence ?", "a": "Whisper est un modèle de transcription open-source à intégrer dans vos propres outils. Otter.ai est un service complet de notes de réunion avec interface. Pour des développeurs intégrant la transcription → Whisper ; pour des notes de réunion prêtes à l'emploi → Otter.ai."}, {"q": "Otter.ai fonctionne-t-il en français ?", "a": "Otter.ai prend en charge la transcription en français. La qualité pour le français est bonne mais peut être légèrement inférieure à l'anglais. Pour des réunions en français, Otter.ai reste un outil efficace."}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Whisper vs Otter.ai — qual é a diferença?", "a": "Whisper é um modelo de transcrição open-source para integrar em suas próprias ferramentas. Otter.ai é um serviço completo de notas de reunião com interface pronta. Para desenvolvedores integrando transcrição → Whisper; para notas de reunião prontas para uso → Otter.ai."}, {"q": "Otter.ai funciona em português?", "a": "Otter.ai é focado principalmente em inglês. O suporte ao português é limitado. Para transcrição em português, considere alternativas como Whisper ou serviços especializados."}]$x$::jsonb
 WHERE slug = 'otter-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Perplexity o NotebookLM para investigación?", "a": "Perplexity busca en internet en tiempo real — ideal para temas actuales y preguntas sobre el mundo. NotebookLM trabaja solo con documentos que tú cargas — ideal para analizar material específico con citas precisas. Perplexity para investigar el mundo; NotebookLM para analizar tu propio material."}, {"q": "¿Perplexity puede analizar PDFs?", "a": "Sí. Perplexity Pro permite cargar PDFs y hacer preguntas sobre ellos. Sin embargo, NotebookLM está más especializado en análisis profundo de documentos con citaciones exactas. Para un PDF ocasional — Perplexity Pro funciona; para investigación intensiva con múltiples documentos — NotebookLM."}]$x$::jsonb
 WHERE slug = 'perplexity' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Perplexity vs Google: Was ist der Unterschied?", "a": "Perplexity fasst die Antwort direkt zusammen mit zitierten Quellen — kein Link-Scrollen nötig. Google gibt Links die Sie selbst besuchen müssen. Perplexity ist schneller für direkte Antworten; Google ist besser für explorative Suche und komplexe Themen."}, {"q": "Ist Perplexity kostenlos?", "a": "Perplexity hat einen kostenlosen Plan mit begrenzten Pro-Suchen. Perplexity Pro ($20/Monat) bietet unbegrenzte Pro-Suchen, GPT-4o, Claude, Gemini und Bildgenerierung. NotebookLM ist kostenlos."}, {"q": "Perplexity für akademische Recherche: Ist es gut?", "a": "Perplexity ist gut für schnelle Literatursuche und Überblicke. Für tiefe akademische Forschung sind Semantic Scholar, Elicit oder Consensus besser — sie sind speziell für peer-reviewed Literatur optimiert. Perplexity als erster Schritt; spezialisierte Tools für tiefere Analyse."}]$x$::jsonb
 WHERE slug = 'perplexity' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Perplexity vs NotebookLM — в чём разница?", "a": "Perplexity ищет в интернете и возвращает ответы со свежими источниками. NotebookLM анализирует только ваши загруженные документы. Perplexity для поиска информации, NotebookLM для анализа своих материалов."}, {"q": "Перплексити точнее Гугла?", "a": "Perplexity приводит источники для каждого утверждения, что упрощает проверку. Но как любой ИИ, он может ошибаться или галлюцинировать. Используйте для исследований, проверяйте критически важные факты."}]$x$::jsonb
 WHERE slug = 'perplexity' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Perplexity vs Google — яка різниця?", "a": "Perplexity синтезує відповідь з кількох джерел і дає цитати. Google показує список посилань де ви самі шукаєте відповідь. Perplexity швидший для прямих відповідей; Google повніший для глибокого пошуку."}, {"q": "Perplexity безкоштовний?", "a": "Perplexity безкоштовний з базовими функціями. Pro $20/міс з розширеними моделями і більше пошуків. NotebookLM повністю безкоштовний від Google."}]$x$::jsonb
 WHERE slug = 'perplexity' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Perplexity לעומת NotebookLM – מה ההבדל?", "a": "Perplexity מחפש מידע באינטרנט בזמן אמת. NotebookLM עובד רק עם המסמכים שהעלאתם. Perplexity לחיפוש עדכני; NotebookLM לניתוח עמוק של מקורות ספציפיים."}, {"q": "Perplexity לעומת ChatGPT – מה עדיף לחיפוש?", "a": "Perplexity מתמחה בחיפוש עם ציטוטים ומקורות. ChatGPT מגוון יותר אך ידע הבסיסי מוגבל לתאריך חיתוך. לחיפוש עדכני עם מקורות – Perplexity; לשיחה וכתיבה – ChatGPT."}]$x$::jsonb
 WHERE slug = 'perplexity' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Perplexity vs NotebookLM — lequel est le meilleur ?", "a": "Perplexity recherche sur internet pour des informations en temps réel. NotebookLM analyse vos propres documents. Pour la recherche web avec sources, Perplexity ; pour analyser vos propres PDFs et notes, NotebookLM."}, {"q": "Perplexity en français — est-ce efficace ?", "a": "Oui. Perplexity fonctionne bien en français. Il comprend les questions en français et peut chercher dans des sources françaises. Pour des recherches sur l'actualité française ou des sources francophones, c'est très efficace."}]$x$::jsonb
 WHERE slug = 'perplexity' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Perplexity vs NotebookLM — qual usar?", "a": "Perplexity é para pesquisa na web em tempo real. NotebookLM é para analisar seus próprios documentos. Para informações atuais da web, Perplexity; para trabalhar com seus documentos e materiais, NotebookLM."}, {"q": "Perplexity é gratuito?", "a": "Perplexity tem plano gratuito com buscas ilimitadas. Perplexity Pro custa $20/mês com mais pesquisas profundas e acesso a modelos avançados. NotebookLM é gratuito do Google."}, {"q": "Perplexity cita suas fontes?", "a": "Sim, Perplexity cita todas as fontes usadas nas respostas. Você pode verificar cada informação clicando nas referências. Este é um dos diferenciais principais da plataforma."}]$x$::jsonb
 WHERE slug = 'perplexity' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Photomath o Wolfram Alpha para matemáticas?", "a": "Photomath es más accesible — fotografías el problema y obtienes pasos explicados en lenguaje simple. Wolfram Alpha es más potente para matemáticas avanzadas (universitarias, cálculo complejo) pero requiere escribir el problema correctamente. Para estudiantes de secundaria — Photomath; para matemáticas avanzadas — Wolfram Alpha."}, {"q": "¿Photomath es gratuito?", "a": "Photomath tiene una versión gratuita que resuelve problemas y muestra pasos básicos. Photomath Plus ($9.99/mes o $29.99/año) desbloquea pasos animados, más métodos de solución y práctica adicional. Duolingo Max ($14.99/mes, incluido en Super Duolingo en algunos planes)."}, {"q": "¿Puede Photomath hacer trampa en los deberes?", "a": "Photomath puede resolver problemas automáticamente, lo que algunos usan para copiar en lugar de aprender. La herramienta está diseñada para aprender los pasos, no para obtener respuestas sin entender. Usarla responsablemente — entender cada paso — hace la diferencia entre aprender y copiar."}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Photomath vs Mathway: Was ist besser?", "a": "Photomath ist besser für Schüler: Die Schritt-für-Schritt-Erklärungen sind didaktisch aufgebaut. Mathway löst schneller aber erklärt weniger. Photomath für Lernende; Mathway für schnelle Antworten."}, {"q": "Ist Photomath kostenlos?", "a": "Photomath ist kostenlos mit grundlegenden Lösungsschritten. Photomath Plus ($9,99/Monat oder $69,99/Jahr) bietet detailliertere Erklärungen und Animationen. Duolingo Max kostet ab $13,99/Monat als Upgrade."}, {"q": "Kann Photomath Handschrift lesen?", "a": "Ja. Photomath erkennt handgeschriebene Matheaufgaben sowie Drucktext. Die Handschrift-Erkennungsrate ist beeindruckend obwohl klare Handschrift bessere Ergebnisse liefert."}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Photomath vs Duolingo Max — это разные инструменты?", "a": "Да, полностью разные. Photomath — решатель математических задач по фото. Duolingo Max — премиум-уровень языкового приложения с ИИ. Photomath для математики, Duolingo для языков."}, {"q": "Photomath бесплатный?", "a": "Photomath бесплатен с базовыми решениями. Photomath Plus ($9.99/мес или $59.99/год) добавляет анимированные пошаговые объяснения. Duolingo Max — $30/мес или $168/год."}, {"q": "Что точнее — Photomath или ChatGPT для математики?", "a": "Оба хороши, но по-разному. Photomath специализируется на математике и пошаговых решениях — очень точен для школьного уровня. ChatGPT охватывает более широкий математический контекст, но может ошибаться в сложных задачах."}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Photomath безкоштовний?", "a": "Photomath безкоштовний з базовими розв'язаннями. Photomath Plus ($9,99/міс або $59,99/рік) дає покрокові пояснення і анімовані підказки. Duolingo безкоштовний; Max від $13,99/міс."}, {"q": "Photomath vs Wolfram Alpha — яка різниця?", "a": "Photomath спеціалізований на шкільній математиці з візуальними покроковими поясненнями. Wolfram Alpha потужніший для університетської математики, фізики і наукових розрахунків. Photomath для школярів; Wolfram Alpha для університету."}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Photomath לעומת Duolingo Max – מה ההבדל?", "a": "שניהם כלי חינוך AI אך לתחומים שונים. Photomath למתמטיקה; Duolingo Max ללימוד שפות. לפי צרכיכם."}, {"q": "Photomath חינמי?", "a": "Photomath חינמי לפתרונות בסיסיים; Photomath Plus ב-$9.99/חודש לפתרונות מפורטים. Duolingo Plus ב-$14.99/חודש; Duolingo Max ב-$29.99/חודש."}]$x$::jsonb
 WHERE slug = 'photomath' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Photomath vs Duolingo Max — pour quoi utiliser lequel ?", "a": "Ce sont des outils pour des objectifs complètement différents. Photomath pour apprendre et résoudre des mathématiques. Duolingo Max pour apprendre des langues avec des fonctionnalités IA. Il n'y a pas de comparaison directe."}, {"q": "Photomath est-il gratuit ?", "a": "Photomath a un plan gratuit avec des étapes de base. Plus à partir de 9,99 $/mois pour des explications complètes. Duolingo Max à partir de 13,99 $/mois en plus de Duolingo Super."}, {"q": "Photomath peut-il aider en prépa ou en université ?", "a": "Photomath couvre les mathématiques jusqu'au niveau bac et partiellement les mathématiques universitaires. Pour les mathématiques avancées de prépa ou licence, des outils comme Wolfram Alpha ou Symbolab sont plus appropriés."}]$x$::jsonb
