UPDATE tools SET faq = $x$[{"q": "Beautiful.ai vs Pitch: Welches ist besser für Startups?", "a": "Pitch ist beliebter bei Startups für Investor-Decks: bessere Templates für Fundraising und stärkere Kollaboration. Beautiful.ai ist gut für regelmäßige Unternehmenspräsentationen wo Konsistenz wichtig ist. Für Investor-Pitches — Pitch; für laufende Business-Präsentationen — Beautiful.ai."}, {"q": "Pitch vs PowerPoint: Was ist besser?", "a": "Pitch hat schönere moderne Templates und stärkere Online-Kollaboration als PowerPoint. PowerPoint ist universeller und offline nutzbar. Für moderne Team-Präsentationen — Pitch; für maximale Kompatibilität und Offline-Nutzung — PowerPoint."}]$x$::jsonb
