UPDATE tools SET faq = $x$[{"q": "¿Semantic Scholar es gratuito?", "a": "Sí. Semantic Scholar es completamente gratuito — es un proyecto del Allen Institute for AI. Incluye 200M+ papers, gráficos de citas, papers relacionados y funciones de IA básicas sin costo. Scite tiene funciones limitadas gratuitas; el plan premium cuesta $20/mes."}, {"q": "¿Qué disciplinas cubre Semantic Scholar?", "a": "Semantic Scholar cubre todas las disciplinas académicas: ciencias, medicina, informática, ciencias sociales, humanidades, ingeniería y más. Con 200 millones de papers, es una de las bases de datos académicas más completas disponibles gratuitamente."}]$x$::jsonb
 WHERE slug = 'semantic-scholar' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Ist Semantic Scholar kostenlos?", "a": "Ja. Semantic Scholar ist vollständig kostenlos auf semanticscholar.org. Es wird vom Allen Institute for AI betrieben. Scite hat einen kostenlosen Plan mit begrenztem Zugang; kostenpflichtige Pläne ab $20/Monat."}, {"q": "Kann Semantic Scholar auf Deutsch arbeiten?", "a": "Semantic Scholar kann deutsche Suchanfragen verarbeiten, aber die Datenbank enthält überwiegend englischsprachige Publikationen. Für deutschsprachige wissenschaftliche Literatur sind Datenbanken wie DBIS oder spezifische Fach-Repositorien besser."}]$x$::jsonb
 WHERE slug = 'semantic-scholar' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Scite vs Semantic Scholar — в чём разница?", "a": "Scite уникален тем, что показывает, как статья процитирована — поддерживающие, опровергающие или нейтральные упоминания. Semantic Scholar — бесплатный ИИ-поисковик по научным работам с суммаризацией. Scite для оценки доказательной базы, Semantic Scholar для широкого поиска."}, {"q": "Semantic Scholar лучше Google Scholar?", "a": "Semantic Scholar добавляет ИИ-функции: суммаризация, связанные работы, граф влияния. Google Scholar охватывает больше источников, включая патенты и диссертации. Для академических работ — Semantic Scholar, для широкого поиска — Google Scholar."}]$x$::jsonb
 WHERE slug = 'semantic-scholar' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Що таке Semantic Scholar?", "a": "Semantic Scholar — безкоштовна пошукова система наукових публікацій від Allen Institute for AI. Охоплює понад 220 мільйонів статей і використовує ШІ для аналізу важливості і зв'язків між публікаціями."}]$x$::jsonb
 WHERE slug = 'semantic-scholar' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Scite לעומת Semantic Scholar – מה ההבדל?", "a": "Scite מתמחה בניתוח ציטוטים לפי הקשר – תומך, סותר או ניטרלי. Semantic Scholar הוא מנוע חיפוש אקדמי כללי עם AI. Scite לאימות מחקר; Semantic Scholar לחיפוש ספרות."}, {"q": "Semantic Scholar לעומת Google Scholar?", "a": "שניהם חינמיים ומאנדקסים מאמרים אקדמיים. Semantic Scholar מציע AI כמו TLDR ו-Paper Recommendations. Google Scholar מכסה יותר מקורות ויש לו אינדקס גדול יותר."}]$x$::jsonb
