UPDATE tools SET faq = $x$[{"q": "Scite vs Semantic Scholar — lequel est le meilleur ?", "a": "Scite est unique pour analyser comment une étude est citée (soutenue ou contredite). Semantic Scholar est meilleur pour la découverte large de littérature gratuite. Évaluation de la robustesse des preuves → Scite ; découverte de littérature → Semantic Scholar."}, {"q": "Semantic Scholar est-il disponible en français ?", "a": "Semantic Scholar est principalement en anglais mais indexe aussi des publications en d'autres langues. L'interface est en anglais. Pour la recherche francophone, PubMed et Google Scholar sont aussi de bonnes options."}]$x$::jsonb
