UPDATE tools SET faq = $x$[{"q": "Scite vs Semantic Scholar — qual usar?", "a": "Scite é para análise qualitativa de citações — entender como papers são citados. Semantic Scholar é para descoberta e recomendação de papers. Para análise de evidências, Scite; para descoberta de literatura, Semantic Scholar."}, {"q": "Semantic Scholar é confiável?", "a": "Sim, Semantic Scholar é desenvolvido pelo Allen Institute for AI e é amplamente usado por pesquisadores. Cobre mais de 200 milhões de papers com dados de citações precisos."}]$x$::jsonb
