 WHERE slug = 'semrush' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Semrush vs Copy.ai — это сравнение разных инструментов?", "a": "Да. Semrush — SEO-платформа для анализа данных, исследования ключевых слов и аудита сайтов. Copy.ai — ИИ-генератор контента для написания текстов. Они решают разные задачи, хотя оба используются в контент-маркетинге."}, {"q": "Semrush бесплатный?", "a": "Semrush предлагает ограниченный бесплатный план (10 запросов в день). Pro план — от $139.95/мес. Copy.ai бесплатен с ограниченными словами; платные планы от $49/мес."}, {"q": "Нужны ли оба инструмента?", "a": "Для контент-маркетинга — да: Semrush находит ключевые слова и темы для контента, Copy.ai помогает его написать быстро. Многие маркетинговые команды используют оба в связке."}]$x$::jsonb
