UPDATE tools SET faq = $x$[{"q": "Was ist Slidesgo?", "a": "Slidesgo ist eine Plattform mit kostenlosen und kostenpflichtigen Präsentationsvorlagen für PowerPoint und Google Slides. Slidesgo AI kann Präsentationen aus Beschreibungen generieren und direkt in Google Slides oder PowerPoint öffnen."}, {"q": "Ist Slidesgo kostenlos?", "a": "Slidesgo hat viele kostenlose Templates. Premium ab $8,25/Monat für alle Templates ohne Einschränkungen. Gamma hat einen kostenlosen Plan mit 400 KI-Credits; Plus ab $10/Monat."}, {"q": "Slidesgo AI vs Gamma: Was ist besser?", "a": "Gamma ist besser wenn Sie keinen Content haben und von Null starten. Slidesgo AI ist besser wenn Sie bereits wissen was Sie präsentieren möchten und eine schöne Vorlage in Google Slides oder PowerPoint wollen. Gamma ist output-Tool; Slidesgo ist template-basiert."}, {"q": "Slidesgo für Google Slides: Wie funktioniert es?", "a": "Slidesgo-Templates können direkt in Google Slides geöffnet werden. Sie klicken 'Use as Google Slides theme' und der Template öffnet sich in Ihrem Google Slides-Account. Slidesgo AI generiert direkt in Google Slides ohne Zwischen-Download."}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Slidesgo vs Gamma — что лучше?", "a": "Slidesgo даёт шаблоны для самостоятельного создания презентаций в Google Slides/PowerPoint. Gamma генерирует всю презентацию по описанию с помощью ИИ. Slidesgo для тех, кто хочет контроль над дизайном, Gamma — для тех, кто хочет скорость."}, {"q": "Slidesgo бесплатный?", "a": "Slidesgo предлагает сотни бесплатных шаблонов. Premium ($5.99/мес) открывает все шаблоны и функции. Gamma бесплатен с ограниченными ИИ-генерациями; Pro — $10/мес."}, {"q": "Можно ли использовать шаблоны Slidesgo в Canva?", "a": "Да. У Slidesgo есть отдельная коллекция шаблонов для Canva, помимо Google Slides и PowerPoint. Это удобно для пользователей Canva, которым нужен более широкий выбор дизайнов."}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Що таке Slidesgo?", "a": "Slidesgo — платформа з безкоштовними і платними шаблонами презентацій для PowerPoint і Google Slides. Slidesgo AI може генерувати презентації з описів і відкривати їх прямо в Google Slides або PowerPoint."}, {"q": "Slidesgo AI чи Gamma — що краще?", "a": "Gamma краще якщо у вас нема контенту і ви починаєте з нуля. Slidesgo AI краще якщо ви вже знаєте що хочете презентувати і потрібен красивий шаблон у Google Slides або PowerPoint."}, {"q": "Slidesgo для Google Slides — як це працює?", "a": "Шаблони Slidesgo можна відкрити прямо в Google Slides. Клацніть «Use as Google Slides theme» і шаблон відкриється у вашому Google Slides. Slidesgo AI генерує прямо в Google Slides без проміжного завантаження."}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Slidesgo ?", "a": "Slidesgo est une plateforme avec des templates de présentation gratuits et payants pour PowerPoint et Google Slides. Slidesgo AI peut générer des présentations à partir de descriptions et les ouvrir directement dans Google Slides ou PowerPoint."}, {"q": "Slidesgo est-il gratuit ?", "a": "Slidesgo a de nombreux templates gratuits. Premium à partir de 8,25 $/mois pour tous les templates sans restrictions. Gamma a un plan gratuit avec 400 crédits IA ; Plus à partir de 10 $/mois."}, {"q": "Slidesgo AI vs Gamma — lequel est le meilleur ?", "a": "Gamma est meilleur si vous n'avez pas de contenu et démarrez de zéro. Slidesgo AI est meilleur si vous savez déjà ce que vous voulez présenter et voulez un beau template dans Google Slides ou PowerPoint. Gamma est un outil de génération ; Slidesgo est basé sur les templates."}, {"q": "Slidesgo pour Google Slides — comment ça fonctionne ?", "a": "Les templates Slidesgo peuvent être ouverts directement dans Google Slides. Vous cliquez sur 'Use as Google Slides theme' et le template s'ouvre dans votre compte Google Slides. Slidesgo AI génère directement dans Google Slides sans téléchargement intermédiaire."}]$x$::jsonb
 WHERE slug = 'slidesgo' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "O que é o Slidesgo?", "a": "Slidesgo é uma plataforma com templates de apresentação gratuitos e pagos para PowerPoint e Google Slides. Slidesgo AI pode gerar apresentações a partir de descrições e abri-las diretamente no Google Slides ou PowerPoint."}, {"q": "Slidesgo é gratuito?", "a": "Slidesgo tem muitos templates gratuitos. Premium a partir de $8,25/mês para todos os templates sem restrições. Gamma tem plano gratuito com 400 créditos de IA; Plus a partir de $10/mês."}, {"q": "Slidesgo AI vs Gamma — qual é o melhor?", "a": "Gamma é melhor se você não tem conteúdo e está começando do zero. Slidesgo AI é melhor se você já sabe o que quer apresentar e quer um belo template no Google Slides ou PowerPoint. Gamma é uma ferramenta de geração; Slidesgo é baseado em templates."}, {"q": "Slidesgo para Google Slides — como funciona?", "a": "Os templates do Slidesgo podem ser abertos diretamente no Google Slides. Você clica em 'Use as Google Slides theme' e o template abre na sua conta. Slidesgo AI gera diretamente no Google Slides sem download intermediário."}]$x$::jsonb
