UPDATE tools SET faq = $x$[{"q": "Suno vs ElevenLabs — qual é a diferença?", "a": "Suno gera músicas completas com instrumentos e vocal cantado. ElevenLabs gera fala realista para narração e dublagem. São ferramentas de áudio diferentes: Suno para música; ElevenLabs para voz falada."}, {"q": "Suno pode criar música em português?", "a": "Sim, Suno pode gerar músicas com letras em português. Você pode especificar o idioma e o estilo musical. A qualidade das letras em português é boa, mas pode ter nuances menos precisas que em inglês."}]$x$::jsonb
 WHERE slug = 'suno' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿SurferSEO o SEMrush para contenido?", "a": "SurferSEO es mejor para la optimización de contenido paso a paso — te dice exactamente qué palabras clave incluir y cuántas veces mientras escribes. SEMrush es mejor para la estrategia global: encontrar temas, analizar competidores y auditar el sitio. Muchos equipos SEO usan ambas herramientas juntas."}, {"q": "¿SurferSEO vale la pena?", "a": "SurferSEO es valioso si produces contenido SEO regularmente. El Content Score y las sugerencias de términos semánticamente relacionados aceleran significativamente el proceso de optimización. Para creadores de contenido activos — el ROI suele ser positivo. Para publicación ocasional, puede ser caro."}, {"q": "¿Cuánto cuesta SurferSEO?", "a": "SurferSEO empieza desde $99/mes (Essential), con planes más avanzados para agencias. SEMrush empieza desde $139.95/mes (Pro). Ambos tienen pruebas gratuitas."}, {"q": "¿Puede SurferSEO reemplazar a SEMrush?", "a": "No completamente. SurferSEO es excelente para optimización on-page y creación de contenido. SEMrush cubre análisis de backlinks, auditorías técnicas y seguimiento de rankings con mayor profundidad. Para una estrategia SEO completa, necesitas capacidades de ambas."}]$x$::jsonb
 WHERE slug = 'surferseo' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Surfer SEO?", "a": "Surfer SEO ist ein Content-Optimierungstool das SERP-Ergebnisse analysiert und Ihnen sagt, welche Keywords, Überschriften und Struktur Ihr Artikel braucht um zu ranken. Der Editor zeigt einen Content-Score in Echtzeit während Sie schreiben."}, {"q": "Wie viel kostet Surfer SEO?", "a": "Surfer SEO Essential beginnt ab $89/Monat, Scale ab $129/Monat. SEMrush beginnt ab $139,95/Monat (Pro). Beide haben kostenlose Testphasen."}, {"q": "Surfer SEO vs SEMrush: Was ist der Unterschied?", "a": "Surfer ist ein Content-Optimizer: Er hilft Ihnen, bessere Artikel zu schreiben. SEMrush ist eine vollständige SEO-Suite für Keyword-Recherche, Backlinks, technische Audits und Wettbewerbs-Tracking. Viele SEO-Profis nutzen beide — Surfer zum Schreiben, SEMrush für Strategie."}, {"q": "Kann Surfer SEO auf Deutsch arbeiten?", "a": "Ja. Surfer SEO unterstützt Keyword-Analyse und Content-Optimierung für deutsche Suchanfragen. Sie geben einfach Ihr deutsches Keyword ein und Surfer analysiert die deutschen Google-SERPs."}]$x$::jsonb
 WHERE slug = 'surferseo' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Surfer SEO vs Semrush — что выбрать?", "a": "Surfer SEO специализируется на оптимизации контента: показывает, как улучшить страницу, чтобы она ранжировалась лучше. Semrush — полноценная SEO-платформа с исследованием ключевых слов, анализом конкурентов, аудитом и PPC. Surfer — инструмент контент-маркетолога, Semrush — инструмент SEO-стратега."}, {"q": "Surfer SEO дешевле Semrush?", "a": "Да. Surfer SEO Essential — $89/мес, Scale — $129/мес. Semrush Pro — $139.95/мес, Guru — $249.95/мес. Surfer дешевле, но охватывает меньше задач."}, {"q": "Surfer SEO помогает с написанием контента?", "a": "Да. Surfer SEO включает ИИ-редактор Surfer AI, который генерирует SEO-статьи по ключевому слову. Он также даёт рекомендации в реальном времени при написании вручную."}]$x$::jsonb
 WHERE slug = 'surferseo' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Surfer SEO чи SEMrush — що обрати?", "a": "Surfer SEO краще для on-page оптимізації і написання контенту. SEMrush кращий для комплексної SEO-стратегії: ключові слова, зворотні посилання, аудит і конкуренти. Для авторів контенту — Surfer; для SEO-менеджерів — SEMrush."}, {"q": "Скільки коштує Surfer SEO?", "a": "Surfer SEO від $99/міс (Essential) до $299/міс (Scale). SEMrush від $139,95/міс (Pro). Обидва мають пробний доступ."}, {"q": "Чи інтегрується Surfer SEO з Google Docs?", "a": "Так. Surfer SEO має розширення Google Docs і інтеграцію з WordPress. Ви пишете статтю в Google Docs і одночасно бачите поради Surfer у бічній панелі."}]$x$::jsonb
 WHERE slug = 'surferseo' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Surfer SEO מול SEMrush — מה ההבדל?", "a": "Surfer SEO מתמקד באופטימיזציית תוכן on-page: ניתוח SERP ויצירת תוכן. SEMrush הוא חבילת SEO מלאה: מחקר מילות מפתח, backlinks, PPC ועוד. Surfer ל-content writers; SEMrush ל-SEO מקצועי מלא."}, {"q": "כמה עולה Surfer SEO?", "a": "Surfer SEO מ-89$/חודש (Essential) עד 219$/חודש (Scale). SEMrush מ-139.95$/חודש. שניהם מציעים ניסיונות חינמיים."}, {"q": "Surfer SEO עם Jasper — האם אפשר לשלב?", "a": "כן. Surfer SEO משתלב ישירות עם Jasper AI. אתם יכולים ליצור תוכן ב-Jasper ולהשתמש בניקוד Surfer לאופטימיזציה בו-זמנית. זוהי שילוב פופולרי לייצור תוכן SEO בקנה מידה גדול."}]$x$::jsonb
 WHERE slug = 'surferseo' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Surfer SEO vs SEMrush — lequel est le meilleur pour le référencement de contenu ?", "a": "Surfer SEO est spécialisé dans l'optimisation du contenu et donne des conseils précis sur le nombre de mots, la densité de mots-clés et la structure basés sur les pages en tête de classement. SEMrush est une suite complète. Pour la rédaction SEO, Surfer ; pour le SEO complet, SEMrush."}, {"q": "Combien coûte Surfer SEO ?", "a": "Surfer SEO à partir de 99 $/mois (Essential). SEMrush à partir de 139,95 $/mois. Les deux offrent des essais. Surfer est moins cher mais avec un périmètre plus étroit."}, {"q": "Surfer SEO vaut-il le coup pour un blog ?", "a": "Oui, si vous publiez régulièrement et voulez maximiser les classements. L'éditeur de contenu guide votre rédaction vers les pages en tête de classement. Pour les blogs publiant 4+ articles par mois avec un objectif SEO, l'investissement se justifie."}, {"q": "Surfer SEO fonctionne-t-il pour le contenu en français ?", "a": "Oui. Surfer SEO prend en charge le français et analyse les SERPs français. Les recommandations sont basées sur ce qui est classé pour votre terme cible sur Google.fr, ce qui en fait un outil efficace pour le SEO en français."}]$x$::jsonb
 WHERE slug = 'surferseo' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "SurferSEO ou SEMrush — qual é o melhor para SEO?", "a": "SurferSEO é melhor para otimização de conteúdo na página — análise de NLP e pontuação de conteúdo em tempo real. SEMrush é melhor para SEO técnico, pesquisa de palavras-chave e análise de concorrentes. Muitos profissionais de SEO usam os dois."}, {"q": "SurferSEO é gratuito?", "a": "SurferSEO não tem plano gratuito. Planos a partir de $89/mês (Essential). SEMrush tem uma versão gratuita limitada; planos pagos a partir de $139,95/mês."}, {"q": "SurferSEO realmente funciona?", "a": "Sim, SurferSEO é uma das ferramentas de otimização de conteúdo mais comprovadas. Muitos profissionais de SEO relatam melhoras significativas no ranqueamento após implementar as recomendações do Surfer."}, {"q": "SurferSEO vs Clearscope — qual é a diferença?", "a": "Ambos otimizam conteúdo para SEO. SurferSEO tem recursos mais amplos incluindo auditoria de site. Clearscope é focado exclusivamente na otimização de conteúdo e tem interface mais simples. Clearscope é mais caro mas mais específico para conteúdo."}]$x$::jsonb
 WHERE slug = 'surferseo' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿HeyGen o Synthesia para videos de formación?", "a": "Synthesia está más orientado a formación corporativa y eLearning — tiene más integraciones con LMS y flujos de trabajo de L&D. HeyGen es mejor para videos de marketing personalizados y clonación de voz/avatar. Para formación interna a escala — Synthesia; para marketing con avatar propio — HeyGen."}, {"q": "¿Son legales los avatares de IA?", "a": "HeyGen y Synthesia requieren consentimiento explícito para crear avatares de personas reales. Las plataformas tienen políticas de uso aceptable que prohíben la creación de deepfakes no autorizados. Usar avatares con consentimiento para marketing propio o formación corporativa es completamente legal."}]$x$::jsonb
 WHERE slug = 'synthesia' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "HeyGen vs Synthesia: Was ist der Unterschied?", "a": "HeyGen ist stärker bei Video-Übersetzung und interaktiven Avataren für Echtzeit-Anwendungen. Synthesia hat mehr Avatare und ist stärker für Enterprise-Trainingsvideos und E-Learning. HeyGen für Video-Lokalisierung; Synthesia für skalierbare Unternehmenskommunikation."}, {"q": "Sind KI-Avatar-Videos überzeugend?", "a": "Moderne KI-Avatare von HeyGen und Synthesia sind für professionelle Präsentationen und E-Learning überzeugend. Sie sind ideal für Schulungsvideos, Produktdemos und interne Kommunikation. Für emotionale Marketingvideos die menschliche Verbindung erfordern sind echte Kameras noch besser."}]$x$::jsonb
 WHERE slug = 'synthesia' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "HeyGen чи Synthesia для корпоративних відео?", "a": "Synthesia краще для корпоративного навчання і HR: більше аватарів, мов і enterprise-функцій. HeyGen краще для маркетингу і продажових відео де потрібна персоналізація. Для L&D — Synthesia; для маркетингу — HeyGen."}, {"q": "Чи підтримує Synthesia українську мову?", "a": "Synthesia підтримує 140+ мов включно з українською. Ви можете генерувати навчальні відео з аватарами що говорять українською без записи живого спікера."}]$x$::jsonb
