UPDATE tools SET faq = $x$[{"q": "HeyGen מול Synthesia לוידאו ארגוני?", "a": "Synthesia עדיף לאימון ארגוני ו-HR: יותר אווטרים, שפות ותכונות enterprise. HeyGen עדיף לשיווק ולמכירות שדורשים פרסונליזציה. ל-L&D — Synthesia; לשיווק — HeyGen."}, {"q": "האם Synthesia תומך בעברית?", "a": "Synthesia תומך ב-140+ שפות כולל עברית. ניתן ליצור וידאו הדרכה עם אווטרים המדברים עברית ללא צילום דובר חי."}]$x$::jsonb
