UPDATE tools SET faq = $x$[{"q": "HeyGen vs Synthesia — qual escolher?", "a": "HeyGen tem avatares de melhor qualidade e mais recursos de marketing. Synthesia é mais adequado para treinamento corporativo e e-learning. Para marketing e conteúdo viral, HeyGen; para treinamento corporativo, Synthesia."}, {"q": "Synthesia é confiável para uso corporativo?", "a": "Sim, Synthesia é amplamente usado por grandes corporações para treinamento e comunicações internas. Tem conformidade SOC 2 e GDPR."}]$x$::jsonb
 WHERE slug = 'synthesia' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Synthesis?", "a": "Synthesis es una plataforma de aprendizaje matemático para niños que nació en la escuela de SpaceX (Ad Astra School de Elon Musk). Usa videojuegos multijugador donde los niños resuelven problemas matemáticos y de pensamiento lógico en desafíos colaborativos. Fue considerada la mejor plataforma de matemáticas para niños en su lanzamiento."}, {"q": "¿Synthesis es gratuito?", "a": "Synthesis tiene un plan gratuito limitado para explorar. El plan completo cuesta $35/mes por familia. Khanmigo cuesta $9/mes o $44/año. Khan Academy (sin Khanmigo) es completamente gratuito."}, {"q": "¿Para qué edades es Synthesis?", "a": "Synthesis está diseñado para niños de 6 a 14 años (primaria y secundaria baja). Khanmigo cubre más rango de edad — desde primaria hasta preparatoria e incluso universitaria para algunas materias."}, {"q": "¿Synthesis o Beast Academy para matemáticas avanzadas?", "a": "Synthesis es mejor para aprendizaje a través del juego y pensamiento matemático. Beast Academy (de Art of Problem Solving) está orientado a matemáticas de competencia — más riguroso y desafiante para niños que quieren matemáticas olímpicas. Para motivación y hábito — Synthesis; para matemáticas avanzadas de competencia — Beast Academy."}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Synthesis?", "a": "Synthesis ist eine Lernplattform ursprünglich für SpaceX-Mitarbeiterkinder entwickelt. Es nutzt kollaborative Spiele und Simulationen um mathematisches Denken zu fördern. Kinder 5-14 Jahre spielen zusammen und lösen dabei komplexe mathematische Probleme."}, {"q": "Wie viel kostet Synthesis?", "a": "Synthesis kostet $35/Monat. Khanmigo kostet $4/Monat als Add-on. Synthesis ist teurer aber bietet eine engagierende Spiel-Erfahrung. Für Eltern die ein engagierendes Mathe-Lernspiel suchen — Synthesis; für günstigen breiten Tutor — Khanmigo."}, {"q": "Synthesis für deutschsprachige Kinder: Ist es geeignet?", "a": "Synthesis ist primär auf Englisch. Die mathematischen Konzepte sind sprachübergreifend, aber die Spielanleitungen und Kommunikation sind auf Englisch. Für deutschsprachige Kinder ohne gute Englischkenntnisse kann das eine Barriere sein."}, {"q": "Synthesis vs Prodigy: Was ist besser?", "a": "Prodigy ist kostenlos und breit verfügbar für Grundschul-Mathe. Synthesis ist teurer aber hat komplexere, kollaborative Lernspiele. Prodigy für einfaches Mathe-Üben; Synthesis für tieferes mathematisches Denken und kollaborative Problemlösung."}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Synthesis vs Khanmigo — в чём разница?", "a": "Synthesis (от SpaceX Education) — обучающая игровая платформа по математике для детей с акцентом на проблемное мышление. Khanmigo — ИИ-репетитор Khan Academy с Сократовским подходом для более широкого круга предметов. Synthesis — игры, Khanmigo — репетиторство."}, {"q": "Synthesis бесплатный?", "a": "Synthesis предлагает бесплатный пробный период. Подписка — около $35/мес. Khanmigo — $9/мес как дополнение к бесплатной Khan Academy."}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Synthesis vs Khan Academy — яка різниця?", "a": "Khan Academy — безкоштовна навчальна платформа з відео і вправами. Synthesis — платформа з головоломками і командними завданнями для розвитку мислення. Khan Academy для стандартної програми; Synthesis для розвитку нестандартного мислення."}, {"q": "Synthesis скільки коштує?", "a": "Synthesis від $35/міс. Khanmigo $44/рік або безкоштовно через партнерства зі школами. Khan Academy повністю безкоштовний."}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Synthesis vs Khanmigo — qual é melhor para crianças?", "a": "Synthesis é mais voltado para pensamento matemático e lógico através de jogos para crianças. Khanmigo é um tutor geral mais alinhado ao currículo escolar. Para pensamento criativo e matemático, Synthesis; para apoio escolar geral, Khanmigo."}, {"q": "Synthesis é gratuito?", "a": "Synthesis custa $35/mês por aluno. Não tem plano gratuito permanente. Khanmigo custa $44/ano. Khan Academy é gratuita."}, {"q": "Synthesis é adequado para crianças brasileiras?", "a": "Synthesis está disponível internacionalmente mas o conteúdo é principalmente em inglês. Para crianças que estudam em inglês ou aprendem o idioma, pode ser valioso. Para currículo brasileiro em português, pode não ser ideal."}, {"q": "A Khan Academy é boa para o Brasil?", "a": "Sim, Khan Academy tem uma versão completa em português (pt.khanacademy.org) com conteúdo alinhado ao currículo brasileiro. É amplamente usada por estudantes e professores no Brasil."}]$x$::jsonb
 WHERE slug = 'synthesis' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Tableau AI?", "a": "Tableau AI son las funciones de inteligencia artificial integradas en Tableau: Einstein Analytics explica automáticamente por qué cambian los datos, Ask Data permite preguntas en lenguaje natural sobre cualquier dashboard, y Tableau Pulse envía resúmenes inteligentes automáticos. Disponibles en Tableau Cloud."}]$x$::jsonb
