UPDATE tools SET faq = $x$[{"q": "Kann Tableau AI natürliche Sprache verwenden?", "a": "Ja. Tableau hat Ask Data und Tableau AI Features die natürlichsprachige Fragen zu Ihren Daten ermöglichen. Sie können fragen 'Was waren unsere Top-Produkte letztes Quartal?' und Tableau generiert die Visualisierung."}]$x$::jsonb
