UPDATE tools SET faq = $x$[{"q": "Tableau AI що вміє?", "a": "Tableau AI (Tableau Einstein) дозволяє ставити запитання до ваших даних природньою мовою і отримувати візуалізації. Також прогнозування трендів і виявлення аномалій автоматично."}]$x$::jsonb
