UPDATE tools SET faq = $x$[{"q": "Tableau AI – מה הכוונה?", "a": "Tableau AI (Einstein Copilot) הוא שכבת AI ש-Salesforce מוסיפה ל-Tableau. מאפשר שאילת שאלות בשפה טבעית, זיהוי חריגות ויצירת תובנות אוטומטית."}]$x$::jsonb
