UPDATE tools SET faq = $x$[{"q": "Tableau AI peut-il générer des insights automatiquement ?", "a": "Oui. Tableau Pulse utilise l'IA pour surveiller automatiquement vos métriques et envoyer des insights et alertes dans Slack ou par email. C'est une fonctionnalité puissante pour les équipes qui veulent être proactives sur leurs données."}]$x$::jsonb
