 WHERE slug = 'tableau-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Tickeron es fiable para señales de trading?", "a": "Las señales de IA de Tickeron muestran resultados históricos pero, como toda predicción de mercado, no garantizan rentabilidad futura. Tickeron es transparente sobre la precisión histórica de sus patrones. Para traders que quieren asistencia IA — útil como referencia; para trading real — siempre requiere criterio propio."}, {"q": "¿Tickeron es gratuito?", "a": "Tickeron tiene un plan gratuito limitado. Los planes de pago empiezan desde $17/mes con acceso a más funciones de IA y señales. TradingView tiene plan gratuito sólido; planes de pago desde $12.95/mes."}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Tickeron?", "a": "Tickeron ist eine KI-Trading-Plattform die automatisch Handelsmuster erkennt, Signale generiert und AI Robots für automatisiertes Trading anbietet. Es kombiniert technische Analyse mit KI um Kauf- und Verkaufssignale zu identifizieren."}, {"q": "Tickeron vs TradingView: Welches ist für Anfänger?", "a": "Tickeron ist einsteigerfreundlicher für KI-gestützte Signals ohne tiefes Chart-Wissen. TradingView hat eine steilere Lernkurve für technische Analyse. Aber TradingView ist kostenlos einsteigerfreundlich für einfaches Chart-Lesen."}, {"q": "Sind Tickeron-Signale zuverlässig?", "a": "KI-Trading-Signale haben keine garantierte Genauigkeit. Tickeron zeigt historische Performance seiner Patterns. Wie alle Trading-Tools sollte Tickeron als eines von mehreren Analyse-Werkzeugen genutzt werden, nicht als alleinige Entscheidungsgrundlage."}, {"q": "Wie viel kostet Tickeron?", "a": "Tickeron beginnt ab $90/Monat für Basis-Features. Höhere Pläne für mehr AI Robots und Signale. TradingView hat einen kostenlosen Plan; Essential ab $14,95/Monat."}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Tickeron vs TradingView — в чём разница?", "a": "Tickeron — ИИ-торговая платформа с автоматическими сигналами и роботами. TradingView — профессиональная платформа для графиков с инструментами технического анализа. Tickeron предлагает ИИ-рекомендации, TradingView — инструменты для самостоятельного анализа."}, {"q": "Tickeron бесплатный?", "a": "Tickeron предлагает ограниченный бесплатный план. Платные планы от $90/мес. TradingView бесплатен с базовыми функциями; Essential — $12.95/мес."}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Що таке Tickeron?", "a": "Tickeron — ШІ-торгова платформа що автоматично розпізнає торгові патерни, генерує сигнали і пропонує AI Robots для автоматизованої торгівлі. Поєднує технічний аналіз із ШІ для визначення сигналів."}, {"q": "Tickeron vs TradingView — що для початківців?", "a": "Tickeron більш зручний для початківців з ШІ-сигналами без глибоких знань графіків. TradingView має крутіший поріг входу для технічного аналізу. Але TradingView безкоштовно зручний для простого читання графіків."}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "מה זה Tickeron?", "a": "Tickeron פלטפורמת מסחר AI שמזהה דפוסי מסחר, מייצרת אותות ומציעה AI Robots לאוטומציה. משלב ניתוח טכני עם AI."}, {"q": "Tickeron לעומת TradingView – למתחילים?", "a": "Tickeron ידידותי יותר למתחילים עם אותות AI. TradingView דורש ידע בניתוח טכני. אך TradingView חינמי ומצוין לקריאת גרפים בסיסית."}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Tickeron ?", "a": "Tickeron est une plateforme de trading IA qui reconnaît automatiquement les patterns de marché, génère des signaux et propose des AI Robots pour le trading automatisé. Elle combine l'analyse technique avec l'IA pour identifier les signaux d'achat et de vente."}, {"q": "Tickeron vs TradingView — lequel est meilleur pour les débutants ?", "a": "Tickeron est plus accessible pour les débutants souhaitant des signaux IA sans connaissances approfondies en graphiques. TradingView a une courbe d'apprentissage plus importante pour l'analyse technique. Mais TradingView est gratuit et facile à utiliser pour la lecture basique de graphiques."}, {"q": "Les signaux Tickeron sont-ils fiables ?", "a": "Les signaux de trading IA n'ont pas de précision garantie. Tickeron montre les performances historiques de ses patterns. Comme tous les outils de trading, Tickeron doit être utilisé comme un outil parmi d'autres, pas comme seule base de décision."}, {"q": "Combien coûte Tickeron ?", "a": "Tickeron commence à partir de 90 $/mois pour les fonctionnalités de base. Les plans supérieurs pour plus d'AI Robots et de signaux. TradingView a un plan gratuit ; Essential à partir de 14,95 $/mois."}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "O que é o Tickeron?", "a": "Tickeron é uma plataforma de trading com IA que reconhece padrões de mercado automaticamente, gera sinais e oferece AI Robots para trading automatizado. Combina análise técnica com IA para identificar sinais de compra e venda."}, {"q": "Tickeron vs TradingView — qual é melhor para iniciantes?", "a": "Tickeron é mais acessível para iniciantes que querem sinais de IA sem conhecimentos avançados em gráficos. TradingView tem curva de aprendizado maior para análise técnica. Mas TradingView é gratuito e fácil para leitura básica de gráficos."}, {"q": "Os sinais do Tickeron são confiáveis?", "a": "Sinais de trading com IA não têm precisão garantida. Tickeron mostra o desempenho histórico de seus padrões. Como todas as ferramentas de trading, deve ser usado como um entre vários recursos, não como base única de decisão."}, {"q": "Quanto custa o Tickeron?", "a": "Tickeron começa a partir de $90/mês para funcionalidades básicas. Planos superiores para mais AI Robots e sinais. TradingView tem plano gratuito; Essential a partir de $14,95/mês."}]$x$::jsonb
 WHERE slug = 'tickeron' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿TradingView o Bloomberg para traders?", "a": "Bloomberg es la herramienta profesional institucional ($2.000+/mes). TradingView es la mejor opción para traders retail e inversores individuales — mejores gráficos del mercado consumer a un precio accesible. Para traders no institucionales, TradingView es el estándar de facto."}, {"q": "¿TradingView es gratuito?", "a": "TradingView tiene un plan gratuito con funciones básicas (3 indicadores por gráfico, 1 alerta). Los planes de pago (Essential $12.95/mes, Plus $24.95/mes, Premium $49.95/mes) desbloquean más indicadores, alertas y funciones. FinChat tiene plan gratuito limitado; Pro desde $17/mes."}, {"q": "¿Qué es FinChat?", "a": "FinChat (anteriormente conocido como Fiscal AI) es una plataforma de análisis financiero con IA. Permite hacer preguntas en lenguaje natural sobre empresas públicas: 'cuál fue el margen bruto de Apple en Q3 2024', analizar earnings calls y comparar métricas financieras entre competidores."}, {"q": "¿TradingView tiene análisis fundamental?", "a": "TradingView tiene datos fundamentales básicos (P/E, EPS, ingresos) pero no está especializado en análisis fundamental profundo. Para análisis fundamental serio — FinChat, Koyfin o Tikr son más completos. TradingView es imbatible en análisis técnico y gráficos."}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "TradingView vs Finchat: Was ist der Unterschied?", "a": "TradingView ist für technische Analyse: Charts, Indikatoren, Handelsideen. Finchat ist für fundamentale KI-Analyse: Sie stellen Fragen zu Unternehmensberichten. TradingView für Trader; Finchat für langfristige Investoren die Unternehmen tief analysieren."}, {"q": "Ist TradingView kostenlos?", "a": "TradingView hat einen kostenlosen Plan mit 3 Indikatoren und einer Daten-Verzögerung. Essential ab $14,95/Monat, Essential+ ab $29,95. Finchat hat einen kostenlosen Plan; Pro ab $30/Monat."}, {"q": "Was ist Pine Script?", "a": "Pine Script ist TradingView's eigene Programmiersprache für benutzerdefinierte Indikatoren und Handelssysteme. Sie können eigene technische Indikatoren schreiben und backtesten. Die Community teilt tausende Pine Script-Indikatoren kostenlos."}, {"q": "Finchat für deutsche Aktien: Ist es gut?", "a": "Finchat hat Daten für internationale Märkte inklusive DACH-Aktien. Die Tiefe der KI-Analyse kann für kleinere deutsche Unternehmen geringer sein als für US-Großunternehmen wo mehr Dokumentation verfügbar ist."}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "TradingView vs Finchat — для кого каждый?", "a": "TradingView — для технических трейдеров и тех, кто анализирует графики. Finchat — для фундаментальных инвесторов, изучающих финансовую отчётность компаний. Это разные инструменты для разных стилей инвестирования."}, {"q": "TradingView бесплатный?", "a": "TradingView имеет бесплатный план с ограниченными индикаторами и алертами. Essential — $12.95/мес, Plus — $24.95/мес, Premium — $49.95/мес. Finchat предлагает бесплатный план с базовыми данными; Pro — $22/мес."}, {"q": "Что такое Finchat?", "a": "Finchat — ИИ-финансовый аналитик с доступом к 750 000+ KPI из отчётности публичных компаний. Задайте вопрос на естественном языке — получите данные из 10-K, 10-Q и звонков с аналитиками с ссылками на источники."}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "TradingView vs Finchat — яка різниця?", "a": "TradingView для технічного аналізу: графіки, індикатори, торгові ідеї. Finchat для фундаментального ШІ-аналізу: ставте запитання до корпоративних звітів. TradingView для трейдерів; Finchat для довгострокових інвесторів."}, {"q": "TradingView безкоштовний?", "a": "TradingView має безкоштовний план з 3 індикаторами і затримкою даних. Essential від $14,95/міс. Finchat має безкоштовний план; Pro від $30/міс."}, {"q": "Що таке Pine Script?", "a": "Pine Script — власна мова програмування TradingView для кастомних індикаторів і торгових систем. Можна писати і тестувати власні технічні індикатори. Спільнота ділиться тисячами Pine Script-індикаторів безкоштовно."}, {"q": "Finchat для українських акцій?", "a": "Finchat має дані для міжнародних ринків. Для українських акцій охоплення може бути обмеженим. Для великих міжнародних компаній доступні повноцінний аналіз і документація."}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "TradingView לעומת Finchat – מה ההבדל?", "a": "TradingView לניתוח טכני. Finchat לניתוח פונדמנטלי עם AI. TradingView לסוחרים; Finchat למשקיעים שמנתחים חברות."}, {"q": "TradingView חינמי?", "a": "TradingView מציע תוכנית חינמית עם 3 אינדיקטורים; Essential מ-$14.95/חודש. Finchat מציע תוכנית חינמית; Pro ב-$30/חודש."}, {"q": "מה זה Pine Script?", "a": "Pine Script היא שפת התכנות של TradingView לכתיבת אינדיקטורים מותאמים אישית ואסטרטגיות מסחר. הקהילה משתפת אלפי scripts חינם."}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "TradingView vs Finchat — quelle est la différence ?", "a": "TradingView est pour l'analyse technique : graphiques, indicateurs, idées de trading. Finchat est pour l'analyse IA fondamentale : posez des questions sur les rapports d'entreprise. TradingView pour les traders ; Finchat pour les investisseurs long terme."}, {"q": "TradingView est-il gratuit ?", "a": "TradingView a un plan gratuit avec 3 indicateurs et un délai des données. Essential à partir de 14,95 $/mois, Essential+ à partir de 29,95 $. Finchat a un plan gratuit ; Pro à partir de 30 $/mois."}, {"q": "Qu'est-ce que Pine Script ?", "a": "Pine Script est le langage de programmation propriétaire de TradingView pour créer des indicateurs et systèmes de trading personnalisés. Vous pouvez écrire et backtester vos propres indicateurs techniques. La communauté partage des milliers d'indicateurs Pine Script gratuitement."}, {"q": "Finchat pour les actions françaises — est-il efficace ?", "a": "Finchat couvre les marchés internationaux incluant les actions françaises (CAC40). La profondeur de l'analyse IA peut être moindre pour les petites capitalisations françaises que pour les grandes entreprises américaines où plus de documentation est disponible."}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "TradingView vs Finchat — qual é a diferença?", "a": "TradingView é para análise técnica: gráficos, indicadores, ideias de trading. Finchat é para análise fundamentalista com IA: faça perguntas sobre relatórios de empresas. TradingView para traders; Finchat para investidores de longo prazo."}, {"q": "TradingView é gratuito?", "a": "TradingView tem plano gratuito com 3 indicadores e delay nos dados. Essential a partir de $14,95/mês. Finchat tem plano gratuito; Pro a partir de $30/mês."}, {"q": "O que é Pine Script?", "a": "Pine Script é a linguagem de programação proprietária do TradingView para criar indicadores e sistemas de trading personalizados. Você pode escrever e fazer backtest dos seus próprios indicadores técnicos. A comunidade compartilha milhares de indicadores Pine Script gratuitamente."}, {"q": "Finchat para ações brasileiras — é eficaz?", "a": "Finchat cobre mercados internacionais incluindo ações da B3. A profundidade da análise com IA pode ser menor para pequenas empresas brasileiras que para grandes empresas americanas onde mais documentação está disponível."}]$x$::jsonb
 WHERE slug = 'tradingview' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Suno или Udio — что лучше?", "a": "Suno лучше для быстрой генерации полных песен — быстрее и удобнее. Udio в целом производит более высокое качество звука, но имеет ограничения на скачивание в некоторых регионах. Оба конкурентоспособны, Suno лидирует по удобству использования и размеру сообщества."}, {"q": "Suno бесплатный?", "a": "Suno предлагает бесплатный план с 50 кредитами в день (около 10 песен). Plan Pro — $8/мес, Premier — $24/мес для большего количества кредитов, прав на коммерческое использование и приоритетной генерации."}, {"q": "Что такое Udio AI?", "a": "Udio — инструмент генерации ИИ-музыки, создающий песни из текстовых запросов. Запущен в 2024 году и известен особенно высоким качеством звука. Udio столкнулся с юридическими претензиями от крупных звукозаписывающих лейблов относительно обучающих данных."}]$x$::jsonb
 WHERE slug = 'udio' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Suno чи Udio — що краще?", "a": "Suno простіший і швидший — ідеально для початківців і швидкого контенту. Udio виробляє більш якісну музику для тих хто хоче деталі і professional звучання. Для соціального контенту — Suno; для якості — Udio."}, {"q": "Suno безкоштовний?", "a": "Suno має безкоштовний план з 50 генераціями/день. Pro $10/міс; Premier $30/міс. Udio має безкоштовний план; від $12/міс."}]$x$::jsonb
 WHERE slug = 'udio' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Suno מול Udio — מה עדיף?", "a": "Suno מהיר יותר לשירים מוגמרים. Udio מציע שליטה מדויקת יותר. Suno לשירים מהירים; Udio לשירים עם תחכום רב יותר."}, {"q": "האם Suno בחינם?", "a": "Suno מציע 50 קרדיטים/יום בחינם (5 שירים). Pro מ-10$/חודש. Udio מציע 100 שירים/חודש בחינם; Standard מ-10$/חודש."}]$x$::jsonb
 WHERE slug = 'udio' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Uizard o Figma para startups?", "a": "Uizard es ideal en fases tempranas para validar ideas rápidamente — un fundador puede crear un prototipo funcional en minutos sin diseñador. Figma es mejor cuando el equipo crece y necesita un sistema de diseño formal. Muchas startups empiezan en Uizard y migran a Figma al escalar."}, {"q": "¿Uizard es gratuito?", "a": "Uizard tiene un plan gratuito con 3 proyectos y funciones limitadas. Los planes de pago empiezan desde $12/mes (Pro). Figma tiene plan gratuito para 3 proyectos; planes de pago desde $15/mes."}, {"q": "¿Qué es Uizard Autodesigner?", "a": "Autodesigner es la función IA estrella de Uizard — describes la app que quieres en texto ('aplicación de fitness para seguimiento de rutinas') y Uizard genera automáticamente múltiples pantallas de UI con diseño coherente. Es el flujo más rápido para convertir una idea en un prototipo visual."}, {"q": "¿Uizard puede usarse para desarrollo real?", "a": "Uizard es para prototipado y diseño conceptual, no para desarrollo. No genera código listo para producción. Los prototipos son para validar ideas y presentar conceptos. Para desarrollo real, el diseño de Uizard se usa como referencia visual."}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Uizard?", "a": "Uizard ist ein KI-Design-Tool das Wireframes und App-Mockups aus Text-Beschreibungen, Screenshots oder Hand-Sketches generiert. Es ist primär für nicht-technische Nutzer — Produkt-Manager, Gründer und Business-Analysten die App-Ideen schnell visualisieren wollen."}, {"q": "Ist Uizard kostenlos?", "a": "Uizard hat einen kostenlosen Plan mit 3 Projekten und begrenzten KI-Features. Pro beginnt ab $12/Monat, Business ab $39/Monat. Figma hat einen kostenlosen Plan; Professional ab $15/Benutzer/Monat."}, {"q": "Kann Uizard Figma ersetzen?", "a": "Nicht für professionelle Designer. Uizard ist für die schnelle Konzept-Visualisierung ohne Design-Kenntnisse. Figma ist das Profi-Tool für präzises UI/UX-Design. Uizard kann Figma ergänzen: Uizard für erste Konzepte, Figma für die finale Ausarbeitung."}, {"q": "Kann Uizard mobile Apps designen?", "a": "Ja. Uizard unterstützt Mobile-App-Design für iOS und Android sowie Web-Interfaces. Sie können Templates für verschiedene App-Typen auswählen und mit KI-Hilfe schnell iterieren."}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое Uizard?", "a": "Uizard — ИИ-инструмент прототипирования, позволяющий не-дизайнерам создавать макеты приложений и сайтов. Умеет преобразовывать скетчи и скриншоты в редактируемые прототипы, генерировать дизайны по текстовым описаниям."}, {"q": "Uizard заменяет Figma?", "a": "Нет. Uizard — для быстрого прототипирования и не-дизайнеров. Figma — для профессионального производственного дизайна. Uizard идеален для демонстрации концепции, Figma — для финального продукта."}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Uizard для не-дизайнерів?", "a": "Так. Uizard розроблений спеціально для non-дизайнерів: founders, product managers і розробників що хочуть створювати прототипи. Figma потужніший але потребує більше навчання."}, {"q": "Uizard vs Figma — яка головна різниця?", "a": "Uizard простіший і орієнтований на швидкі прототипи для не-дизайнерів. Figma — professional дизайн-інструмент для продуктових команд. Для ідей і валідації — Uizard; для реального продукту — Figma."}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Uizard vs Figma — lequel est le meilleur pour un non-designer ?", "a": "Uizard est clairement plus accessible pour les non-designers : générez des maquettes en minutes à partir de descriptions. Figma est puissant mais a une courbe d'apprentissage importante. Pour les PM et fondateurs sans compétences en design, Uizard."}, {"q": "Uizard est-il gratuit ?", "a": "Uizard a un plan gratuit avec 3 projets. Pro à partir de 12 $/mois. Figma a un plan gratuit ; Professional à partir de 15 $/éditeur/mois."}, {"q": "Uizard peut-il convertir des screenshots en maquettes ?", "a": "Oui. C'est l'une des fonctionnalités phares d'Uizard : téléchargez un screenshot de n'importe quelle app et Uizard le convertit en maquette modifiable. C'est très utile pour recréer des interfaces existantes ou s'inspirer de designs."}, {"q": "Uizard vs Mockup.io vs Balsamiq — quelle est la différence ?", "a": "Uizard génère des maquettes avec IA à partir de descriptions ou screenshots. Balsamiq est pour les wireframes basse fidélité rapides. Les deux sont plus accessibles que Figma pour les non-designers. Uizard est plus moderne avec l'IA intégrée."}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Uizard vs Figma AI — qual usar?", "a": "Uizard é para protótipos rápidos por não-designers. Figma é o padrão para design profissional de produto. Para ideação rápida, Uizard; para design profissional e colaboração em equipe, Figma."}, {"q": "Uizard é gratuito?", "a": "Uizard tem plano gratuito com 2 projetos. Planos pagos a partir de $12/mês. Figma tem plano gratuito com até 3 projetos; planos pagos a partir de $12/mês."}, {"q": "Uizard consegue converter sketches em wireframes?", "a": "Sim, este é um dos principais recursos do Uizard. Você fotografa um esboço à mão e ele converte automaticamente em wireframe digital editável. Muito útil para reuniões de ideação."}, {"q": "Uizard tem geração de UI por IA?", "a": "Sim, o Uizard Autodesigner gera wireframes e UIs completos a partir de uma descrição de texto. Você descreve o aplicativo e ele gera as telas iniciais para você editar."}]$x$::jsonb
 WHERE slug = 'uizard' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Qué es Uptrends AI?", "a": "Uptrends AI es una plataforma de análisis de tendencias de mercado que usa IA para identificar qué activos, sectores y temáticas de inversión están ganando momentum. Se enfoca en la detección temprana de tendencias emergentes, diferenciándose de herramientas de análisis fundamental como Koyfin."}, {"q": "¿Uptrends AI es gratuito?", "a": "Uptrends AI tiene acceso gratuito limitado. Los planes de pago varían según las funciones de análisis de tendencias. Koyfin tiene un plan gratuito más completo para análisis fundamental de empresas."}]$x$::jsonb
 WHERE slug = 'uptrends-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist Uptrends AI?", "a": "Uptrends AI ist ein KI-Investmenttool das Markttrends analysiert und Signale für aufkommende Preisbewegungen identifiziert. Es nutzt Machine Learning um Muster in Marktdaten zu erkennen und Investoren auf potenzielle Chancen hinzuweisen."}, {"q": "Uptrends AI vs Koyfin: Wer ist besser?", "a": "Koyfin ist ausgereifter und bekannter für fundamentale Analyse und Portfolio-Management. Uptrends AI ist spezialisierter auf KI-Trendanalyse und Signale. Für fundamentale Investoren — Koyfin; für trendorientierte Signale — Uptrends AI."}, {"q": "Ist Uptrends AI für Kryptowährungen?", "a": "Uptrends AI deckt verschiedene Asset-Klassen ab. Prüfen Sie die aktuelle Plattform für den genauen Umfang der unterstützten Assets."}]$x$::jsonb
 WHERE slug = 'uptrends-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Що таке Uptrends AI?", "a": "Uptrends AI — ШІ-інвестиційний інструмент що аналізує ринкові тренди і визначає сигнали для нових цінових рухів. Використовує машинне навчання для розпізнавання патернів і попередження інвесторів про можливості."}, {"q": "Uptrends AI vs Koyfin — хто кращий?", "a": "Koyfin більш зрілий і відомий для фундаментального аналізу і управління портфелем. Uptrends AI спеціалізується на ШІ-аналізі трендів і сигналах. Для фундаментальних інвесторів — Koyfin; для трендових сигналів — Uptrends AI."}]$x$::jsonb
 WHERE slug = 'uptrends-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "מה זה Uptrends AI?", "a": "Uptrends AI כלי השקעות AI שמנתח מגמות שוק ומזהה הזדמנויות השקעה באמצעות Machine Learning."}, {"q": "Uptrends AI לעומת Koyfin – מי עדיף?", "a": "Koyfin בוגר יותר לניתוח פונדמנטלי ולניהול תיק. Uptrends AI מתמחה באותות מגמה. Koyfin למשקיעים פונדמנטליים; Uptrends לאותות מגמה."}]$x$::jsonb
 WHERE slug = 'uptrends-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Uptrends AI ?", "a": "Uptrends AI est un outil d'investissement IA qui analyse les tendances de marché et identifie les signaux de mouvements de prix émergents. Il utilise le machine learning pour reconnaître des patterns dans les données de marché."}, {"q": "Uptrends AI vs Koyfin — lequel est le meilleur ?", "a": "Koyfin est plus mature et reconnu pour l'analyse fondamentale et la gestion de portefeuille. Uptrends AI est plus spécialisé dans l'analyse de tendances IA et les signaux. Pour les investisseurs fondamentaux → Koyfin ; pour les signaux de tendance → Uptrends AI."}, {"q": "Uptrends AI couvre-t-il les cryptomonnaies ?", "a": "Uptrends AI couvre différentes classes d'actifs. Vérifiez la plateforme actuelle pour la couverture exacte des actifs supportés."}]$x$::jsonb
 WHERE slug = 'uptrends-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "O que é o Uptrends AI?", "a": "Uptrends AI é uma ferramenta de investimento com IA que analisa tendências de mercado e identifica sinais de movimentos de preço emergentes. Usa machine learning para reconhecer padrões nos dados de mercado."}, {"q": "Uptrends AI vs Koyfin — qual é o melhor?", "a": "Koyfin é mais maduro e reconhecido para análise fundamentalista e gestão de carteira. Uptrends AI é mais especializado em análise de tendências com IA e sinais. Para investidores fundamentalistas → Koyfin; para sinais de tendência → Uptrends AI."}, {"q": "Uptrends AI cobre criptomoedas?", "a": "Uptrends AI cobre diferentes classes de ativos. Verifique a plataforma atual para a cobertura exata dos ativos suportados."}]$x$::jsonb
 WHERE slug = 'uptrends-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Qué es UXPilot?", "a": "UXPilot es una herramienta de IA específica para diseño UX. Puede generar wireframes desde descripciones de texto, crear personas de usuario, mapas de empatía, user journeys y documentación de UX. Está orientada a investigadores UX y product managers que necesitan documentación UX rápida."}, {"q": "¿UXPilot genera código?", "a": "UXPilot se centra en wireframes y documentación de UX, no en código. Para generar código desde diseños, herramientas como GitHub Copilot o Cursor con contexto de diseño son más adecuadas. UXPilot es para la fase de descubrimiento y definición, no implementación."}, {"q": "¿UXPilot vs Uizard?", "a": "Ambas usan IA para UI/UX, pero con enfoques distintos. Uizard es mejor para prototipado rápido de apps con diseño visual completo. UXPilot es mejor para investigación y documentación de UX: personas, journeys, wireframes conceptuales. Para un prototipo que mostrar — Uizard; para investigación de UX — UXPilot."}]$x$::jsonb
 WHERE slug = 'uxpilot' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Что такое UXPilot?", "a": "UXPilot — ИИ-инструмент для UX-дизайна, генерирующий wireframes, UI-экраны и прототипы по текстовым описаниям. Специализируется на быстром создании пользовательских потоков и макетов без глубоких дизайнерских навыков."}, {"q": "UXPilot или Figma AI — что выбрать стартапу?", "a": "Для стартапа без дизайнеров UXPilot позволяет быстро создать прототипы. Figma AI требует понимания Figma. Многие стартапы используют UXPilot для генерации идей, затем доводят их в Figma."}, {"q": "UXPilot экспортирует в Figma?", "a": "Да. UXPilot позволяет экспортировать дизайны в Figma для дальнейшего редактирования и уточнения. Это типичный рабочий процесс: генерация в UXPilot, финальная полировка в Figma."}]$x$::jsonb
 WHERE slug = 'uxpilot' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "UXpilot — що це?", "a": "UXpilot — ШІ-інструмент для UX-дизайнерів що генерує UI-макети, user personas і UX-аналіз. Він орієнтований на дослідницьку і аналітичну частину UX а не лише на візуальний дизайн."}, {"q": "Figma AI vs UXpilot — яка різниця?", "a": "Figma AI — ШІ вбудований у Figma для дизайн-задач. UXpilot — окремий інструмент фокусований на UX-дослідженні і аналізі. Вони доповнюють а не замінюють одне одного."}, {"q": "UXpilot для user research?", "a": "Так. UXpilot допомагає автоматизувати частини UX-дослідження: генерує personas, аналізує юзабіліті і пропонує покращення. Для команд де немає dedicated UX-дослідника — цінний інструмент."}]$x$::jsonb
 WHERE slug = 'uxpilot' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "UXPilot מול Figma AI — מה ההבדל?", "a": "UXPilot מתמקד במחקר UX ובדליברבלים תיעודיים. Figma AI בעיצוג ואב-טיפוס. UXPilot לחוקרי UX; Figma AI למעצבי UI."}, {"q": "UXPilot בחינם?", "a": "ל-UXPilot יש ניסיון חינמי. תוכניות בתשלום מ-18$/חודש. Figma יש תוכנית חינמית; Professional מ-15$/חודש."}, {"q": "UXPilot מייצר wireframes?", "a": "כן. UXPilot מייצר wireframes מתיאורים טקסטואליים. הם פשוטים ומהירים לאב-טיפוס. לhigh-fidelity wireframes — Figma או Uizard מדויקים יותר."}]$x$::jsonb
 WHERE slug = 'uxpilot' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "¿Qué es v0 by Vercel?", "a": "v0 es una herramienta de generación de código de UI de Vercel. Describes la interfaz que necesitas y genera componentes React con shadcn/ui y Tailwind CSS listos para copiar o desplegar en Vercel. Es especialmente potente para diseños de dashboard y landing pages."}, {"q": "¿v0 by Vercel es gratuito?", "a": "v0 tiene un plan gratuito con créditos mensuales limitados. Los planes de pago ($10-20/mes) desbloquean más generaciones. Cursor cuesta $20/mes para el plan Pro."}, {"q": "¿v0 puede generar código de backend?", "a": "v0 está principalmente enfocado en UI/frontend. Para desarrollo backend completo, Cursor o Claude Code son más adecuados."}, {"q": "¿Cuánto cuesta V0?", "a": "Nivel gratuito con créditos limitados. Premium es $20/mes. Planes de equipo disponibles para proyectos colaborativos."}, {"q": "¿Puede V0 generar aplicaciones completas?", "a": "V0 se centra en la generación de UI frontend. Para apps completas, se integra con la plataforma de Vercel y puede generar rutas API y conexiones de base de datos."}, {"q": "¿Qué frameworks soporta V0?", "a": "V0 genera principalmente React con Tailwind CSS y componentes shadcn/ui. Compatible con Next.js y despliega de forma nativa en Vercel."}]$x$::jsonb
 WHERE slug = 'v0-by-vercel' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist v0 by Vercel?", "a": "v0 ist Vercels KI-Tool zur Generierung von React/Next.js UI-Komponenten. Sie beschreiben eine UI in Text ('erstelle eine Produktkarte mit Bild, Preis und Kaufen-Button') und v0 generiert den Code mit Live-Vorschau. Es ist besonders stark für shadcn/ui und Tailwind CSS Komponenten."}, {"q": "Ist v0 kostenlos?", "a": "v0 hat einen kostenlosen Plan mit begrenzten Credits (200/Monat). Premium-Pläne ($20/Monat und mehr) bieten mehr Credits und erweiterte Funktionen. Cursor hat ebenfalls einen kostenlosen Plan; Pro kostet $20/Monat."}, {"q": "v0 vs Figma für UI-Design?", "a": "v0 generiert direkt Code — kein Handoff nötig. Figma ist die professionelle Design-Tool für UI/UX-Designer mit Prototyping, Design-Systemen und Team-Kollaboration. Für Designer — Figma; für Entwickler die schnell UI-Code benötigen — v0."}, {"q": "Kann v0 ganze Anwendungen erstellen?", "a": "v0 fokussiert sich auf UI-Komponenten und Seiten, nicht auf vollständige Anwendungen mit Backend-Logik. Für vollständige App-Generierung sind Bolt.new oder Lovable besser geeignet. v0 glänzt bei einzelnen UI-Komponenten und Seiten in Next.js/React."}, {"q": "Was kostet V0?", "a": "Kostenloses Kontingent mit begrenzten Credits. Premium kostet $20/Monat. Team-Pläne für kollaborative Projekte verfügbar."}, {"q": "Kann V0 vollständige Apps generieren?", "a": "V0 fokussiert sich auf Frontend-UI-Generierung. Für vollständige Apps integriert es sich mit der Vercel-Plattform und kann API-Routen und Datenbankverbindungen erstellen."}, {"q": "Welche Frameworks unterstützt V0?", "a": "V0 generiert hauptsächlich React mit Tailwind CSS und shadcn/ui-Komponenten. Kompatibel mit Next.js und deployed nativ auf Vercel."}]$x$::jsonb
 WHERE slug = 'v0-by-vercel' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Что такое v0 by Vercel?", "a": "v0 — ИИ-инструмент от Vercel для генерации React/Next.js UI-компонентов по текстовым описаниям. Выдаёт готовый код на основе shadcn/ui и Tailwind CSS. Идеален для быстрого прототипирования интерфейсов."}, {"q": "v0 бесплатный?", "a": "v0 предлагает ограниченное бесплатное использование. Платные планы от $10/мес с большим количеством запросов. Cursor стоит $20/мес за Pro."}, {"q": "Работает ли v0 только с Next.js?", "a": "v0 оптимизирован для React/Next.js, но может генерировать компоненты и для других фреймворков. Интеграция с Vercel обеспечивает мгновенный деплой созданных компонентов."}]$x$::jsonb
 WHERE slug = 'v0-by-vercel' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "v0 Vercel безкоштовний?", "a": "v0 має безкоштовний план з обмеженими повідомленнями. Преміум плани від $10/міс. Cursor Free — обмежений; Pro — $20/міс."}, {"q": "Що таке v0?", "a": "v0 від Vercel — ШІ-генератор UI-компонентів. Ви описуєте інтерфейс природною мовою і v0 генерує готовий React+Tailwind код. Ідеально для дизайнерів і розробників що хочуть швидко будувати якісні інтерфейси."}, {"q": "Що таке V0 by Vercel?", "a": "V0 — AI-генератор UI від Vercel. Опишіть інтерфейс текстом — отримаєте готовий React і Tailwind CSS код, який деплоїться прямо на Vercel."}]$x$::jsonb
 WHERE slug = 'v0-by-vercel' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "האם v0 של Vercel בחינם?", "a": "ל-v0 יש תוכנית חינמית עם הודעות מוגבלות. תוכניות Premium מ-10$/חודש. Cursor Free — מוגבל; Pro — 20$/חודש."}, {"q": "מה זה v0?", "a": "v0 מ-Vercel הוא מחולל UI של רכיבי React+Tailwind. אתם מתארים את הממשק בשפה טבעית ו-v0 מייצר קוד מוכן. מושלם למעצבים ומפתחים שרוצים לבנות ממשקים איכותיים במהירות."}, {"q": "מה זה V0 by Vercel?", "a": "V0 הוא מחולל UI מבוסס AI של Vercel. תאר ממשק בשפה טבעית ו-V0 מייצר קוד React ו-Tailwind CSS מוכן לייצור שנפרס ישירות ב-Vercel."}]$x$::jsonb
 WHERE slug = 'v0-by-vercel' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "v0 Vercel est-il gratuit ?", "a": "v0 a un plan gratuit avec des messages limités. Les plans Premium à partir de 10 $/mois. Cursor Free — limité ; Pro — 20 $/mois."}, {"q": "Qu'est-ce que v0 ?", "a": "v0 de Vercel est un générateur de composants UI IA. Vous décrivez une interface en langage naturel et v0 génère du code React+Tailwind prêt à l'emploi. Idéal pour les designers et développeurs souhaitant créer rapidement des interfaces de qualité."}, {"q": "Qu'est-ce que V0 by Vercel ?", "a": "V0 est le générateur d'UI propulsé par IA de Vercel. Décrivez une interface en langage naturel et V0 génère du code React et Tailwind CSS prêt pour la production, qui se déploie directement sur Vercel."}, {"q": "Combien coûte V0 ?", "a": "Niveau gratuit avec crédits limités. Premium à $20/mois. Plans équipe disponibles pour les projets collaboratifs."}, {"q": "V0 peut-il générer des applications complètes ?", "a": "V0 se concentre sur la génération d'UI frontend. Pour des apps complètes, il s'intègre avec la plateforme Vercel et peut créer des routes API et des connexions de base de données."}, {"q": "Quels frameworks V0 prend-il en charge ?", "a": "V0 génère principalement React avec Tailwind CSS et les composants shadcn/ui. Compatible avec Next.js et se déploie nativement sur Vercel."}]$x$::jsonb
 WHERE slug = 'v0-by-vercel' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "v0 Vercel é gratuito?", "a": "v0 tem plano gratuito com mensagens limitadas. Planos Premium a partir de $10/mês. Cursor Free — limitado; Pro — $20/mês."}, {"q": "O que é v0?", "a": "v0 da Vercel é um gerador de componentes UI de IA. Você descreve uma interface em linguagem natural e o v0 gera código React+Tailwind pronto para uso. Ideal para designers e desenvolvedores que querem criar interfaces de qualidade rapidamente."}, {"q": "O que é o V0 by Vercel?", "a": "O V0 é o gerador de UI com IA da Vercel. Descreva uma interface em linguagem natural e o V0 gera código React e Tailwind CSS pronto para produção, que é implantado diretamente na Vercel."}, {"q": "Quanto custa o V0?", "a": "Nível gratuito com créditos limitados. Premium custa $20/mês. Planos de equipe disponíveis para projetos colaborativos."}, {"q": "O V0 pode gerar aplicativos completos?", "a": "O V0 foca na geração de UI frontend. Para apps completos, integra-se com a plataforma Vercel e pode criar rotas de API e conexões de banco de dados."}, {"q": "Quais frameworks o V0 suporta?", "a": "O V0 gera principalmente React com Tailwind CSS e componentes shadcn/ui. Compatível com Next.js e implanta nativamente na Vercel."}]$x$::jsonb
 WHERE slug = 'v0-by-vercel' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Bubble o Webflow para startups?", "a": "Depende del producto. Si construyes una aplicación SaaS con usuarios, datos y lógica — Bubble. Si construyes el sitio web de marketing de tu startup — Webflow. Muchas startups usan ambas: Webflow para el sitio de marketing y Bubble para el producto."}, {"q": "¿Puede Webflow construir aplicaciones?", "a": "Webflow tiene lógica básica (formularios, filtros, miembros) pero no está diseñado para aplicaciones complejas con base de datos propia y lógica de negocio. Para funcionalidades de app reales — Bubble. Webflow es mejor para sitios con contenido dinámico pero no para productos SaaS."}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Bubble oder Webflow: Was soll ich wählen?", "a": "Bubble für Web-Apps: Sie brauchen Nutzeraccounts, Datenbank und komplexe Logik — z.B. ein SaaS-Produkt oder Marktplatz. Webflow für Marketing-Websites: Sie brauchen eine schöne, schnelle Website mit CMS aber keine App-Logik."}, {"q": "Webflow für E-Commerce: Ist das gut?", "a": "Webflow hat eingebautes E-Commerce für einfache Online-Shops. Für komplexere E-Commerce-Anforderungen (große Produktkataloge, komplexe Varianten) ist Shopify leistungsfähiger. Webflow ist gut für Design-orientierte kleine Shops."}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между Bubble и Webflow?", "a": "Bubble — конструктор no-code приложений: для создания веб-приложений с базами данных, логикой и пользовательскими взаимодействиями. Webflow — конструктор сайтов с фокусом на дизайн и CMS. Bubble строит приложения, Webflow строит сайты."}, {"q": "Есть ли у Webflow база данных?", "a": "У Webflow есть CMS для структурированного контента (статьи блога, каталог товаров). Это не полноценная база данных приложения — для пользовательских данных, транзакций или сложной логики нужен Bubble или собственный бэкенд."}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Bubble vs Webflow — що обрати для стартапу?", "a": "Bubble для стартапів що будують SaaS або застосунки з бізнес-логікою і базами даних. Webflow для маркетингових сайтів і агентств. Для MVP з функціональністю — Bubble; для красивого сайту — Webflow."}, {"q": "Webflow vs WordPress — яка різниця?", "a": "Webflow — візуальний конструктор сайтів з чистим кодом. WordPress — CMS з тисячами плагінів і більшою гнучкістю контенту. Webflow для дизайнерів що хочуть контроль; WordPress для контент-важких сайтів з великою екосистемою."}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Bubble לעומת Webflow – מה לבחור?", "a": "Bubble לאפליקציות web עם לוגיקה ומסד נתונים. Webflow לאתרים ויזואליים ו-CMS. SaaS ו-Web App – Bubble; אתרי שיווק ועיצוב – Webflow."}, {"q": "Webflow SEO – כמה זה טוב?", "a": "Webflow מצוין ל-SEO – HTML נקי, meta tags, sitemap אוטומטי ו-301 redirects. אחד הפתרונות הטובים ביותר ל-SEO בין בוני האתרים ללא קוד."}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Bubble vs Webflow — lequel est le meilleur ?", "a": "Bubble est pour créer des applications web complexes (SaaS, marketplaces). Webflow est pour les sites web marketing et de contenu. Application web avec logique métier → Bubble ; site marketing ou portfolio → Webflow."}, {"q": "Webflow est-il adapté au SEO ?", "a": "Oui. Webflow produit du HTML sémantique propre, des temps de chargement rapides et offre un contrôle total des balises SEO. C'est l'un des meilleurs constructeurs de sites web pour le SEO."}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Bubble vs Webflow — qual escolher?", "a": "Bubble é para construir aplicativos com lógica de negócios complexa. Webflow é para criar sites belos com CMS. Para apps SaaS, Bubble; para sites de marketing de alta qualidade, Webflow."}, {"q": "Webflow é bom para e-commerce?", "a": "Webflow tem funcionalidades básicas de e-commerce. Para lojas menores, funciona bem. Para e-commerce complexo com muitos produtos, Shopify pode ser mais adequado."}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Whimsical vs Figma — в чём разница?", "a": "Whimsical специализируется на диаграммах, mind maps, flowcharts и быстрых wireframes. Figma — профессиональный UI/UX дизайн-инструмент для создания интерфейсов продуктов. Whimsical для визуализации идей, Figma для дизайна продуктов."}, {"q": "Whimsical бесплатный?", "a": "Да. Whimsical предлагает бесплатный план с неограниченными файлами и ограниченными ИИ-генерациями. Pro — $10/пользователь/мес. Figma имеет бесплатный план для индивидуалов."}, {"q": "Whimsical подходит для UX-дизайна?", "a": "Whimsical отлично подходит для wireframing на начальной стадии и пользовательских потоков. Для финального дизайна с компонентами и handoff — Figma. Многие UX-дизайнеры используют Whimsical для планирования, Figma для исполнения."}]$x$::jsonb
 WHERE slug = 'whimsical-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "¿Whisper es gratuito?", "a": "Whisper es open-source (modelo gratuito de OpenAI para descargar y usar localmente). Vía la API de OpenAI, cuesta $0.006/minuto. Otter AI tiene plan gratuito con 300 minutos/mes; planes de pago desde $16.99/mes."}, {"q": "¿Qué precisión tiene Whisper?", "a": "Whisper large-v3 tiene una de las mayores precisiones de transcripción disponibles, especialmente en inglés. En español y otros idiomas también es muy competitivo. Para audio limpio, la precisión supera el 95%. Para audio de baja calidad — la precisión baja pero sigue siendo buena comparada con alternativas."}, {"q": "¿Cómo uso Whisper sin ser técnico?", "a": "Whisper está disponible de forma accesible en: MacWhisper (app Mac gratuita), OpenAI Playground, varias apps de escritorio que lo integran. No necesitas ser programador para usarlo. La versión más técnica (línea de comandos) ofrece más control pero no es necesaria para uso básico."}]$x$::jsonb
 WHERE slug = 'whisper' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Whisper vs Otter.ai — в чём разница?", "a": "Whisper — open-source модель транскрипции от OpenAI, которую запускают локально или через API. Otter.ai — коммерческий продукт для транскрипции встреч в реальном времени с командными функциями. Whisper — технология, Otter — готовый сервис."}, {"q": "Whisper бесплатный?", "a": "Whisper как модель полностью бесплатен с открытым исходным кодом. API OpenAI ($0.006/мин) — платный. Для запуска локально (через WhisperX, faster-whisper) — бесплатно без лимитов. Otter.ai — бесплатен с 600 мин/мес."}]$x$::jsonb
 WHERE slug = 'whisper' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Whisper vs Otter.ai — для чого що?", "a": "Whisper — відкрита технологія для розробників і технічних команд що хочуть транскрипцію у власних продуктах. Otter.ai — готовий продукт для бізнес-команд що хочуть зручну транскрипцію нарад без розробки."}, {"q": "Whisper безкоштовний?", "a": "Модель Whisper відкрита і безкоштовна для локального запуску. OpenAI Whisper API — $0,006/хв. Otter.ai має безкоштовний план з 600 хв/міс; Pro від $17/міс."}]$x$::jsonb
 WHERE slug = 'whisper' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Whisper לעומת Otter.ai?", "a": "Whisper Open Source API לפיתוחים. Otter.ai מוצר מוכן לשימוש לפגישות. Whisper למפתחים; Otter.ai לאנשי עסקים."}, {"q": "Whisper חינמי?", "a": "Whisper Open Source חינמי לחלוטין. OpenAI Whisper API ב-$0.006/דקה. Otter.ai מציע 300 דקות חינם; Pro ב-$16.99/חודש."}]$x$::jsonb
 WHERE slug = 'whisper' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Whisper vs Otter.ai — quelle est la différence ?", "a": "Whisper est un modèle de transcription open-source à intégrer dans vos propres outils. Otter.ai est un service complet de notes de réunion avec interface. Pour des développeurs intégrant la transcription → Whisper ; pour des notes de réunion prêtes à l'emploi → Otter.ai."}, {"q": "Whisper est-il gratuit ?", "a": "Le modèle Whisper est open-source et gratuit à utiliser localement. L'API Whisper via OpenAI est payante (environ 0,006 $/minute). Otter.ai a un plan gratuit avec 300 minutes/mois."}, {"q": "Whisper transcrit-il bien le français ?", "a": "Oui. Whisper est excellent pour le français — l'un des meilleurs modèles de transcription open-source pour les langues européennes. Il gère bien les accents régionaux et le français courant."}]$x$::jsonb
 WHERE slug = 'whisper' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Whisper vs Otter.ai — qual é a diferença?", "a": "Whisper é um modelo de transcrição open-source para integrar em suas próprias ferramentas. Otter.ai é um serviço completo de notas de reunião com interface pronta. Para desenvolvedores integrando transcrição → Whisper; para notas de reunião prontas para uso → Otter.ai."}, {"q": "Whisper é gratuito?", "a": "O modelo Whisper é open-source e gratuito para usar localmente. A API Whisper via OpenAI é paga (cerca de $0,006/minuto). Otter.ai tem plano gratuito com 300 minutos/mês."}, {"q": "Whisper transcreve bem o português?", "a": "Sim. Whisper é excelente para português — um dos melhores modelos de transcrição open-source para idiomas ibéricos. Lida bem com sotaques regionais e português coloquial."}]$x$::jsonb
 WHERE slug = 'whisper' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "Windsurf лучше Cursor?", "a": "Windsurf предлагает более автономный опыт через Cascade (агент, который самостоятельно планирует изменения). Cursor считается более зрелым с лучшей поддержкой контекста кодовой базы. Оба на уровне друг друга по функциональности — выбор зависит от предпочтений рабочего процесса."}, {"q": "Что такое Windsurf Cascade?", "a": "Cascade — флагманская агентная система Windsurf. В отличие от обычных ИИ-автодополнений, Cascade понимает контекст всего проекта и самостоятельно планирует и выполняет многошаговые изменения кода без постоянного ввода промптов."}, {"q": "Windsurf — это от Cognition?", "a": "Да. Windsurf был приобретён Cognition (создателями Devin — первого ИИ-разработчика). Это означает доступ к передовым разработкам в области агентного кодирования. Продукт переименован, но доступен как windsurf.com."}]$x$::jsonb
 WHERE slug = 'windsurf' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "¿Es Jasper mejor que Writesonic?", "a": "Para empresas que necesitan herramientas de marketing a escala con Brand Voice y colaboración en equipo — Jasper suele valer la pena el precio extra. Para freelancers y pequeñas empresas que necesitan contenido de IA de calidad a mejor precio — Writesonic ofrece más por menos dinero."}, {"q": "¿Writesonic tiene búsqueda en internet?", "a": "Sí. Chatsonic de Writesonic tiene acceso a internet en tiempo real vía Google Search. Esto lo hace útil para contenido basado en noticias actuales o tendencias recientes, a diferencia de modelos sin acceso web."}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Jasper vs Writesonic: Welches ist besser für Blogs?", "a": "Beide können Blog-Artikel generieren. Jasper ist besser für Markenkonsistenz und Team-Workflows; Writesonic bietet oft mehr Content für weniger Geld. Für Solo-Blogger mit Budget — Writesonic; für Marketingteams mit Markenstimmen-Anforderungen — Jasper."}, {"q": "Ist KI-generierter Content für SEO geeignet?", "a": "Ja, wenn er qualitativ hochwertig, einzigartig und für Menschen geschrieben ist. Suchmaschinen bewerten Qualität und Relevanz — KI-Content der gut recherchiert, überprüft und bearbeitet wurde kann gut ranken. Google hat klargestellt, dass KI-Content nicht per se gegen ihre Richtlinien verstößt."}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "Для чего используется Writesonic?", "a": "Writesonic — ИИ-контент-платформа для маркетологов и бизнеса. Генерирует публикации в блогах, рекламные тексты, описания товаров и лендинги. Chatsonic (его чатбот) имеет доступ к Google Поиску для актуальной информации. Также генерирует ИИ-изображения через Photosonic."}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Jasper чи Writesonic для блогу?", "a": "Обидва генерують блог-статті. Jasper кращий для командного контенту і брендовою узгодженості. Writesonic дає більше за менші гроші. Для соло-блогерів — Writesonic; для маркетингових команд — Jasper."}, {"q": "ШІ-контент добре ранжується в Google?", "a": "Так, якщо він якісний, унікальний і написаний для людей. Google оцінює якість і релевантність — ШІ-контент що добре відредагований може добре ранжуватись. Google прямо заявив що ШІ-контент сам по собі не порушує їхні правила."}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Jasper או Writesonic לבלוג?", "a": "שניהם מייצרים מאמרי בלוג. Jasper עדיף לעקביות מותג ותהליכי עבודה של צוות. Writesonic מספק יותר בפחות כסף. לבלוגרים יחידים — Writesonic; לצוותי שיווק — Jasper."}, {"q": "האם תוכן AI מדורג טוב בגוגל?", "a": "כן, אם הוא איכותי, ייחודי וכתוב לבני אדם. גוגל מעריכה איכות ורלוונטיות — תוכן AI שנערך היטב יכול לדורג טוב. גוגל הצהירה שתוכן AI כשלעצמו אינו מפר את מדיניותה."}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Jasper ou Writesonic pour un blog ?", "a": "Les deux génèrent des articles de blog. Jasper est meilleur pour la cohérence de la marque et les workflows d'équipe. Writesonic offre plus pour moins cher. Pour les blogueurs solo, Writesonic ; pour les équipes marketing, Jasper."}, {"q": "Le contenu IA se classe-t-il bien sur Google ?", "a": "Oui, s'il est de haute qualité, unique et écrit pour les humains. Google évalue la qualité et la pertinence — le contenu IA bien recherché, vérifié et édité peut bien se classer. Google a clairement indiqué que le contenu IA ne viole pas en soi ses directives."}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Jasper ou Writesonic para um blog?", "a": "Ambos geram artigos de blog. Jasper é melhor para consistência de marca e fluxos de trabalho em equipe. Writesonic oferece mais por menos dinheiro. Para blogueiros solo, Writesonic; para equipes de marketing, Jasper."}, {"q": "Conteúdo de IA ranqueia bem no Google?", "a": "Sim, se for de alta qualidade, único e escrito para humanos. O Google avalia qualidade e relevância — conteúdo de IA bem pesquisado, verificado e editado pode ranquear bem. O Google deixou claro que conteúdo de IA não viola suas diretrizes por si só."}]$x$::jsonb
 WHERE slug = 'writesonic' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿YouLearn o Recall para aprender de YouTube?", "a": "YouLearn permite conversaciones profundas sobre videos de YouTube con preguntas y respuestas. Recall crea tarjetas de memoria automáticamente de videos y artículos para repaso espaciado. Para entender en profundidad — YouLearn; para memorizar a largo plazo — Recall."}, {"q": "¿YouLearn es gratuito?", "a": "YouLearn tiene un plan gratuito con acceso limitado. Los planes de pago empiezan desde $12/mes. NotebookLM de Google es gratuito con límites generosos."}, {"q": "¿YouLearn puede crear flashcards?", "a": "Sí. YouLearn puede generar flashcards automáticamente a partir del contenido de videos o documentos cargados para estudio activo. NotebookLM no tiene esta función específica de flashcards — se centra más en preguntas y respuestas y Audio Overview."}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Was ist YouLearn?", "a": "YouLearn ist ein KI-Lernassistent der YouTube-Videos und Dokumente in interaktive Lernmaterialien umwandelt. Er generiert automatisch Zusammenfassungen, Quizfragen und Karteikarten aus dem Video-Content und ermöglicht Fragen an das Video zu stellen."}, {"q": "YouLearn vs Recall: Was ist besser?", "a": "Recall ist breiter: Es speichert und verknüpft Wissen aus allen Quellen (Web, PDFs, Videos) in einer persönlichen Wissensdatenbank. YouLearn ist fokussierter auf aktives Lernen aus Videos mit Quiz-Generierung. Für Wissensmanagement — Recall; für aktives Lernen aus Videos — YouLearn."}, {"q": "Ist YouLearn kostenlos?", "a": "YouLearn hat eine kostenlose Version mit begrenzten Funktionen. Kostenpflichtige Pläne bieten unbegrenzte Verarbeitung. NotebookLM ist vollständig kostenlos."}, {"q": "Kann YouLearn deutsche YouTube-Videos verarbeiten?", "a": "Ja. YouLearn kann deutsche Videos transkribieren und analysieren. Die Qualität hängt von der Audio-Qualität des Videos ab. Gut artikulierte deutschsprachige Vorlesungen und Kurse werden gut verarbeitet."}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "YouLearn vs NotebookLM — в чём разница?", "a": "YouLearn специализируется на обучении по видео: анализирует YouTube и загруженные видео, создаёт конспекты и тесты. NotebookLM фокусируется на текстовых документах (PDF, заметки). YouLearn для видеообучения, NotebookLM для анализа документов."}, {"q": "YouLearn бесплатный?", "a": "YouLearn предлагает ограниченный бесплатный план. Pro-план для полного функционала. NotebookLM полностью бесплатен от Google с более щедрыми ограничениями."}]$x$::jsonb
 WHERE slug = 'youlearn' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "¿Zapier AI puede trabajar con Notion?", "a": "Sí. Zapier tiene integración nativa con Notion — puede leer y escribir en bases de datos de Notion, crear páginas automáticamente cuando ocurren eventos en otras apps, y usar IA para procesar datos antes de insertarlos en Notion."}, {"q": "¿Qué es Zapier AI?", "a": "Zapier AI es la capa de IA dentro de Zapier que permite crear flujos de trabajo automatizados usando lenguaje natural. Describe lo que quieres automatizar y Zapier AI genera el flujo conectando más de 7.000 apps."}, {"q": "¿Cuánto cuesta Zapier?", "a": "Plan gratuito con 100 tareas/mes y 5 Zaps. Starter es $29.99/mes (750 tareas). Professional es $73.50/mes (2K tareas). Team es $103.50/mes. Enterprise a precio personalizado."}, {"q": "¿Qué puede automatizar Zapier AI?", "a": "Respuestas de correo, actualizaciones de CRM, publicaciones en redes sociales, entrada de datos, enrutamiento de leads y cualquier tarea repetitiva en más de 7.000 apps conectadas, por evento o por horario."}, {"q": "¿En qué se diferencia Zapier AI de n8n?", "a": "Zapier es un SaaS sin código con la mayor biblioteca de integraciones. n8n es de código abierto y autoalojable, ofreciendo más flexibilidad y menor costo a escala para usuarios técnicos."}]$x$::jsonb
 WHERE slug = 'zapier-ai' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Kann Zapier KI-Workflows erstellen?", "a": "Ja. Zapier hat KI-Funktionen: AI-gestützte Zap-Generierung, Formatter mit KI und AI-Steps in Workflows. Sie können KI-Verarbeitung als Schritt in Automationen einbauen — z.B. E-Mail-Inhalt zusammenfassen und in Notion speichern."}, {"q": "Was ist Zapier AI?", "a": "Zapier AI ist die KI-Schicht in Zapier, die es ermöglicht, automatisierte Workflows in natürlicher Sprache zu erstellen. Beschreibe was du automatisieren möchtest, und Zapier AI erstellt den Workflow, der 7.000+ Apps verbindet."}, {"q": "Was kostet Zapier?", "a": "Kostenloser Plan mit 100 Aufgaben/Monat und 5 Zaps. Starter kostet $29.99/Monat (750 Aufgaben). Professional $73.50/Monat (2K Aufgaben). Team $103.50/Monat. Enterprise auf Anfrage."}, {"q": "Was kann Zapier AI automatisieren?", "a": "E-Mail-Antworten, CRM-Updates, Social-Media-Posts, Dateneingabe, Lead-Routing und alle wiederkehrenden Aufgaben in 7.000+ verbundenen Apps — ausgelöst durch Ereignisse oder Zeitpläne."}, {"q": "Wie unterscheidet sich Zapier AI von n8n?", "a": "Zapier ist eine No-Code-SaaS-Lösung mit der größten Integrationsbibliothek. n8n ist Open-Source und selbst-hostbar und bietet mehr Flexibilität und niedrigere Kosten bei größerem Umfang für technische Nutzer."}]$x$::jsonb
 WHERE slug = 'zapier-ai' AND lang = 'de';

UPDATE tools SET faq = $x$[{"q": "В чём разница между Notion AI и Zapier AI?", "a": "Notion AI — ИИ-ассистент внутри Notion для создания и улучшения контента в вашем рабочем пространстве. Zapier AI ориентирован на автоматизацию — он использует ИИ для улучшения автоматизации рабочих процессов между приложениями. Notion AI — для работы со знаниями, Zapier AI — для автоматизации процессов."}, {"q": "Может ли Zapier AI заменить разработчика?", "a": "Zapier AI может автоматизировать многие задачи, ранее требовавшие участия разработчика: извлечение данных, классификацию и преобразование. Однако сложная кастомная логика по-прежнему требует программирования. Zapier AI снижает, но не устраняет потребность в технических ресурсах."}, {"q": "Есть ли у Notion автоматизация?", "a": "В Notion есть базовые встроенные автоматизации (триггеры кнопок, автоматизации баз данных). Для сложных межприложных рабочих процессов используйте Zapier или Make с интеграцией Notion. Notion AI обрабатывает контент, Zapier — внешние подключения к приложениям."}, {"q": "Сколько стоит Zapier?", "a": "Бесплатный план — 100 задач/месяц, 5 Zap. Starter — $29.99/месяц (750 задач). Professional — $73.50/месяц (2K задач). Team — $103.50/месяц. Компании — по запросу."}, {"q": "Чем Zapier AI отличается от n8n?", "a": "Zapier — no-code SaaS с крупнейшей библиотекой интеграций. n8n — open-source с возможностью самостоятельного хостинга, предлагает больше гибкости и ниже стоимость при масштабировании для технических пользователей."}]$x$::jsonb
 WHERE slug = 'zapier-ai' AND lang = 'ru';

UPDATE tools SET faq = $x$[{"q": "Zapier AI що це таке?", "a": "Zapier AI — набір ШІ-функцій у Zapier включно з AI Actions (природньомовні кроки у Zap), AI Chatbot (побудова чат-ботів) і Canvas (візуальний будівник автоматизацій з ШІ). Дозволяє будувати складніші автоматизації."}, {"q": "Скільки коштує Zapier?", "a": "Безкоштовний план — 100 завдань/місяць, 5 Zap. Starter — $29.99/місяць (750 завдань). Professional — $73.50/місяць (2K завдань). Team — $103.50/місяць. Компанії — за запитом."}, {"q": "Чим Zapier AI відрізняється від n8n?", "a": "Zapier — no-code SaaS з найбільшою бібліотекою інтеграцій. n8n — open-source з можливістю самостійного хостингу, пропонує більше гнучкості і нижчу вартість при масштабуванні для технічних користувачів."}]$x$::jsonb
 WHERE slug = 'zapier-ai' AND lang = 'ua';

UPDATE tools SET faq = $x$[{"q": "Notion AI לעומת Zapier AI – מה ההבדל?", "a": "Notion AI הוא עוזר כתיבה ועריכה בתוך Notion. Zapier AI הוא פלטפורמת אוטומציה שמוסיפה AI לזרימות עבודה בין אפליקציות. Notion למסמכים וידע; Zapier לאוטומציה."}, {"q": "Zapier AI – האם זה שימושי לעסקים קטנים?", "a": "כן. Zapier AI מאפשר לעסקים קטנים לאוטומט תהליכים שדרשו כוח אדם. מאיל עד CRM ועד ניהול לידים – Zapier חוסך שעות עבודה שבועיות."}, {"q": "כמה עולה Zapier?", "a": "תוכנית חינמית עם 100 משימות לחודש ו-5 Zaps. Starter עולה $29.99 לחודש (750 משימות). Professional עולה $73.50 לחודש (2K משימות). Team עולה $103.50 לחודש. Enterprise במחיר מותאם."}, {"q": "במה Zapier AI שונה מ-n8n?", "a": "Zapier הוא SaaS ללא קוד עם ספריית האינטגרציות הגדולה ביותר. n8n הוא קוד פתוח ומתארח בעצמו, ומציע גמישות רבה יותר ועלות נמוכה יותר בקנה מידה למשתמשים טכניים."}]$x$::jsonb
 WHERE slug = 'zapier-ai' AND lang = 'he';

UPDATE tools SET faq = $x$[{"q": "Notion AI vs Zapier AI — quelle est la différence ?", "a": "Notion AI vous aide à créer et gérer du contenu dans Notion. Zapier AI automatise des workflows entre différentes applications. Notion AI pour la productivité documentaire ; Zapier AI pour l'automatisation de processus."}, {"q": "Zapier AI peut-il créer des automatisations en français ?", "a": "Oui. Zapier AI comprend les instructions en français pour créer des automatisations. Vous décrivez ce que vous voulez automatiser en français et Zapier génère le workflow correspondant."}, {"q": "Qu'est-ce que Zapier AI ?", "a": "Zapier AI est la couche IA de Zapier qui permet de créer des workflows automatisés en langage naturel. Décrivez ce que vous voulez automatiser et Zapier AI génère le workflow connectant plus de 7 000 applications."}, {"q": "Combien coûte Zapier ?", "a": "Plan gratuit avec 100 tâches/mois et 5 Zaps. Starter à $29.99/mois (750 tâches). Professional à $73.50/mois (2K tâches). Team à $103.50/mois. Enterprise sur devis."}, {"q": "Que peut automatiser Zapier AI ?", "a": "Réponses aux emails, mises à jour CRM, publications sur les réseaux sociaux, saisie de données, routage des leads et toute tâche répétitive dans 7 000+ applications connectées, déclenchée par des événements ou par planification."}, {"q": "En quoi Zapier AI diffère-t-il de n8n ?", "a": "Zapier est un SaaS sans code avec la plus grande bibliothèque d'intégrations. n8n est open-source et auto-hébergeable, offrant plus de flexibilité et un coût réduit à grande échelle pour les utilisateurs techniques."}]$x$::jsonb
 WHERE slug = 'zapier-ai' AND lang = 'fr';

UPDATE tools SET faq = $x$[{"q": "Notion AI vs Zapier AI — qual usar?", "a": "Notion AI é para trabalhar com conteúdo e documentos dentro do Notion. Zapier AI é para automação inteligente entre aplicativos. Para criar e editar no Notion, use Notion AI; para automatizar fluxos entre ferramentas, use Zapier AI."}, {"q": "Zapier AI pode tomar decisões?", "a": "Sim, Zapier AI pode classificar conteúdo, resumir emails, extrair informações e tomar decisões baseadas em contexto. Útil para automatizar processos que antes requeriam julgamento humano."}, {"q": "O que é o Zapier AI?", "a": "O Zapier AI é a camada de IA dentro do Zapier que permite criar fluxos de trabalho automatizados em linguagem natural. Descreva o que quer automatizar e o Zapier AI gera o fluxo conectando mais de 7.000 apps."}, {"q": "Quanto custa o Zapier?", "a": "Plano gratuito com 100 tarefas/mês e 5 Zaps. Starter a $29.99/mês (750 tarefas). Professional a $73.50/mês (2K tarefas). Team a $103.50/mês. Enterprise sob consulta."}, {"q": "O que o Zapier AI pode automatizar?", "a": "Respostas de e-mail, atualizações de CRM, publicações em redes sociais, entrada de dados, roteamento de leads e qualquer tarefa repetitiva em mais de 7.000 apps conectados, acionada por eventos ou agendamento."}, {"q": "Como o Zapier AI se diferencia do n8n?", "a": "O Zapier é um SaaS sem código com a maior biblioteca de integrações. O n8n é open-source e auto-hospedável, oferecendo mais flexibilidade e custo menor em escala para usuários técnicos."}]$x$::jsonb
 WHERE slug = 'zapier-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"q": "¿Zed o VS Code para desarrollo?", "a": "Zed es significativamente más rápido que VS Code — lanzamiento instantáneo, sin lag en archivos grandes. VS Code tiene ecosistema de extensiones mucho mayor. Cursor está basado en VS Code. Para velocidad pura — Zed; para mayor ecosistema — VS Code o Cursor."}, {"q": "¿Zed es gratuito?", "a": "Zed es gratuito y open-source. Las funciones de IA (Zed AI) usan la API de Anthropic o pueden configurarse con otros modelos. Cursor tiene plan gratuito con 2.000 autocompletados; Pro ($20/mes) para uso ilimitado."}, {"q": "¿Zed está disponible en Windows?", "a": "Zed empezó como exclusivo de macOS pero lanzó soporte para Linux. El soporte para Windows está en desarrollo activo pero puede no estar completamente estable. Cursor está disponible en macOS, Windows y Linux."}]$x$::jsonb
 WHERE slug = 'zed' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "Zed vs Cursor — что быстрее?", "a": "Zed значительно быстрее запускается и работает — он написан на Rust, нативно многопоточный. Cursor базируется на VS Code (Electron) и тяжелее. Для скорости редактора — Zed, для ИИ-функционала — Cursor."}, {"q": "Zed бесплатный?", "a": "Да. Zed полностью бесплатен с открытым исходным кодом. ИИ-функции (Zed AI) бесплатны с ограничениями; платный доступ для более высоких лимитов. Cursor — $20/мес за Pro."}, {"q": "Расширения VS Code работают в Zed?", "a": "Нет. Zed не использует формат расширений VS Code. У Zed своя экосистема плагинов, которая пока меньше. Если вы зависите от специфических расширений VS Code — учтите это при переходе."}]$x$::jsonb
 WHERE slug = 'zed' AND lang = 'ru';
